INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'vocabulary', '刀', '刀', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna!', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'Pedang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'Katana', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'かたな', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'あのさむらいに、刀をぬすまれたんだ。', 'Pedangku dicuri oleh samurai itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'あのアメリカ人は刀を二ほんもっている。', 'Orang Amerika itu punya dua katana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25f8f1aa-9e2a-447a-bca2-ee3f15074687', 'スラリと刀をぬいたあのおとこはだれだ？', 'Siapa pria yang baru saja mengeluarkan pedang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9fb29743-c05a-4eca-bd02-d47fafd29be1', 'vocabulary', '矢', '矢', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
