INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9fb29743-c05a-4eca-bd02-d47fafd29be1', '矢はなん本のこっていますか？', 'Berapa banyak anak panah yang tersisa?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9fb29743-c05a-4eca-bd02-d47fafd29be1', 'こいのキューピッドが矢をはなとうとしているよ。', 'Cupid hendak menembakkan panah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9fb29743-c05a-4eca-bd02-d47fafd29be1', 'ほくべい土人の矢じりがとんできた。', 'Mata panah penduduk asli Amerika terbang ke arah saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f17daee-e360-4d12-ae8c-db44d3eccd8d', 'vocabulary', '羊', '羊', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7f17daee-e360-4d12-ae8c-db44d3eccd8d', 'Domba', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7f17daee-e360-4d12-ae8c-db44d3eccd8d', 'ひつじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f17daee-e360-4d12-ae8c-db44d3eccd8d', 'どうぶつえんで、羊にえさをやりました。', 'Saya harus memberi makan domba di kebun binatang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f17daee-e360-4d12-ae8c-db44d3eccd8d', 'いつ何がおこるか分からないんだから、羊がかいたいなら、かいたいと思ったときにかった方がいいよ。', 'Apa pun bisa terjadi kapan saja, jadi jika Anda menginginkan seekor domba, dapatkanlah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f17daee-e360-4d12-ae8c-db44d3eccd8d', '毛を刈られた時、羊も恥ずかしい思いをしていると思う？', 'Apakah menurut Anda domba merasa malu ketika bulunya dicukur?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('97826f32-9c55-4f87-96d4-17d02eb92d4f', 'vocabulary', '羊毛', '羊毛', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Bulu domba adalah wol.', 'Bulu domba adalah wol.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('97826f32-9c55-4f87-96d4-17d02eb92d4f', 'Wol', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('97826f32-9c55-4f87-96d4-17d02eb92d4f', 'ようもう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97826f32-9c55-4f87-96d4-17d02eb92d4f', 'クリスマスプレゼントに、羊毛のブランケットをもらいました。', 'Saya mendapat selimut wol sebagai hadiah Natal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97826f32-9c55-4f87-96d4-17d02eb92d4f', 'この羊毛フェルトの人形に出会えて本当によかった。', 'Saya sangat senang bisa menemukan boneka wol ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97826f32-9c55-4f87-96d4-17d02eb92d4f', '羊毛の手袋は、枕の詰め物に適している。', 'Sarung tangan wol sangat bagus untuk mengisi bantal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'vocabulary', '〜氏', '〜氏', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji berarti nama keluarga karena digunakan setelah nama keluarga dalam situasi yang sangat formal. Jadi, ini sangat erat kaitannya dengan hal itu. Karena pada masa itu hanya laki-laki yang mendapat rasa hormat, kami menyebut kosakata ini sebagai tuan. Anda juga bisa memanggil saya Tuan Koichi jika Anda mau.', 'Kanji berarti nama keluarga karena digunakan setelah nama keluarga dalam situasi yang sangat formal. Jadi, ini sangat erat kaitannya dengan hal itu. Karena pada masa itu hanya laki-laki yang mendapat rasa hormat, kami menyebut kosakata ini sebagai tuan. Anda juga bisa memanggil saya Tuan Koichi jika Anda mau.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'Tuan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'Madam', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'Miss', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'Mixter', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'し', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'やはり、アベ氏のはつげんはいつも全くブレませんね。', 'Seperti kita ketahui bersama, pernyataan Pak Abe tidak pernah berubah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'コウイチ氏とビエト氏はとても気が合う。', 'Pak Koichi dan Pak Viet punya chemistry yang bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cc0f5e9-b329-4887-851b-4aefad73a0ec', 'おお、ホワイト氏、ちょっと座れば？', 'Yo, Tuan White, kenapa Anda tidak duduk saja?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c265d17c-d8bb-41fb-bcf2-cac8f4213b7f', 'vocabulary', '氏名', '氏名', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kedua kanji ini ada hubungannya dengan nama. Anda memiliki nama keluarga dan nama. Kedua nama itu digabungkan menjadi Nama Depan dan Belakang... nama lengkap jika Anda mau.', 'Kedua kanji ini ada hubungannya dengan nama. Anda memiliki nama keluarga dan nama. Kedua nama itu digabungkan menjadi Nama Depan dan Belakang... nama lengkap jika Anda mau.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c265d17c-d8bb-41fb-bcf2-cac8f4213b7f', 'Nama Lengkap', true) ON CONFLICT DO NOTHING;
