INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c265d17c-d8bb-41fb-bcf2-cac8f4213b7f', 'しめい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c265d17c-d8bb-41fb-bcf2-cac8f4213b7f', '自分の氏名ぐらいは、日本ごでかけるようになりたいよね。', 'Anda setidaknya ingin bisa menulis nama lengkap Anda dalam bahasa Jepang, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c265d17c-d8bb-41fb-bcf2-cac8f4213b7f', 'ごさん考までに、わたしの氏名は、高 一子です。', 'Sekadar informasi, nama saya Ichiko Ko.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c265d17c-d8bb-41fb-bcf2-cac8f4213b7f', 'そちらの誓約書に氏名をご記入頂ければ、大砲で貴方の頭の上の林檎を撃ちぬいて差し上げます。', 'Jika Anda berkenan menuliskan nama depan dan belakang Anda di surat pernyataan, kami akan melanjutkan dengan menembakkan sebuah apel dari kepala Anda dengan meriam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('60d5f268-292b-4d8c-b093-1346c61f4990', 'vocabulary', '丁度', '丁度', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Oke, kita akan sedikit curang untuk mengingat arti kata ini. Katakanlah Anda mengukur suhu jalanan. Tepatnya seratus derajat. Memang itulah kenyataannya. Hanya 100 derajat, tidak lebih atau kurang satu derajat. Anda menaruh telur Anda di jalan dan melihatnya memasak.', 'Oke, kita akan sedikit curang untuk mengingat arti kata ini. Katakanlah Anda mengukur suhu jalanan. Tepatnya seratus derajat. Memang itulah kenyataannya. Hanya 100 derajat, tidak lebih atau kurang satu derajat. Anda menaruh telur Anda di jalan dan melihatnya memasak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('60d5f268-292b-4d8c-b093-1346c61f4990', 'Tepatnya', true) ON CONFLICT DO NOTHING;
