INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60d5f268-292b-4d8c-b093-1346c61f4990', '丁度おふろから出たところです。', 'Saya baru saja keluar dari kamar mandi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60d5f268-292b-4d8c-b093-1346c61f4990', '丁度いいゆかげんです。', 'Suhu mandinya pas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60d5f268-292b-4d8c-b093-1346c61f4990', 'まあ、偶然！今丁度あなたに電話をしようと思っていたところよ！', 'Suatu kebetulan! Aku baru saja akan meneleponmu!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aabcdce0-ca8e-4c2a-b106-dcd28b970fe4', 'vocabulary', '仮に', '仮に', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji sendiri artinya sementara. Saat Anda menambahkan に, kami meminta Anda membayangkan suatu situasi untuk sementara, sehingga maknanya berubah menjadi andaikan atau jika.', 'Kanji sendiri artinya sementara. Saat Anda menambahkan に, kami meminta Anda membayangkan suatu situasi untuk sementara, sehingga maknanya berubah menjadi andaikan atau jika.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aabcdce0-ca8e-4c2a-b106-dcd28b970fe4', 'Misalkan', true) ON CONFLICT DO NOTHING;
