INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd8a7a24-eb7f-4b66-9468-847f5b4e8907', '気にするなって。失ぱいは成功のもとだよ。', 'Jangan khawatir. Kegagalan mengajarkan kesuksesan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd8a7a24-eb7f-4b66-9468-847f5b4e8907', '新しいお仕事での成功をおいのりしています。', 'Saya berharap Anda sukses dalam pekerjaan baru Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd8a7a24-eb7f-4b66-9468-847f5b4e8907', '「ビジネスで成功したければ、型にはまらない考え方をしなさい」と言われて、カレー味の歯磨き粉を思いついたんだ。', 'Saya membuat pasta gigi rasa kari ketika saya diberi tahu, "Jika Anda ingin sukses dalam bisnis, Anda harus berpikir di luar kebiasaan."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36db7974-12e4-41d6-bad1-6b3812d0aa7d', 'vocabulary', '高級', '高級', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Item kelas tinggi sebenarnya hanyalah item bermutu tinggi atau kelas atas.', 'Item kelas tinggi sebenarnya hanyalah item bermutu tinggi atau kelas atas.') ON CONFLICT (id) DO NOTHING;
