INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c297eb0e-ff9f-43f2-b07d-38348a8583c6', 'しょきゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c297eb0e-ff9f-43f2-b07d-38348a8583c6', '来週、初級から中級に進級します。', 'Saya pindah ke kelas tingkat menengah dari kelas tingkat pemula minggu depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c297eb0e-ff9f-43f2-b07d-38348a8583c6', 'エトエトは、初級、中級、上級の三つのレベルに分かれていました。', 'EtoEto dibagi menjadi 3 level: level pemula, level menengah, dan level mahir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c297eb0e-ff9f-43f2-b07d-38348a8583c6', '私の日本語はまだ初級レベルですが、一生懸命勉強しています。', 'Bahasa Jepang saya masih di tingkat dasar, tapi saya berusaha keras untuk itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d4c46451-9e29-43a6-9eeb-a97ed21a7101', 'vocabulary', '中級', '中級', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Sesuatu yang berada pada peringkat atau kelas menengah berada pada tingkat menengah.', 'Sesuatu yang berada pada peringkat atau kelas menengah berada pada tingkat menengah.') ON CONFLICT (id) DO NOTHING;
