INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d4c46451-9e29-43a6-9eeb-a97ed21a7101', 'ちゅうきゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d4c46451-9e29-43a6-9eeb-a97ed21a7101', '中級のなんい度はどのぐらいですか？', 'Seberapa sulitkah tingkat menengahnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d4c46451-9e29-43a6-9eeb-a97ed21a7101', '明日から、また中級クラスにぎゃくもどりです。', 'Saya harus kembali ke kelas menengah mulai besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d4c46451-9e29-43a6-9eeb-a97ed21a7101', 'この会社には英語が中級の人たちは少ない。', 'Hanya ada sedikit orang yang mampu berbahasa Inggris tingkat menengah di perusahaan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29b2b1f0-fa49-4284-ac05-5a3d0fba5af0', 'vocabulary', '上級', '上級', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ketika kalian berada pada rank di atas maka kalian sudah berada pada level advanced. Ini mengacu pada hal-hal seperti kemahiran berbahasa Jepang, atau hal-hal seperti itu.', 'Ketika kalian berada pada rank di atas maka kalian sudah berada pada level advanced. Ini mengacu pada hal-hal seperti kemahiran berbahasa Jepang, atau hal-hal seperti itu.') ON CONFLICT (id) DO NOTHING;
