INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29b2b1f0-fa49-4284-ac05-5a3d0fba5af0', '上級クラスについていけずにこまっています。', 'Saya kesulitan mengikuti kelas tingkat lanjutan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29b2b1f0-fa49-4284-ac05-5a3d0fba5af0', 'コウイチ子ちゃん、上級生からいじめられているみたいなんです。', 'Koichiko sepertinya telah diintimidasi oleh siswa tingkat tinggi.') ON CONFLICT DO NOTHING;
