INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2433264b-d7d1-4484-91f0-6d90e3205dd4', 'vocabulary', '第二章', '第二章', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Awalan nomor urut dua bab mempunyai cara mendeskripsikan yang lebih sederhana yaitu bab dua.', 'Awalan nomor urut dua bab mempunyai cara mendeskripsikan yang lebih sederhana yaitu bab dua.') ON CONFLICT (id) DO NOTHING;
