INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e5d8433-d5b7-49cf-9a40-27dc0b36ee04', '自分のけんこうが第一ですよ。', 'Anda harus mengutamakan kesehatan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e5d8433-d5b7-49cf-9a40-27dc0b36ee04', '第一きぼうは二月十四日で、第二きぼうは二月二十一日です。', 'Preferensi pertama saya adalah 14 Februari dan preferensi kedua saya adalah 21 Februari.') ON CONFLICT DO NOTHING;
