INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82ec1704-7587-44e9-a016-d315ebb530c5', 'vocabulary', '第一位', '第一位', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Awalan bilangan urut satu pangkat. Pada dasarnya, ini berarti “peringkat pertama” atau peringkat pertama.', 'Awalan bilangan urut satu pangkat. Pada dasarnya, ini berarti “peringkat pertama” atau peringkat pertama.') ON CONFLICT (id) DO NOTHING;
