INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47ca7c79-661a-438a-a409-d8f0cab0594b', '暑すぎてとけそう。', 'Panas sekali hingga aku hampir meleleh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47ca7c79-661a-438a-a409-d8f0cab0594b', '日本では、このところ暑い日がつづいています。', 'Akhir-akhir ini cuaca di Jepang panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47ca7c79-661a-438a-a409-d8f0cab0594b', 'クソ暑いし蒸し蒸しするしたまんねぇな！この暑さでは寝られないよ。プールに行こうぜ！', 'Terlalu panas dan lembab! Saya tidak bisa tidur dalam cuaca panas ini. Ayo pergi ke kolam renang!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('557567fa-4386-40fd-93e1-3f858d34f645', 'vocabulary', '短刀', '短刀', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Pedang pendek adalah pedang pendek. Apa kata lain dari pedang pendek? Itu belati.', 'Pedang pendek adalah pedang pendek. Apa kata lain dari pedang pendek? Itu belati.') ON CONFLICT (id) DO NOTHING;
