INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('557567fa-4386-40fd-93e1-3f858d34f645', 'その短刀、どこで買ったの？', 'Tantonya beli dimana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('557567fa-4386-40fd-93e1-3f858d34f645', 'ビエトは、短刀を使ってとても上手にりょう理をします。', 'Viet memasak dengan sangat baik dengan pedang pendek.') ON CONFLICT DO NOTHING;
