INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1fe2b14e-621d-4b3e-b58f-01781a1a2394', 'vocabulary', '器', '器', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain itu, Anda juga bisa menyebutnya mangkuk, jika mau.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain itu, Anda juga bisa menyebutnya mangkuk, jika mau.') ON CONFLICT (id) DO NOTHING;
