INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1f5a50c-3efd-45c5-ba7e-ce13b3c5af39', 'きよう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1f5a50c-3efd-45c5-ba7e-ce13b3c5af39', 'コウイチは手先がとても器用です。', 'Koichi sangat cekatan dengan jari-jarinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1f5a50c-3efd-45c5-ba7e-ce13b3c5af39', 'ビエトはワニカニの着ぐるみを着たまま、器用にコカ・コーラを飲んだ。', 'Viet dengan lihai meminum coca cola sambil mengenakan pakaian maskot WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1f5a50c-3efd-45c5-ba7e-ce13b3c5af39', '彼女はいつも明るくて良い子なんだけど、あまり器用じゃないので、首にしようか迷ってるんです。', 'Dia selalu menjadi gadis yang ceria dan menyenangkan, tetapi dia tidak terlalu ahli dalam menggunakan tangannya, jadi aku bertanya-tanya apakah aku harus memecatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45f90b71-1770-454f-beb8-4c0c605fb947', 'vocabulary', '楽器', '楽器', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ingat bagaimana 楽 digunakan dalam 音楽 dan berarti "musik"? Nah ini dia 楽 lagi. Wadah musik adalah sesuatu yang dapat menghasilkan musik. Itu adalah alat musik.', 'Ingat bagaimana 楽 digunakan dalam 音楽 dan berarti "musik"? Nah ini dia 楽 lagi. Wadah musik adalah sesuatu yang dapat menghasilkan musik. Itu adalah alat musik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('45f90b71-1770-454f-beb8-4c0c605fb947', 'Alat Musik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('45f90b71-1770-454f-beb8-4c0c605fb947', 'がっき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45f90b71-1770-454f-beb8-4c0c605fb947', '楽器にも色々ありますが、どんな楽器が好きですか。私は打楽器が好きです。', 'Ada berbagai macam jenis alat musik. Tipe mana yang kamu suka? Saya suka perkusi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45f90b71-1770-454f-beb8-4c0c605fb947', 'まずは楽器を楽ふ通りにえんそうしてみてください。', 'Silakan mulai dengan mencoba memainkan not instrumen Anda demi not.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45f90b71-1770-454f-beb8-4c0c605fb947', '「あなたのCDを持ってくるのを忘れてしまったわ。」「別にいいよ、またの機会で。でも、その代わりにBGMとして何か楽器を弾いてくれない。」', '"Aku lupa membawa CDmu." "Tidak apa-apa. Saya bisa mendapatkannya lain kali, tapi bisakah Anda memainkan alat musik sebagai musik latar?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('80a93461-49a1-463c-84fb-23ebb5a17175', 'vocabulary', '食器', '食器', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Wadah makan yang Anda maksud adalah peralatan makan, termasuk peralatan makan, seperti pisau, garpu, sendok, dan sumpit, serta peralatan penyajian, seperti piring, mangkok, dan tatakan. Pada dasarnya, itu adalah bahan yang Anda gunakan untuk memakan makanan Anda.', 'Wadah makan yang Anda maksud adalah peralatan makan, termasuk peralatan makan, seperti pisau, garpu, sendok, dan sumpit, serta peralatan penyajian, seperti piring, mangkok, dan tatakan. Pada dasarnya, itu adalah bahan yang Anda gunakan untuk memakan makanan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('80a93461-49a1-463c-84fb-23ebb5a17175', 'Peralatan makan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('80a93461-49a1-463c-84fb-23ebb5a17175', 'Eating Utensils', false) ON CONFLICT DO NOTHING;
