INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('196f8b0a-eecc-4dbd-9db2-5e38eb628051', '川村さんの人生の目標はなんですか。', 'Tuan Kawamura, apa tujuan hidup Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('196f8b0a-eecc-4dbd-9db2-5e38eb628051', '五十メートル先の目標に向かって矢を放ちました。', 'Saya menembakkan panah ke arah target 50m di depan saya.') ON CONFLICT DO NOTHING;
