INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c78fa589-8d1e-44fa-8b9a-e4ae52ded47c', 'vocabulary', '詩', '詩', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
