INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c78fa589-8d1e-44fa-8b9a-e4ae52ded47c', '詩が大好きで、毎日詩を読んでいます。', 'Saya sangat menyukai puisi, jadi saya membacanya setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c78fa589-8d1e-44fa-8b9a-e4ae52ded47c', 'わたしの心のやみを詩で表げんしてみたんだけど、ちょっと読んでみてくれない？', 'Aku mengungkapkan kegelapan pikiranku dalam sebuah puisi. Bisakah kamu melihatnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c78fa589-8d1e-44fa-8b9a-e4ae52ded47c', '今日の宿題は、日本語で詩を書くことです。', 'Pekerjaan rumah hari ini adalah menulis puisi dalam bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26227e36-af3a-4e06-97ba-0a53b71bd86d', 'vocabulary', '詩人', '詩人', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Orang yang menulis puisi adalah seorang penyair.', 'Orang yang menulis puisi adalah seorang penyair.') ON CONFLICT (id) DO NOTHING;
