INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4a3edf7-0c05-4638-afc9-ff84dc189dba', 'ワニカニがトーフグを養っているの？それともトーフグがワニカニを養っているの？', 'WaniKani menumbuhkan Tofugu atau Tofugu menumbuhkan WaniKani?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4a3edf7-0c05-4638-afc9-ff84dc189dba', 'コウイチのにんじゅつにだまされない目を養う必要があります。', 'Kita harus tetap waspada agar tidak tertipu oleh ninjutsu Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a4a3edf7-0c05-4638-afc9-ff84dc189dba', 'たまにはご主人にも感謝しろよ。あいつだって、立派に家族を養ってきたじゃないか。', 'Terkadang kamu harus berterima kasih pada suamimu. Dia telah melakukan pekerjaan yang baik dalam membesarkan keluargamu, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7c71e274-1858-4952-90df-11f1c5cfa0e1', 'vocabulary', '養子', '養子', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Anak angkat yang Anda bawa ke dalam keluarga Anda adalah anak angkat Anda.', 'Anak angkat yang Anda bawa ke dalam keluarga Anda adalah anak angkat Anda.') ON CONFLICT (id) DO NOTHING;
