INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c71e274-1858-4952-90df-11f1c5cfa0e1', 'あの駅長の子は、どうやら養子らしいです。', 'Kudengar anak kepala stasiun sebenarnya adalah anak angkat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c71e274-1858-4952-90df-11f1c5cfa0e1', 'わたしの友人は九月に養子をむかえいれることにした。', 'Teman saya memutuskan untuk mengadopsi anak pada bulan September.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c71e274-1858-4952-90df-11f1c5cfa0e1', '養子の態度が悪いから、叱ってやったんだ。', 'Saya memarahi anak angkat saya karena sikapnya yang buruk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69fdd8f7-48bd-4ff4-916d-20930e0957e4', 'vocabulary', '雰囲気', '雰囲気', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Energi yang mengelilingi atmosfer inilah yang membentuk atmosfer. Saya suka ketika dibutuhkan tiga kanji untuk mewakili apa yang sudah diwakili oleh salah satu dari tiga kanji.', 'Energi yang mengelilingi atmosfer inilah yang membentuk atmosfer. Saya suka ketika dibutuhkan tiga kanji untuk mewakili apa yang sudah diwakili oleh salah satu dari tiga kanji.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('69fdd8f7-48bd-4ff4-916d-20930e0957e4', 'Suasana', true) ON CONFLICT DO NOTHING;
