INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8cfe2609-ba02-4f74-9b00-36cf7e3c5998', 'じょうし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8cfe2609-ba02-4f74-9b00-36cf7e3c5998', 'その上司のコートは、とても丈夫な生地で出来ていました。', 'Jas bos itu terbuat dari bahan yang sangat awet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8cfe2609-ba02-4f74-9b00-36cf7e3c5998', 'うちの上司は、日本のれきしに大変きょう味があるようです。', 'Tampaknya atasan saya sangat tertarik dengan sejarah Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8cfe2609-ba02-4f74-9b00-36cf7e3c5998', 'シャークがあなたのこと、名ばかりの上司だと言ってましたよ。', 'Shark mengatakan kamu adalah bos hanya dalam nama saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('48b05c74-8f27-488e-9f93-dacae336321f', 'vocabulary', '泣く', '泣く', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menangis jadi versi vocab verbanya adalah menangis.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menangis jadi versi vocab verbanya adalah menangis.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('48b05c74-8f27-488e-9f93-dacae336321f', 'Menangis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('48b05c74-8f27-488e-9f93-dacae336321f', 'なく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48b05c74-8f27-488e-9f93-dacae336321f', 'ヤバイ。うれしすぎて、泣きそう。', 'Aduh. Aku sangat senang hingga aku hampir menangis!!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48b05c74-8f27-488e-9f93-dacae336321f', '情けないことに、晴れのぶ台で泣いてしまった。', 'Sungguh memalukan kalau saya menangis di atas panggung di depan umum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48b05c74-8f27-488e-9f93-dacae336321f', '減給になっちゃって泣いてます。もっと給料のいい会社に移りたいよ。', 'Saya menangis karena gaji saya dipotong. Saya ingin pindah ke pekerjaan dengan gaji lebih tinggi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bc3f10ff-4645-4e03-b0a1-6aecb1e4bf17', 'vocabulary', '世紀', '世紀', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kisah satu generasi... ini mencakup seluruh generasi, dan mengingat berapa lama orang Jepang hidup, total kisah ini adalah satu abad penuh.', 'Kisah satu generasi... ini mencakup seluruh generasi, dan mengingat berapa lama orang Jepang hidup, total kisah ini adalah satu abad penuh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bc3f10ff-4645-4e03-b0a1-6aecb1e4bf17', 'Abad', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bc3f10ff-4645-4e03-b0a1-6aecb1e4bf17', 'せいき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc3f10ff-4645-4e03-b0a1-6aecb1e4bf17', '「今って何世紀だっけ？」「二十一世紀だよ。」', '“Sekarang abad berapa?” “Ini abad ke-21.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc3f10ff-4645-4e03-b0a1-6aecb1e4bf17', 'コウイチは少なくとも一世紀は生きたいと思っている。', 'Koichi ingin hidup setidaknya satu abad.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc3f10ff-4645-4e03-b0a1-6aecb1e4bf17', 'あいにく、その日のスケジュールは少しきついですね。今世紀最大の日本語学習祭り関連の会議がいくつか入っているんですよ。', 'Saya khawatir jadwal saya sedikit padat hari itu. Saya mengadakan beberapa pertemuan terkait dengan festival pembelajaran bahasa Jepang, yang akan menjadi festival terbesar abad ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'vocabulary', '紀元後', '紀元後', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Apa asal muasal narasi setelahnya? Nah, cara kita menghitung tahun selama beberapa milenium terakhir memiliki narasi spesifik pada asal usulnya, dan segala sesuatu yang terjadi setelahnya adalah Masehi, alias Masehi, atau anno Domini.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'Era Umum', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'CE', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'Anno Domini', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'AD', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'きげんご', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', '紀元後64年にローマで大火事が発生したのを知っていますか？', 'Tahukah Anda bahwa pada tahun 64 M terjadi kebakaran besar di Roma?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'パピルスは紀元後10世紀ぐらいまで使われていた。', 'Papirus digunakan sampai sekitar abad ke-10 M') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('692c8a7e-c842-4826-baf8-43d6e0d6b10b', 'え、こないだ会った時より日本語めっちゃ上手になってない？紀元前と紀元後くらいちがうじゃん。', 'Oh, bahasa Jepangmu jauh lebih baik dibandingkan terakhir kali kita bertemu, bukan? Ini seperti dua era yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e0be06c4-b6bc-4ca9-8a7f-42b3865ef527', 'vocabulary', '仮面', '仮面', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Wajah sementara adalah sesuatu yang Anda tempelkan pada wajah Anda untuk menutupinya. Itu topeng.', 'Wajah sementara adalah sesuatu yang Anda tempelkan pada wajah Anda untuk menutupinya. Itu topeng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e0be06c4-b6bc-4ca9-8a7f-42b3865ef527', 'Masker', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e0be06c4-b6bc-4ca9-8a7f-42b3865ef527', 'かめん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0be06c4-b6bc-4ca9-8a7f-42b3865ef527', 'ハロウィンの日の夜、仮面ライダーのコスプレをしながら、チョコレートを一箱平らげたビエトを見ました。', 'Pada malam Halloween, saya melihat Viet mengenakan kostum Masked Rider dan memakan sekotak coklat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0be06c4-b6bc-4ca9-8a7f-42b3865ef527', 'わぁ、びっくりした！何で仮面なんてかぶってるの？', 'Ah, kamu mengagetkanku! Kenapa kamu memakai topeng itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0be06c4-b6bc-4ca9-8a7f-42b3865ef527', 'ヴェネツィアの仮面舞踏会に行って白馬の王子様に会うことが私の夢です。', 'Impianku adalah pergi ke pesta topeng di Venesia dan bertemu dengan seorang ksatria berkuda putih.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8e047cd4-a91b-419e-a77b-1fc8f9187a22', 'vocabulary', '保守的', '保守的', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Siapa yang semua seperti "Saya ingin melestarikan dan melindungi apa yang saya miliki, keluar dari bisnis saya, pemerintah!"? Tentu saja, orang-orang konservatif.', 'Siapa yang semua seperti "Saya ingin melestarikan dan melindungi apa yang saya miliki, keluar dari bisnis saya, pemerintah!"? Tentu saja, orang-orang konservatif.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8e047cd4-a91b-419e-a77b-1fc8f9187a22', 'Konservatif', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8e047cd4-a91b-419e-a77b-1fc8f9187a22', 'ほしゅてき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e047cd4-a91b-419e-a77b-1fc8f9187a22', '保守的な学校だったので、学生はみんな校そく通りにせい服を着用するよう要求されました。', 'Sekolah saya sangat konservatif, sehingga siswanya diwajibkan mengenakan seragam sesuai dengan peraturan sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e047cd4-a91b-419e-a77b-1fc8f9187a22', '日本国民は、保守的な国民だと思いますか？', 'Apakah menurut Anda orang Jepang adalah orang yang konservatif?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e047cd4-a91b-419e-a77b-1fc8f9187a22', 'コウイチはビエトに、年をとるにつれて保守的になる人が多いけど、俺はそうはなりたくない、と言った。', 'Koichi mengatakan kepada Viet bahwa orang-orang cenderung menjadi lebih konservatif seiring bertambahnya usia, namun dia tidak ingin menjadi seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', 'vocabulary', '保存', '保存', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kami berusaha melestarikan apa pun yang kami inginkan dengan pelestarian. Ingin makhluk laut atau burung istimewa ada? Tingkatkan upaya konservasi! Dan, jika Anda ingin menyimpan data (seperti di komputer), Anda juga dapat menggunakan kata ini untuk penyimpanan semacam itu.', 'Kami berusaha melestarikan apa pun yang kami inginkan dengan pelestarian. Ingin makhluk laut atau burung istimewa ada? Tingkatkan upaya konservasi! Dan, jika Anda ingin menyimpan data (seperti di komputer), Anda juga dapat menggunakan kata ini untuk penyimpanan semacam itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', 'Pelestarian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', 'Conservation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', 'Saving', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', 'ほぞん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', 'コウイチのデスクのかぎのかかった引き出しに、重要文書が保存されています。', 'Dokumen penting disimpan di laci meja Koichi yang terkunci.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', '母乳は、れいとうすれば保存がききます。', 'ASI bisa awet jika dibekukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebb5791b-717a-4f24-ba85-a95bb553f39e', '「このベーコンは、着色保存料を一切使用しておりません。」「ってことは、本当のベーコンではありませんね。」', '"Bacon ini tidak mengandung pewarna makanan atau pengawet." "Yah, kalau begitu, itu sebenarnya bukan bacon."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'vocabulary', '保持', '保持', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ketika Anda memegang dan melestarikan sesuatu, Anda sedang melakukan tindakan retensi atau pemeliharaan terhadapnya. Ini adalah pelestarian.', 'Ketika Anda memegang dan melestarikan sesuatu, Anda sedang melakukan tindakan retensi atau pemeliharaan terhadapnya. Ini adalah pelestarian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'Retensi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'Maintenance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'Preservation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'ほじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'コウイチは何かの世界記録保持者だと聞きました。', 'Kudengar Koichi adalah pemegang rekor dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'かくへい器の保持についてどうお考えですか？', 'Apa pendapat Anda tentang retensi senjata nuklir?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c9b0b9cd-b4fc-4445-abf0-c1f55715cabf', 'トーフグは、火星の治安を保持することに、微力ながら貢献したいと思います。', 'Tofugu akan menyumbangkan upaya sederhana kami untuk menjaga perdamaian Mars.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1191b8e9-b681-4f8c-a9a4-c5477b99e925', 'vocabulary', '保険', '保険', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ketika Anda dapat menjamin terhadap risiko, itu mungkin karena Anda membeli asuransi yang bagus! Apa yang kamu gunakan? Tokek 保険?', 'Ketika Anda dapat menjamin terhadap risiko, itu mungkin karena Anda membeli asuransi yang bagus! Apa yang kamu gunakan? Tokek 保険?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1191b8e9-b681-4f8c-a9a4-c5477b99e925', 'Asuransi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1191b8e9-b681-4f8c-a9a4-c5477b99e925', 'ほけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1191b8e9-b681-4f8c-a9a4-c5477b99e925', 'どうして日本では、女性が保険の外交をすることが多いんですか？', 'Mengapa perempuan lebih umum melakukan penjualan asuransi di Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1191b8e9-b681-4f8c-a9a4-c5477b99e925', '保険にか入するのに、出生証明書は必要ですか？', 'Apakah saya memerlukan akta kelahiran untuk mendapatkan asuransi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1191b8e9-b681-4f8c-a9a4-c5477b99e925', 'しまった。また家に健康保険証を忘れてきちゃった。', 'Oh tidak, kartu asuransi kesehatan saya tertinggal lagi di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('24662347-f522-4fec-8025-753d85703815', 'vocabulary', '生保', '生保', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Jaminan Hidup adalah sesuatu yang Anda dapatkan dari orang lain. Jika nyawa mereka berakhir, dijamin dengan uang. Itu polis asuransi jiwa ya! (A.K.A. jaminan hidup di beberapa belahan dunia!)', 'Jaminan Hidup adalah sesuatu yang Anda dapatkan dari orang lain. Jika nyawa mereka berakhir, dijamin dengan uang. Itu polis asuransi jiwa ya! (A.K.A. jaminan hidup di beberapa belahan dunia!)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('24662347-f522-4fec-8025-753d85703815', 'Asuransi Jiwa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('24662347-f522-4fec-8025-753d85703815', 'せいほ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24662347-f522-4fec-8025-753d85703815', '生保はもちろんつみ立てですよね？', 'Tentu saja asuransi jiwa Anda berjenis cadangan bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24662347-f522-4fec-8025-753d85703815', '日本ではけんこう保険のせい度が整っているんだから、わざわざ生保に入る必要はあまりないよ。', 'Di Jepang, sistem asuransi kesehatan bersifat all-inclusive, sehingga Anda tidak perlu membeli asuransi jiwa secara terpisah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24662347-f522-4fec-8025-753d85703815', '日本では、女性の生命保険販売員は「生保レディ」と呼ばれます。', 'Penjual asuransi jiwa disebut "wanita seiho" di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'vocabulary', '保つ', '保つ', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti melestarikan dan versi vocab verbanya adalah melestarikan sesuatu, menjaga sesuatu, atau memelihara sesuatu.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'Untuk Melestarikan Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'To Keep Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'To Maintain Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'たもつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'わかさを保つひけつは何ですか？', 'Apa rahasia melestarikan masa muda Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'ビエトのおかげで、コウイチはメンツを保つことができた。', 'Berkat Viet, Koichi mampu menjaga mukanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b407629f-8d68-49cd-8b2e-96a7ac57627f', 'あのお医者さんに、「体調を保つためには、日々の運動が大切だよ」なんて言われたけど、そのお医者さん自体がすっごく太ってるんだよね。', 'Dokter memberi tahu saya bahwa penting untuk berolahraga secara teratur untuk menjaga kesehatan fisik, tetapi dia sangat gemuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('089fedd0-01a5-4d3e-828d-be9f49631471', 'vocabulary', '古典的', '古典的', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Jika ada sesuatu yang "seperti aturan lama", maka itu tidak terlalu modern. Itu terjadi di masa lalu. Itu klasik.', 'Jika ada sesuatu yang "seperti aturan lama", maka itu tidak terlalu modern. Itu terjadi di masa lalu. Itu klasik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('089fedd0-01a5-4d3e-828d-be9f49631471', 'Klasik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('089fedd0-01a5-4d3e-828d-be9f49631471', 'こてんてき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('089fedd0-01a5-4d3e-828d-be9f49631471', 'コウイチは写真で古典的なポーズをとるのが好きなようだね。', 'Koichi sepertinya suka mengambil pose klasik dalam foto.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('089fedd0-01a5-4d3e-828d-be9f49631471', 'こんな古典的なさぎに引っかかってしまって、本当に情けないです。', 'Sangat memalukan bahwa saya tertipu oleh penipuan klasik seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('089fedd0-01a5-4d3e-828d-be9f49631471', 'あの日本の古典的なスタイルの画家は、私が知っている人の中で、一番好みがうるさいです。どうしてそんなに色々気にするのか理解不能です。', 'Pelukis Jepang bergaya klasik itu adalah orang paling pemilih yang saya kenal. Saya tidak mengerti mengapa dia begitu peduli.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', 'vocabulary', '仏典', '仏典', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Aturan Buddha adalah aturan yang dibuat Buddha untuk umat Buddha. Hal ini dapat ditemukan dalam Kitab Suci Buddha dan Tulisan Buddha.', 'Aturan Buddha adalah aturan yang dibuat Buddha untuk umat Buddha. Hal ini dapat ditemukan dalam Kitab Suci Buddha dan Tulisan Buddha.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', 'Kitab Suci Buddha', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', 'Buddhist Writing', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', 'ぶってん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', 'その仏典はこの箱の中にしまってもらえますか？', 'Bisakah Anda memasukkan kitab suci Buddha ke dalam kotak ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', 'こんざつ時は、ゆずり合って仏典をご利用ください。', 'Selama jam sibuk, harap mempertimbangkan orang lain yang menunggu untuk menggunakan tulisan Buddha.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bdca300d-2855-40e7-8ff6-4b1341ee43f6', '仏典がどのようにしてサンスクリット語から漢語に訳されたのかご存じですか？', 'Tahukah Anda bagaimana kitab Buddha diterjemahkan dari bahasa Sanskerta ke bahasa Mandarin?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'vocabulary', '字典', '字典', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Aturan huruf dapat ditemukan di kamus karakter. Dalam bahasa Jepang, satu "huruf" atau "karakter" kanji dapat menyimpan banyak informasi, jadi Anda memiliki kamus yang didedikasikan untuk arti kanji. Itulah yang terjadi.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'Kamus Karakter', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'Kanji Dictionary', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'じてん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'コウイチは、ぬれた字典について、ビエトにせつ明を要求しました。', 'Koichi meminta penjelasan tentang kamus karakter basah dari Viet.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'とつ然大雨になったので、手でもっていた字典がびしょぬれになっちゃったんです。', 'Tiba-tiba hujan mulai turun dan kamus kanji yang saya pegang basah kuyup.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a8556985-923a-4836-9d91-d27b398cf1d4', 'この書道字典はあそこの古本屋で買ったんです。', 'Kamus karakter kaligrafi ini saya beli di toko buku bekas di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e49b289e-7d56-45e0-9b63-3d7a91f12caf', 'vocabulary', '事典', '事典', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Sesuatu yang berisi aturan berbagai tindakan adalah sesuatu yang mengandung segudang ilmu. Itu berisi semua hal dan tindakan, bukan? "Benda" macam apa yang berisi semua informasi ini (yang ada selama penciptaan kata dan kanji?)? Satu hal adalah ensiklopedia.', 'Sesuatu yang berisi aturan berbagai tindakan adalah sesuatu yang mengandung segudang ilmu. Itu berisi semua hal dan tindakan, bukan? "Benda" macam apa yang berisi semua informasi ini (yang ada selama penciptaan kata dan kanji?)? Satu hal adalah ensiklopedia.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e49b289e-7d56-45e0-9b63-3d7a91f12caf', 'Ensiklopedia', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e49b289e-7d56-45e0-9b63-3d7a91f12caf', 'じてん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e49b289e-7d56-45e0-9b63-3d7a91f12caf', 'コウイチなら、サンルームの日光浴用のイスで事典とにらめっこしていますよ。', 'Jika Anda mencari Koichi, dia sedang menatap ensiklopedia di kursi santai di ruang berjemur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e49b289e-7d56-45e0-9b63-3d7a91f12caf', 'あなたが事典を万引きしたしゅん間がカメラに映っているんですよ。', 'Kamera menunjukkan bahwa Anda mengutil sebuah ensiklopedia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e49b289e-7d56-45e0-9b63-3d7a91f12caf', '本としてはちょっと大きすぎたので、私は百科事典を枕として使っていました。', 'Saya menggunakan ensiklopedia saya sebagai bantal karena terlalu besar untuk dijadikan sebuah buku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', 'vocabulary', '不器用', '不器用', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Anda tahu bagaimana 器用 berarti "cekatan" dan "terampil"? Nah, inilah saatnya Anda tidak seperti itu. Bila Anda tidak tangkas, Anda kikuk dan bila Anda tidak terampil, Anda tidak terampil.', 'Anda tahu bagaimana 器用 berarti "cekatan" dan "terampil"? Nah, inilah saatnya Anda tidak seperti itu. Bila Anda tidak tangkas, Anda kikuk dan bila Anda tidak terampil, Anda tidak terampil.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', 'Kikuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', 'Unskillful', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', 'Awkward', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', 'ぶきよう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', 'ぶきっちょ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', '十代は、不器用な私にとって、とても大変な時期でした。', 'Masa remaja saya adalah tahun-tahun tersulit bagi orang canggung seperti saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', '不器用な助手が、不器用な手つきで、いつものようにクソ不味いコーヒーをいれてくれた。', 'Asisten saya yang canggung membuat kopi yang sangat menjijikkan dengan tangannya yang canggung, seperti biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c5051d4-293a-40da-874c-5aa010b73093', '私の主人は堅苦しくて不器用ですが、正直者です。', 'Suamiku tegas dan kikuk, tapi dia orang yang jujur.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('31541a42-b6f9-443a-bbfd-26a58801a6ce', 'vocabulary', '整理する', '整理する', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ketika Anda mengatur sesuatu dengan alasan, Anda sedang mengaturnya. Itu sebabnya ini harus diatur.', 'Ketika Anda mengatur sesuatu dengan alasan, Anda sedang mengaturnya. Itu sebabnya ini harus diatur.') ON CONFLICT (id) DO NOTHING;
