INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3e68b4ec-4900-4c08-b1d8-026e3ff4b28d', 'このアパートの住民の部屋はみんなきちんと整理されています。', 'Kamar-kamar penghuni apartemen ini semuanya tertata rapi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3e68b4ec-4900-4c08-b1d8-026e3ff4b28d', '整理整とんすることは大切です。', 'Mengorganisir dengan baik itu penting.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3e68b4ec-4900-4c08-b1d8-026e3ff4b28d', '修学旅行で撮った写真を整理しました。', 'Saya mengatur foto-foto dari karyawisata saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4f8636e8-2e7f-4b60-909e-0fb5804739ba', 'vocabulary', '基本的', '基本的', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Hal-hal yang mendasar (基本) seperti (的) bersifat mendasar dan mendasar.', 'Hal-hal yang mendasar (基本) seperti (的) bersifat mendasar dan mendasar.') ON CONFLICT (id) DO NOTHING;
