INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4f8636e8-2e7f-4b60-909e-0fb5804739ba', 'きほんてき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f8636e8-2e7f-4b60-909e-0fb5804739ba', '基本的に政治に関心がないんです。', 'Pada dasarnya, saya tidak tertarik pada politik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f8636e8-2e7f-4b60-909e-0fb5804739ba', '上司に、基本的な事も知らない役立たずだと言われました。', 'Saya diberitahu oleh atasan saya bahwa saya bahkan tidak mengetahui dasar-dasarnya dan saya tidak berguna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f8636e8-2e7f-4b60-909e-0fb5804739ba', 'どのくらい頻繁に自分の超基本的な間違いにびっくりしますか？', 'Seberapa sering Anda terkejut ketika melakukan kesalahan mendasar?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1941f83f-7d36-4e7f-905e-dc5004d3fb39', 'vocabulary', '妥協する', '妥協する', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Anda tahu bahwa 妥協 berarti kompromi. Jadi, apa yang terjadi jika Anda menjadikannya kata kerja? Ini menjadi kompromi.', 'Anda tahu bahwa 妥協 berarti kompromi. Jadi, apa yang terjadi jika Anda menjadikannya kata kerja? Ini menjadi kompromi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1941f83f-7d36-4e7f-905e-dc5004d3fb39', 'Untuk Berkompromi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1941f83f-7d36-4e7f-905e-dc5004d3fb39', 'だきょうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1941f83f-7d36-4e7f-905e-dc5004d3fb39', '十万円で妥協しました。', 'Kami berkompromi dengan 100.000 yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1941f83f-7d36-4e7f-905e-dc5004d3fb39', 'コウイチとビエトは、マクドナルドに行くことで妥協しました。', 'Koichi dan Viet berkompromi dengan pergi ke McDonald''s.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1941f83f-7d36-4e7f-905e-dc5004d3fb39', '「ねぇ、サーモン。あんたとフグが一緒に住み始めた時、やっぱり二人とも妥協しなきゃいけなかった？」「うーん。私はしなかったけど、フグはね！」', '"Hei Salmon, apakah kamu dan Fugu harus membuat kompromi saat pertama kali tinggal bersama?" "Yah, bukan aku, tapi Fugu yang melakukannya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', 'vocabulary', '妥協', '妥協', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ketika Anda memiliki kerja sama yang lembut, tidak ada orang yang bisa melakukan apa yang mereka inginkan. Anda dengan sangat hati-hati mendekati titik tengah, mencapai kompromi. (Suka atau tidak.)', 'Ketika Anda memiliki kerja sama yang lembut, tidak ada orang yang bisa melakukan apa yang mereka inginkan. Anda dengan sangat hati-hati mendekati titik tengah, mencapai kompromi. (Suka atau tidak.)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', 'Kompromi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', 'Giving In', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', 'だきょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', '妥協したくないの。', 'Aku tidak mau menyerah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', 'うまく妥協することができなくて、ちょっとせい神的に参っちゃったんだよね。', 'Saya tidak bisa berkompromi dengan baik dan semuanya berantakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e8ef543-29c5-48ef-9ce7-8c6c5172be72', 'この仕事に、妥協は許されないよ。', 'Dalam pekerjaan ini, kompromi tidak diperbolehkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'vocabulary', '紀元前', '紀元前', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ingat bagaimana 紀元後 adalah "Common Era", atau "anno Domini"? Ini kebalikannya karena ada sebelum (前), bukan 後. Itu Sebelum Masehi atau Sebelum Masehi.', 'Ingat bagaimana 紀元後 adalah "Common Era", atau "anno Domini"? Ini kebalikannya karena ada sebelum (前), bukan 後. Itu Sebelum Masehi atau Sebelum Masehi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'Sebelum Masehi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'BCE', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'Before Christ', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'BC', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'きげんぜん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'きょうりゅうがいたのは、紀元前何年ごろまでですか。', 'Sampai kira-kira tahun berapa sebelum Masehi dinosaurus ada?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', '今日のコウイチは、自分は紀元前の古代ローマからタイムスリップしてきた男だって言いはってきかないんです。', 'Kochi ini terus bersikeras bahwa dia adalah seorang pria yang melakukan perjalanan waktu dari Roma Kuno.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9173bdb-a3b5-49b2-8067-59133adf36f2', 'もしタイムマシーンがあったなら、紀元前三千年紀に行ってみたいな。', 'Jika mesin waktu ada, saya ingin pergi ke 3000 SM.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8128b93a-638c-40a0-8ca6-82f9309bd740', 'vocabulary', '泣き虫', '泣き虫', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Anda pernah melihat bahwa 泣く berarti menangis, jadi Anda mungkin bisa menebak bahwa 泣き hanyalah "menangis". Anda juga telah melihat betapa jarangnya memanggil seseorang dengan 虫 merupakan hal yang menyenangkan. Jadi, apa sebutan kejam yang bisa Anda berikan kepada seseorang yang menangis? Bagaimana dengan bayi cengeng?', 'Anda pernah melihat bahwa 泣く berarti menangis, jadi Anda mungkin bisa menebak bahwa 泣き hanyalah "menangis". Anda juga telah melihat betapa jarangnya memanggil seseorang dengan 虫 merupakan hal yang menyenangkan. Jadi, apa sebutan kejam yang bisa Anda berikan kepada seseorang yang menangis? Bagaimana dengan bayi cengeng?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8128b93a-638c-40a0-8ca6-82f9309bd740', 'Bayi cengeng', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8128b93a-638c-40a0-8ca6-82f9309bd740', 'なきむし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8128b93a-638c-40a0-8ca6-82f9309bd740', '泣き虫コウちゃーん、ほら、コウちゃんの好きなトンネルだよーっ！', 'Hei, Ko-chan yang cengeng. Ini dia terowongan yang kamu suka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8128b93a-638c-40a0-8ca6-82f9309bd740', 'コウイチだけがビエトが泣き虫だということを知っている。', 'Hanya Koichi yang tahu Viet itu cengeng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8128b93a-638c-40a0-8ca6-82f9309bd740', '娘の高熱が中々下がりません。普段は泣き虫なんですが、今は泣く元気も無いようで、心配です。', 'Demam tinggi putriku sepertinya tidak kunjung turun. Dia biasanya cengeng, tapi sepertinya dia bahkan tidak punya tenaga untuk menangis sekarang dan aku khawatir.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc4d1c96-aae1-4940-a3af-a53ecb8734e9', 'vocabulary', '泣き声', '泣き声', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Suara tangis adalah suara tangis atau isak tangis. Jangan menangis! Kanji akan menjadi lebih mudah suatu hari nanti!', 'Suara tangis adalah suara tangis atau isak tangis. Jangan menangis! Kanji akan menjadi lebih mudah suatu hari nanti!') ON CONFLICT (id) DO NOTHING;
