INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68a42663-4e8c-4823-be0b-dca7e9ae6c2e', '兵器使用の是非について語り合いました。', 'Kami berdiskusi apakah menggunakan senjata itu benar atau salah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68a42663-4e8c-4823-be0b-dca7e9ae6c2e', '化学兵器の研究室で働いていたことがあります。', 'Saya dulu bekerja di laboratorium senjata kimia.') ON CONFLICT DO NOTHING;
