INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4f993842-a1b4-42ae-a113-d6ddbecfdf23', 'vocabulary', '兵士', '兵士', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Seorang prajurit samurai tetaplah seorang prajurit biasa.', 'Seorang prajurit samurai tetaplah seorang prajurit biasa.') ON CONFLICT (id) DO NOTHING;
