INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f993842-a1b4-42ae-a113-d6ddbecfdf23', 'あの兵士の泣き声が頭からはなれません。', 'Aku tidak bisa menghilangkan teriakan prajurit itu dari kepalaku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f993842-a1b4-42ae-a113-d6ddbecfdf23', 'その兵士はコウイチの車に火を付けた。', 'Tentara itu membakar mobil Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f993842-a1b4-42ae-a113-d6ddbecfdf23', '仲間がいないといつもの道が遠く感じると思いながら、兵士は足早に歩いた。', 'Prajurit itu berjalan dengan langkah cepat memikirkan betapa jauhnya jarak terasa lebih lama tanpa pendamping.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5fe83f0b-6a7e-40d3-86c4-a4d551f9a55f', 'vocabulary', '仮説', '仮説', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Teori sementara bukanlah teori yang sudah pasti. Faktanya, ini sama sekali bukan teori, ini lebih merupakan hipotesis.', 'Teori sementara bukanlah teori yang sudah pasti. Faktanya, ini sama sekali bukan teori, ini lebih merupakan hipotesis.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5fe83f0b-6a7e-40d3-86c4-a4d551f9a55f', 'Hipotesis', true) ON CONFLICT DO NOTHING;
