INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf39d5b4-de7f-49b3-8c18-c562e8b86015', '私達は、製品の品質において、業界基準を大きく上回っています。', 'Kualitas produk kami jauh di atas standar industri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ca6c93c6-84ff-4740-b017-ddb172143acb', 'vocabulary', '典型的', '典型的', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Model aturan adalah model yang mengikuti semua aturan. Itu model yang normal. Itu tipikal.', 'Model aturan adalah model yang mengikuti semua aturan. Itu model yang normal. Itu tipikal.') ON CONFLICT (id) DO NOTHING;
