INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('376cd463-35c7-40a6-b493-4b31ebb13008', 'vocabulary', '武器', '武器', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Sebuah kontainer yang digunakan oleh militer kemungkinan besar akan digunakan sebagai senjata. Lagipula, itulah yang dilakukan militer... senjata.', 'Sebuah kontainer yang digunakan oleh militer kemungkinan besar akan digunakan sebagai senjata. Lagipula, itulah yang dilakukan militer... senjata.') ON CONFLICT (id) DO NOTHING;
