INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68506846-fc73-4503-bd0b-a60d513e71c0', 'vocabulary', '武士', '武士', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Seorang samurai militer adalah seorang samurai. Ini adalah bagaimana kebanyakan orang mengatakan "samurai" dalam bahasa Jepang.', 'Seorang samurai militer adalah seorang samurai. Ini adalah bagaimana kebanyakan orang mengatakan "samurai" dalam bahasa Jepang.') ON CONFLICT (id) DO NOTHING;
