INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68506846-fc73-4503-bd0b-a60d513e71c0', 'コウイチは武士のようにストイックに走り続け、フルマラソンを完走した。', 'Koichi terus berlari dengan tabah seperti seorang samurai dan menyelesaikan maraton penuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b07412d-a6cf-4743-af4e-b9544e7b547b', 'vocabulary', '第一印象', '第一印象', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Fenomena (第一) pertama adalah apa yang tersegel di kepala Anda. Ini adalah kesan pertama Anda terhadap sesuatu.', 'Fenomena (第一) pertama adalah apa yang tersegel di kepala Anda. Ini adalah kesan pertama Anda terhadap sesuatu.') ON CONFLICT (id) DO NOTHING;
