INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f687890d-a556-4791-a2d1-46204d2f45cd', 'vocabulary', '均整', '均整', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Segalanya setara dalam cara pengaturannya. Mereka memiliki simetri dan keseimbangan yang sempurna.', 'Segalanya setara dalam cara pengaturannya. Mereka memiliki simetri dan keseimbangan yang sempurna.') ON CONFLICT (id) DO NOTHING;
