INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('177ee893-5a1b-4216-9fec-3203b5d40e64', 'コウイチ：明日富士山に登るなんて、もう気が狂っちゃいそうだよ。 ビエト：分かる分かる。俺もめちゃくちゃ不安。', 'Koichi: Aku jadi takut untuk mendaki Gunung Fuji besok. Viet: Aku tahu, aku tahu. Itu membuatku takut juga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b07f4dc9-c772-4f91-bfcd-061e92e029cc', 'vocabulary', '功績', '功績', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Prestasi dan eksploitasi Anda adalah pencapaian Anda.', 'Prestasi dan eksploitasi Anda adalah pencapaian Anda.') ON CONFLICT (id) DO NOTHING;
