INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b07f4dc9-c772-4f91-bfcd-061e92e029cc', '成功が誰の功績かを判断するのは難しい。', 'Sulit untuk memutuskan siapa yang pantas mendapat pujian atas kesuksesannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('999d8e19-feaf-4565-ad9e-f428432b9622', 'vocabulary', '蒸し暑い', '蒸し暑い', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', '蒸れる berarti "menjadi lembab." Jadi, kalau cuacanya panas lembab, berarti cuacanya panas dan lembap (atau bisa dibilang lembab, karena biasanya berarti panas juga). Ini adalah kata yang berguna untuk musim panas di Jepang, karena Anda akan selalu mengeluh tentang hal ini.', '蒸れる berarti "menjadi lembab." Jadi, kalau cuacanya panas lembab, berarti cuacanya panas dan lembap (atau bisa dibilang lembab, karena biasanya berarti panas juga). Ini adalah kata yang berguna untuk musim panas di Jepang, karena Anda akan selalu mengeluh tentang hal ini.') ON CONFLICT (id) DO NOTHING;
