INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('999d8e19-feaf-4565-ad9e-f428432b9622', '今年の夏は絶対去年よりも蒸し暑いよね。', 'Musim panas kali ini jelas lebih lembap dibandingkan tahun lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f3cdf305-1614-4e0d-b22a-1c74ac6143d7', 'vocabulary', '彼氏', '彼氏', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'A he mister bukan hanya dia, tapi "mister he", dan mister dia adalah dia, pacarmu.', 'A he mister bukan hanya dia, tapi "mister he", dan mister dia adalah dia, pacarmu.') ON CONFLICT (id) DO NOTHING;
