INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('843b1072-8914-4c61-9d18-8c077317bb59', 'ぼくのかの女は、同じ町の二丁目にすんでいるミイコちゃんです。', 'Pacarku Miiko juga tinggal di 2-chome.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('843b1072-8914-4c61-9d18-8c077317bb59', 'その台風で、一丁目と二丁目がしん水してしまいました。', 'Topan membanjiri 1-chome dan 2-chome.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('843b1072-8914-4c61-9d18-8c077317bb59', 'この桃、三丁目の田中さんから頂いたの。', 'Saya mendapat buah persik ini dari Tanaka dari 3-chome.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('321485e7-96a5-4654-8c03-f37b3b9e4cb2', 'vocabulary', '片仮名', '片仮名', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kana satu sisi adalah katakana. Mungkin akan lebih mudah untuk melakukan pembacaan terlebih dahulu yang satu ini.', 'Kana satu sisi adalah katakana. Mungkin akan lebih mudah untuk melakukan pembacaan terlebih dahulu yang satu ini.') ON CONFLICT (id) DO NOTHING;
