INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2dba6e51-123b-47fb-a4a1-5dcc474b2794', 'vocabulary', '包丁', '包丁', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Bungkus jalan dan bawa pergi. Saya memotongnya dengan pisau dapur (jangan tanya kenapa kata ini berasal dari kanji ini). Bayangkan saja Anda menggunakan pisau dapur untuk memotong jalan sehingga Anda bisa membungkusnya dan membawanya pergi.', 'Bungkus jalan dan bawa pergi. Saya memotongnya dengan pisau dapur (jangan tanya kenapa kata ini berasal dari kanji ini). Bayangkan saja Anda menggunakan pisau dapur untuk memotong jalan sehingga Anda bisa membungkusnya dan membawanya pergi.') ON CONFLICT (id) DO NOTHING;
