INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0933775b-44c9-4f3d-93e1-b569131fb2d8', 'vocabulary', '加湿器', '加湿器', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Sebuah "wadah penambah kelembapan" adalah wadah yang menambah kelembapan pada udara. Itu pelembab udara.', 'Sebuah "wadah penambah kelembapan" adalah wadah yang menambah kelembapan pada udara. Itu pelembab udara.') ON CONFLICT (id) DO NOTHING;
