INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd13b958-b227-4f48-a648-6328f9a7017d', '毎月の鈍器代はいくらですか。', 'Berapa banyak yang Anda keluarkan untuk membeli senjata tumpul setiap bulan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25a99ada-924a-4198-b32b-f403d6d77173', 'vocabulary', '丁度いい', '丁度いい', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Jika 丁度 adalah "tepat", maka "sangat bagus" akan menjadi jumlah yang tepat, alias pas.', 'Jika 丁度 adalah "tepat", maka "sangat bagus" akan menjadi jumlah yang tepat, alias pas.') ON CONFLICT (id) DO NOTHING;
