INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d0694609-900a-495d-847a-3844e533bc9a', 'vocabulary', '保持する', '保持する', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ini adalah versi kata kerja 保持, dari dua tingkat yang lalu.', 'Ini adalah versi kata kerja 保持, dari dua tingkat yang lalu.') ON CONFLICT (id) DO NOTHING;
