INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8747e5c1-7b96-4496-8004-bc2bf8a54bb9', '医者から慰謝料をもらうというダジャレを作ったのは僕だ。', 'Sayalah yang melontarkan plesetan, "Saya mendapat ganti rugi dari dokter."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8747e5c1-7b96-4496-8004-bc2bf8a54bb9', 'これは僕の缶珈琲だぞ！', 'Ini kopi kalenganku!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('170fc0c6-bebe-4285-845c-a5a4fb45b003', 'vocabulary', '平仮名', '平仮名', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ingat bagaimana Anda mengetahui bahwa 仮名 berarti "kana?" Nah ini kana datar. Kana datar hanyalah hiragana.', 'Ingat bagaimana Anda mengetahui bahwa 仮名 berarti "kana?" Nah ini kana datar. Kana datar hanyalah hiragana.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('170fc0c6-bebe-4285-845c-a5a4fb45b003', 'Hiragana', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('170fc0c6-bebe-4285-845c-a5a4fb45b003', 'ひらがな', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('170fc0c6-bebe-4285-845c-a5a4fb45b003', '平仮名は読めるけど書けません。', 'Saya bisa membaca hiragana tetapi saya tidak bisa menulisnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('170fc0c6-bebe-4285-845c-a5a4fb45b003', '平仮名でかいていただけませんか？', 'Bisakah Anda menulisnya dalam hiragana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('170fc0c6-bebe-4285-845c-a5a4fb45b003', 'ビエトが、平仮名を五分で全部おぼえられるアプリを開発しました。', 'Viet mengembangkan sebuah aplikasi yang memungkinkan orang menghafal semua hiragana dalam lima menit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4ddd0ee2-9b92-47c0-aae5-a1f8d81a3868', 'vocabulary', '辞典', '辞典', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Anda perlu mengetahui aturan kata dari bahasa yang Anda pelajari, bukan? Maka Anda memerlukan kamus bagus yang dapat menjelaskan leksikonnya!', 'Anda perlu mengetahui aturan kata dari bahasa yang Anda pelajari, bukan? Maka Anda memerlukan kamus bagus yang dapat menjelaskan leksikonnya!') ON CONFLICT (id) DO NOTHING;
