INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ddd0ee2-9b92-47c0-aae5-a1f8d81a3868', 'その辞典、使い終わったらちゃんと箱の中にもどしておいてね。', 'Bisakah Anda mengembalikan kamus ke dalam kotaknya setelah Anda menggunakannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ddd0ee2-9b92-47c0-aae5-a1f8d81a3868', '電子辞書には色んな辞典が入っています。', 'Kamus elektronik mempunyai berbagai kamus di dalamnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ddd0ee2-9b92-47c0-aae5-a1f8d81a3868', '辞典の使い方が分かりません。', 'Saya tidak tahu cara menggunakan kamus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', 'vocabulary', '整える', '整える', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mengatur, dan versi verbanya juga berarti menyusun atau menertibkan. Hal ini berkaitan dengan meletakkan barang-barang pada tempatnya, membereskan urusan, atau bahkan menyiapkan perlengkapan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mengatur, dan versi verbanya juga berarti menyusun atau menertibkan. Hal ini berkaitan dengan meletakkan barang-barang pada tempatnya, membereskan urusan, atau bahkan menyiapkan perlengkapan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', 'Untuk Mengatur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', 'To Put In Order', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', 'ととのえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', 'ビエトは、口ひげが三角になるように毎日整えています。', 'Viet menata kumisnya menjadi segitiga setiap pagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', '父のそうぎの手はずは、兄が全て整えてくれました。', 'Kakak laki-laki saya membereskan segala sesuatunya mengenai pemakaman ayah kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85376ba3-f4c5-42bf-a0d5-2b75465fcbfb', 'ホルモンバランスを整える方法をご紹介致します。', 'Kami akan memperkenalkan Anda pada metode untuk mengatur keseimbangan hormon Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ace629fe-6ad2-4d6a-814d-3fd9c6030af7', 'vocabulary', '〜斤', '〜斤', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Ini memiliki 〜 untuk penghitung, jadi Anda bisa bertaruh ini memiliki arti penghitung roti yang sama dengan kanji.', 'Ini memiliki 〜 untuk penghitung, jadi Anda bisa bertaruh ini memiliki arti penghitung roti yang sama dengan kanji.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ace629fe-6ad2-4d6a-814d-3fd9c6030af7', 'Penghitung Roti', true) ON CONFLICT DO NOTHING;
