INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace629fe-6ad2-4d6a-814d-3fd9c6030af7', 'ストレスで4斤のパンを一気に食べてしまった。', 'Saya makan empat potong roti sekaligus karena stres.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace629fe-6ad2-4d6a-814d-3fd9c6030af7', '食パンを五斤買うなら、自分で焼いた方が安いよ。', 'Akan lebih murah untuk membuat roti sendiri jika Anda membeli lima potong roti tawar sekaligus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ace629fe-6ad2-4d6a-814d-3fd9c6030af7', '8斤のパンで、卵サンドが23個とツナサンドが23個できる予定だ。', 'Delapan potong roti akan menghasilkan dua puluh tiga sandwich telur dan dua puluh tiga sandwich tuna.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d2a54331-880f-4fe6-88ad-c97b23992b78', 'vocabulary', '一斤', '一斤', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Satu penghitung roti berarti menghitung satu potong roti.', 'Satu penghitung roti berarti menghitung satu potong roti.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d2a54331-880f-4fe6-88ad-c97b23992b78', 'Satu Roti', true) ON CONFLICT DO NOTHING;
