INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d2a54331-880f-4fe6-88ad-c97b23992b78', 'いっきん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d2a54331-880f-4fe6-88ad-c97b23992b78', '一斤のパンは6枚切りか8枚切りで売られていることが多い。', 'Roti sering kali dijual dalam potongan enam atau delapan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d2a54331-880f-4fe6-88ad-c97b23992b78', 'たった一斤のパンで給料日までを生き延びなければいけない。', 'Saya hanya perlu bertahan hidup dengan satu potong roti sampai hari gajian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d2a54331-880f-4fe6-88ad-c97b23992b78', '食パン一斤と、ニュテラがあれば生きていけるよ。', 'Saya bisa hidup dari sepotong roti dan sedikit Nutella.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('792a7db0-866b-4b3e-bf42-10529a74c6a0', 'vocabulary', '二斤', '二斤', 1, '14977908-2bf8-494d-a6f6-d2f7fb21ef92', 'Dua penghitung roti sedang menghitung dua potong roti.', 'Dua penghitung roti sedang menghitung dua potong roti.') ON CONFLICT (id) DO NOTHING;
