INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('792a7db0-866b-4b3e-bf42-10529a74c6a0', '二斤買えば100円もお得です。', 'Jika Anda membeli dua potong roti, harganya akan lebih murah 100 yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('792a7db0-866b-4b3e-bf42-10529a74c6a0', 'パンを二斤も焼いたのに、すぐに食べ切ってしまった。', 'Meskipun saya memanggang dua potong roti, kami menghabiskan semuanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('792a7db0-866b-4b3e-bf42-10529a74c6a0', '賞味期限が明後日だけど、二斤も食べきれるかな？', 'Apakah menurut Anda kita bisa menghabiskan dua potong roti ini meskipun masa berlakunya sudah habis lusa?') ON CONFLICT DO NOTHING;
