INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a6e827e2-1a00-4cec-9a67-76603b06054e', 'radical', '歩', 'walk', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Radikal ini sama dengan kanji. Artinya berjalan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a6e827e2-1a00-4cec-9a67-76603b06054e', 'Berjalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5d111c55-fe50-4c67-bd1d-06530491a8fa', 'radical', '句', 'paragraph', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda mengunci hal-hal yang keluar dari mulut Anda di penjara. Penjara kertas dan aturan. Kata-kata ini berubah menjadi paragraf yang terbentuk dengan baik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5d111c55-fe50-4c67-bd1d-06530491a8fa', 'Paragraf', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('6ba02c70-c35c-48b2-a025-6cc90e5a96d9', 'radical', '巛', 'flood', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Tiga garis yang membentuk radikal sungai ditarik ke satu arah. Ini adalah kekuatan air yang sangat besar yang bergerak ke kiri. Ini banjir! BERLARI!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6ba02c70-c35c-48b2-a025-6cc90e5a96d9', 'Banjir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5f2637a5-84bd-466f-b4d6-4c07b310862f', 'radical', '[explosion]', 'explosion', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Lihat energinya meledak keluar? Itu ledakan. Ledakan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f2637a5-84bd-466f-b4d6-4c07b310862f', 'Ledakan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2995129b-3a65-49ce-9eea-62309f41507d', 'radical', '兼', 'mona-lisa', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Radikal ini terlihat seperti kombinasi radikal kuas dan kanji kecantikan (美). Jadi, keindahan apa yang bisa kamu lukis dengan kuas? Yang paling terkenal mungkin adalah Mona Lisa.') ON CONFLICT (id) DO NOTHING;
