INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c35227ae-7cd2-4eae-a8cc-8e047fbcf1d2', 'ほしょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c35227ae-7cd2-4eae-a8cc-8e047fbcf1d2', '来年もどってきても、あなたのポジションがあるかは保証しませんよ。', 'Saya tidak dapat menjamin bahwa posisi Anda akan tetap ada ketika Anda kembali tahun depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c35227ae-7cd2-4eae-a8cc-8e047fbcf1d2', 'うまく組織を固められる保証はありませんよ。', 'Tidak ada jaminan saya bisa memperkuat organisasi dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c35227ae-7cd2-4eae-a8cc-8e047fbcf1d2', '私はワニカニのライフタイムメンバーですが、トーフグが五年後もあるなんて保証はないから本当にライフタイムでワニカニが使えるなんて思っていませんよ。', 'Saya adalah anggota WaniKani seumur hidup, tapi saya rasa saya tidak bisa menggunakannya seumur hidup, karena tidak ada jaminan bahwa Tofugu akan tetap ada dalam lima tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c373590-98ee-4393-916d-cde5adabd9f2', 'vocabulary', '冒険', '冒険', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda berani melakukan sesuatu yang berisiko. Saatnya berpetualang! Bayangkan diri Anda menantang diri sendiri untuk melakukan hal-hal yang berisiko. Apakah ini sebuah petualangan? Jika tidak, buatlah demikian!', 'Anda berani melakukan sesuatu yang berisiko. Saatnya berpetualang! Bayangkan diri Anda menantang diri sendiri untuk melakukan hal-hal yang berisiko. Apakah ini sebuah petualangan? Jika tidak, buatlah demikian!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6c373590-98ee-4393-916d-cde5adabd9f2', 'Petualangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6c373590-98ee-4393-916d-cde5adabd9f2', 'ぼうけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c373590-98ee-4393-916d-cde5adabd9f2', 'ビエトは仕事を残したまま、冒険に出かけた。', 'Viet meninggalkan pekerjaannya yang belum selesai dan melanjutkan petualangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c373590-98ee-4393-916d-cde5adabd9f2', '明日からの冒険のために、力を残しておいた方がいいよ。', 'Kita harus menyimpan energi untuk petualangan kita besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c373590-98ee-4393-916d-cde5adabd9f2', '私たち、ナイル川を遡るっていう冒険旅行をしたんだけど、彼氏が西ナイル熱にかかっちゃってさあ。未だに病院で入院してるんだよね。', 'Kami melakukan perjalanan petualangan menyusuri Sungai Nil, tetapi pacar saya tertular Virus West Nile dan dia masih di rumah sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1520cc7-69db-4bbe-acd8-3439a2999a5e', 'vocabulary', '冗談', '冗談', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Saat Anda mendiskusikan sesuatu yang berlebihan, Anda tidak serius, Anda hanya menceritakan lelucon.', 'Saat Anda mendiskusikan sesuatu yang berlebihan, Anda tidak serius, Anda hanya menceritakan lelucon.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1520cc7-69db-4bbe-acd8-3439a2999a5e', 'Lelucon', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a1520cc7-69db-4bbe-acd8-3439a2999a5e', 'じょうだん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1520cc7-69db-4bbe-acd8-3439a2999a5e', 'つまらない冗談に係わってるひまはないんだよ。', 'Saya tidak punya waktu untuk menyia-nyiakan lelucon bodoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1520cc7-69db-4bbe-acd8-3439a2999a5e', 'トーフグはポッドキャストで冗談ばかり言っているが、時々冗談の通じない人からいかりのメールをもらうことがあります。', 'Tofugu suka bercanda di podcastnya, tetapi terkadang mereka menerima email kemarahan dari orang yang tidak mengerti lelucon tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1520cc7-69db-4bbe-acd8-3439a2999a5e', '冗談はヤメてよ！何でフレンチレストランなんて行きたいの？私達の柄じゃないっしょ。飲めればどこでもいいじゃん？違う？', 'Berhentilah bercanda. Mengapa Anda ingin pergi ke restoran Prancis? Kita tidak boleh merusak pola kita. Jika kita hanya pergi minum, di mana pun tidak apa-apa, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('14913afb-c333-4518-969d-059592bca826', 'vocabulary', '弁当', '弁当', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Tahukah Anda bagaimana 弁 berarti dialek dan 当 berarti sukses? Yah, ini tidak akan banyak membantu Anda, karena ini berarti bento atau bekal makan siang. Namun kemungkinan besar Anda tahu kata "bento" dari bahasa Inggris. Jadi, jika kamu membaca kata ini (yang seharusnya bisa kamu baca), kamu bisa mengetahui bahwa itu adalah べんとう. Jika Anda melakukannya, Anda akan menyadari bahwa kata ini juga berarti bento!', 'Tahukah Anda bagaimana 弁 berarti dialek dan 当 berarti sukses? Yah, ini tidak akan banyak membantu Anda, karena ini berarti bento atau bekal makan siang. Namun kemungkinan besar Anda tahu kata "bento" dari bahasa Inggris. Jadi, jika kamu membaca kata ini (yang seharusnya bisa kamu baca), kamu bisa mengetahui bahwa itu adalah べんとう. Jika Anda melakukannya, Anda akan menyadari bahwa kata ini juga berarti bento!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('14913afb-c333-4518-969d-059592bca826', 'Bento', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('14913afb-c333-4518-969d-059592bca826', 'Box Lunch', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('14913afb-c333-4518-969d-059592bca826', 'べんとう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14913afb-c333-4518-969d-059592bca826', '私のかばんの中には、さいふと、弁当と、タバコが一箱入っています。', 'Di tasku ada dompet, bekal bento, dan sebungkus rokok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14913afb-c333-4518-969d-059592bca826', 'お弁当のおかずを少し残しておいて、子猫にあげました。', 'Saya meninggalkan beberapa sisi di kotak makan siang saya dan memberikannya kepada anak kucing.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14913afb-c333-4518-969d-059592bca826', '明日あなたにお弁当作ってあげようと思うんだけど、何か苦手なものとかあるの？', 'Kurasa aku akan membuatkan kotak bento untukmu besok. Apakah ada sesuatu yang Anda tidak ingin miliki?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf60a680-2e75-435b-bfb2-7e5f77f00814', 'vocabulary', '東京弁', '東京弁', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda tahu bahwa 東京 adalah Tokyo, dan Anda tahu bahwa 弁 adalah dialek, jadi Anda sendiri memiliki dialek Tokyo.', 'Anda tahu bahwa 東京 adalah Tokyo, dan Anda tahu bahwa 弁 adalah dialek, jadi Anda sendiri memiliki dialek Tokyo.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bf60a680-2e75-435b-bfb2-7e5f77f00814', 'Dialek Tokyo', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bf60a680-2e75-435b-bfb2-7e5f77f00814', 'とうきょうべん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf60a680-2e75-435b-bfb2-7e5f77f00814', '東京弁は共通語とほとんど同じですよ。', 'Dialek Tokyo hampir sama dengan bahasa Jepang standar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf60a680-2e75-435b-bfb2-7e5f77f00814', '東京弁でしゃべってほしいというコウイチの要求をしりぞけました。', 'Saya menolak permintaan Koichi agar saya berbicara dalam dialek Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf60a680-2e75-435b-bfb2-7e5f77f00814', '「ねえ、無料で東京弁のレッスンを受けたいんだけど。」「コウイチに聞けよ。アイツは何でもするぞ。」', '"Saya perlu mendapatkan pelajaran dialek Tokyo gratis." "Tanyakan pada Koichi. Dia akan melakukan apa saja."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f35a60a-3303-4b84-8d7f-2c4ec4a442eb', 'vocabulary', '〜弁', '〜弁', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Tanda 〜 ada untuk menunjukkan kemelekatan pada sesuatu, seperti 東京弁, yang berarti "Dialek Tokyo".', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Tanda 〜 ada untuk menunjukkan kemelekatan pada sesuatu, seperti 東京弁, yang berarti "Dialek Tokyo".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7f35a60a-3303-4b84-8d7f-2c4ec4a442eb', 'Dialek', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7f35a60a-3303-4b84-8d7f-2c4ec4a442eb', 'べん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f35a60a-3303-4b84-8d7f-2c4ec4a442eb', '日本語で一番面白い方言は東北弁でしょうか？', 'Apakah dialek Tohoku merupakan dialek Jepang yang paling menarik?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f35a60a-3303-4b84-8d7f-2c4ec4a442eb', '私は日本語の共通語も関西弁も話せるからバイリンガルなんですよ。', 'Saya bilingual karena saya bisa berbicara bahasa Jepang standar dan juga dialek Kansai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f35a60a-3303-4b84-8d7f-2c4ec4a442eb', '博多弁で喋る女性はとても可愛いと思います。', 'Menurutku wanita yang berbicara dengan aksen Hakata sungguh manis.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', 'vocabulary', '証', '証', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', 'Bukti', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', 'Proof', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', 'あかし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', '友情の証として、このふじ山のキーホルダーをあげます。', 'Sebagai bukti persahabatan kita, aku akan memberimu gantungan kunci Gunung Fuji ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', 'あいつの身の証を立てるのはそうかん単なことじゃないかもしれない。', 'Mungkin tidak mudah untuk menunjukkan bukti bahwa dia tidak bersalah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1420a53-94a8-4517-9b7e-8e9bb1806e29', '君の両親だって本当は叱りたくないけど、叱っているんだよ。愛の証だよ。', 'Orang tuamu melarangmu, padahal sebenarnya mereka tidak mau. Itu bukti cinta mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da8f9b62-ac8d-452a-98e8-4eedd7125c62', 'vocabulary', '証人', '証人', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Pembuktian adalah saksi, karena saksi adalah orang yang memberikan bukti (lho dengan mulut atau semacamnya).', 'Pembuktian adalah saksi, karena saksi adalah orang yang memberikan bukti (lho dengan mulut atau semacamnya).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('da8f9b62-ac8d-452a-98e8-4eedd7125c62', 'Saksi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('da8f9b62-ac8d-452a-98e8-4eedd7125c62', 'しょうにん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da8f9b62-ac8d-452a-98e8-4eedd7125c62', '証人が、ビエトが有ざいであることを証明してくれました。', 'Saksi membuktikan Viet bersalah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da8f9b62-ac8d-452a-98e8-4eedd7125c62', '私の夫のさいばんでは、夫の口座がある銀行の行員の人たちが証人として出ていしてくれました。', 'Dalam kasus suami saya di pengadilan, pegawai bank tempat dia menyimpan rekeningnya hadir di pengadilan sebagai saksi untuknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da8f9b62-ac8d-452a-98e8-4eedd7125c62', '証人として、遠回しに言わずに率直に君の質問に答えさせてもらうよ。ああ、あのフグが確かに君のプリンを食べていたね。', 'Sebagai saksi, saya tidak akan bertele-tele, saya akan menjawab pertanyaan Anda dengan jujur. Ya, Fugu itu benar-benar memakan pudingmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('033f893b-21f6-4dff-9334-cebfcfc6e86f', 'vocabulary', '証言', '証言', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Bukti yang anda sampaikan adalah kesaksian. Anda juga bisa mengatakan bahwa Anda memberikan bukti lisan. Mudah-mudahan Anda tidak perlu memberikan terlalu banyak hal ini dalam hidup Anda.', 'Bukti yang anda sampaikan adalah kesaksian. Anda juga bisa mengatakan bahwa Anda memberikan bukti lisan. Mudah-mudahan Anda tidak perlu memberikan terlalu banyak hal ini dalam hidup Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('033f893b-21f6-4dff-9334-cebfcfc6e86f', 'Kesaksian', true) ON CONFLICT DO NOTHING;
