INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5d91b3f2-d59c-48a6-8fa1-3a67a974a250', 'Verification', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5d91b3f2-d59c-48a6-8fa1-3a67a974a250', 'しょうめい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d91b3f2-d59c-48a6-8fa1-3a67a974a250', 'クリステンが正真正めいの箱入りむすめであることが証明された。', 'Kami memiliki verifikasi bahwa Kristen benar-benar putri yang terlindungi dengan baik dari keluarga terhormat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d91b3f2-d59c-48a6-8fa1-3a67a974a250', '何か身分を証明できる物は持っていますか？', 'Apakah Anda memiliki sesuatu untuk memverifikasi identitas Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d91b3f2-d59c-48a6-8fa1-3a67a974a250', 'テキストフグとワニカニの各コースが修了するごとに、修了証明書のようなものが受け取れた方がいいですか？', 'Apakah Anda lebih suka menerima semacam sertifikat yang membuktikan bahwa Anda telah menyelesaikan kursus TextFugu dan WaniKani?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aa90ac42-8573-4cae-ad5b-637df861e564', 'vocabulary', '干渉', '干渉', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Saat Anda mengarungi sungai, dan tiba-tiba Anda merasakan perasaan kering di sekitar Anda, hal itu tidak masuk akal untuk sesuatu yang basah. Kekeringan ini merupakan sebuah gangguan. Ini adalah intervensi yang mencoba menghentikan Anda untuk mengarungi.', 'Saat Anda mengarungi sungai, dan tiba-tiba Anda merasakan perasaan kering di sekitar Anda, hal itu tidak masuk akal untuk sesuatu yang basah. Kekeringan ini merupakan sebuah gangguan. Ini adalah intervensi yang mencoba menghentikan Anda untuk mengarungi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aa90ac42-8573-4cae-ad5b-637df861e564', 'Gangguan', true) ON CONFLICT DO NOTHING;
