INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('aa8c9957-23c4-45d3-a9e6-5295e4b7d422', 'ぜひ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa8c9957-23c4-45d3-a9e6-5295e4b7d422', 'また是非日本にお来しくださいね。', 'Tentu saja, silakan kembali ke Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa8c9957-23c4-45d3-a9e6-5295e4b7d422', 'トーフグのパーティーには是非出席させていただきたいと思っています。', 'Saya sangat ingin menghadiri pesta Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa8c9957-23c4-45d3-a9e6-5295e4b7d422', 'トーフグの製品に興味がありそうな人を知っていたら、是非私達に知らせてくださいね。', 'Silakan beri tahu kami jika Anda mengenal seseorang yang mungkin tertarik dengan produk Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('adb0743e-b5da-4ca1-977e-a2a35c207c5a', 'vocabulary', '結果', '結果', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda mengikat semua buah karena Anda akan menggunakannya untuk membuat huruf buah raksasa. Huruf buah raksasa ini akan menunjukkan hasil pemilihan monyet besar.', 'Anda mengikat semua buah karena Anda akan menggunakannya untuk membuat huruf buah raksasa. Huruf buah raksasa ini akan menunjukkan hasil pemilihan monyet besar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('adb0743e-b5da-4ca1-977e-a2a35c207c5a', 'Hasil', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('adb0743e-b5da-4ca1-977e-a2a35c207c5a', 'けっか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adb0743e-b5da-4ca1-977e-a2a35c207c5a', '今年のAKBの選きょの結果が気になります。', 'Saya tidak sabar untuk mengetahui hasil pemilu AKB tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adb0743e-b5da-4ca1-977e-a2a35c207c5a', 'コウイチは、結果が一番大事だとよく口にしています。', 'Koichi sering mengatakan bahwa hasil adalah yang terpenting.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adb0743e-b5da-4ca1-977e-a2a35c207c5a', 'その結果には全然満足していませんよ。彼女の役に立とうという計画は、いつも裏目裏目に出るんです。今回もまた然りでした。', 'Saya sama sekali tidak senang dengan hasilnya. Rencanaku untuk membantunya selalu menjadi bumerang karena suatu alasan dan kali ini tidak terkecuali.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7fdf5455-41ea-40b3-8f99-58f647e5a1fb', 'vocabulary', '梅', '梅', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
