INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7fdf5455-41ea-40b3-8f99-58f647e5a1fb', 'うめ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fdf5455-41ea-40b3-8f99-58f647e5a1fb', '梅の花がさき始めました。', 'Pohon plum Jepang mulai berbunga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fdf5455-41ea-40b3-8f99-58f647e5a1fb', '「こんなにたくさんの梅の実、どうしたの？」「今日、梅園に行ってきたんだよ。」', '"Dari mana kamu mendapatkan ume sebanyak ini?" “Saya mengunjungi kebun ume hari ini.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fdf5455-41ea-40b3-8f99-58f647e5a1fb', '給料日が来たら、一粒一万円もする高級梅干を買ってあげるよ。', 'Begitu hari gajian tiba, saya akan membeli acar plum Jepang berkualitas tinggi yang harganya 10.000 yen per buah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'vocabulary', '梅酒', '梅酒', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Alkohol yang berasal dari ume adalah anggur ume. Bisa juga disebut anggur prem atau minuman keras prem. Jika Anda sudah cukup umur, cobalah rasanya, rasanya enak!', 'Alkohol yang berasal dari ume adalah anggur ume. Bisa juga disebut anggur prem atau minuman keras prem. Jika Anda sudah cukup umur, cobalah rasanya, rasanya enak!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'Anggur Ume', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'Plum Wine', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'Plum Liquor', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'Umeshu', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'うめしゅ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', '風ろ上がりに梅酒を開けると、一本飲み切るまで止まりません。', 'Ketika saya membuka sekaleng wine ume setelah mandi, saya tidak bisa berhenti sampai saya menghabiskannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', '日本では、電車の中で梅酒を飲んでもいいんですか？', 'Bolehkah minum anggur prem di kereta di Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('700ddb0a-76b4-498c-9d99-404cdcf425d5', 'よっしゃ〜花金だ〜。今夜の自家製梅酒が待ち遠しい。', 'Alhamdulillah ini hari Jumat! Saya menantikan untuk minum anggur prem buatan sendiri malam ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5be1d666-cc83-4035-8ccb-ed1b5e92a631', 'vocabulary', '交渉', '交渉', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ketika Anda terlibat dalam banyak hal dan mencampuradukkan segalanya, Anda terlibat dalam negosiasi. Tapi itulah yang dimaksud dengan negosiasi, bukan? Anda harus segera masuk ke sana, melewati kotoran. Kemudian, Anda harus mencampuradukkan dan berkompromi antara kedua belah pihak.', 'Ketika Anda terlibat dalam banyak hal dan mencampuradukkan segalanya, Anda terlibat dalam negosiasi. Tapi itulah yang dimaksud dengan negosiasi, bukan? Anda harus segera masuk ke sana, melewati kotoran. Kemudian, Anda harus mencampuradukkan dan berkompromi antara kedua belah pihak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5be1d666-cc83-4035-8ccb-ed1b5e92a631', 'Negosiasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5be1d666-cc83-4035-8ccb-ed1b5e92a631', 'こうしょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5be1d666-cc83-4035-8ccb-ed1b5e92a631', 'クリステンは、交渉のプロです。', 'Kristen adalah negosiator profesional.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5be1d666-cc83-4035-8ccb-ed1b5e92a631', 'なんとか交渉してみますが、期待はしないでくださいね。', 'Saya akan mencoba bernegosiasi, tapi tolong jangan mengharapkan apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5be1d666-cc83-4035-8ccb-ed1b5e92a631', '新婚旅行の際、フグはサーモンが値段の交渉が得意だということを知ってとても感心した。', 'Saat berbulan madu, Fugu sangat terkesan saat mengetahui Salmon sangat pandai dalam menegosiasikan harga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', 'vocabulary', '結局', '結局', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Jika Anda mengikat biro dengan penundaan Anda, hal ini mungkin tidak akan selesai tahun ini.', 'Jika Anda mengikat biro dengan penundaan Anda, hal ini mungkin tidak akan selesai tahun ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', 'Lagipula', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', 'Eventually', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', 'In The End', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', 'けっきょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', '結局、梅干しはつけませんでした。', 'Saya tidak akhirnya membuat umeboshi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', '目覚まし時計で一たんは目が覚めたが、結局またねむりに落ちてしまいました。', 'Saya terbangun karena alarm sekali, tetapi akhirnya saya tertidur kembali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2694a5a7-4ec2-4ec7-914b-f2da6845e387', 'バレンタインの友チョコを買いに行ったんだけど、結局自分用チョコしか買わなかったわ。', 'Aku pergi membeli coklat Valentine untuk teman-temanku, tapi pada akhirnya aku hanya membelikannya untuk diriku sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d6f146c-b7d6-44e6-939b-8f6eb30781a6', 'vocabulary', '虚栄心', '虚栄心', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ketika seberapa banyak kekayaanmu masuk ke dalam hatimu dan masuk begitu saja ke dalam kehampaan, jarang sekali hal itu akan berarti apa-apa bagimu. Seseorang yang memiliki sifat ini akan memiliki kesombongan yang ekstrim karena dia hanya perlu menyedot lebih banyak kemakmuran ke dalam jurang mautnya. Ini seperti lubang hitam. Mereka membutuhkan lebih dan lebih lagi sehingga mereka menjadi sia-sia.', 'Ketika seberapa banyak kekayaanmu masuk ke dalam hatimu dan masuk begitu saja ke dalam kehampaan, jarang sekali hal itu akan berarti apa-apa bagimu. Seseorang yang memiliki sifat ini akan memiliki kesombongan yang ekstrim karena dia hanya perlu menyedot lebih banyak kemakmuran ke dalam jurang mautnya. Ini seperti lubang hitam. Mereka membutuhkan lebih dan lebih lagi sehingga mereka menjadi sia-sia.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5d6f146c-b7d6-44e6-939b-8f6eb30781a6', 'Kesombongan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5d6f146c-b7d6-44e6-939b-8f6eb30781a6', 'きょえいしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d6f146c-b7d6-44e6-939b-8f6eb30781a6', '虚栄心の強い人は、男でも女でも苦手です。', 'Saya tidak suka orang yang sombong, apapun jenis kelaminnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d6f146c-b7d6-44e6-939b-8f6eb30781a6', '自分の虚栄心に度々きずつけられます。', 'Saya terluka oleh kesombongan saya sendiri dari waktu ke waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d6f146c-b7d6-44e6-939b-8f6eb30781a6', 'トーフグソフトボールチームに入る際の第一規則は、虚栄心をベンチに置いておくことです。', 'Aturan pertama tim softball Tofugu adalah Anda harus meninggalkan kesombongan Anda di bangku cadangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', 'vocabulary', '虚弱', '虚弱', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda tidak memiliki kelemahan. Ini berarti Anda lemah dan lemah.', 'Anda tidak memiliki kelemahan. Ini berarti Anda lemah dan lemah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', 'Lemah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', 'Feeble', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', 'Weakness', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', 'Feebleness', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', 'きょじゃく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', '虚弱な子どもを見ると、心配になります。', 'Setiap kali saya melihat anak yang lemah, saya merasa khawatir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', '私はいちょうが虚弱なんです。', 'Saya memiliki perut yang lemah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('360db0e4-686e-4aaa-91d0-2863d6982725', '私の息子は生まれつき虚弱体質で、運動はできません。', 'Anak saya lahir dengan kondisi fisik yang lemah, jadi dia tidak bisa berolahraga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10f65fde-5cf1-4f6a-ae9e-980dff7e1dcc', 'vocabulary', '関西弁', '関西弁', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Apakah Anda ingat 関西, yang merupakan wilayah Kansai di Jepang? Ya, mereka punya dialeknya sendiri, yaitu Dialek Kansai.', 'Apakah Anda ingat 関西, yang merupakan wilayah Kansai di Jepang? Ya, mereka punya dialeknya sendiri, yaitu Dialek Kansai.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('10f65fde-5cf1-4f6a-ae9e-980dff7e1dcc', 'Dialek Kansai', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('10f65fde-5cf1-4f6a-ae9e-980dff7e1dcc', 'かんさいべん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10f65fde-5cf1-4f6a-ae9e-980dff7e1dcc', '関西弁で、ウンチのことをババというらしいです。', 'Saya mendengar kotoran disebut baba dalam dialek Kansai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10f65fde-5cf1-4f6a-ae9e-980dff7e1dcc', '関西弁で文句を言われると、かなりこわいよね。', 'Menakutkan sekali kalau orang mengeluh dalam dialek Kansai, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10f65fde-5cf1-4f6a-ae9e-980dff7e1dcc', '彼、私に向かって、「お前のこと嫌いやねん」とか「帰れや」とか言ったのよ。ひどいでしょ？でもさ、実は関西弁で言われたもんだから、ちょっと格好いいなんて思っちゃったんだよね。何か、すごいセクシーだったの。', 'Dia mengatakan hal-hal kepadaku seperti, “Aku benci kamu” dan “pulanglah” dan kedengarannya buruk, bukan? Tapi menurutku itu cukup keren karena dia mengatakan semuanya menggunakan dialek Kansai. Itu sangat panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', 'vocabulary', '証明書', '証明書', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Mudah-mudahan Anda tahu bahwa 証明 berarti "bukti". Lantas, ketika pembuktiannya ditulis, pembuktiannya seperti apa? Itu semacam sertifikat. Saya perlu melihat beberapa 証明書 jika Anda ingin masuk ke sini, Pak.', 'Mudah-mudahan Anda tahu bahwa 証明 berarti "bukti". Lantas, ketika pembuktiannya ditulis, pembuktiannya seperti apa? Itu semacam sertifikat. Saya perlu melihat beberapa 証明書 jika Anda ingin masuk ke sini, Pak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', 'Sertifikat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', 'Credentials', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', 'しょうめいしょ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', '電車の中に証明書が入ったかばんを忘れてきてしまった。', 'Saya lupa tas saya dengan sertifikat di kereta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', '証明書のていじは必要ですか？', 'Apakah saya harus menunjukkan kredensial saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('699e709f-cbec-464a-bba5-5787dd0fa53c', '身分証明書をご提示頂けますか？', 'Bisakah saya memeriksa ID Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', 'vocabulary', '僧院', '僧院', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Institusi bagi para biksu akan berupa kuil atau biara. Saya yakin itu adalah tempat yang menyenangkan untuk ditinggali!', 'Institusi bagi para biksu akan berupa kuil atau biara. Saya yakin itu adalah tempat yang menyenangkan untuk ditinggali!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', 'Kuil', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', 'Monastery', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', 'そういん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', 'この僧院では、良い食生活は健康に不可欠だと考えているので、僧りょ達は毎日美味しい料理を食べます。', 'Di kuil ini, diyakini bahwa makan dengan baik sangat penting untuk kesehatan, sehingga para biksu menyantap makanan lezat setiap hari di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', '映画「ゴジラ対キングコウイチ」のロケ地めぐりをしたんですが、この僧院も私がおとずれた場所の一つです。', 'Saya mengunjungi tempat pembuatan film "Godzilla vs King Koichi" dan biara ini adalah salah satunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b5621c3e-e65c-48ac-8b41-14c40dbb8229', '初めまして。今日からこの僧院で働く予定になっているコウイチです。よろしくお願いいたします。', 'Senang berkenalan dengan Anda. Saya Koichi. Saya dijadwalkan untuk mulai bekerja di biara ini hari ini. Saya menantikan untuk bekerja sama dengan Anda semua.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('35efc499-7563-4999-915b-dd304f2cc2d9', 'vocabulary', '仏僧', '仏僧', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Seorang pendeta Buddha adalah seorang pendeta Buddha.', 'Seorang pendeta Buddha adalah seorang pendeta Buddha.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('35efc499-7563-4999-915b-dd304f2cc2d9', 'Pendeta Buddha', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('35efc499-7563-4999-915b-dd304f2cc2d9', 'ぶっそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35efc499-7563-4999-915b-dd304f2cc2d9', 'あの仏僧は、あと一ヶ月で九十九才に達します。', 'Pendeta Budha itu akan mencapai usia sembilan puluh sembilan dalam satu bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35efc499-7563-4999-915b-dd304f2cc2d9', 'コウイチのダジャレがつまらなさすぎて、仏僧ははとがまめ鉄っぽうを食ったような顔をしていた。', 'Permainan kata-kata Koichi sangat timpang sehingga pendeta Buddha itu tampak seperti rusa yang terkena lampu depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35efc499-7563-4999-915b-dd304f2cc2d9', 'その魔女は仏僧の心をも燃え上がらせた。', 'Penyihir itu bahkan membakar hati pendeta Buddha itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3883bb81-b2fc-400b-8171-b9ce0ad42df0', 'vocabulary', '文句', '文句', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Paragraf dalam bentuk tertulis adalah apa yang Anda kirimkan kepada seseorang ketika Anda ingin menyampaikan pengaduan. Namun, Anda ingin memastikan bahwa keluhan tersebut dibuat secara tertulis, jika tidak, Anda tidak memiliki bukti atas keluhan Anda. Selain itu, jangan membuatnya lebih panjang dari satu paragraf, karena itu terlalu panjang dan tidak ada yang peduli menurut Anda bagaimana staf toko menganiaya anjing Anda, Fluffy.', 'Paragraf dalam bentuk tertulis adalah apa yang Anda kirimkan kepada seseorang ketika Anda ingin menyampaikan pengaduan. Namun, Anda ingin memastikan bahwa keluhan tersebut dibuat secara tertulis, jika tidak, Anda tidak memiliki bukti atas keluhan Anda. Selain itu, jangan membuatnya lebih panjang dari satu paragraf, karena itu terlalu panjang dan tidak ada yang peduli menurut Anda bagaimana staf toko menganiaya anjing Anda, Fluffy.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3883bb81-b2fc-400b-8171-b9ce0ad42df0', 'Keluhan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3883bb81-b2fc-400b-8171-b9ce0ad42df0', 'もんく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3883bb81-b2fc-400b-8171-b9ce0ad42df0', 'コウイチは、トーフグ社員のJLPTの試験結果に文句タラタラだった。', 'Koichi tak henti-hentinya mengeluhkan hasil JLPT karyawan Tofugu itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3883bb81-b2fc-400b-8171-b9ce0ad42df0', 'オンラインの日本語学習教材の中では、トーフグが文句無しで一番いいと思っています。', 'Saya rasa Tofugu tidak diragukan lagi adalah alat belajar bahasa Jepang online terbaik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3883bb81-b2fc-400b-8171-b9ce0ad42df0', '日本語で、文句という言葉が、英語の僧侶という単語と発音が似ているということは面白いですね。', 'Lucu sekali kata dalam bahasa Jepang untuk keluhan diucapkan seperti kata dalam bahasa Inggris biksu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'vocabulary', '禁句', '禁句', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Suatu ayat yang dilarang termasuk dalam larangan karena mengandung kata tabu atau kalimat tabu. Tolong jangan ucapkan kata ini!', 'Suatu ayat yang dilarang termasuk dalam larangan karena mengandung kata tabu atau kalimat tabu. Tolong jangan ucapkan kata ini!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'Kata Tabu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'Taboo Phrase', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'Dirty Word', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'Bad Word', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'きんく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', '本当に申しわけないです。どうして禁句を言ってしまったんだろう。ごめんなさい。', 'Saya merasa tidak enak. Saya tidak tahu mengapa saya mengatakan kata buruk itu! Saya minta maaf.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'コウイチが言った禁句が頭からはなれません。', 'Aku tidak bisa menghilangkan kata-kata kotor yang diucapkan Koichi dari pikiranku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('088500b4-fa24-4e58-8872-556d34fa627a', 'トーフグソフトボールチームに入る際の第二規則は、お腹がすきすぎちゃうので、昼食前には「ベーコン」という言葉は禁句だということを肝に銘じることです。', 'Aturan kedua tim softball Tofugu adalah harus ingat bahwa "bacon" adalah kata yang tabu sebelum waktu makan siang karena membuat kita terlalu lapar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', 'vocabulary', '座禅', '座禅', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Saat Anda duduk dan melakukan zen, Anda mungkin sedang melakukan meditasi zen. Hmmmm.', 'Saat Anda duduk dan melakukan zen, Anda mungkin sedang melakukan meditasi zen. Hmmmm.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', 'Meditasi Zen', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', 'Zazen', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', 'ざぜん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', '座禅は、そこでクライマックスに達した。', 'Meditasi Zen mencapai klimaksnya di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', '京都に旅行に行ったら、ぜひ座禅の体験をしてみたいなあ。', 'Saya pasti ingin merasakan meditasi Zen ketika saya bepergian ke Kyoto.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7faa8845-3a05-480c-882e-98e908ed946c', '私の友達はお坊さんで、自分のお寺で座禅の会を開いています。彼は、座禅によって、リラックスできるだけでなく、欲望や執着心が無くなる悟りの境地に至ることもできると教えてくれました。', 'Teman saya adalah seorang biksu dan dia melakukan sesi meditasi Zen di kuilnya. Dia mengatakan kepada saya bahwa kita tidak hanya bisa bersantai tetapi juga mencapai pencerahan dan bebas dari keinginan dan keterikatan dengan meditasi Zen.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', 'vocabulary', '駅弁', '駅弁', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ingat bagaimana 弁当 adalah "bento"? Ya, 弁 dalam kata ini berasal dari kata itu, jadi anggap saja artinya "bento". Kemudian, jika Anda memiliki stasiun kereta untuk menemani bento, Anda juga memiliki bento stasiun kereta. Seperti yang mungkin Anda bayangkan, bento stasiun kereta hanyalah bento yang dijual di stasiun kereta. Mudah!', 'Ingat bagaimana 弁当 adalah "bento"? Ya, 弁 dalam kata ini berasal dari kata itu, jadi anggap saja artinya "bento". Kemudian, jika Anda memiliki stasiun kereta untuk menemani bento, Anda juga memiliki bento stasiun kereta. Seperti yang mungkin Anda bayangkan, bento stasiun kereta hanyalah bento yang dijual di stasiun kereta. Mudah!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', 'Stasiun Kereta Bento', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', 'Station Bento', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', 'えきべん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', 'いそがしすぎて、駅弁を買うのを忘れてました。', 'Saya sangat sibuk sehingga saya lupa membeli bento stasiun kereta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', '日本国内の旅行の楽しみの一つは、色々な駅弁を食べくらべることです。', 'Salah satu hal menyenangkan yang bisa dilakukan selama perjalanan domestik di Jepang adalah membandingkan berbagai stasiun bento.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2adab82a-ca58-4888-978d-dd3ca9a94277', 'あっ、おにぎりを持ってくるのを忘れたの？じゃあ、お昼は駅弁を買わなくちゃいけませんね。', 'Oh, kamu lupa membawa onigirinya? Kita harus membeli stasiun bento untuk makan siang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00d39555-936f-43a8-be2e-d4b6f22cd362', 'vocabulary', '弓', '弓', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('00d39555-936f-43a8-be2e-d4b6f22cd362', 'Busur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('00d39555-936f-43a8-be2e-d4b6f22cd362', 'ゆみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00d39555-936f-43a8-be2e-d4b6f22cd362', 'コウイチの弓がどこにも見当たらないんだ。', 'Kami tidak dapat menemukan busur Koichi di mana pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00d39555-936f-43a8-be2e-d4b6f22cd362', '弓を引くには、まず上半身を安定させなくてはいけません。', 'Anda harus menstabilkan tubuh bagian atas untuk menarik busur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00d39555-936f-43a8-be2e-d4b6f22cd362', 'うん、ローソンは確かに二十四時間営業だよ。でもさぁ、あのー、多分弓と矢は置いてないと思うよ？', 'Ya, Lawson buka 24/7, tapi, tahukah Anda, menurut saya mereka tidak membawa busur dan anak panah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', 'vocabulary', '弓道', '弓道', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Jalur haluan. Ini memanah.', 'Jalur haluan. Ini memanah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', 'Panahan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', 'Kyudo', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', 'Kyuudou', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', 'きゅうどう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', '弓道はむずかしいという結ろんに達しました。', 'Saya sampai pada kesimpulan bahwa kyudo itu sulit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', '日本の弓道の弓って、どうしてそんなに強いの？', 'Mengapa busur Jepang untuk kyudo begitu kuat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d49f55c-9cd1-4718-a3ee-a7fd5ea0ee89', '「一生懸命何しているの？」「弓道だよ。」', '"Apa yang sedang kamu kerjakan?" "Panahan Jepang."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', 'vocabulary', '禅寺', '禅寺', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kuil zen memang seperti namanya, kuil zen. Kedengarannya bagus.', 'Kuil zen memang seperti namanya, kuil zen. Kedengarannya bagus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', 'Kuil Zen', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', 'ぜんでら', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', 'ぜんじ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', 'あの禅寺の名前は何だっけ？', 'Apa nama kuil Zen itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', 'あの禅寺、さいむちょうかの会社のかぶに投しをして、痛い目にあったらしいよ。', 'Saya membaca di suatu tempat bahwa kuil Zen berinvestasi di saham sebuah perusahaan dengan kewajiban berlebihan dan mereka memiliki pengalaman yang mengerikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ef26968d-ae79-483b-bf18-7852fcceb6f1', '天龍寺という、十四世紀に京都市西部に建てられた禅寺が好きです。', 'Tenryū-ji adalah kuil Zen yang saya sukai yang dibangun pada abad ke-14 di barat Kyoto.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7b778ee-c23d-4b68-9324-4b9e53425259', 'vocabulary', '禅僧', '禅僧', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Seorang pendeta Zen adalah seorang pendeta zen.', 'Seorang pendeta Zen adalah seorang pendeta zen.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b7b778ee-c23d-4b68-9324-4b9e53425259', 'Pendeta Zen', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b7b778ee-c23d-4b68-9324-4b9e53425259', 'ぜんそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7b778ee-c23d-4b68-9324-4b9e53425259', 'その禅僧は、すきっぱらに不味いものは無いという言葉を実感しました。', 'Pendeta Zen secara harfiah memahami ungkapan "kelaparan adalah saus terbaik".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7b778ee-c23d-4b68-9324-4b9e53425259', '努力は全て無だに終わったが、禅僧は少しもはらが立たなかった。', 'Meski usahanya sia-sia, pendeta Zen itu tidak merasa kesal sedikit pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7b778ee-c23d-4b68-9324-4b9e53425259', 'もし禅僧になりたければ、とんでもなくきつい修行を終える必要があります。', 'Jika Anda ingin menjadi pendeta Zen, Anda harus melalui pelatihan yang sangat sulit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', 'vocabulary', '二枚舌', '二枚舌', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda memiliki dua benda datar yang membentuk lidah Anda. Lidah macam apa yang terdiri dari dua hal? Itu lidah yang terbelah, itulah lidah yang bercabang.', 'Anda memiliki dua benda datar yang membentuk lidah Anda. Lidah macam apa yang terdiri dari dua hal? Itu lidah yang terbelah, itulah lidah yang bercabang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', 'Lidah Bercabang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', 'Duplicity', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', 'にまいじた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', '政治家達の二枚舌の政さくにはもううんざりだよ。', 'Saya benar-benar muak dengan kebijakan-kebijakan politisi yang bermuka dua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', 'あいつは二枚舌だから気をつけた方がいいよ。', 'Lidahnya bercabang, jadi berhati-hatilah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bbcef7cd-5753-4e3d-88e0-81e7c316e99c', '○×クイズ: ビエトは等身大の初音ミク人形を買うお金を儲けるために、二枚舌を使ってコウイチを騙しました。○か×か？', 'Kuis Benar atau Salah: Untuk mendapatkan uang untuk boneka Hatsune Miku seukuran aslinya, Viet menggunakan lidahnya yang bercabang untuk menipu Koichi. Benar atau salah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', 'vocabulary', '改善', '改善', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ketika Anda memperbarui sesuatu dan hasilnya baik secara moral, itu jelas merupakan kemajuan.', 'Ketika Anda memperbarui sesuatu dan hasilnya baik secara moral, itu jelas merupakan kemajuan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', 'Peningkatan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', 'Betterment', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', 'かいぜん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', 'この絵はまだ改善のよ地があると思うんだよね。', 'Saya pikir masih ada ruang untuk perbaikan pada lukisan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', 'コウイチは、トーフグの体しつ改善を図っています。', 'Koichi telah berusaha memperbaiki konstitusi Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5baa4573-821b-446c-ae8a-700347f64a15', '私達のサイトに関して、何か改善すべき点などがございましたら、どうぞご連絡くださいませ。', 'Jika Anda mempunyai saran untuk perbaikan situs kami, silakan hubungi kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', 'vocabulary', '善悪', '善悪', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda memiliki moral yang baik dan buruk. Ini adalah pertarungan antara kebaikan dan kejahatan.', 'Anda memiliki moral yang baik dan buruk. Ini adalah pertarungan antara kebaikan dan kejahatan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', 'Baik Dan Jahat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', 'Right and Wrong', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', 'ぜんあく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', '善悪を見きわめることって、大人でもむずかしいですよね。', 'Membedakan yang baik dan yang jahat itu sulit, bahkan bagi orang dewasa sekalipun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', '一才をすぎたころから、だんだん善悪が分かるようになってきました。', 'Setelah menginjak usia satu tahun, dia mulai memahami apa yang benar dan apa yang salah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e01bd03-2e97-4205-ab5f-efe5dbfe3d6c', '彼は赤ちゃんなので、まだ善悪の区別がつきません。', 'Dia masih bayi, jadi dia masih belum tahu perbedaan antara benar dan salah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2ecae6a6-3f94-4bf5-9931-cef115460297', 'vocabulary', '季節', '季節', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Musim musim adalah musimnya. Siapa yang suka musim dingin? Ini adalah favoritku 季節.', 'Musim musim adalah musimnya. Siapa yang suka musim dingin? Ini adalah favoritku 季節.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2ecae6a6-3f94-4bf5-9931-cef115460297', 'Musim', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2ecae6a6-3f94-4bf5-9931-cef115460297', 'きせつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ecae6a6-3f94-4bf5-9931-cef115460297', 'このマーケットには、季節の野さいがたくさん売っています。', 'Banyak sayuran musiman yang dijual di pasar ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ecae6a6-3f94-4bf5-9931-cef115460297', 'その服そうは、ちょっと季節外れじゃない？', 'Bukankah pakaianmu sedikit keluar dari musimnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ecae6a6-3f94-4bf5-9931-cef115460297', '心配しないで。季節の変わり目に風邪をひくのは、私の習慣のようなものなの。', 'Jangan khawatir. Masuk angin saat pergantian musim adalah kebiasaan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', 'vocabulary', '宇宙', '宇宙', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ruang tengah luar angkasa adalah ruang yang berada di luar angkasa yaitu luar angkasa, luar angkasa, dan alam semesta!', 'Ruang tengah luar angkasa adalah ruang yang berada di luar angkasa yaitu luar angkasa, luar angkasa, dan alam semesta!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', 'Luar Angkasa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', 'Space', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', 'Universe', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', 'うちゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', '宇宙での生活には、いい加減あきてしまいました。', 'Aku muak dengan kehidupan luar angkasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', '宇宙の果てには何があると思いますか。', 'Menurut Anda apa yang ada di akhir alam semesta?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ba0b596-c03f-43cf-a3a7-0f6928678425', 'フグ、サーモンはあなたが復縁したいって知らないのよ。 もし知ったら、彼女も違うように感じるかもしれないわ。もしかしたら、他の魚と月を見に宇宙へなんて行かないかもしれないわよ。', 'Fugu, Salmon tidak tahu kamu ingin kembali bersama. Jika dia melakukannya, dia mungkin akan merasakan hal yang berbeda. Dia bahkan mungkin tidak pergi ke luar angkasa untuk melihat bulan dengan ikan yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79684313-b7d2-4206-8d84-159e953c096d', 'vocabulary', '履歴書', '履歴書', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kelanjutan dari berada di posisi seseorang dan menuliskannya, itulah tulisan "berjalan di posisi seseorang". Ini memberi Anda gambaran tentang orang itu. Itu adalah sejarah pribadi, meski bisa juga berupa resume.', 'Kelanjutan dari berada di posisi seseorang dan menuliskannya, itulah tulisan "berjalan di posisi seseorang". Ini memberi Anda gambaran tentang orang itu. Itu adalah sejarah pribadi, meski bisa juga berupa resume.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('79684313-b7d2-4206-8d84-159e953c096d', 'Riwayat Pribadi', true) ON CONFLICT DO NOTHING;
