INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('92d70fd7-44f4-431d-ab75-5abe314ccc8c', 'To Put On Boots', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('92d70fd7-44f4-431d-ab75-5abe314ccc8c', 'はく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92d70fd7-44f4-431d-ab75-5abe314ccc8c', 'ゆかたを着て、下たを履きました。', 'Saya mengenakan yukata dan mengenakan geta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92d70fd7-44f4-431d-ab75-5abe314ccc8c', 'くつ下を履かずにスニーカーを履かないで！スニーカーがくさくなるって何度言ったら分かるの？', 'Jangan memakai sepatu kets tanpa kaus kaki! Sepatu ketsnya akan berbau busuk. Berapa kali aku harus mengatakan ini padamu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92d70fd7-44f4-431d-ab75-5abe314ccc8c', '道路上のウンチを踏まないようにするために、人々がハイヒールを履き始めたって知ってた？', 'Tahukah Anda bahwa orang-orang mulai memakai sepatu hak tinggi untuk menghindari menginjak kotoran di jalanan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'vocabulary', '昆布', '昆布', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kain serangga sebenarnya adalah konbu. Rumput laut konbu sangat umum di Jepang dan rasanya lezat. Dan serangga juga suka menggunakannya sebagai kain. Mereka membuat semua pakaian mereka dari konbu.', 'Kain serangga sebenarnya adalah konbu. Rumput laut konbu sangat umum di Jepang dan rasanya lezat. Dan serangga juga suka menggunakannya sebagai kain. Mereka membuat semua pakaian mereka dari konbu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'Konbu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'Kombu', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'Konbu Seaweed', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'Kombu Seaweed', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'こんぶ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', 'こぶ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', '昆布でだしを取りました。', 'Saya membuat kaldu dengan kombu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', '昆布と若布のちがいを教えてください。', 'Tolong beritahu saya perbedaan antara rumput laut wakame dan rumput laut konbu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f4554cc-4453-4b6a-9c37-a762a03e09a9', '「よくも私に対して昆布を投げつけてくれたわね。」「ごめん。そんな大ごとだとは思わなかったんだよ。」', '"Beraninya kamu melempar rumput laut konbu ke arahku!" "Saya minta maaf. Saya tidak berpikir itu akan menjadi masalah besar."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', 'vocabulary', '梅干', '梅干', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ini adalah makanan khas Jepang, sehingga agak aneh untuk dipelajari. Anda memiliki Plum Jepang. Maka Anda sudah kering. Jadi ketika plum Jepang dikeringkan, itu bukanlah plum kering (itu terlalu mudah), melainkan acar plum atau acar ume. Jika Anda tahu nama makanan ini, Anda juga bisa menyebutnya dengan nama itu: umeboshi.', 'Ini adalah makanan khas Jepang, sehingga agak aneh untuk dipelajari. Anda memiliki Plum Jepang. Maka Anda sudah kering. Jadi ketika plum Jepang dikeringkan, itu bukanlah plum kering (itu terlalu mudah), melainkan acar plum atau acar ume. Jika Anda tahu nama makanan ini, Anda juga bisa menyebutnya dengan nama itu: umeboshi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', 'Acar Plum', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', 'Pickled Ume', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', 'Umeboshi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', 'うめぼし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', '梅干は乗り物よいにきくんですよ。', 'Umeboshi bagus untuk mabuk perjalanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', '梅干は何に混ぜて食べても美味しい。', 'Umeboshi bisa dicampur dengan apa saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7aec9258-b421-4f5a-b10a-613091fc31cb', 'すみません、 前を通らせてもらってもよろしいでしょうか。あの梅干しが入った小瓶を買いたいので。', 'Permisi. Bisakah saya melewatinya? Saya ingin membeli sebotol acar plum itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7477d272-3bd9-4ead-8505-b39503c9e4b6', 'vocabulary', '節句', '節句', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Bayangkan seperti apa satu paragraf suatu musim. Ini adalah bagian kecil dari musim ini, tetapi layak untuk ditulis. Itu adalah festival musiman. Ini menyenangkan!', 'Bayangkan seperti apa satu paragraf suatu musim. Ini adalah bagian kecil dari musim ini, tetapi layak untuk ditulis. Itu adalah festival musiman. Ini menyenangkan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7477d272-3bd9-4ead-8505-b39503c9e4b6', 'Festival Musiman', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7477d272-3bd9-4ead-8505-b39503c9e4b6', 'せっく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7477d272-3bd9-4ead-8505-b39503c9e4b6', 'もうすぐももの節句なので、ひな人形を出しました。', 'Saya mengeluarkan boneka hina karena Festival Anak Perempuan sudah dekat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7477d272-3bd9-4ead-8505-b39503c9e4b6', '五節句を全部言えますか。', 'Bisakah Anda menyebutkan kelima festival musiman?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7477d272-3bd9-4ead-8505-b39503c9e4b6', '「端午の節句」と呼ばれる日本の男の子の日に欠かせないのが、鯉をかたどった「鯉のぼり」と呼ばれる吹き流しです。', 'Hari anak laki-laki di Jepang, yang disebut "Hari Anak Laki-Laki", tidak akan lengkap tanpa pita berbentuk ikan mas yang dikenal sebagai "koi nobori".') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c2e6c50-ed62-4d59-973a-611b6224bba9', 'vocabulary', '舌', '舌', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c2e6c50-ed62-4d59-973a-611b6224bba9', 'Lidah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c2e6c50-ed62-4d59-973a-611b6224bba9', 'した', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c2e6c50-ed62-4d59-973a-611b6224bba9', '舌のしびれはもう取れましたか？', 'Apakah rasa kebas di lidahmu sudah hilang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c2e6c50-ed62-4d59-973a-611b6224bba9', 'ビタミンCが足りてないからか、最近舌があれてるんだよね。', 'Mungkin karena aku kurang vitamin C, tapi akhir-akhir ini lidahku jadi kasar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c2e6c50-ed62-4d59-973a-611b6224bba9', 'いいえ、結構です。昨夜、舌を焼けどしたので、コーヒーは飲みたくないんです。', 'Tidak terima kasih. Lidahku terbakar tadi malam, jadi aku tidak mau minum kopi apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('92572b90-fd32-403a-83d6-52f8b73104a8', 'vocabulary', '猫舌', '猫舌', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Lidah kucing entah kenapa diasosiasikan dengan keengganan terhadap makanan panas. Saya rasa saya belum pernah melihat kucing meminum susu mendidih, tapi terserah. Bayangkan saja seekor kucing menjilati sesuatu yang sangat panas dan ketakutan. Kucing tidak menyukai makanan panas, itulah sebabnya kucing tidak menyukai makanan panas.', 'Lidah kucing entah kenapa diasosiasikan dengan keengganan terhadap makanan panas. Saya rasa saya belum pernah melihat kucing meminum susu mendidih, tapi terserah. Bayangkan saja seekor kucing menjilati sesuatu yang sangat panas dan ketakutan. Kucing tidak menyukai makanan panas, itulah sebabnya kucing tidak menyukai makanan panas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('92572b90-fd32-403a-83d6-52f8b73104a8', 'Keengganan Terhadap Makanan Panas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('92572b90-fd32-403a-83d6-52f8b73104a8', 'ねこじた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92572b90-fd32-403a-83d6-52f8b73104a8', '私が猫舌だってこと、忘れてない？', 'Apakah kamu tidak lupa bahwa aku tidak menyukai makanan panas?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92572b90-fd32-403a-83d6-52f8b73104a8', 'ごめんなさい。私、猫舌なんです。', 'Saya minta maaf. Saya tidak bisa makan makanan panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('92572b90-fd32-403a-83d6-52f8b73104a8', 'コウイチは猫舌なので、スープをふうふうしないと食べられません。本当でしょうか嘘でしょうか？', 'Koichi tidak suka makanan panas, jadi dia tidak bisa makan sup tanpa meniupnya. Apakah ini benar atau salah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', 'vocabulary', '財閥', '財閥', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Klan kekayaan adalah sekelompok orang yang melakukan apa pun yang mereka bisa untuk mendapatkan uang mereka. Mereka adalah kaum plutokrat dunia, namun Anda juga bisa menyebut mereka klik finansial atau bahkan Zaibatsu (terkadang disebutkan dalam buku sejarah/ekonomi berbahasa Inggris mengenai Jepang).', 'Klan kekayaan adalah sekelompok orang yang melakukan apa pun yang mereka bisa untuk mendapatkan uang mereka. Mereka adalah kaum plutokrat dunia, namun Anda juga bisa menyebut mereka klik finansial atau bahkan Zaibatsu (terkadang disebutkan dalam buku sejarah/ekonomi berbahasa Inggris mengenai Jepang).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', 'Plutokrat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', 'Financial Clique', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', 'Zaibatsu', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', 'ざいばつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', '彼はこの財閥のあと取りです。', 'Dia adalah pewaris zaibatsu ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', 'おそかれ早かれ、トーフグは財閥として日本のビジネス界に君りんするでしょう。', 'Tofugu cepat atau lambat akan menguasai dunia bisnis di Jepang sebagai zaibatsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36203ac9-8875-4ddf-b595-fcd803fa3dc7', '日本には、第二次世界大戦前に三井財閥、三菱財閥、住友財閥、安田財閥などの財閥がありました。', 'Di Jepang, ada beberapa kelompok keuangan sebelum Perang Dunia II, termasuk Mitsui Zaibatsu, Mitsubishi Zaibatsu, Sumitomo Zaibatsu dan Yasuda Zaibatsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', 'vocabulary', '妨害', '妨害', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Sesuatu yang menghalangi dan juga menimbulkan kerusakan adalah suatu penghalang. Tidak ada halangan yang baik dan jika dibiarkan terlalu lama justru akan menimbulkan kerusakan dan gangguan pula.', 'Sesuatu yang menghalangi dan juga menimbulkan kerusakan adalah suatu penghalang. Tidak ada halangan yang baik dan jika dibiarkan terlalu lama justru akan menimbulkan kerusakan dan gangguan pula.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', 'Obstruksi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', 'Interference', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', 'ぼうがい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', 'これ以上妨害するのを止めないと、えい業妨害でうったえるぞ！', 'Jika Anda tidak berhenti ikut campur, saya akan menuntut Anda karena menghalangi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', 'ここまで来れば、てきの妨害の危険はほぼ無いだろう。', 'Karena kita sudah melangkah cukup jauh, risiko dicegat oleh musuh seharusnya hampir nol.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c5856556-c97f-4984-95f4-f5231a9d85d9', '私はいつか映画のように公務執行妨害で逮捕されてみたい。', 'Suatu hari nanti saya ingin ditangkap karena mengganggu petugas polisi, seperti di film.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'vocabulary', '妨げる', '妨げる', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghalangi, lalu versi vocab verbanya apa? Itu untuk menghalangi.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghalangi, lalu versi vocab verbanya apa? Itu untuk menghalangi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'Untuk Menghalangi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'To Prevent', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'To Hamper', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'さまたげる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'あの会社は、トーフグの成功を妨げようとしているらしい。', 'Saya mendengar bahwa perusahaan berusaha menghambat kesuksesan Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', '生産性を妨げるものは、すててしまった方がいいよ。', 'Sebaiknya Anda menyingkirkan hal-hal yang menghambat produktivitas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9341baf-53d4-4e9b-94ec-371ad3bac772', 'どうして人々は宇宙人が地球にやってくる事を妨げようとするのか理解できません。', 'Saya tidak mengerti mengapa orang mencoba mencegah alien mencapai bumi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', 'vocabulary', '嫌', '嫌', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kosa kata tersebut mempunyai arti tambahan yaitu eww, kasar, dan bahkan enggan.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kosa kata tersebut mempunyai arti tambahan yaitu eww, kasar, dan bahkan enggan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', 'Tidak suka', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', 'Eww', false) ON CONFLICT DO NOTHING;
