INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', 'いや', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', '嫌な仕事を嫌々するのは体に良くないよ。', 'Enggan melakukan pekerjaan yang tidak Anda sukai tidak baik untuk kesehatan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', '嫌嫌嫌嫌嫌！無理無理無理無理無理！クモがいる！気持ち悪い！', 'Ewwwwww!!!! Tidaaaak!!!! Ada laba-laba! Bruto!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70470475-3b93-48fc-b27a-ea102694750a', '「これ以上は安くできないよ。嫌ならやめて帰ってくれ。」 「分かったよ。買うことにするよ。」', '"Itu tawaran terakhirku. Jika kamu tidak menyukainya, berhentilah datang kembali." “Baiklah, baiklah. Aku akan mengambilnya.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3154a619-eaf2-4420-bda7-2ce5520d9421', 'vocabulary', '嫌い', '嫌い', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda tahu bahwa 嫌 berarti tidak suka dan kosakata ini memiliki arti yang sama: tidak suka atau benci!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3154a619-eaf2-4420-bda7-2ce5520d9421', 'Tidak suka', true) ON CONFLICT DO NOTHING;
