INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3154a619-eaf2-4420-bda7-2ce5520d9421', 'きらい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3154a619-eaf2-4420-bda7-2ce5520d9421', '私の嫌いな穴うめ問題がテストに出ました。', 'Ada pertanyaan-pertanyaan yang kosong dalam ujian, yang saya benci.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3154a619-eaf2-4420-bda7-2ce5520d9421', '単じゅん作業は嫌いです。そんなものは機械にまかせるべきだと思います。', 'Saya tidak suka pekerjaan yang sibuk. Saya pikir kita harus menyelesaikannya dengan mesin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3154a619-eaf2-4420-bda7-2ce5520d9421', '色々と振り回してごめんなさい。嫌なやつと思ってるかもしれないけど、嫌いにならないで。', 'Saya minta maaf telah menyebabkan begitu banyak masalah. Anda mungkin berpikir saya tidak menyenangkan, tapi tolong jangan membenci saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', 'vocabulary', '機嫌', '機嫌', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Mesin tidak menyukai segalanya. Suasana hati, atau watak mereka, sangat buruk. Bagaimana dengan suasana hatimu?', 'Mesin tidak menyukai segalanya. Suasana hati, atau watak mereka, sangat buruk. Bagaimana dengan suasana hatimu?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', 'suasana hati', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', 'Temper', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', 'きげん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', 'コウイチは、機械のように、毎日三時のおやつの時間になると機嫌が良くなる。', 'Koichi mempunyai suasana hati yang baik pada jam tiga waktu camilan, setiap hari seperti jam kerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', '今日のお母さんの機嫌はどう？', 'Suasana hati ibu seperti apa hari ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71015a8d-e362-4ac3-81aa-225ff493e8d2', '「彼女は朝、機嫌が悪いわね。」「ええ、全くその通りね。」', '“Suasana hatinya buruk di pagi hari.” "Ya, aku tidak mengetahuinya!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c119ffb-abc5-4e51-89ec-d35048ef1f2f', 'vocabulary', '嫌疑', '嫌疑', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Aku tidak menyukainya dan aku meragukannya. Oleh karena itu, saya juga mempunyai banyak kecurigaan terhadapnya.', 'Aku tidak menyukainya dan aku meragukannya. Oleh karena itu, saya juga mempunyai banyak kecurigaan terhadapnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0c119ffb-abc5-4e51-89ec-d35048ef1f2f', 'Kecurigaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0c119ffb-abc5-4e51-89ec-d35048ef1f2f', 'けんぎ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c119ffb-abc5-4e51-89ec-d35048ef1f2f', 'ビエトがヤクザだという嫌疑がぬぐえません。', 'Kecurigaan kami bahwa Viet adalah yakuza tidak bisa dihilangkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c119ffb-abc5-4e51-89ec-d35048ef1f2f', '警察に嫌疑をかけられているんだ。', 'Aku dicurigai oleh polisi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c119ffb-abc5-4e51-89ec-d35048ef1f2f', 'ビエトがコウイチにかかった殺人の嫌疑を晴らした。', 'Viet menghilangkan kecurigaan bahwa Koichi adalah seorang pembunuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bd7a2327-591c-4406-9d83-4d2d60397de7', 'vocabulary', '弓矢', '弓矢', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Busur dan anak panah. Gabungkan keduanya dan Anda akan mendapatkan busur dan anak panah.', 'Busur dan anak panah. Gabungkan keduanya dan Anda akan mendapatkan busur dan anak panah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bd7a2327-591c-4406-9d83-4d2d60397de7', 'Busur Dan Anak Panah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bd7a2327-591c-4406-9d83-4d2d60397de7', 'ゆみや', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd7a2327-591c-4406-9d83-4d2d60397de7', '弓矢でシカを仕留めるには、にんたいがいります。', 'Anda harus bersabar jika ingin menembak rusa dengan busur dan anak panah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd7a2327-591c-4406-9d83-4d2d60397de7', 'その夜、両親は、弓矢を売るべきかどうか議論しました。', 'Malam itu, orang tuaku mendiskusikan apakah busur dan anak panah itu akan dijual atau tidak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd7a2327-591c-4406-9d83-4d2d60397de7', '昔はうさぎ狩りに弓矢を使っていました。', 'Kami biasa menggunakan busur dan anak panah untuk berburu kelinci.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', 'vocabulary', '災い', '災い', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ini bentuk kata benda dari bencana, jadi artinya musibah atau kesialan.', 'Ini bentuk kata benda dari bencana, jadi artinya musibah atau kesialan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', 'Bencana', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', 'Misfortune', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', 'わざわい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', 'これは、災いを防いでくれるお守りです。', 'Ini adalah jimat keberuntungan yang melindungi Anda dari kemalangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', '災い転じて福となすという言葉を信じてがんばりました。', 'Saya percaya pada ungkapan, "ubah bencana menjadi keuntungan," dan itu benar-benar berhasil.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a4d6ebe-ea1b-4aab-85ca-96ffff17eff2', 'シャークは他人の災いを願っているようだね。', 'Sepertinya Hiu menginginkan kemalangan pada orang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'vocabulary', '災害', '災害', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Bencana yang menimbulkan kerusakan. Biasanya ini adalah bencana alam, namun bisa juga hanya bencana biasa.', 'Bencana yang menimbulkan kerusakan. Biasanya ini adalah bencana alam, namun bisa juga hanya bencana biasa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'Bencana Alam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'Disaster', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'Accident', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'さいがい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', '自然災害ほどおそろしいものはありません。', 'Tidak ada yang lebih menakutkan daripada bencana alam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'そもそも、どうして災害が起こる可能性の高い場所に原子力発電所を建てたのかが理かいできません。', 'Saya tidak mengerti mengapa mereka membangun pembangkit listrik tenaga nuklir di lokasi yang berpotensi terjadinya bencana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54fa8127-f797-4a3d-8f94-a99c4a45387d', 'それぞれの部屋には、災害の場合に備えて懐中電灯とペットボトルのお水が何本か用意してあります。', 'Setiap ruangan telah disiapkan senter dan botol air jika terjadi bencana alam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('32ec1985-da46-45a8-afc8-213c5cf658ca', 'vocabulary', '火災', '火災', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Bencana kebakaran adalah bencana kebakaran. Mungkin kamu akan bertemu dengan petugas pemadam kebakaran seksi jika semuanya berjalan lancar...', 'Bencana kebakaran adalah bencana kebakaran. Mungkin kamu akan bertemu dengan petugas pemadam kebakaran seksi jika semuanya berjalan lancar...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('32ec1985-da46-45a8-afc8-213c5cf658ca', 'Bencana Kebakaran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('32ec1985-da46-45a8-afc8-213c5cf658ca', 'かさい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32ec1985-da46-45a8-afc8-213c5cf658ca', 'どうやって火災が大水害を引き起こしたの？', 'Bagaimana bencana kebakaran menyebabkan banjir besar?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32ec1985-da46-45a8-afc8-213c5cf658ca', '今日中に火災で空いた穴をふさがなくてはいけません。', 'Saya harus mengisi lubang akibat bencana kebakaran pada akhir hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32ec1985-da46-45a8-afc8-213c5cf658ca', '彼は深夜二時に換気扇を回さずにフライパンでステーキを焼いて、火災警報装置を鳴らした。', 'Dia memasak steak di penggorengan tanpa menyalakan kipas ventilasi pada jam 2 pagi dan alarm kebakaran berbunyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', 'vocabulary', '災難', '災難', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Bencana yang sulit sangatlah sulit, menjadikannya lebih merupakan kemalangan. Tentu saja bencana yang tidak sulit sebenarnya tidak akan seburuk itu, sehingga bencana yang sulit mendapat label “kemalangan” atau malapetaka.', 'Bencana yang sulit sangatlah sulit, menjadikannya lebih merupakan kemalangan. Tentu saja bencana yang tidak sulit sebenarnya tidak akan seburuk itu, sehingga bencana yang sulit mendapat label “kemalangan” atau malapetaka.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', 'Kemalangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', 'Calamity', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', 'Disaster', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', 'さいなん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', '私は、運良く海外にいたので、その災難をまぬがれることができました。', 'Untungnya, saya sedang berada di luar negeri saat itu, jadi saya bisa lolos dari bencana tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', '今日学校で、「災難は勇気を試す試金石である。」ということわざを習いました。', 'Hari ini di sekolah saya belajar sebuah pepatah yang mengatakan, "bencana adalah batu ujian dari pikiran yang berani."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a859fd20-fc09-4e42-8c1b-c23e34c25ffc', 'どうしてあいつはあんなに災難に見舞われてばかりいるのかな？本当に偶然なのか、それともあいつ自体に何か問題があるんだろうか。', 'Aku heran kenapa kemalangan selalu mengikuti pria itu? Apakah hanya kebetulan saja atau ada yang salah dengan dirinya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a46ea5de-60bc-435d-bb08-95690cb19c15', 'vocabulary', '震災', '震災', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Bencana gempa bumi hanyalah bencana gempa bumi. Ini tidak bagus.', 'Bencana gempa bumi hanyalah bencana gempa bumi. Ini tidak bagus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a46ea5de-60bc-435d-bb08-95690cb19c15', 'Bencana Gempa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a46ea5de-60bc-435d-bb08-95690cb19c15', 'しんさい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a46ea5de-60bc-435d-bb08-95690cb19c15', '震災で、地面が穴ぼこだらけになってしまいました。', 'Akibat bencana gempa, banyak lubang di tanah saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a46ea5de-60bc-435d-bb08-95690cb19c15', '震災にあった日のことが、今でもわすれられないトラウマになっています。', 'Saya masih belum bisa melupakan trauma yang saya alami sejak hari terjadinya bencana gempa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a46ea5de-60bc-435d-bb08-95690cb19c15', '日本に行く時に、2011年の東北大震災の大津波に耐えた一本の松の木を見に行きたいです。', 'Kalau aku ke Jepang, aku ingin melihat satu-satunya pohon pinus yang tahan terhadap tsunami raksasa akibat Gempa Besar Tōhoku pada tahun 2011.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'vocabulary', '確率', '確率', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda yakin ada kemungkinan sebesar ini hal itu akan terjadi? Anda tahu bahwa ini adalah kemungkinannya?', 'Anda yakin ada kemungkinan sebesar ini hal itu akan terjadi? Anda tahu bahwa ini adalah kemungkinannya?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'Kemungkinan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'Likelihood', false) ON CONFLICT DO NOTHING;
