INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'かくりつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'コウイチがあやまってこの穴に落ちる確率は、20%ぐらいだろうね。', 'Kemungkinan Koichi secara tidak sengaja jatuh ke dalam lubang ini adalah sekitar 20%.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'コウイチが友情に厚い人である確率はどのぐらいだと思いますか？', 'Seberapa besar kemungkinan Koichi menjadi seseorang yang baik terhadap teman-temannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed16ecb3-9693-4d8c-a7cf-ba56c90f4afc', 'ビエトはコウイチに、トーフグが成功する確率は二百パーセントだと言いきった。', 'Viet memberi tahu Koichi bahwa peluang keberhasilan Tofugu adalah 200%.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', 'vocabulary', '比率', '比率', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda membandingkan persentasenya dan dengan melakukan itu, tentukan persentase dan rasio sesuatu.', 'Anda membandingkan persentasenya dan dengan melakukan itu, tentukan persentase dan rasio sesuatu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', 'Persentase', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', 'Ratio', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', 'ひりつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', '機械ほんやくにはどれぐらいの比率でたよっていますか？', 'Berapa persen yang bergantung pada terjemahan mesin?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', 'トーフグのオフィスの男女比率は、5:2です。', 'Perbandingan laki-laki dan perempuan di kantor Tofugu adalah 5 berbanding 2.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b94881b-f227-4928-8da9-405dee48799a', 'トーフグの自己資本比率は100％だと思います。', 'Saya pikir Tofugu memiliki rasio modal terhadap aset sebesar 100%.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', 'vocabulary', '余裕', '余裕', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda memiliki surplus yang melimpah! Betapa menyenangkannya memiliki surplus dengan begitu banyak waktu luang.', 'Anda memiliki surplus yang melimpah! Betapa menyenangkannya memiliki surplus dengan begitu banyak waktu luang.') ON CONFLICT (id) DO NOTHING;
