INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', 'Leeway', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', 'Room', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', 'よゆう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', 'トーフグは今年は予算にかなりの余裕があります。', 'Tofugu memiliki cukup ruang dalam anggaran tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', 'まだ二、三人分ぐらい余裕があるよ。', 'Kami masih memiliki cukup ruang untuk beberapa orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b9e0ca9-b85b-4f3b-8075-4546fca3ca5e', '新しいパソコンとAKB48のフィギュアを買いたいが、今は余裕が無い。', 'Saya ingin membeli komputer baru dan beberapa figure AKB48, tapi saya tidak mampu membelinya saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', 'vocabulary', '裕福', '裕福', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda memiliki keberuntungan yang melimpah! Kalau rejekimu melimpah, kemungkinan besar kamu juga kaya raya, karena banyak harta sama dengan banyak rejeki, bukan?', 'Anda memiliki keberuntungan yang melimpah! Kalau rejekimu melimpah, kemungkinan besar kamu juga kaya raya, karena banyak harta sama dengan banyak rejeki, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', 'Kaya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', 'Wealth', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', 'ゆうふく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', '不けい気を尻目に、コウイチはどんどん裕福になっていった。', 'Seolah-olah depresi adalah masalah orang lain, Koichi menjadi semakin kaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', 'ビエトって、裕福な家庭の出身だと思うんだよね。', 'Saya pikir Viet berasal dari keluarga kaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8449d452-3810-4f4a-9eca-6b9ccce1f316', '僕の両親はド金持ちって訳じゃないけど、比較的裕福な方ではあります。', 'Orang tua saya tidak super kaya tetapi mereka relatif kaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4c73c2de-389d-4df6-bcff-fbcbfd288db8', 'vocabulary', '汽車', '汽車', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Mobil uap adalah mobil yang berjalan dengan tenaga uap. Tidak ada mobil biasa yang menggunakan tenaga uap, tetapi benda apa yang disebut "mobil" yang menggunakan tenaga uap? Bagaimana dengan kereta uap? Anda juga dapat memikirkan 電車s, yaitu mobil listrik (tetapi berarti "kereta api"). Mirip dengan itu, tapi sekarang dijalankan dengan uap, menjadikannya kereta uap.', 'Mobil uap adalah mobil yang berjalan dengan tenaga uap. Tidak ada mobil biasa yang menggunakan tenaga uap, tetapi benda apa yang disebut "mobil" yang menggunakan tenaga uap? Bagaimana dengan kereta uap? Anda juga dapat memikirkan 電車s, yaitu mobil listrik (tetapi berarti "kereta api"). Mirip dengan itu, tapi sekarang dijalankan dengan uap, menjadikannya kereta uap.') ON CONFLICT (id) DO NOTHING;
