INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c73c2de-389d-4df6-bcff-fbcbfd288db8', 'その駅員は、汽車を静止させるのを忘れていたことに気が付きました。', 'Pekerja stasiun itu menyadari bahwa dia lupa menghentikan kereta uap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c73c2de-389d-4df6-bcff-fbcbfd288db8', '大好きな汽車だったので、何枚も何枚も写真をとってしまいました。', 'Itu adalah mesin uap favorit saya, jadi saya mengambil ribuan foto.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c73c2de-389d-4df6-bcff-fbcbfd288db8', '「すみません。汽車は何分おきに来ますか？」「大体20分おきくらいです。」', '“Maaf, seberapa sering kereta uap datang?” "Kira-kira setiap dua puluh menit."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e3703c3-08e7-43eb-9e55-8ed1b0121e98', 'vocabulary', '汽船', '汽船', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kapal uap adalah kapal uap atau kapal uap. Sangat mewah di zaman mereka!', 'Kapal uap adalah kapal uap atau kapal uap. Sangat mewah di zaman mereka!') ON CONFLICT (id) DO NOTHING;
