INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e3703c3-08e7-43eb-9e55-8ed1b0121e98', '汽船を一台借り切って、シンガポールへ行きました。', 'Kami menyewa kapal uap untuk perjalanan kami ke Singapura.') ON CONFLICT DO NOTHING;
