INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc8dfa69-c806-4655-932d-91c35afaed45', 'その笛には、ツタが絡まっていました。', 'Seruling itu terjerat tanaman merambat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc8dfa69-c806-4655-932d-91c35afaed45', 'このはと笛、お母さんがおまつりで買ってくれたの。', 'Ibuku membelikan seruling merpati ini untukku di sebuah festival.') ON CONFLICT DO NOTHING;
