INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e03c36b-89c0-4c16-8a40-100db351082d', 'vocabulary', '汽笛', '汽笛', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Seruling uap adalah seruling yang berbunyi menggunakan uap. Satu-satunya saat saya dapat memikirkan hal ini terjadi adalah melalui peluit uap. Choo chooooo!', 'Seruling uap adalah seruling yang berbunyi menggunakan uap. Satu-satunya saat saya dapat memikirkan hal ini terjadi adalah melalui peluit uap. Choo chooooo!') ON CONFLICT (id) DO NOTHING;
