INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e03c36b-89c0-4c16-8a40-100db351082d', 'まどの外から、汽車の汽笛が聞こえてきました。', 'Kami mendengar peluit kereta uap datang dari luar jendela.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e03c36b-89c0-4c16-8a40-100db351082d', 'いいか？汽笛が鳴ったら、船から飛び下りるんだぞ。', 'Anda siap? Anda harus melompat dari kapal ketika peluit uap berbunyi.') ON CONFLICT DO NOTHING;
