INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f9ac297d-3fa8-435b-a849-adff78ae61bb', 'vocabulary', '口笛', '口笛', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Seruling mulut... Seruling biasa yang Anda gunakan untuk meniupkan udara untuk menghasilkan suara. Bagaimana cara meniupkan udara melalui mulut hingga menimbulkan suara? Dengan bersiul.', 'Seruling mulut... Seruling biasa yang Anda gunakan untuk meniupkan udara untuk menghasilkan suara. Bagaimana cara meniupkan udara melalui mulut hingga menimbulkan suara? Dengan bersiul.') ON CONFLICT (id) DO NOTHING;
