INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f9ac297d-3fa8-435b-a849-adff78ae61bb', '口笛が下手くそなので、私が口笛を吹いても犬が来てくれません。', 'Anjing saya tidak mau bersiul karena saya buruk dalam bersiul.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('adb5903f-7ecc-4454-98c9-18c2d718a0f6', 'vocabulary', '文句する', '文句する-4369', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda tahu bagaimana 文句 merupakan keluhan, bukan? Nah, tambahkan する untuk menjadikannya kata kerja dan Anda harus mengeluh. Ini adalah cara yang sangat santai untuk mengeluh, biasanya digunakan di manga atau media sosial. Awasi itu!', 'Anda tahu bagaimana 文句 merupakan keluhan, bukan? Nah, tambahkan する untuk menjadikannya kata kerja dan Anda harus mengeluh. Ini adalah cara yang sangat santai untuk mengeluh, biasanya digunakan di manga atau media sosial. Awasi itu!') ON CONFLICT (id) DO NOTHING;
