INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adb5903f-7ecc-4454-98c9-18c2d718a0f6', '意見を言っただけなのに、上司に「文句するな」と怒鳴られました。', 'Saya baru saja mengutarakan pendapat saya, namun atasan saya berteriak, "jangan mengeluh," kepada saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('99233ae9-6153-4819-87c1-636ce9c87851', 'vocabulary', '宇宙人', '宇宙人', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda tahu bagaimana 宇宙 itu ruang? Ya, orang dari luar angkasa adalah alien.', 'Anda tahu bagaimana 宇宙 itu ruang? Ya, orang dari luar angkasa adalah alien.') ON CONFLICT (id) DO NOTHING;
