INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3efc5061-7d7b-4d3a-81d1-1879ae21f8ea', 'コウイチはあなたのことが大嫌いなので、彼に代わってビエトがお会いします。', 'Tuan Viet yang akan menemuimu, bukan Tuan Koichi, karena Tuan Koichi sangat membencimu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('08024a31-4584-46fd-a6bc-21d557e72c3a', 'vocabulary', '結構です', '結構です', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', '結構 adalah sesuatu seperti "baik" atau "baiklah". Ini sedikit lebih sopan. Anda dapat menggunakan ini untuk mengatakan tidak, terima kasih kepada seseorang yang mencoba menawarkan sesuatu kepada Anda.', '結構 adalah sesuatu seperti "baik" atau "baiklah". Ini sedikit lebih sopan. Anda dapat menggunakan ini untuk mengatakan tidak, terima kasih kepada seseorang yang mencoba menawarkan sesuatu kepada Anda.') ON CONFLICT (id) DO NOTHING;
