INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('84613342-fb82-44b5-a004-a2e6faac15d6', 'vocabulary', '凍結', '凍結', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ketika benda-benda dibekukan, benda-benda itu akan terikat dalam es, sehingga menyebabkan pembekuan.', 'Ketika benda-benda dibekukan, benda-benda itu akan terikat dalam es, sehingga menyebabkan pembekuan.') ON CONFLICT (id) DO NOTHING;
