INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84613342-fb82-44b5-a004-a2e6faac15d6', 'まだ完全には凍結していないかもしれないから、気を付けてね。', 'Ini mungkin belum sepenuhnya beku, jadi berhati-hatilah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84613342-fb82-44b5-a004-a2e6faac15d6', '凍結防止のために道に塩をまきます。', 'Kami menyebarkan garam di jalan untuk mencegah pembekuan.') ON CONFLICT DO NOTHING;
