INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7328c028-73dc-4ab8-9932-39f52c792696', 'vocabulary', '結婚', '結婚', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Mari kita ikat pernikahan ini dengan sebuah pernikahan. Tidak ada cara yang lebih baik untuk mewujudkan pernikahan selain pernikahan, bukan?', 'Mari kita ikat pernikahan ini dengan sebuah pernikahan. Tidak ada cara yang lebih baik untuk mewujudkan pernikahan selain pernikahan, bukan?') ON CONFLICT (id) DO NOTHING;
