INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7328c028-73dc-4ab8-9932-39f52c792696', '「シャーク、私がフグと結婚したってどうして分かったの？」 「ただ人づてに聞いただけさ。」', '“Hiu, bagaimana kamu tahu kalau aku menikah dengan Fugu?” "Kau tahu. Aku baru saja mendengarnya dari selentingan."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f961beaa-f234-40b7-9457-86a30c27bda2', 'vocabulary', '詳しい', '詳しい', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari detail? Ini juga rinci.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari detail? Ini juga rinci.') ON CONFLICT (id) DO NOTHING;
