INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c5299a8-1763-49a9-b32a-72b220b34b33', '昨日、年れい不詳な美人女性に出会ったんだ。', 'Kemarin, saya bertemu dengan seorang wanita cantik yang usianya tidak diketahui.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c5299a8-1763-49a9-b32a-72b220b34b33', 'ワニカニは、性別不詳のモンスターです。', 'Wanikani adalah monster yang jenis kelaminnya tidak diketahui.') ON CONFLICT DO NOTHING;
