INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c8590937-fad4-4527-ab62-a4f5a88d5cd2', '「もう明日だけど、でも、やっぱり、私たちの結婚式を中止するべきだと思うの。」「僕もそれを言おうと思っていたんだ。」', '"Itu besok, tapi menurutku kita tetap harus membatalkan pernikahan kita." "Kau mengeluarkan kata-kata itu langsung dari mulutku."') ON CONFLICT DO NOTHING;
