INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8e0c409-404f-4df3-becf-291728a51b1c', 'vocabulary', '口笛を吹く', '口笛を吹く', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Anda tahu bahwa 口笛 berarti "bersiul". Jadi, jika Anda meniup peluit, Anda akan bersiul.', 'Anda tahu bahwa 口笛 berarti "bersiul". Jadi, jika Anda meniup peluit, Anda akan bersiul.') ON CONFLICT (id) DO NOTHING;
