INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b4616a6c-3b32-4ab0-9872-7dfde3eb6af6', 'vocabulary', '不機嫌', '不機嫌', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Ingat bagaimana 機嫌 berarti suasana hati? Nah, jika Anda menambahkannya, itu menjadi suasana hati yang buruk. Ini sangat buruk seolah-olah Anda tidak punya mood sama sekali.', 'Ingat bagaimana 機嫌 berarti suasana hati? Nah, jika Anda menambahkannya, itu menjadi suasana hati yang buruk. Ini sangat buruk seolah-olah Anda tidak punya mood sama sekali.') ON CONFLICT (id) DO NOTHING;
