INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e5a4399-e108-400b-bcdd-599c2cf4b9b5', 'この小説は、次号で完結する予定です。', 'Novel ini akan selesai pada edisi berikutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6e5a4399-e108-400b-bcdd-599c2cf4b9b5', 'しつ問しようと思ってたけど、勝手に自こ完結しちゃったんだよね。', 'Saya hendak mengajukan pertanyaan, tetapi akhirnya saya mengambil kesimpulan sendiri.') ON CONFLICT DO NOTHING;
