INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('af09fb69-e1cc-4c11-b497-22184c39e428', 'vocabulary', '尾', '尾', 1, '53c29db3-c52d-4a61-a4e7-5ce6a747dd77', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
