INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('020fcfd2-1e3d-4eab-84f7-8e856f1f2580', '毎日泣いてばかりいるのは虚しい。', 'Percuma saja menangis setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('020fcfd2-1e3d-4eab-84f7-8e856f1f2580', '今日は何だか虚しい気分です。', 'Aku merasa hampa hari ini, entah kenapa.') ON CONFLICT DO NOTHING;
