INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbf51d47-2e92-4ff2-98b6-12fa94b2ecc1', 'コウイチのヘリコプターのラジコンは宙をまって地面にげきとつした。', 'Helikopter yang dikendalikan radio milik Koichi jatuh ke tanah setelah melayang di udara.') ON CONFLICT DO NOTHING;
