INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3bb4d42e-0b6f-4f33-b32f-6f1f1bb0501c', 'クリステンはクイン・ベリルを嫌悪している。', 'Kristen membenci Ratu Beryl.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3bb4d42e-0b6f-4f33-b32f-6f1f1bb0501c', 'コウイチは嫌悪の目で私をにらんできた。', 'Koichi memelototiku dengan ekspresi jijik di matanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3bb4d42e-0b6f-4f33-b32f-6f1f1bb0501c', 'あいつの顔を見るだけで、嫌悪を催す。', 'Melihat wajahnya saja membuatku mendidih karena kebencian.') ON CONFLICT DO NOTHING;
