INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b4d2ad5c-0207-489c-b096-3a2f909ed031', 'radical', '番', 'number', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Radikal ini sama dengan kanji, namun "angka dalam satu rangkaian" terlalu panjang. Mari kita persingkat menjadi angka.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b4d2ad5c-0207-489c-b096-3a2f909ed031', 'Nomor', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f2bb78c6-4325-4068-be1f-f5fdc9b2d372', 'radical', '安', 'cheap', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Radikal ini sama dengan kanji. Artinya murah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f2bb78c6-4325-4068-be1f-f5fdc9b2d372', 'Murah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('af2b0b8b-d918-4983-86f3-46a2053ba7dd', 'radical', '充', 'allocate', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Anda memiliki beberapa kaki dan Anda harus membuangnya ke tempat sampah. Namun Anda akan ketahuan jika memasukkannya ke dalam satu tempat sampah. Cepat, potong dan buang ke tempat sampah lain di sekitar kota. Maka Anda tidak akan pernah tertangkap.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('af2b0b8b-d918-4983-86f3-46a2053ba7dd', 'Alokasikan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2156b216-029c-4b25-b107-5b46bf6f315a', 'radical', '爰', 'football', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Teman Anda tergeletak di tanah dan Anda menginjaknya dengan gerigi sepatu Anda. Tidak ada persahabatan di sini. Ini adalah olahraga sejati yang Anda mainkan. Inilah sepak bola.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2156b216-029c-4b25-b107-5b46bf6f315a', 'Sepak Bola', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d7494290-4321-4b86-90f2-7a772a4e8d97', 'radical', '能', 'ability', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Radikal ini sama dengan kanji. Artinya kemampuan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d7494290-4321-4b86-90f2-7a772a4e8d97', 'Kemampuan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9c7d9c60-8ff2-4c6a-8f47-4bec23d45e94', 'radical', '鬼', 'demon', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Ini adalah setan. Bisakah kamu melihatnya? Dia memiliki wajah gila dan beberapa tentakel memegang sesuatu yang jahat. Cobalah mencari cara untuk melihat setan. Tapi jangan melihatnya terlalu bagus, karena dia akan keluar dari komputer Anda dan memakan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c7d9c60-8ff2-4c6a-8f47-4bec23d45e94', 'Setan', true) ON CONFLICT DO NOTHING;
