INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e3158887-061a-4b84-9a16-2620193a52e4', 'vocabulary', '穴', '穴', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e3158887-061a-4b84-9a16-2620193a52e4', 'Lubang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e3158887-061a-4b84-9a16-2620193a52e4', 'あな', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3158887-061a-4b84-9a16-2620193a52e4', 'はずかしくて、穴があったら入りたいよ！', 'Saya sangat malu, saya berharap saya bisa tenggelam ke lantai!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3158887-061a-4b84-9a16-2620193a52e4', 'あそこのほら穴には、コウモリが住んでいるらしいよ。', 'Saya mendengar bahwa kelelawar tinggal di dalam gua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3158887-061a-4b84-9a16-2620193a52e4', '彼が深くて素晴らしい穴を掘れるのは、持って生まれた才能です。', 'Dia memiliki kemampuan alami untuk menggali lubang yang dalam dan menakjubkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'vocabulary', '穴場', '穴場', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Tempat berlubang inilah yang disebut lubang di dinding. Ini adalah tempat yang terlihat kecil, tersembunyi dan suram, tapi mungkin memiliki makanan yang enak.', 'Tempat berlubang inilah yang disebut lubang di dinding. Ini adalah tempat yang terlihat kecil, tersembunyi dan suram, tapi mungkin memiliki makanan yang enak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'Lubang Di Dinding', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'Little Known Good Place', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'あなば', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'ここは、フグ料理の穴場なんですよ。', 'Ini adalah restoran ikan buntal yang bagus, yang tidak diketahui publik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'このい酒屋、カガヤって言うんだけど、東京でも穴場中の穴場だよ。', 'Restoran Izakaya ini bernama Kagaya dan ini adalah salah satu restoran hole in the wall terbaik di Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3af83b53-ea14-4da3-9aff-666e6b16c65e', 'あのことがあって以来、もう二度とああいう思いをしたくないし、周りにも迷惑をかけたくないので、フグ釣りの穴場に行くことは止めました。', 'Sejak saat itu, saya tidak ingin mengalami pengalaman seperti itu lagi, atau menimbulkan masalah bagi orang lain, jadi saya berhenti pergi ke tempat yang kurang dikenal di mana Anda bisa memancing ikan fugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', 'vocabulary', '鼻の穴', '鼻の穴', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Apa lubang hidungmu? Bagaimana dengan lubang hidungmu?', 'Apa lubang hidungmu? Bagaimana dengan lubang hidungmu?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', 'Lubang hidung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', 'Nose Hole', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', 'はなのあな', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', '「コウイチの鼻の穴の形ってちょっと変じゃない？」「そう？私はかわいいと思うけど。」', '“Bukankah bentuk lubang hidung Koichi agak aneh?” "Benarkah? Menurutku mereka lucu."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', 'コウイチは、鼻血が出てくる時は鼻の穴にチクワをさしこんで止血します。', 'Saat Koichi mengalami mimisan, dia memasukkan kue pasta ikan berbentuk tabung ke dalamnya untuk menghentikannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('daf15757-b4b8-41aa-85eb-6b09526ca13a', '「君の鼻の穴…。」「何？聞こえないわ。」「ええっと、やっぱり何でもないよ。大したことじゃないから。」「教えてくれなきゃだめよ。何を言おうとしてたの？」', '"Lubang hidungmu..." "Apa? Aku tidak bisa mendengarmu." "Yah sudahlah. Bukan apa-apa." “Sekarang kamu harus memberitahuku. Apa yang kamu katakan tadi?”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5fa5404f-57d1-44da-a64e-b5d735d60177', 'vocabulary', '穴子', '穴子', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Anak lubang bukanlah anak lubang yang menyeramkan (tidak yakin bagaimana lagi menjelaskannya). Itu adalah belut conger, sejenis belut enak yang dimakan di Jepang. Mungkin akan lebih mudah untuk mempelajari bacaannya terlebih dahulu, dan menggunakannya, karena pilihan makna yang kedua adalah anago, kata dalam bahasa Jepang untuk itu (juga digunakan dalam bahasa Inggris).', 'Anak lubang bukanlah anak lubang yang menyeramkan (tidak yakin bagaimana lagi menjelaskannya). Itu adalah belut conger, sejenis belut enak yang dimakan di Jepang. Mungkin akan lebih mudah untuk mempelajari bacaannya terlebih dahulu, dan menggunakannya, karena pilihan makna yang kedua adalah anago, kata dalam bahasa Jepang untuk itu (juga digunakan dalam bahasa Inggris).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5fa5404f-57d1-44da-a64e-b5d735d60177', 'Belut Conger', true) ON CONFLICT DO NOTHING;
