INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ddf952ea-df75-46f4-be09-3ee7169b3c7d', '私の両親は、二人とも教師で、めちゃくちゃ古風な保守主義者です。', 'Kedua orang tua saya adalah guru dan sangat konservatif.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d0a8edf1-8caf-4eb7-bd56-40871ebfcdda', 'vocabulary', '敵', '敵', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
