INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d0a8edf1-8caf-4eb7-bd56-40871ebfcdda', '「フグ、あなたはどっちの味方なの？私の敵なの？」「僕は君の味方だよ、サーモン。」', '"Kamu berada di pihak mana, Fugu? Apakah kamu musuhku?" "Aku di pihakmu, Salmon."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('28d7704a-4234-4e87-84c2-9ae60b398d44', 'vocabulary', '素敵', '素敵', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Unsur musuh bukanlah sesuatu yang harus dianggap buruk. Anda harus memiliki "elemen musuh" jika Anda ingin memiliki hal-hal yang indah, melamun, dan indah juga. Ini adalah kata yang bagus ketika Anda berbicara tentang pria yang menurut Anda tidak sopan. Tidak bekerja dengan baik pada perempuan.', 'Unsur musuh bukanlah sesuatu yang harus dianggap buruk. Anda harus memiliki "elemen musuh" jika Anda ingin memiliki hal-hal yang indah, melamun, dan indah juga. Ini adalah kata yang bagus ketika Anda berbicara tentang pria yang menurut Anda tidak sopan. Tidak bekerja dengan baik pada perempuan.') ON CONFLICT (id) DO NOTHING;
