INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28d7704a-4234-4e87-84c2-9ae60b398d44', '彼の他の人を助けたいっていう熱意が、素敵だなって思うのよね。', 'Saya menganggapnya menarik karena antusiasmenya dalam membantu orang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('833a1a17-99ba-4f48-9e4c-998831404b9d', 'vocabulary', '大敵', '大敵', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Musuh terbesar Anda adalah musuh terburuk Anda. Musuh bebuyutanmu.', 'Musuh terbesar Anda adalah musuh terburuk Anda. Musuh bebuyutanmu.') ON CONFLICT (id) DO NOTHING;
