INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5af2ab36-937d-4014-a7c7-a51c2744c5f0', 'しりとりで、コウイチは無敵だ。', 'Koichi tidak terkalahkan di Shiritori.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('72fca1a0-18cc-445b-98ca-49b6caf12efc', 'vocabulary', '挙がる', '挙がる', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Saat Anda mengangkat sesuatu, Anda menyebabkannya naik. Kata kerja ini juga bisa berarti seperti dicantumkan dan dicalonkan. Untuk makna tambahan ini, Anda mungkin ingin membayangkan sesuatu yang masuk dalam daftar atau seseorang yang masuk dalam nominasi, karena daftar dan nominasi selalu menempati urutan teratas.', 'Saat Anda mengangkat sesuatu, Anda menyebabkannya naik. Kata kerja ini juga bisa berarti seperti dicantumkan dan dicalonkan. Untuk makna tambahan ini, Anda mungkin ingin membayangkan sesuatu yang masuk dalam daftar atau seseorang yang masuk dalam nominasi, karena daftar dan nominasi selalu menempati urutan teratas.') ON CONFLICT (id) DO NOTHING;
