INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('53c4b72b-3ede-4b2c-94d7-6e8d906ea5a1', 'vocabulary', '選挙', '選挙', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Anda harus memilih seseorang dan mengangkatnya ke jabatan. Ini adalah pemilu.', 'Anda harus memilih seseorang dan mengangkatnya ke jabatan. Ini adalah pemilu.') ON CONFLICT (id) DO NOTHING;
