INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53c4b72b-3ede-4b2c-94d7-6e8d906ea5a1', 'コウイチは、選挙演説中にブルースを歌って声がつぶれた。', 'Koichi kehilangan suaranya karena menyanyikan lagu blues selama pidato pemilihannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b59a7021-2e0b-4251-947f-bc0f7cda6978', 'vocabulary', '評判', '評判', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Ketika orang mengevaluasi dan menilai Anda di setiap kesempatan, itu berarti Anda memiliki reputasi yang cukup baik, dan tentu saja ketenaran. Bukankah akan sangat buruk jika orang mengevaluasi dan menghakimi Anda 24/7? Memiliki reputasi atau ketenaran seperti itu akan sulit.', 'Ketika orang mengevaluasi dan menilai Anda di setiap kesempatan, itu berarti Anda memiliki reputasi yang cukup baik, dan tentu saja ketenaran. Bukankah akan sangat buruk jika orang mengevaluasi dan menghakimi Anda 24/7? Memiliki reputasi atau ketenaran seperti itu akan sulit.') ON CONFLICT (id) DO NOTHING;
