INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a525881c-9de4-49db-8956-f1d6bc9a55c2', 'vocabulary', '素材', '素材', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Saat Anda ingin menggunakan elemen paling dasar dari suatu bahan, Anda akan mendapatkan bahan mentah. Mungkin itu bahan mentah yang akan Anda gunakan untuk membangun rumah. Mungkin itu bahan mentah yang Anda perlukan untuk membuat sup yang enak. Bagaimanapun, mereka (belum) belum banyak tersentuh.', 'Saat Anda ingin menggunakan elemen paling dasar dari suatu bahan, Anda akan mendapatkan bahan mentah. Mungkin itu bahan mentah yang akan Anda gunakan untuk membangun rumah. Mungkin itu bahan mentah yang Anda perlukan untuk membuat sup yang enak. Bagaimanapun, mereka (belum) belum banyak tersentuh.') ON CONFLICT (id) DO NOTHING;
