INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d1fb458-7a16-4de2-b88b-cc813ecbd4a1', '検査の結果、エンジンには何のいじょうも認められませんでした。', 'Setelah diperiksa, kami tidak menemukan ada yang salah dengan mesinnya.') ON CONFLICT DO NOTHING;
