INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b426002-36d1-41a6-8e80-e2bc10e180ac', 'vocabulary', '審判', '審判', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Kata ini mengandung hakim dan hakim, jadi ada kaitannya dengan penghakiman. Biasanya digunakan dalam olahraga, jadi wasit atau wasitnya, tergantung olahraga pilihan Anda.', 'Kata ini mengandung hakim dan hakim, jadi ada kaitannya dengan penghakiman. Biasanya digunakan dalam olahraga, jadi wasit atau wasitnya, tergantung olahraga pilihan Anda.') ON CONFLICT (id) DO NOTHING;
