INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9384c701-3a4f-496e-8c01-3a4b6a3c116e', 'vocabulary', '正義', '正義', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Kebenaran yang benar selalu merupakan kebenaran Anda. Itu adalah bentuk keadilan Anda.', 'Kebenaran yang benar selalu merupakan kebenaran Anda. Itu adalah bentuk keadilan Anda.') ON CONFLICT (id) DO NOTHING;
