INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('40a6009b-ed6e-497b-95c3-8c9f231a4294', 'vocabulary', '誕生', '誕生', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Melahirkan kehidupan! Itu adalah kelahiran.', 'Melahirkan kehidupan! Itu adalah kelahiran.') ON CONFLICT (id) DO NOTHING;
