INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40a6009b-ed6e-497b-95c3-8c9f231a4294', '私の誕生日は四月八日で、お釈迦様の誕生日と同じ日です。', 'Ulang tahun saya tanggal 8 April, yang merupakan hari ulang tahun yang sama dengan hari ulang tahun Buddha.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a3483ab7-020d-46d2-aa37-593d0073bb21', 'vocabulary', '脱ぐ', '脱ぐ', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menanggalkan pakaian dan kata kerjanya adalah menanggalkan pakaian.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menanggalkan pakaian dan kata kerjanya adalah menanggalkan pakaian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a3483ab7-020d-46d2-aa37-593d0073bb21', 'Untuk menanggalkan pakaian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a3483ab7-020d-46d2-aa37-593d0073bb21', 'To Take Off Clothes', false) ON CONFLICT DO NOTHING;
