INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a3483ab7-020d-46d2-aa37-593d0073bb21', '「分かったよ。気温が何度だろうが、服を脱いでやるよ。」「いいぞ。その意気だ。」', '"Baiklah, aku akan melepas pakaianku tidak peduli berapa suhunya." "Bagus! Itulah semangatnya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc255461-65d8-4dbe-a519-1b929d1e174d', 'vocabulary', '脱線', '脱線', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Saat Anda melepaskan pakaian dari garis itu seperti Anda mengupas sesuatu dari garis itu, pergi ke arah lain, dan kemudian menyebabkan penyimpangan pada apa pun yang ada di garis itu. Ini seperti ketika Anda sedang berbicara dan Anda ngelantur. Bayangkan pidato Anda sebagai sebuah baris. Kemudian, buka pakaian sebagian dan biarkan terlepas. Itu adalah penyimpangan Anda.', 'Saat Anda melepaskan pakaian dari garis itu seperti Anda mengupas sesuatu dari garis itu, pergi ke arah lain, dan kemudian menyebabkan penyimpangan pada apa pun yang ada di garis itu. Ini seperti ketika Anda sedang berbicara dan Anda ngelantur. Bayangkan pidato Anda sebagai sebuah baris. Kemudian, buka pakaian sebagian dan biarkan terlepas. Itu adalah penyimpangan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cc255461-65d8-4dbe-a519-1b929d1e174d', 'Penyimpangan', true) ON CONFLICT DO NOTHING;
