INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc255461-65d8-4dbe-a519-1b929d1e174d', 'その電車は、運転手のとっさの判断で、脱線をまぬがれました。', 'Kereta mampu menghindari tergelincir karena keputusan cepat masinis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc255461-65d8-4dbe-a519-1b929d1e174d', '話が脱線しました。', 'Saya menyimpang dari topik pembicaraan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc255461-65d8-4dbe-a519-1b929d1e174d', '電車が脱線しましたが、怪我人はありませんでした。', 'Kereta tergelincir, namun tidak ada yang terluka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4532c4a3-6ecf-4045-82b8-48dd10a538d8', 'vocabulary', '脱字', '脱字', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Surat yang tidak dipakai adalah surat yang hilang. Itu adalah karakter yang dihilangkan atau kata yang dihilangkan.', 'Surat yang tidak dipakai adalah surat yang hilang. Itu adalah karakter yang dihilangkan atau kata yang dihilangkan.') ON CONFLICT (id) DO NOTHING;
