INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4532c4a3-6ecf-4045-82b8-48dd10a538d8', '誤字脱字を見つけたら、遠慮せずに教えてくださいね。', 'Jangan takut untuk memberi tahu saya jika Anda menemukan kata-kata yang salah eja atau hilang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36b65a4c-3e38-480c-939b-4ffa9d36f5a3', 'vocabulary', '脱走する', '脱走する', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Anda menanggalkan pakaian dan keluar dari ruangan itu. Anda harus melepas pakaian Anda untuk melarikan diri, tapi sekarang Anda bisa lari dan mulai melarikan diri. Bayangkan saja ada semacam alat yang menahan Anda di tempat melalui pakaian Anda, dan Anda harus melepaskan diri darinya dengan melepas pakaian tersebut. Sekarang bayangkan melarikan diri dari tempat itu dalam keadaan telanjang. Melarikan diri!', 'Anda menanggalkan pakaian dan keluar dari ruangan itu. Anda harus melepas pakaian Anda untuk melarikan diri, tapi sekarang Anda bisa lari dan mulai melarikan diri. Bayangkan saja ada semacam alat yang menahan Anda di tempat melalui pakaian Anda, dan Anda harus melepaskan diri darinya dengan melepas pakaian tersebut. Sekarang bayangkan melarikan diri dari tempat itu dalam keadaan telanjang. Melarikan diri!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36b65a4c-3e38-480c-939b-4ffa9d36f5a3', 'Untuk Melarikan Diri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36b65a4c-3e38-480c-939b-4ffa9d36f5a3', 'To Flee', false) ON CONFLICT DO NOTHING;
