INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36b65a4c-3e38-480c-939b-4ffa9d36f5a3', '重い刑罰を言い渡された犯罪者が、刑務所から脱走した。', 'Penjahat yang mendapat hukuman berat kabur dari penjara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b413264-a141-4493-824b-faa894f40c84', 'vocabulary', '脱税', '脱税', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Membuka pakaian pajak Anda berarti membuangnya. Buang saja, siapa yang membutuhkannya? Saya tidak akan membayar pajak tersebut, oleh karena itu saya melakukan penghindaran pajak.', 'Membuka pakaian pajak Anda berarti membuangnya. Buang saja, siapa yang membutuhkannya? Saya tidak akan membayar pajak tersebut, oleh karena itu saya melakukan penghindaran pajak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1b413264-a141-4493-824b-faa894f40c84', 'Penghindaran Pajak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1b413264-a141-4493-824b-faa894f40c84', 'だつぜい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b413264-a141-4493-824b-faa894f40c84', '私は小さい頃、両親から親切な人になるよう教わりましたが、二人は脱税容疑で逮捕されました。', 'Orang tua saya mengajari saya bagaimana menjadi orang baik ketika saya masih kecil, namun mereka ditangkap atas tuduhan penggelapan pajak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f0ff39b9-94f7-4b62-89ef-e4405769b595', 'vocabulary', '宮', '宮', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Kuil Shinto yang kamu tinggali ini? Ternyata Anda masuk ke dalam dan secara ajaib berubah menjadi istana yang menakjubkan ini. Wow! Saya benar-benar menjadi biksu Shinto.', 'Kuil Shinto yang kamu tinggali ini? Ternyata Anda masuk ke dalam dan secara ajaib berubah menjadi istana yang menakjubkan ini. Wow! Saya benar-benar menjadi biksu Shinto.') ON CONFLICT (id) DO NOTHING;
