INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7080000a-b7dd-4f7b-8fd1-17afa173f715', '友人が、県営プールまで案内してくれました。', 'Teman saya membimbing saya ke kolam prefektur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7080000a-b7dd-4f7b-8fd1-17afa173f715', '先生の案内で学校を見て回った後、入学案内をわたされました。', 'Setelah guru membimbing kami berkeliling sekolah, kami diberi panduan penerimaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7080000a-b7dd-4f7b-8fd1-17afa173f715', '「二人なんですが、席は空いていますか？」「お席にご案内するまで少しお待ちください。」', '"Apakah kamu punya meja untuk dua orang?" “Mohon tunggu sebentar, dan saya akan memandu Anda ke tempat duduk Anda.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae63ae3e-67da-4156-8232-f3b17c19a033', 'vocabulary', '案外', '案外', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Sesuatu yang terjadi di luar rencana adalah sesuatu yang terjadi secara tidak terduga.', 'Sesuatu yang terjadi di luar rencana adalah sesuatu yang terjadi secara tidak terduga.') ON CONFLICT (id) DO NOTHING;
