INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae63ae3e-67da-4156-8232-f3b17c19a033', '日本語学習は私にはかなりハードルが高いんじゃないかと思っていたんですが、案外そうでもなかったです。', 'Saya pikir belajar bahasa Jepang akan sangat sulit bagi saya, namun di luar dugaan, ternyata tidak seburuk itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb56a19e-ba62-4e42-bc6e-9e6e6bfb27d4', 'vocabulary', '価', '価', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
