INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb56a19e-ba62-4e42-bc6e-9e6e6bfb27d4', 'その価には同意できないな。タダ同然じゃないか。', 'Saya tidak setuju dengan harga ini. Itu tidak benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc007bd3-f176-4864-92b5-7aa94f44e672', 'vocabulary', '物価', '物価', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Sesuatu yang bernilai mempunyai harga. Ini hanyalah harga umum suatu barang. Dengan kata lain, harga komoditas atau biaya hidup.', 'Sesuatu yang bernilai mempunyai harga. Ini hanyalah harga umum suatu barang. Dengan kata lain, harga komoditas atau biaya hidup.') ON CONFLICT (id) DO NOTHING;
