INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc007bd3-f176-4864-92b5-7aa94f44e672', '日本では、物価が上がり始めたようだ。', 'Di Jepang, tampaknya harga sudah mulai naik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54bca88a-a0f2-4980-89db-70099ce68885', 'vocabulary', '地価', '地価', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Nilai tanah adalah nilai tanah.', 'Nilai tanah adalah nilai tanah.') ON CONFLICT (id) DO NOTHING;
