INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fe49bb89-3618-441a-b073-18a1ee279eff', 'vocabulary', '大統領', '大統領', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Saat Anda berkuasa besar atas suatu wilayah, Anda mungkin adalah pemimpin yang cukup hebat. Seorang presiden, mungkin?', 'Saat Anda berkuasa besar atas suatu wilayah, Anda mungkin adalah pemimpin yang cukup hebat. Seorang presiden, mungkin?') ON CONFLICT (id) DO NOTHING;
