INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('079289b0-acf4-4b19-b45b-cff5b911d356', '彼女は、彼に態と気のないふりをした。', 'Dia sengaja berpura-pura tidak peduli padanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d54ecf7-a7e8-47d7-9e2b-62105d7df4f3', 'vocabulary', '態度', '態度', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Penampilan Anda memiliki banyak derajat. Anda memutarnya, dan Anda menunjukkan satu sikap. Kemudian Anda menolaknya sedikit dan Anda memiliki perilaku lain. Begitu banyak sopan santun untuk dipamerkan.', 'Penampilan Anda memiliki banyak derajat. Anda memutarnya, dan Anda menunjukkan satu sikap. Kemudian Anda menolaknya sedikit dan Anda memiliki perilaku lain. Begitu banyak sopan santun untuk dipamerkan.') ON CONFLICT (id) DO NOTHING;
