INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d6b2fdda-76d4-4bdc-85e6-19edf644c245', 'vocabulary', '誕生日', '誕生日', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Ingat bagaimana 誕生 kelahiran? Jika Anda menambahkan hari di sana, Anda berulang tahun. Selamat ulang tahun!', 'Ingat bagaimana 誕生 kelahiran? Jika Anda menambahkan hari di sana, Anda berulang tahun. Selamat ulang tahun!') ON CONFLICT (id) DO NOTHING;
