INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d39547c-947c-4d2c-bfdc-72c4535300cb', 'この番組はごらんのスポンサーの提供でお送りします。', 'Program ini dipersembahkan oleh sponsor berikut.') ON CONFLICT DO NOTHING;
