INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc692759-01d1-425e-ad29-bb2c230c14a8', 'vocabulary', '対応', '対応', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Anda merespons versus orang lain untuk berinteraksi dengan mereka. Jika salah satu dari Anda berhenti merespons, begitu pula korespondensinya.', 'Anda merespons versus orang lain untuk berinteraksi dengan mereka. Jika salah satu dari Anda berhenti merespons, begitu pula korespondensinya.') ON CONFLICT (id) DO NOTHING;
