INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc692759-01d1-425e-ad29-bb2c230c14a8', 'あの医者の対応は素晴らしかった。', 'Berinteraksi dengan dokter itu sungguh luar biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b82133f8-289a-46fa-8906-c91e7f30d89e', 'vocabulary', '楽天主義', '楽天主義', 1, '8b528bd8-b23e-4a72-a200-d27e02a6a4e0', 'Anda tahu bahwa 主義 adalah "-isme." Jika Anda menambahkannya menjadi nyaman seperti berada di surga maka Anda memiliki banyak optimisme. Anda yakin Anda akan baik-baik saja dalam situasi apa pun!
