INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b82133f8-289a-46fa-8906-c91e7f30d89e', '兄は人付き合いがありませんが、楽天主義だから自分ではあまり気にしていません。', 'Kakak laki-laki saya tidak memiliki kehidupan sosial, tapi dia tidak terlalu keberatan karena optimismenya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b82133f8-289a-46fa-8906-c91e7f30d89e', 'あいつほど楽天主義だなあと思うやつはいない。', 'Saya tidak berpikir ada orang yang lebih optimis daripada dia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b82133f8-289a-46fa-8906-c91e7f30d89e', 'フグは評判通りの楽天主義者だね。', 'Fugu optimis seperti yang dikatakan orang.') ON CONFLICT DO NOTHING;
