INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2e9a3287-7543-4b88-b032-98bd5d03a776', 'radical', '乃', 'stairs', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Lihat bentuk tangga di sisi kanan? Perhatikan juga tangga tersebut tertahan oleh pilar atau balok atau semacamnya, untuk memastikan tangga tidak runtuh begitu saja saat Anda menaikinya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2e9a3287-7543-4b88-b032-98bd5d03a776', 'Tangga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('62279f48-348f-4077-bd34-be8f4264e467', 'radical', '制', 'control', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Radikal ini sama dengan kanji. Artinya kendali.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('62279f48-348f-4077-bd34-be8f4264e467', 'Kontrol', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('07a1ff06-3165-4bff-818c-582b92ccd8d3', 'radical', '禹', 'mantis', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Radikal ini memiliki slide, kepala, dan serangga di dalamnya. Serangga manakah yang akan memenggal kepala Anda dalam hitungan detik dan kemudian memakannya? Belalang sembah yang menakutkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('07a1ff06-3165-4bff-818c-582b92ccd8d3', 'belalang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f037a24e-f420-494b-be64-445ded96532e', 'radical', '巴', 'bed', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Anda harus menyelesaikan garis di sisi kanan dalam pikiran Anda, tetapi lihat tempat tidur persegi panjang dan bantal? Ini benar-benar sebuah tempat tidur. Garis yang hilang itu adalah tempat Anda menarik kembali seprai ketika Anda bangun pagi ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f037a24e-f420-494b-be64-445ded96532e', 'Tempat tidur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('133483bd-38f5-40af-9c5f-2492431dbc81', 'radical', '受', 'accept', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Radikal ini sama dengan kanji. Artinya menerima.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('133483bd-38f5-40af-9c5f-2492431dbc81', 'Terima', true) ON CONFLICT DO NOTHING;
