INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('835f1f8e-23db-48c1-94a8-10d5a6ae04e3', 'vocabulary', '看護師', '看護師', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Seorang ahli yang mengawasi dan membela orang sepanjang waktu adalah perawat. Itulah yang dilakukan perawat, 24/7. Mereka harus memeriksa orang-orang, menjaga kesehatan mereka, dan mengawasi mereka, memastikan mereka baik-baik saja. Pekerjaan yang sulit.', 'Seorang ahli yang mengawasi dan membela orang sepanjang waktu adalah perawat. Itulah yang dilakukan perawat, 24/7. Mereka harus memeriksa orang-orang, menjaga kesehatan mereka, dan mengawasi mereka, memastikan mereka baik-baik saja. Pekerjaan yang sulit.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('835f1f8e-23db-48c1-94a8-10d5a6ae04e3', 'Perawat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('835f1f8e-23db-48c1-94a8-10d5a6ae04e3', 'かんごし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('835f1f8e-23db-48c1-94a8-10d5a6ae04e3', 'その看護師は患者に作り笑いをした。', 'Perawat itu berpura-pura tertawa kepada pasiennya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('89f61f60-985d-4dce-8e9c-833f0ef6b719', 'vocabulary', '裁く', '裁く', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghakimi, jadi versi verbanya adalah menghakimi.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghakimi, jadi versi verbanya adalah menghakimi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('89f61f60-985d-4dce-8e9c-833f0ef6b719', 'Untuk Menilai', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('89f61f60-985d-4dce-8e9c-833f0ef6b719', 'さばく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('89f61f60-985d-4dce-8e9c-833f0ef6b719', 'コウイチの罪は最高裁判所で裁かれる予定です。', 'Kejahatan Koichi akan diadili di Mahkamah Agung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('89f61f60-985d-4dce-8e9c-833f0ef6b719', '裁判所はできるだけ公平に裁かなければなりませんが、裁判官も人なので難しいこともあります。', 'Pengadilan harus mengambil keputusan setidak memihak, namun hal ini sulit dilakukan karena hakim juga manusia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('89f61f60-985d-4dce-8e9c-833f0ef6b719', 'その男が殺人犯であることがわかったが、時効を迎えているので法的には誰も彼を裁く事ができない。', 'Ternyata pria tersebut adalah seorang pembunuh, namun batas waktu sudah habis, sehingga tidak ada seorang pun yang secara hukum dapat menghakiminya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ae65129-f797-4a9b-9a62-73aba3b9b76e', 'vocabulary', '裁判', '裁判', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Anda akan dihakimi dua kali. Hakim dan hakim lagi. Satu kali oleh juri dan satu kali lagi oleh juri. Ini adalah keseluruhan cobaan di sini.', 'Anda akan dihakimi dua kali. Hakim dan hakim lagi. Satu kali oleh juri dan satu kali lagi oleh juri. Ini adalah keseluruhan cobaan di sini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0ae65129-f797-4a9b-9a62-73aba3b9b76e', 'Percobaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0ae65129-f797-4a9b-9a62-73aba3b9b76e', 'さいばん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ae65129-f797-4a9b-9a62-73aba3b9b76e', 'できるだけ、裁判するのはさけたいんですよ。', 'Saya ingin menghindari persidangan, jika memungkinkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ae65129-f797-4a9b-9a62-73aba3b9b76e', '裁判の費用がいくらぐらいかかるか知っていますか？', 'Tahukah Anda berapa biaya uji cobanya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ae65129-f797-4a9b-9a62-73aba3b9b76e', 'この貯金箱には小遣いからためた80ドルが入っているんだけど、裁判を起こすには到底足りないと思うんだよね。', 'Celengan ini berisi delapan puluh dolar yang saya tabung dari uang saku saya, tapi saya rasa itu tidak cukup untuk mengajukan tuntutan hukum.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d7f8339-61fb-465c-8a16-08aa4219cd18', 'vocabulary', '崎', '崎', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
