INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d7f8339-61fb-465c-8a16-08aa4219cd18', '今日志賀直哉の小説『城の崎にて』を読み始めました。', 'Saya mulai membaca novel Naoya Shiga, "Di Cape Kinosaki" hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('622eceac-9b14-45fb-891b-fe799f9bc690', 'vocabulary', '川崎', '川崎', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Ini adalah salah satu kata yang lebih mudah diketahui jika Anda langsung membaca. Mengapa? Karena itu nama sebuah kota/sebuah nama. Itu Kawasaki.', 'Ini adalah salah satu kata yang lebih mudah diketahui jika Anda langsung membaca. Mengapa? Karena itu nama sebuah kota/sebuah nama. Itu Kawasaki.') ON CONFLICT (id) DO NOTHING;
