INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7691f07-8320-4427-b648-10a652298f54', '「私、もう何週間もフグを見てないわ。」「ほら、見て。ちょうど今フグが来たわよ。」「あら、噂をすれば影がさす、ね。こんにちは。私たち、今ちょうどあなたのことを話していたのよ。」', '"Aku sudah berminggu-minggu tidak bertemu Fugu." "Oh, lihat. Fugu datang sekarang." "Nah, bicaralah tentang iblis. Hai, yang disana. Kami baru saja membicarakanmu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29632fef-d5f0-4a3f-b390-824345ecc40d', 'vocabulary', '響く', '響く', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya gema, jadi kata kerjanya adalah menggemakan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya gema, jadi kata kerjanya adalah menggemakan.') ON CONFLICT (id) DO NOTHING;
