INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29632fef-d5f0-4a3f-b390-824345ecc40d', 'おこったコウイチの声が部屋中に響いた。', 'Suara marah Koichi bergema di seluruh ruangan.') ON CONFLICT DO NOTHING;
