INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0eeabeb9-53fa-4b11-82da-d407796880fc', '残業は健康に悪影響を及ぼす可能性があるということを考えた方がいいですよ。', 'Anda harus mempertimbangkan bahwa bekerja lembur mungkin berdampak negatif pada kesehatan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a629e931-20a1-409c-bb4b-ab54c251eae7', 'vocabulary', '票', '票', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Bisa juga berupa pemungutan suara, karena itulah yang cenderung terjadi pada pemungutan suara.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Bisa juga berupa pemungutan suara, karena itulah yang cenderung terjadi pada pemungutan suara.') ON CONFLICT (id) DO NOTHING;
