INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3524d5e5-bdad-4ecc-a1c7-47af1914692d', 'vocabulary', '先輩', '先輩', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Temanku yang datang sebelumku adalah seniorku, senpaiku (せんぱい).', 'Temanku yang datang sebelumku adalah seniorku, senpaiku (せんぱい).') ON CONFLICT (id) DO NOTHING;
