INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d6d79e2e-a1ab-4848-b864-48bba74d14fa', 'vocabulary', '年輩', '年輩', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Seseorang yang merupakan kawan bertahun-tahun telah ada selama bertahun-tahun tersebut. Mereka adalah orang-orang lanjut usia.', 'Seseorang yang merupakan kawan bertahun-tahun telah ada selama bertahun-tahun tersebut. Mereka adalah orang-orang lanjut usia.') ON CONFLICT (id) DO NOTHING;
