INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6d79e2e-a1ab-4848-b864-48bba74d14fa', '年輩の上司が、牛の乳搾り体験の費用を払ってくれた。', 'Bos saya yang sudah lanjut usia membayar saya untuk mendapatkan pengalaman memerah susu sapi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('90a52ab7-95ae-4d2b-a046-8ae130f6c5bd', 'vocabulary', '隠す', '隠す', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menyembunyikan dan versi vocab verbanya adalah menyembunyikan sesuatu atau menyembunyikan sesuatu.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya menyembunyikan dan versi vocab verbanya adalah menyembunyikan sesuatu atau menyembunyikan sesuatu.') ON CONFLICT (id) DO NOTHING;
