INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90a52ab7-95ae-4d2b-a046-8ae130f6c5bd', 'コウイチはドアにかぎを掛けた後、そのかぎを隠した。', 'Koichi mengunci pintu dan kemudian menyembunyikan kuncinya.') ON CONFLICT DO NOTHING;
