INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90a52ab7-95ae-4d2b-a046-8ae130f6c5bd', '秘密の花園への入口は隠されている。', 'Pintu masuk ke Secret Garden tersembunyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b0adafd7-b32e-4123-ab0a-79c39af2c0ad', 'vocabulary', '隠居', '隠居', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Anda bersembunyi tetapi Anda masih hidup. Anda telah menjalani hidup Anda, jadi sekarang saatnya bersembunyi dan menikmati masa pensiun Anda dengan mundur dari kehidupan kerja.
