INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0adafd7-b32e-4123-ab0a-79c39af2c0ad', '私の父は隠居生活をエンジョイしていますよ。', 'Ayah saya telah menikmati masa pensiunnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0adafd7-b32e-4123-ab0a-79c39af2c0ad', 'この里は、かつては隠居の地として人気がありました。', 'Desa ini dulunya merupakan tempat yang populer untuk retret.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0adafd7-b32e-4123-ab0a-79c39af2c0ad', 'お前は本当に隠居したいのか？', 'Apakah Anda benar-benar ingin pensiun?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8b8d7de6-eff3-4fe8-b40e-0d2c403226da', 'vocabulary', '施設', '施設', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Silakan laksanakan tugas dan dirikan lembaganya. Melaksanakan dan menetapkan sesuatu berarti melembagakannya juga. Apa yang Anda lembagakan? Sebuah institusi.', 'Silakan laksanakan tugas dan dirikan lembaganya. Melaksanakan dan menetapkan sesuatu berarti melembagakannya juga. Apa yang Anda lembagakan? Sebuah institusi.') ON CONFLICT (id) DO NOTHING;
