INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8b8d7de6-eff3-4fe8-b40e-0d2c403226da', '児童養護施設の仕事がきついので辞めたいんですが、一方で今まで築き上げてきた関係も壊したくはないんです。', 'Aku ingin berhenti dari pekerjaanku di panti asuhan karena ini terlalu berat, tapi di saat yang sama, aku tidak ingin mengorbankan apapun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e7a52d3e-b664-4dd8-b58d-447bb34da512', 'vocabulary', '長崎県', '長崎県', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Prefektur Long Cape. Ini akan lebih masuk akal ketika Anda melihat bacaannya. Petunjuk: Ini Prefektur Nagasaki.', 'Prefektur Long Cape. Ini akan lebih masuk akal ketika Anda melihat bacaannya. Petunjuk: Ini Prefektur Nagasaki.') ON CONFLICT (id) DO NOTHING;
