INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7a52d3e-b664-4dd8-b58d-447bb34da512', '私は長崎県の出身で、家族の墓も全部そこにあります。', 'Saya berasal dari prefektur Nagasaki dan kuburan keluarga saya juga ada di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e407f08c-cac5-4d2a-9f4a-3c14254f5976', 'vocabulary', '載せる', '載せる', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Anda ingat bagaimana 載る "diterbitkan"? Yang ini untuk mempublikasikan, seperti Anda melakukannya sendiri. Anda mengetahui hal ini karena Anda (せる) menerbitkannya sendiri, sehingga Anda dapat menerbitkan sesuatu (tidak ada penerbit yang mau menerima omong kosong tentang vampir itu, maaf).', 'Anda ingat bagaimana 載る "diterbitkan"? Yang ini untuk mempublikasikan, seperti Anda melakukannya sendiri. Anda mengetahui hal ini karena Anda (せる) menerbitkannya sendiri, sehingga Anda dapat menerbitkan sesuatu (tidak ada penerbit yang mau menerima omong kosong tentang vampir itu, maaf).') ON CONFLICT (id) DO NOTHING;
