INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e407f08c-cac5-4d2a-9f4a-3c14254f5976', '自分の写真をインターネットに載せるのには、ちょっと抵抗があります。', 'Saya sedikit tidak nyaman mempublikasikan foto saya sendiri di Internet.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c265a6a6-7bfe-4ec6-8655-c30c906a6a21', 'vocabulary', '授業', '授業', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Bisnis instruksi adalah ketika Anda memberikan pelajaran atau kelas kepada seseorang.', 'Bisnis instruksi adalah ketika Anda memberikan pelajaran atau kelas kepada seseorang.') ON CONFLICT (id) DO NOTHING;
