INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58e3307b-d68d-494d-a5bc-d04c08067cee', '世界的な景気の減速は、私たちの株式市場にも影響を及ぼした。', 'Perlambatan global juga berdampak signifikan pada pasar saham kita.') ON CONFLICT DO NOTHING;
