INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('540dac1d-4e7c-4d2e-a2c7-d25ca72f02d8', '織り物の製造元でアメリカで事業を拡張しているところがいくつかあるって聞いたんだけど、一体どうやって拡張してるのか知ってる？', 'Saya mendengar beberapa produsen tekstil memperluas operasinya di Amerika Serikat. Tahukah Anda bagaimana mereka melakukannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7d7e795-c02b-4e7c-a262-699bd5bf88af', 'vocabulary', '隠れる', '隠れる', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', '隠す berarti "bersembunyi". 隠れる harus disembunyikan. Anda tahu bahwa ini adalah versi di mana sesuatu disembunyikan (dan Anda tidak menyembunyikannya) karena jarang (れる) Anda menemukan sesuatu yang disembunyikan (bukan oleh Anda).', '隠す berarti "bersembunyi". 隠れる harus disembunyikan. Anda tahu bahwa ini adalah versi di mana sesuatu disembunyikan (dan Anda tidak menyembunyikannya) karena jarang (れる) Anda menemukan sesuatu yang disembunyikan (bukan oleh Anda).') ON CONFLICT (id) DO NOTHING;
