INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7d7e795-c02b-4e7c-a262-699bd5bf88af', '「やばい。多分あれ元彼だ。速く隠れなきゃ。」「まじで？フグってこと？」「違うよ。サメだよ。」「 サメ？サメって誰のこと？てか、あんた元カレ多すぎだっつーの！」', '"Oh tidak. Sepertinya aku baru saja melihat mantanku. Cepat, sembunyi!" "Apa? Maksudmu Fugu?" "Tidak. Hiu." "Hiu? Siapa Hiu? Kamu punya terlalu banyak mantan!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8ca93f2-b060-4a5d-aa7b-4f273fb5554a', 'vocabulary', '頑張れ', '頑張れ', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Ingat 頑張る? Ini hanyalah bentuk lain dari itu, kali ini Anda menyuruh seseorang untuk 頑張る, menjadikan kata ini memiliki arti seperti keberuntungan atau lakukan yang terbaik! Omong-omong, 頑張れ, kamu!', 'Ingat 頑張る? Ini hanyalah bentuk lain dari itu, kali ini Anda menyuruh seseorang untuk 頑張る, menjadikan kata ini memiliki arti seperti keberuntungan atau lakukan yang terbaik! Omong-omong, 頑張れ, kamu!') ON CONFLICT (id) DO NOTHING;
