INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8ca93f2-b060-4a5d-aa7b-4f273fb5554a', 'まあ、結果を気にせずに、頑張れよ！', 'Nah, jangan khawatir dengan hasilnya, cobalah yang terbaik!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e1f3bb9-53ee-4357-ac9f-b2b50a09d88b', 'vocabulary', '大規模', '大規模', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Ingat bagaimana 規模 adalah skala? Ya, ini skala besar, yaitu dalam skala besar.', 'Ingat bagaimana 規模 adalah skala? Ya, ini skala besar, yaitu dalam skala besar.') ON CONFLICT (id) DO NOTHING;
