INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3593e08b-6cab-43f5-be16-6346ae40870a', 'vocabulary', '狭める', '狭める', 1, 'b66b088f-90b1-44e8-aa3c-0ccc4f2f9bd7', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya sempit, jadi versi kata kerjanya adalah menyempit.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya sempit, jadi versi kata kerjanya adalah menyempit.') ON CONFLICT (id) DO NOTHING;
