INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', 'vocabulary', '刺激', '刺激', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Anda memiliki semua tusukan kecil yang sangat keras terhadap Anda. Mereka kesemutan seperti orang gila. Ini merupakan rangsangan yang cukup besar pada tubuh Anda. *kesemutan kesemutan.*', 'Anda memiliki semua tusukan kecil yang sangat keras terhadap Anda. Mereka kesemutan seperti orang gila. Ini merupakan rangsangan yang cukup besar pada tubuh Anda. *kesemutan kesemutan.*') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', 'Stimulasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', 'Encourage', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', 'Excite', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', 'しげき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', '周りに若い人が多いので、私も刺激を受けています。', 'Karena ada begitu banyak anak muda di sekitarku, itu juga merangsang bagiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', 'コウイチをこれ以上刺激しないで。何しでかすか分からないよ。', 'Jangan menyemangati Koichi lebih jauh. Anda tidak pernah tahu apa yang mungkin dia lakukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('658dac74-6b2a-485f-b310-0cdfeb253f4f', '彼女には会ったんだけど、お互いにいまいちピンと来なかったんだよな。俺としては、もうちょっと刺激的な女性の方がいいっていうかさ。', 'Aku bertemu dengannya, tapi kami tidak terlalu cocok. Bagi saya, saya lebih suka memiliki wanita yang sedikit lebih menarik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bfa87f7f-a323-4c4a-bbf3-e7a92a0539fd', 'vocabulary', '創造', '創造', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Membuat! Membuat! Jika Anda melakukan ini, Anda sedang melakukan penciptaan.', 'Membuat! Membuat! Jika Anda melakukan ini, Anda sedang melakukan penciptaan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bfa87f7f-a323-4c4a-bbf3-e7a92a0539fd', 'Penciptaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bfa87f7f-a323-4c4a-bbf3-e7a92a0539fd', 'そうぞう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bfa87f7f-a323-4c4a-bbf3-e7a92a0539fd', '神様は本当に人間を創造したんですか。', 'Benarkah Tuhan menciptakan manusia?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bfa87f7f-a323-4c4a-bbf3-e7a92a0539fd', '常に新たな創造を求められます。', 'Kita selalu dituntut untuk menciptakan sesuatu yang baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bfa87f7f-a323-4c4a-bbf3-e7a92a0539fd', '私は、天地創造のを目の当たりにしました...というのはウソです。', 'Saya menyaksikan Penciptaan... oke itu bohong.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c42990a-a432-456c-90d6-02280d300722', 'vocabulary', '独創', '独創', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Anda sendirian dalam apa yang mampu Anda ciptakan. Tidak ada orang lain yang bisa berkreasi seperti Anda, karena Anda memiliki orisinalitas dan kreativitas di pihak Anda.', 'Anda sendirian dalam apa yang mampu Anda ciptakan. Tidak ada orang lain yang bisa berkreasi seperti Anda, karena Anda memiliki orisinalitas dan kreativitas di pihak Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0c42990a-a432-456c-90d6-02280d300722', 'Orisinalitas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0c42990a-a432-456c-90d6-02280d300722', 'Creativity', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0c42990a-a432-456c-90d6-02280d300722', 'どくそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c42990a-a432-456c-90d6-02280d300722', '彼が独創性に欠けていることは非常に残念です。', 'Sangat mengecewakan karena dia kurang orisinalitas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', 'vocabulary', '創立', '創立', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Ciptakan dan pertahankan. Ini adalah pendirian Anda, pendirian Anda.', 'Ciptakan dan pertahankan. Ini adalah pendirian Anda, pendirian Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', 'Pendirian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', 'Founding', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', 'そうりつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', 'コウイチは、死ぬまでにトーフグ大学を創立するつもりだ。', 'Koichi bermaksud mendirikan Universitas Tofugu sebelum dia meninggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', '今日はトーフグの創立記念日なんです。', 'Hari ini adalah hari jadi berdirinya Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e74977ea-cae1-4c53-b289-583534914b12', '電車に乗り遅れて、会社の創立記念のイベントに遅れそうだ。', 'Saya ketinggalan kereta dan saya terlambat menghadiri acara ulang tahun perusahaan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c649d2c3-f749-4a5f-93b0-a458ef225fdc', 'vocabulary', '激励', '激励', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Beberapa dorongan yang kuat adalah apa yang Anda butuhkan. Beberapa dorongan!', 'Beberapa dorongan yang kuat adalah apa yang Anda butuhkan. Beberapa dorongan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c649d2c3-f749-4a5f-93b0-a458ef225fdc', 'Dorongan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c649d2c3-f749-4a5f-93b0-a458ef225fdc', 'げきれい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c649d2c3-f749-4a5f-93b0-a458ef225fdc', 'テレビ番組が放映された後、何百にも及ぶ激励の電話が、数時間に渡って掛かってきた。', 'Setelah acara TV tersebut, ratusan panggilan telepon yang menawarkan dorongan datang berdatangan selama berjam-jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('147d8814-bac4-4ab8-b55e-c125b35c99ea', 'vocabulary', '励ます', '励ます', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mendorong dan versi vocab verbanya adalah mendorong seseorang (atau mendorong).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mendorong dan versi vocab verbanya adalah mendorong seseorang (atau mendorong).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('147d8814-bac4-4ab8-b55e-c125b35c99ea', 'Untuk Mendorong Seseorang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('147d8814-bac4-4ab8-b55e-c125b35c99ea', 'To Cheer Up Someone', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('147d8814-bac4-4ab8-b55e-c125b35c99ea', 'To Encourage', false) ON CONFLICT DO NOTHING;
