INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('147d8814-bac4-4ab8-b55e-c125b35c99ea', '落ち込んでいる人を励ますのは難しい。', 'Sulit untuk menghibur seseorang yang sedang depresi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec47b6ba-ec6b-45fb-be51-377c05eb3daf', 'vocabulary', '独占', '独占', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Anda sendirian dalam apa yang Anda tempati. Tidak seorang pun kecuali Anda yang menempatinya. Anda memiliki monopoli. Anda memonopolinya.', 'Anda sendirian dalam apa yang Anda tempati. Tidak seorang pun kecuali Anda yang menempatinya. Anda memiliki monopoli. Anda memonopolinya.') ON CONFLICT (id) DO NOTHING;
