INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b78639d2-1f5f-4d09-ba8a-c1d7b91e3297', 'vocabulary', '往復', '往復', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Berangkat dan kembalikan diri Anda ke tempat keberangkatan semula. Jika Anda melakukan ini (berangkat dan kembali), Anda memiliki perjalanan pulang pergi.', 'Berangkat dan kembalikan diri Anda ke tempat keberangkatan semula. Jika Anda melakukan ini (berangkat dan kembali), Anda memiliki perjalanan pulang pergi.') ON CONFLICT (id) DO NOTHING;
