INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e64556c7-d834-41c3-8b11-0cf462129270', 'vocabulary', '従業', '従業', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Anda harus mematuhi bisnis Anda. Ketika Anda berada dalam situasi ini, Anda mendapatkan pekerjaan melalui mereka, itulah sebabnya Anda harus mematuhinya (jika Anda tidak bekerja, Anda tidak perlu mendengarkan mereka).', 'Anda harus mematuhi bisnis Anda. Ketika Anda berada dalam situasi ini, Anda mendapatkan pekerjaan melalui mereka, itulah sebabnya Anda harus mematuhinya (jika Anda tidak bekerja, Anda tidak perlu mendengarkan mereka).') ON CONFLICT (id) DO NOTHING;
