INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ce1c4c3e-3347-4a71-b370-5278a7ef05f4', 'vocabulary', '象徴', '象徴', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Suatu fenomena yang merupakan indikasi dari sesuatu yang lain disebut simbol.', 'Suatu fenomena yang merupakan indikasi dari sesuatu yang lain disebut simbol.') ON CONFLICT (id) DO NOTHING;
