INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('daeca793-99f9-4b53-8f8d-6b9faac4247c', 'vocabulary', '怪しい', '怪しい', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat mencurigakan? Juga mencurigakan!', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat mencurigakan? Juga mencurigakan!') ON CONFLICT (id) DO NOTHING;
