INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c849c7e-5ab6-4643-a61e-2c5c148394b5', 'vocabulary', '怪事件', '怪事件', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Sebuah kejadian mencurigakan (事件) selalu memiliki misteri aneh di baliknya. Itu pun selalu berubah menjadi kasus misteri.', 'Sebuah kejadian mencurigakan (事件) selalu memiliki misteri aneh di baliknya. Itu pun selalu berubah menjadi kasus misteri.') ON CONFLICT (id) DO NOTHING;
