INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('40e9b9e4-15e2-42ee-b258-5f870ed2120d', 'vocabulary', '我', '我', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
