INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40e9b9e4-15e2-42ee-b258-5f870ed2120d', '再度のチャンスを与えてもらえ、我にもなく泣いてしまった。', 'Aku menangis sendiri ketika dia memberiku kesempatan lagi.') ON CONFLICT DO NOTHING;
