INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ab1e11d3-ca9a-4944-88a2-5f51e795f534', 'vocabulary', '無我', '無我', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Tidak ada satu pun dari diri saya. Ini semua tentang orang lain. Ini semua tentang sikap tidak mementingkan diri sendiri.', 'Tidak ada satu pun dari diri saya. Ini semua tentang orang lain. Ini semua tentang sikap tidak mementingkan diri sendiri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ab1e11d3-ca9a-4944-88a2-5f51e795f534', 'Tidak mementingkan diri sendiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ab1e11d3-ca9a-4944-88a2-5f51e795f534', 'むが', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab1e11d3-ca9a-4944-88a2-5f51e795f534', 'コウイチはついに無我の境地に達した。', 'Koichi akhirnya mencapai keadaan tidak mementingkan diri sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab1e11d3-ca9a-4944-88a2-5f51e795f534', '自分に優しくない人は、他人に優しくなれないだろう。だから、自分を大切にすることこそが、無我なんだよ。', 'Jika Anda tidak baik pada diri sendiri, Anda tidak akan baik pada orang lain. Jadi, menjaga diri sendiri adalah inti dari sikap tidak mementingkan diri sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab1e11d3-ca9a-4944-88a2-5f51e795f534', '私は鮫に追いかけられて、無我夢中で泳ぎました。', 'Saya diikuti oleh hiu jadi saya tersesat saat berenang untuk hidup saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c729f7ea-a7c3-4cc5-8fa0-3fef7a92bb7f', 'vocabulary', '振る', '振る', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menggoyang dan kata kerja ini bersifat transitif artinya sedang menggoyangkan sesuatu. Jadi kata kerja ini berarti menggoyangkan sesuatu, melambaikan sesuatu, atau mengayunkan sesuatu. Anda akan sering melihatnya dipasangkan dengan 手, seperti dalam 手を振る, yang berarti "melambaikan tangan" atau, seperti yang biasa kita katakan dalam bahasa Inggris, cukup "melambai".
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c729f7ea-a7c3-4cc5-8fa0-3fef7a92bb7f', 'Untuk Mengguncang Sesuatu', true) ON CONFLICT DO NOTHING;
