INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c729f7ea-a7c3-4cc5-8fa0-3fef7a92bb7f', 'よく振ってから飲んでください。', 'Silakan kocok dengan baik sebelum diminum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c729f7ea-a7c3-4cc5-8fa0-3fef7a92bb7f', 'コウイチは首をたてに振ったが、ビエトは首を横に振った。', 'Koichi menganggukkan kepalanya, tapi Viet menggelengkan kepalanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c729f7ea-a7c3-4cc5-8fa0-3fef7a92bb7f', '「彼に振られたなんて信じられない。」「あんた、浮気してたんでしょ。自業自得だよ。」', '"Aku tidak percaya dia putus denganku." "Kamu berselingkuh. Kamulah yang mewujudkannya."') ON CONFLICT DO NOTHING;
