INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4582399a-ee52-4446-9491-7ade42e9090f', 'vocabulary', '不眠症', '不眠症', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Gejala tidak tidur menunjukkan Anda memiliki kelainan yang melibatkan tidak tidur. Itu adalah insomnia.', 'Gejala tidak tidur menunjukkan Anda memiliki kelainan yang melibatkan tidak tidur. Itu adalah insomnia.') ON CONFLICT (id) DO NOTHING;
