INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a371bb2f-06a1-456f-a737-4d7dc7455a21', 'vocabulary', '中途半端', '中途半端', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Ambil jalan tengah, setengah ke pinggir. Anda tidak melakukan apa pun sepenuhnya. Hanya sampai ke tengah. Hanya sampai setengahnya. Tidak sampai ke tepi. Ini benar-benar setengah selesai dan setengah mengecewakanmu.', 'Ambil jalan tengah, setengah ke pinggir. Anda tidak melakukan apa pun sepenuhnya. Hanya sampai ke tengah. Hanya sampai setengahnya. Tidak sampai ke tepi. Ini benar-benar setengah selesai dan setengah mengecewakanmu.') ON CONFLICT (id) DO NOTHING;
