INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8aca4508-763f-4b7d-ac0c-851980cf663d', 'あなたのような創造力のある人と仕事ができることを、とても楽しみにしています。', 'Saya sangat bersemangat bekerja dengan orang kreatif seperti Anda.') ON CONFLICT DO NOTHING;
