INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7605634e-77b5-4bb8-a7e1-2902a9521863', 'vocabulary', '創造的', '創造的', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Jika 創造 adalah ciptaan, maka Anda menambahkan 的 ke dalamnya, yang berarti Anda memiliki sesuatu yang diciptakan, yang cukup kreatif bukan?', 'Jika 創造 adalah ciptaan, maka Anda menambahkan 的 ke dalamnya, yang berarti Anda memiliki sesuatu yang diciptakan, yang cukup kreatif bukan?') ON CONFLICT (id) DO NOTHING;
