INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e251d0e8-15ce-42a8-a133-8da9def9ebde', 'vocabulary', '身振り', '身振り', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Seseorang menggoyangkan sesuatu padamu. Tampaknya itu adalah jari. Gerakan kecil yang aneh.', 'Seseorang menggoyangkan sesuatu padamu. Tampaknya itu adalah jari. Gerakan kecil yang aneh.') ON CONFLICT (id) DO NOTHING;
