INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f58b0de-7c68-41cd-b798-fc80e8124105', '急に胸が締めつけられているような感覚におそわれ、屈んでしまった。', 'Tiba-tiba aku merasakan dadaku sesak dan membungkuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0265e7fd-8070-4c54-9265-04aae60d1e1e', 'vocabulary', '独裁', '独裁', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Ketika seseorang berada dalam posisi untuk menilai semua orang sendirian, mereka jelas merupakan bagian dari kediktatoran. Seseorang tidak boleh sendirian untuk menghakimi semua orang karena begitulah cara para diktator diciptakan dan mereka tidak begitu hebat.', 'Ketika seseorang berada dalam posisi untuk menilai semua orang sendirian, mereka jelas merupakan bagian dari kediktatoran. Seseorang tidak boleh sendirian untuk menghakimi semua orang karena begitulah cara para diktator diciptakan dan mereka tidak begitu hebat.') ON CONFLICT (id) DO NOTHING;
