INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0265e7fd-8070-4c54-9265-04aae60d1e1e', 'あの会社では社長が独裁しているから働きたくない。', 'Saya tidak ingin bekerja di perusahaan itu karena presiden menjalankannya seperti negara diktator.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0265e7fd-8070-4c54-9265-04aae60d1e1e', '俺は世界一の独裁者になるんだ。', 'Saya akan menjadi diktator terbaik di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f6a7c0ce-3295-4185-9827-78fe8579ee80', 'vocabulary', '従兄弟', '従兄弟', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Ingat bagaimana 兄弟 berarti "saudara kandung?" Nah, jika mereka bersaudara, kamu harus patuh bahwa mereka bukan saudara laki-laki atau perempuanmu, mereka adalah sepupumu.', 'Ingat bagaimana 兄弟 berarti "saudara kandung?" Nah, jika mereka bersaudara, kamu harus patuh bahwa mereka bukan saudara laki-laki atau perempuanmu, mereka adalah sepupumu.') ON CONFLICT (id) DO NOTHING;
