INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3a3fe908-815a-4253-9d5e-9324055ed32d', 'vocabulary', '何故なら', '何故なら', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Saat seseorang menanyakan 何故, atau "mengapa", Anda melakukan sesuatu, Anda menjawab dengan, "何故なら bla bla bla." Itu berarti karena. Mengapa kamu melakukan itu? Karena aku marah! Mengapa kamu menari? Karena saya senang!', 'Saat seseorang menanyakan 何故, atau "mengapa", Anda melakukan sesuatu, Anda menjawab dengan, "何故なら bla bla bla." Itu berarti karena. Mengapa kamu melakukan itu? Karena aku marah! Mengapa kamu menari? Karena saya senang!') ON CONFLICT (id) DO NOTHING;
