INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('188ddd2e-f54d-40ee-b877-12da8e771416', 'その歌手は三人のボディガードを従えてやってきた。', 'Penyanyi itu datang ke sini ditemani ketiga pengawalnya.') ON CONFLICT DO NOTHING;
