INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75a200cd-eae4-4341-9853-2407f2e4bb01', '我が家の今日のディナーはエビフライです。', 'Makan malam hari ini di rumah kami adalah udang goreng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75a200cd-eae4-4341-9853-2407f2e4bb01', 'だれだって、結局我が子が一番可愛いんだよ。', 'Pada akhirnya, semua orang paling mencintai anaknya sendiri.') ON CONFLICT DO NOTHING;
