INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('30766869-d4d2-4c24-a989-ac3ecab0dfff', 'vocabulary', '怪我', '怪我', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Tahukah Anda betapa curiganya saya jika saya mengalami cedera? Saya mulai mencurigai semua orang di sekitar saya telah memberi saya cedera. Itu kamu, bukan?', 'Tahukah Anda betapa curiganya saya jika saya mengalami cedera? Saya mulai mencurigai semua orang di sekitar saya telah memberi saya cedera. Itu kamu, bukan?') ON CONFLICT (id) DO NOTHING;
