INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('30766869-d4d2-4c24-a989-ac3ecab0dfff', '昨日、娘が学校で怪我をしてしまいました。', 'Kemarin, putri saya terluka di sekolah.') ON CONFLICT DO NOTHING;
