INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f94856c-a0a2-4530-98fd-54f8d1699638', 'vocabulary', '豚骨ラーメン', '豚骨ラーメン', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'Ramen tulang babi adalah ramen tonkotsu atau, secara logika, ramen tulang babi.', 'Ramen tulang babi adalah ramen tonkotsu atau, secara logika, ramen tulang babi.') ON CONFLICT (id) DO NOTHING;
