INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f94856c-a0a2-4530-98fd-54f8d1699638', 'ここは豚骨ラーメンの店です。', 'Tempat ini adalah restoran ramen tonkotsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f94856c-a0a2-4530-98fd-54f8d1699638', 'この豚骨ラーメンを食べると懐かしい気持ちになるよ。', 'Ramen tulang babi ini membuatku bernostalgia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f94856c-a0a2-4530-98fd-54f8d1699638', '是非、九州に豚骨ラーメンを食べに来て下さい。', 'Silakan datang ke Kyushu untuk makan ramen tonkotsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79b7303d-a6cd-4d4d-8460-60d10bdfdb4a', 'vocabulary', '豚カツ', '豚カツ', 1, 'f542bb11-d3b4-4838-a05c-c8107dd71869', 'カツ berasal dari kata "potongan daging" dan artinya persis seperti itu. Dan daging babi カツ adalah apa yang mungkin diketahui oleh setiap penggemar makanan Jepang sebagai tonkatsu, alias potongan daging babi yang dilapisi tepung roti.', 'カツ berasal dari kata "potongan daging" dan artinya persis seperti itu. Dan daging babi カツ adalah apa yang mungkin diketahui oleh setiap penggemar makanan Jepang sebagai tonkatsu, alias potongan daging babi yang dilapisi tepung roti.') ON CONFLICT (id) DO NOTHING;
