INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f7767929-a941-4cf9-843a-5469e13e0e8a', 'vocabulary', '野郎', '野郎', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Ugh, orang lapangan itu. Dia yang terburuk. Selalu di ladang, membuat kami terlihat jelek, dasar brengsek. Sebenarnya dia memang cowok yang seperti itu, tapi entah kenapa aku terkadang tidak menyukainya.', 'Ugh, orang lapangan itu. Dia yang terburuk. Selalu di ladang, membuat kami terlihat jelek, dasar brengsek. Sebenarnya dia memang cowok yang seperti itu, tapi entah kenapa aku terkadang tidak menyukainya.') ON CONFLICT (id) DO NOTHING;
