INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f7767929-a941-4cf9-843a-5469e13e0e8a', 'あのクソ野郎がセールス・マネージャーに昇進するなんて本当に気に食わねぇ。', 'itu dipromosikan menjadi manajer penjualan. Perutku sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('09d66fad-3f92-4677-8c89-d92d8916c13f', 'vocabulary', '修士', '修士', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Disiplin seorang samurai. Anda memerlukan ini untuk menyelesaikan gelar master Anda. Sulit untuk mendapatkan salah satu dari hal-hal itu, dan meskipun samurai tidak terlalu banyak mendapatkan gelar master, mereka memiliki disiplin untuk itu.', 'Disiplin seorang samurai. Anda memerlukan ini untuk menyelesaikan gelar master Anda. Sulit untuk mendapatkan salah satu dari hal-hal itu, dan meskipun samurai tidak terlalu banyak mendapatkan gelar master, mereka memiliki disiplin untuk itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('09d66fad-3f92-4677-8c89-d92d8916c13f', 'Gelar Magister', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('09d66fad-3f92-4677-8c89-d92d8916c13f', 'しゅうし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09d66fad-3f92-4677-8c89-d92d8916c13f', 'アルバイトをしながら、修士号を取るために勉強しています。', 'Saya sedang belajar untuk mendapatkan gelar master sambil bekerja paruh waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('59153dcd-a70a-4542-8b43-a4a89a8d0134', 'vocabulary', '修理', '修理', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Disiplin adalah alasan mengapa Anda dapat melakukan perbaikan pada berbagai hal. Dibutuhkan banyak waktu untuk memperbaiki sesuatu, dan membutuhkan banyak pembelajaran. Disiplin itulah yang Anda butuhkan, dan Anda memilikinya. Jadi, itu telah diperbaiki!', 'Disiplin adalah alasan mengapa Anda dapat melakukan perbaikan pada berbagai hal. Dibutuhkan banyak waktu untuk memperbaiki sesuatu, dan membutuhkan banyak pembelajaran. Disiplin itulah yang Anda butuhkan, dan Anda memilikinya. Jadi, itu telah diperbaiki!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('59153dcd-a70a-4542-8b43-a4a89a8d0134', 'Perbaikan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('59153dcd-a70a-4542-8b43-a4a89a8d0134', 'しゅうり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('59153dcd-a70a-4542-8b43-a4a89a8d0134', '「おい、修理屋。これはすぐに直せるか？」「って、君たちの関係ってこと？悪いけど、それはできないよ。」', '"Hei, tukang reparasi. Bisakah kamu memperbaikinya sekarang?" Maksudmu, hubungan kalian? Maaf.Tidak bisa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2689071b-49b8-4634-9afb-6aefb347716c', 'vocabulary', '研修', '研修', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Pertajam disiplin Anda, apa pun itu. Bisa jadi kanji, bisa jadi enggak, bisa jadi curl. Apapun itu, ketika mengasahnya, Anda harus belajar. Anda harus melakukan pelatihan. Itu satu-satunya cara untuk menjadi lebih baik.', 'Pertajam disiplin Anda, apa pun itu. Bisa jadi kanji, bisa jadi enggak, bisa jadi curl. Apapun itu, ketika mengasahnya, Anda harus belajar. Anda harus melakukan pelatihan. Itu satu-satunya cara untuk menjadi lebih baik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2689071b-49b8-4634-9afb-6aefb347716c', 'Pelatihan', true) ON CONFLICT DO NOTHING;
