INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2689071b-49b8-4634-9afb-6aefb347716c', 'その研修は午後3時に始まる予定です。', 'Sesi pelatihan akan dimulai pukul 3 sore.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f9f271d3-3d98-4244-a252-edc20b6d7de5', 'vocabulary', '修辞学', '修辞学', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Disiplin di mana Anda mempelajari kata-kata sehingga Anda bisa mengalahkan siapa pun disebut retorika. Lakukan retorika dengan benar dan Anda bisa menjadi bos dalam situasi atau disiplin apa pun, yo!', 'Disiplin di mana Anda mempelajari kata-kata sehingga Anda bisa mengalahkan siapa pun disebut retorika. Lakukan retorika dengan benar dan Anda bisa menjadi bos dalam situasi atau disiplin apa pun, yo!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f9f271d3-3d98-4244-a252-edc20b6d7de5', 'Retorika', true) ON CONFLICT DO NOTHING;
