INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f9f271d3-3d98-4244-a252-edc20b6d7de5', '私は修辞学の先生に恋をしています。', 'Saya naksir guru retorika.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('599f0c30-37e2-4f15-a6fe-fc413a2556c3', 'vocabulary', '傘', '傘', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
