INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('599f0c30-37e2-4f15-a6fe-fc413a2556c3', '私は傘をクロークに預けました。', 'Aku meninggalkan payungku di ruang ganti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d4ff9de-972d-4cf8-bd80-a90dea6337d3', 'vocabulary', '傘立て', '傘立て', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Ini adalah saat Anda mengambil payung dan berdiri. Tunggu, bagaimana payung bisa berdiri? Pertanyaan bagus, Crabling sayang, kamu meletakkan payungmu di tempat payung.', 'Ini adalah saat Anda mengambil payung dan berdiri. Tunggu, bagaimana payung bisa berdiri? Pertanyaan bagus, Crabling sayang, kamu meletakkan payungmu di tempat payung.') ON CONFLICT (id) DO NOTHING;
