INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d4ff9de-972d-4cf8-bd80-a90dea6337d3', '傘立てに濡れた傘を立てないで下さい。', 'Mohon jangan menaruh payung basah di tempat payung.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5976fa09-42a1-42d4-9986-fedea1b7a3e5', 'vocabulary', '同僚', '同僚', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Kita bekerja di tempat yang sama dan merupakan rekan kerja, sehingga menjadikan kita rekan kerja/rekan kerja.', 'Kita bekerja di tempat yang sama dan merupakan rekan kerja, sehingga menjadikan kita rekan kerja/rekan kerja.') ON CONFLICT (id) DO NOTHING;
