INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5976fa09-42a1-42d4-9986-fedea1b7a3e5', '残念な事に、私の同僚はあの電車の事故によって大きな商談のスケジュールの組み直しを余儀なくされた。', 'Sayangnya, kecelakaan kereta api memaksa rekan kerja saya untuk mengatur ulang pertemuan bisnis besarnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a56be86-63aa-4b7a-9b11-85b52c1376d5', 'vocabulary', '官僚', '官僚', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Rekan pemerintahan adalah orang yang bekerja pada dan menjadi bagian dari birokrasi sehingga menjadikannya birokrat.', 'Rekan pemerintahan adalah orang yang bekerja pada dan menjadi bagian dari birokrasi sehingga menjadikannya birokrat.') ON CONFLICT (id) DO NOTHING;
