INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a56be86-63aa-4b7a-9b11-85b52c1376d5', 'あの官僚が我々の素晴らしい提案を断ったなんて信じられないよ。', 'Saya tidak percaya para birokrat menolak tawaran besar yang kami berikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ff0003b3-f562-43cb-b0e9-a5000c042f7d', 'vocabulary', '博物館', '博物館', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Sebuah pameran untuk berbagai hal diadakan di gedung umum agar siapa pun dapat melihatnya. Tempat ini adalah museum.', 'Sebuah pameran untuk berbagai hal diadakan di gedung umum agar siapa pun dapat melihatnya. Tempat ini adalah museum.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ff0003b3-f562-43cb-b0e9-a5000c042f7d', 'Muzium', true) ON CONFLICT DO NOTHING;
