INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e98e813-c177-4d1a-a41f-c20602ca75e0', 'vocabulary', '妙薬', '妙薬', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Obat aneh yang tampaknya terlalu bagus untuk menjadi kenyataan? Terkadang mereka tidak buruk. Mereka dikenal sebagai obat ajaib.', 'Obat aneh yang tampaknya terlalu bagus untuk menjadi kenyataan? Terkadang mereka tidak buruk. Mereka dikenal sebagai obat ajaib.') ON CONFLICT (id) DO NOTHING;
