INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b35d9284-b376-4c00-b7c1-3aaf5785148e', 'vocabulary', '微か', '微か', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Kanjinya halus, dan kosakatanya juga memiliki arti seperti itu. Itu semacam "halus" yang halus, tidak terlalu membuat sesuatu pecah (seperti halnya dengan kanji). Sesuatu yang agak samar dan tidak jelas mungkin juga akan menjadi halus dalam pengertian ini.', 'Kanjinya halus, dan kosakatanya juga memiliki arti seperti itu. Itu semacam "halus" yang halus, tidak terlalu membuat sesuatu pecah (seperti halnya dengan kanji). Sesuatu yang agak samar dan tidak jelas mungkin juga akan menjadi halus dalam pengertian ini.') ON CONFLICT (id) DO NOTHING;
