INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ebb6292c-6322-4323-bb5d-5d43f56a11c9', 'vocabulary', '微生物', '微生物', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Benda hidup yang halus (生物 = biologi) adalah benda hidup yang sangat peka. Sangat kecil dan halus. Itu adalah mikroorganisme.', 'Benda hidup yang halus (生物 = biologi) adalah benda hidup yang sangat peka. Sangat kecil dan halus. Itu adalah mikroorganisme.') ON CONFLICT (id) DO NOTHING;
