INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7771cc90-0748-4365-b441-b80002d24e77', 'vocabulary', '撃つ', '撃つ', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti menyerang, meskipun biasanya berarti menembak, karena itulah cara yang sangat umum untuk menyerang seseorang. Kekuatan!', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti menyerang, meskipun biasanya berarti menembak, karena itulah cara yang sangat umum untuk menyerang seseorang. Kekuatan!') ON CONFLICT (id) DO NOTHING;
