INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('192f1043-5110-4e53-8348-69ce2a338ead', 'vocabulary', '攻撃', '攻撃', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Dengan agresi Anda menyerang musuh. Ini adalah serangan.', 'Dengan agresi Anda menyerang musuh. Ini adalah serangan.') ON CONFLICT (id) DO NOTHING;
