INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('192f1043-5110-4e53-8348-69ce2a338ead', 'サーバーがサイバー攻撃を受けている。', 'Server sedang diserang dunia maya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('192f1043-5110-4e53-8348-69ce2a338ead', '敵はまず巨大都市を攻撃してくるだろう。', 'Musuh mungkin akan menyerang kota-kota besar terlebih dahulu.') ON CONFLICT DO NOTHING;
