INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a3da881-802e-4136-bd9e-bf49d3ee890d', 'vocabulary', '専攻', '専攻', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Spesialisasi Anda, yang Anda fokuskan dengan agresi, adalah jurusan Anda di perguruan tinggi (jurusan perguruan tinggi Anda). Belajarlah dengan giat, hai belalang muda.', 'Spesialisasi Anda, yang Anda fokuskan dengan agresi, adalah jurusan Anda di perguruan tinggi (jurusan perguruan tinggi Anda). Belajarlah dengan giat, hai belalang muda.') ON CONFLICT (id) DO NOTHING;
