INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8151a6b9-049c-4c48-8ba6-833708d17d9a', 'vocabulary', '潔い', '潔い', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari murni? Itu juga murni. Orang seperti ini juga biasanya sangat ramah terhadap orang lain. Tipe hati murni seperti ini bahkan akan menjadi pecundang.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari murni? Itu juga murni. Orang seperti ini juga biasanya sangat ramah terhadap orang lain. Tipe hati murni seperti ini bahkan akan menjadi pecundang.') ON CONFLICT (id) DO NOTHING;
