INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d94bfe3-2b92-45ef-a647-937adc22f835', 'vocabulary', '催促', '催促', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Saya sangat bersedia mensponsori Anda untuk ini. Saya akan mendorong Anda untuk melakukan ini sampai Anda melakukannya, sehingga saya akan memberi Anda uang. Ini adalah salah satu dorongan dan tekanan besar bagi Anda untuk melakukan ini!', 'Saya sangat bersedia mensponsori Anda untuk ini. Saya akan mendorong Anda untuk melakukan ini sampai Anda melakukannya, sehingga saya akan memberi Anda uang. Ini adalah salah satu dorongan dan tekanan besar bagi Anda untuk melakukan ini!') ON CONFLICT (id) DO NOTHING;
