INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0d94bfe3-2b92-45ef-a647-937adc22f835', 'どうすれば顧客に未払分の支払手続きを丁寧かつ強く催促することができるのでしょうか。', 'Bagaimana saya bisa menekan pelanggan untuk mengambil tindakan atas keterlambatan pembayarannya dengan sopan namun juga tegas?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('13b3278e-3546-4c5b-bf0b-90beeb13ae02', 'vocabulary', '催告', '催告', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Saat Anda mensponsori sebuah pengumuman, Anda mengizinkan orang yang Anda sponsori untuk membuat semacam pemberitahuan untuk semua orang yang ingin mereka hubungi.', 'Saat Anda mensponsori sebuah pengumuman, Anda mengizinkan orang yang Anda sponsori untuk membuat semacam pemberitahuan untuk semua orang yang ingin mereka hubungi.') ON CONFLICT (id) DO NOTHING;
