INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13b3278e-3546-4c5b-bf0b-90beeb13ae02', 'サラ金から、借金の返済を求める催告状が何度も何度も届いています。', 'Sebuah perusahaan kredit konsumen berulang kali mengirimkan surat pemberitahuan kepada saya, meminta saya membayar kembali utang saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc4be66b-e968-45e3-94af-c5d73848e54b', 'vocabulary', '主催', '主催', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Master yang mensponsori Anda adalah orang yang memberikan sponsor Anda. Tanpa orang ini, Anda tidak akan mendapatkan sponsor sama sekali, itulah sebabnya Anda menyebut mereka "master" (plus, itu adalah salah satu aturan dalam sponsorship).', 'Master yang mensponsori Anda adalah orang yang memberikan sponsor Anda. Tanpa orang ini, Anda tidak akan mendapatkan sponsor sama sekali, itulah sebabnya Anda menyebut mereka "master" (plus, itu adalah salah satu aturan dalam sponsorship).') ON CONFLICT (id) DO NOTHING;
