INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8fb632e4-f4a3-4db4-b4d0-12ebb2a0bdc8', 'vocabulary', '壊す', '壊す', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghancurkan jadi versi vocab verbanya adalah menghancurkan sesuatu, karena kamu yang melakukan pelanggaran tersebut. Anda mengetahui hal ini karena seseorang mencoba menuntut (す) Anda atas pelanggaran yang Anda lakukan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghancurkan jadi versi vocab verbanya adalah menghancurkan sesuatu, karena kamu yang melakukan pelanggaran tersebut. Anda mengetahui hal ini karena seseorang mencoba menuntut (す) Anda atas pelanggaran yang Anda lakukan.') ON CONFLICT (id) DO NOTHING;
