INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac23367a-95c5-4068-b616-4ada7fe38763', 'だらだらしてないで、さっさと二階に行って宿題をしなさい。日本の江戸時代についてレポートを書かないといけないって言ってたでしょ！', 'Berhentilah menyia-nyiakan dan naik ke atas dan kerjakan pekerjaan rumahmu. Kamu bilang kamu harus menulis esai tentang zaman Edo di Jepang, kan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b2595fd1-f542-4e02-97c7-1b3e07a11998', 'vocabulary', '入り江', '入り江', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Saat Anda memasuki saluran masuk, Anda telah masuk ke saluran masuk. Itu juga tempat air masuk ke dalam saluran masuk (memasuki saluran masuk dari laut, atau apa pun), jadi itu cara lain untuk memikirkannya.', 'Saat Anda memasuki saluran masuk, Anda telah masuk ke saluran masuk. Itu juga tempat air masuk ke dalam saluran masuk (memasuki saluran masuk dari laut, atau apa pun), jadi itu cara lain untuk memikirkannya.') ON CONFLICT (id) DO NOTHING;
