INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b2595fd1-f542-4e02-97c7-1b3e07a11998', 'バルト海の北の入り江で知らない人からプロポーズされたんですが、とてもロマンチックだったのでつい承諾してしまったんです。', 'Saya dilamar oleh seseorang yang tidak saya kenal di sebuah teluk di utara Laut Baltik. Itu sangat romantis sehingga aku tidak bisa menahan diri untuk menerimanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b2595fd1-f542-4e02-97c7-1b3e07a11998', 'この入江に港を建設しようと思っているんです。', 'Kami berencana membangun pelabuhan di pintu masuk ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b2595fd1-f542-4e02-97c7-1b3e07a11998', 'この入り江にはイルカがよくあそびに来ると入江さんが言っていた。', 'Pak Irie menceritakan kepada saya bahwa lumba-lumba sering mengunjungi teluk ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b88a5bf0-b966-4aab-8016-672a317115c2', 'vocabulary', '商店街', '商店街', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Jalan toko barang dagangan adalah jalan dengan segala macam toko dan barang dagangan di atasnya. Sepertinya banyak belanja yang terjadi di distrik perbelanjaan ini!', 'Jalan toko barang dagangan adalah jalan dengan segala macam toko dan barang dagangan di atasnya. Sepertinya banyak belanja yang terjadi di distrik perbelanjaan ini!') ON CONFLICT (id) DO NOTHING;
