INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b88a5bf0-b966-4aab-8016-672a317115c2', '私の弟は正真正銘の馬鹿だよ。昨日、鼻で牛乳を飲んでみたかったみたいで、商店街に牛乳を買いに行ったんだけど、そこで道に迷って結局牛乳買わずじまいだったんだから。', 'Adikku benar-benar bodoh. Kemarin, dia pergi keluar untuk membeli susu di kawasan perbelanjaan sehingga dia bisa mencoba minum susu dengan hidungnya, tapi dia tersesat di sana dan akhirnya tidak membelinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ebac809e-b75a-4382-b6ae-4c51eeaf71f2', 'vocabulary', '街道', '街道', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Jalan jalan adalah selebar jalan ditambah jalan yang digabungkan menjadi satu. Keren abis! Sangat luas! Itu jalan raya!', 'Jalan jalan adalah selebar jalan ditambah jalan yang digabungkan menjadi satu. Keren abis! Sangat luas! Itu jalan raya!') ON CONFLICT (id) DO NOTHING;
