INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebac809e-b75a-4382-b6ae-4c51eeaf71f2', '東海道、中山道、日光街道、甲州街道、奥州街道は、五街道と呼ばれ、江戸時代の五大陸上交通路であった。', 'Jalan Tokai-do, Jalan Nakasen-do, Jalan Nikko-kaido, Jalan Koshu-kaido, dan Jalan Oshu-kaido disebut Gokaido, yang merupakan lima rute utama yang digunakan pada zaman Edo.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b23ba2da-2050-4e6f-b868-2d377b27886b', 'vocabulary', '診る', '診る', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Untuk mendiagnosis seorang pasien, Anda harus pergi memeriksa pasien terlebih dahulu. Ketika Anda memeriksanya, Anda tahu apa yang salah dengannya dan kemudian Anda dapat mendiagnosisnya, itulah sebabnya kata kerja ini adalah memeriksa.', 'Untuk mendiagnosis seorang pasien, Anda harus pergi memeriksa pasien terlebih dahulu. Ketika Anda memeriksanya, Anda tahu apa yang salah dengannya dan kemudian Anda dapat mendiagnosisnya, itulah sebabnya kata kerja ini adalah memeriksa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b23ba2da-2050-4e6f-b868-2d377b27886b', 'Untuk Memeriksa Pasien', true) ON CONFLICT DO NOTHING;
