INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b23ba2da-2050-4e6f-b868-2d377b27886b', '赤ちゃんがちゃんと育っているのか、お医者さんに診てもらいたいんです。', 'Saya ingin dokter memeriksa bayi saya untuk melihat apakah dia tumbuh dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1d4b8b81-1a39-4a84-8787-c6b5cac5a088', 'vocabulary', '診察', '診察', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Saya akan mendiagnosis Anda dan kemudian menebak apa yang salah dengan diri Anda selama pemeriksaan medis ini.', 'Saya akan mendiagnosis Anda dan kemudian menebak apa yang salah dengan diri Anda selama pemeriksaan medis ini.') ON CONFLICT (id) DO NOTHING;
