INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d4b8b81-1a39-4a84-8787-c6b5cac5a088', '先生は診察の予定がみっちり詰まっています。', 'Dokter memiliki jadwal pemeriksaan kesehatan yang padat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('653adc19-44ba-4314-877f-cea19452ae84', 'vocabulary', '請求', '請求', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Anda meminta lalu meminta lagi. Ini mulai berubah menjadi permintaan jika Anda bertanya kepada saya. Juga bisa merujuk pada klaim atau tagihan juga.', 'Anda meminta lalu meminta lagi. Ini mulai berubah menjadi permintaan jika Anda bertanya kepada saya. Juga bisa merujuk pada klaim atau tagihan juga.') ON CONFLICT (id) DO NOTHING;
