INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b749aeaa-8376-4412-a102-1b36ac6e8c44', 'もしご迷惑でなければ請願書に署名して頂けませんでしょうか。', 'Jika Anda tidak keberatan, maukah Anda menandatangani petisi ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69087282-b0a5-49d2-9c05-6a7c66f0f08d', 'vocabulary', '要請', '要請', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Anda membutuhkan sesuatu jadi Anda memintanya. Tapi, karena kebutuhannya sangat besar, sebenarnya itu bukan permintaan, melainkan permintaan.', 'Anda membutuhkan sesuatu jadi Anda memintanya. Tapi, karena kebutuhannya sangat besar, sebenarnya itu bukan permintaan, melainkan permintaan.') ON CONFLICT (id) DO NOTHING;
