INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('50a9e3b2-ae84-4979-b0cf-61482ed4e548', 'vocabulary', '請ける', '請ける', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Seseorang meminta sesuatu, jadi kamulah yang menerimanya. Anda sungguh baik hati menerima permintaan mereka. Anda orang yang baik!', 'Seseorang meminta sesuatu, jadi kamulah yang menerimanya. Anda sungguh baik hati menerima permintaan mereka. Anda orang yang baik!') ON CONFLICT (id) DO NOTHING;
