INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('50a9e3b2-ae84-4979-b0cf-61482ed4e548', 'お前の顔を立てるためだけにこの仕事を請けたんだからな。', 'Saya hanya mengambil pekerjaan ini agar Anda bisa menyelamatkan muka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('582f18e5-bc1f-4bfc-baba-3779772a47aa', 'vocabulary', '閣僚', '閣僚', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Rekan kabinet adalah menteri kabinet. Mereka adalah orang-orang di Kabinet yang semuanya merupakan rekan satu sama lain. Mereka kebetulan dikenal sebagai menteri.', 'Rekan kabinet adalah menteri kabinet. Mereka adalah orang-orang di Kabinet yang semuanya merupakan rekan satu sama lain. Mereka kebetulan dikenal sebagai menteri.') ON CONFLICT (id) DO NOTHING;
