INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4fd3e7ad-0624-4b6c-a655-0d7fe47ef45f', 'vocabulary', '閣議', '閣議', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Ketika kabinet bertemu untuk musyawarah, mereka mengadakan rapat kabinet. Sangat pemerintahan.', 'Ketika kabinet bertemu untuk musyawarah, mereka mengadakan rapat kabinet. Sangat pemerintahan.') ON CONFLICT (id) DO NOTHING;
