INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4fd3e7ad-0624-4b6c-a655-0d7fe47ef45f', 'さっきの閣議では何が議題だったんだっけ？忘れちゃった。', 'Apa yang kita bahas pada rapat kabinet hari ini? saya lupa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e415a2d7-f5f8-4dcc-9af9-352c43e91169', 'vocabulary', '英雄', '英雄', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Orang Inggris pemberani. Oke, mungkin ada arti kanji lain yang tidak umum diterapkan di sini, tetapi jika Anda menganggapnya sebagai Raja Arthur, seorang pemberani Inggris, maka Anda bisa memahami arti kata ini. Raja Arthur mungkin adalah pahlawan Inggris yang paling terkenal.', 'Orang Inggris pemberani. Oke, mungkin ada arti kanji lain yang tidak umum diterapkan di sini, tetapi jika Anda menganggapnya sebagai Raja Arthur, seorang pemberani Inggris, maka Anda bisa memahami arti kata ini. Raja Arthur mungkin adalah pahlawan Inggris yang paling terkenal.') ON CONFLICT (id) DO NOTHING;
