INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e415a2d7-f5f8-4dcc-9af9-352c43e91169', 'この言葉は、英雄たちについて書かれたとある本からの引用です。', 'Ungkapan ini dikutip dari sebuah buku tentang pahlawan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('996c402e-fd1c-4639-b551-0b54bee7839c', 'vocabulary', '好奇心', '好奇心', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Anda menyukainya karena memberi Anda perasaan aneh di hati Anda. Anda tidak begitu tahu apa yang Anda sukai, tetapi itu karena rasa ingin tahu yang Anda miliki.', 'Anda menyukainya karena memberi Anda perasaan aneh di hati Anda. Anda tidak begitu tahu apa yang Anda sukai, tetapi itu karena rasa ingin tahu yang Anda miliki.') ON CONFLICT (id) DO NOTHING;
