INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6b5e760b-e538-4681-b6a6-6561f70b258e', 'vocabulary', '奇数', '奇数', 1, '99b3c832-94dd-4a27-a0c7-55365b91014c', 'Bilangan ganjil adalah bilangan ganjil (seperti 1, 3, 5, 7, meskipun agak aneh juga).', 'Bilangan ganjil adalah bilangan ganjil (seperti 1, 3, 5, 7, meskipun agak aneh juga).') ON CONFLICT (id) DO NOTHING;
