INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('99fe1c60-72b9-40cf-90bc-7887b3760752', 'radical', '[hills]', 'hills', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Lihat perbukitan dengan jalan yang mengarah ke bukit lain? Itu sebabnya bukit ini radikal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('99fe1c60-72b9-40cf-90bc-7887b3760752', 'Bukit', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9973ec64-7272-43b9-b511-4916a0c44337', 'radical', '离', 'rocket', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Ini adalah radikal yang sangat rumit dan tinggi. Ada penutup di atasnya untuk menahan bahan peledak. Itu juga berisi harta karun, setidaknya bagi orang yang akan menerima apa yang ada di dalamnya. Juga, ia memiliki seekor sapi, yang akan digunakan untuk susu di Mars. Ini adalah roket yang berisi barang-barang untuk manusia luar angkasa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9973ec64-7272-43b9-b511-4916a0c44337', 'Roket', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('79125bd0-3672-4866-9191-f0b2eea42436', 'radical', '鬲', 'bully', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Dia menjalar dan dia Four-T (empat puluh). Jika orang seperti ini merinding pada Anda, dia hanya pengganggu. Ketika Anda mencapai usia empat puluh, Anda tidak seharusnya lagi mengganggu orang lain. Anda pengganggu. Anda brengsek.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('79125bd0-3672-4866-9191-f0b2eea42436', 'Pengganggu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7bf24011-1932-47b0-a706-d133608ca290', 'radical', '牙', 'fang', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Bayangkan ini di mulut Anda. Itu adalah satu gigi yang paling menonjol dibandingkan gigi lainnya. Itu taringmu. Dapatkah Anda melihat ini keluar dari mulut serigala? Cobalah jika Anda tidak dapat membayangkan diri Anda memiliki taring sekeren ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7bf24011-1932-47b0-a706-d133608ca290', 'taring', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('231e4455-e2f3-4bcb-a92d-3708734460e4', 'radical', '監', 'oversee', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Radikal ini sama dengan kanji. Artinya mengawasi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('231e4455-e2f3-4bcb-a92d-3708734460e4', 'Mengawasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('304e57da-b821-434e-a4de-312bc231c646', 'radical', '郎', 'guy', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Radikal ini sama dengan kanji. Artinya laki-laki.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('304e57da-b821-434e-a4de-312bc231c646', 'Pria', true) ON CONFLICT DO NOTHING;
