INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f0704bef-99d9-4d4c-85f4-2f750ab2bf10', 'vocabulary', '宗派', '宗派', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Kemungkinan besar sekte agama adalah sekte dalam agama, tetapi bisa juga disebut sebagai sekte atau denominasi.', 'Kemungkinan besar sekte agama adalah sekte dalam agama, tetapi bisa juga disebut sebagai sekte atau denominasi.') ON CONFLICT (id) DO NOTHING;
