INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f842e443-a16d-4a8b-a5e0-c27c6f5378a8', 'vocabulary', '禅宗', '禅宗', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Agama zen adalah bagian dari agama Buddha. Ini adalah Sekte Zen dalam agama Buddha.', 'Agama zen adalah bagian dari agama Buddha. Ini adalah Sekte Zen dalam agama Buddha.') ON CONFLICT (id) DO NOTHING;
