INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8327be21-e91b-46bd-875e-73ef71f5c4a9', 'vocabulary', '国旗', '国旗', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Bendera suatu negara adalah bendera yang mereka gunakan untuk negaranya. Itu bendera nasional.', 'Bendera suatu negara adalah bendera yang mereka gunakan untuk negaranya. Itu bendera nasional.') ON CONFLICT (id) DO NOTHING;
