INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21408525-1a53-4705-b6a2-af0027f2ec11', 'vocabulary', '渇く', '渇く', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Saat Anda haus, Anda cenderung menjadi haus.', 'Saat Anda haus, Anda cenderung menjadi haus.') ON CONFLICT (id) DO NOTHING;
