INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9200fad7-f202-4620-8df7-a7baeb77d571', 'vocabulary', '漏出', '漏出', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Ada yang bocor dan apa pun yang bocor keluar dari keadaan sebelumnya. Saat inilah terjadi kebocoran.', 'Ada yang bocor dan apa pun yang bocor keluar dari keadaan sebelumnya. Saat inilah terjadi kebocoran.') ON CONFLICT (id) DO NOTHING;
