INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9200fad7-f202-4620-8df7-a7baeb77d571', '﻿全壊したビルからガスが漏出して危険だから近寄らないように。', 'Gas bocor dari bangunan yang hancur total dan itu berbahaya, jadi jangan mendekat.') ON CONFLICT DO NOTHING;
