INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9200fad7-f202-4620-8df7-a7baeb77d571', '原油の海への漏出事故を防ぐために、どんな手段を講じていますか。', 'Tindakan apa yang diambil perusahaan Anda untuk mencegah kebocoran minyak mentah ke laut secara tidak sengaja?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb1f5e5f-422c-4f43-b3e8-ea1c136d9a7b', 'vocabulary', '漏れる', '漏れる', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bocor jadi versi vocab verbanya adalah bocor.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bocor jadi versi vocab verbanya adalah bocor.') ON CONFLICT (id) DO NOTHING;
