INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb1f5e5f-422c-4f43-b3e8-ea1c136d9a7b', 'ねえ、なんかガスが漏れてる臭いがしない？', 'Hei, bukankah baunya seperti gas bocor?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d8a93333-e24c-43f7-9715-e8d93a5c39c3', 'vocabulary', '〜系', '〜系', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Ketika Anda bergaul dengan garis keturunan tertentu, Anda menelusuri kembali diri Anda dengan sekelompok orang. Kelompok orang ini adalah suku Anda, garis keturunan Anda, kelompok Anda.', 'Ketika Anda bergaul dengan garis keturunan tertentu, Anda menelusuri kembali diri Anda dengan sekelompok orang. Kelompok orang ini adalah suku Anda, garis keturunan Anda, kelompok Anda.') ON CONFLICT (id) DO NOTHING;
