INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d8a93333-e24c-43f7-9715-e8d93a5c39c3', '私、アキバ系のオタッキーな男性に何故か魅力を感じるんだよね。', 'Entah kenapa aku tertarik dengan gaya Akihabara, pria kutu buku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58c1fe26-d59a-4145-84ed-c3616eb4d658', 'vocabulary', '日系', '日系', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', '日 adalah 日 dalam 日本, sehingga berarti bahasa Jepang dalam kata ini. Jika Anda adalah orang Jepang dalam garis keturunan maka Anda adalah keturunan Jepang.', '日 adalah 日 dalam 日本, sehingga berarti bahasa Jepang dalam kata ini. Jika Anda adalah orang Jepang dalam garis keturunan maka Anda adalah keturunan Jepang.') ON CONFLICT (id) DO NOTHING;
