INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d49da71a-408a-458c-ab7f-cbf653dd4a24', 'vocabulary', '太陽系', '太陽系', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Silsilah matahari (太陽) adalah segala sesuatu yang mengelilinginya. Ini adalah tata surya.', 'Silsilah matahari (太陽) adalah segala sesuatu yang mengelilinginya. Ini adalah tata surya.') ON CONFLICT (id) DO NOTHING;
