INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9d4565e-69d9-44ec-a02e-81b80f93c909', 'vocabulary', 'ご覧', 'ご覧', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Anda akan sering mendengar ini dalam pidato sopan, digunakan sebagai pengganti 見る (itu akan menjadi ご覧になって下さい, yang secara harafiah berarti "tolong jadilah sehingga Anda melihat _____"). Artinya sama dengan kanji, jadi bagian ini setidaknya mudah. Mengapa Anda tidak ご覧 penjelasan bacaannya sekarang.', 'Anda akan sering mendengar ini dalam pidato sopan, digunakan sebagai pengganti 見る (itu akan menjadi ご覧になって下さい, yang secara harafiah berarti "tolong jadilah sehingga Anda melihat _____"). Artinya sama dengan kanji, jadi bagian ini setidaknya mudah. Mengapa Anda tidak ご覧 penjelasan bacaannya sekarang.') ON CONFLICT (id) DO NOTHING;
