INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b3e1b27-2d87-4564-b6cc-d8b9cd029ba2', 'vocabulary', '観覧', '観覧', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Jika Anda melihat dan memandang sesuatu, Anda sedang melihat benda itu, atau melihatnya.', 'Jika Anda melihat dan memandang sesuatu, Anda sedang melihat benda itu, atau melihatnya.') ON CONFLICT (id) DO NOTHING;
