INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36dc76ac-759e-4c85-a6f6-bafed9913e04', 'vocabulary', '中華', '中華', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', '中国 adalah Tiongkok, kan? Itulah yang diwakili oleh 中 ini. Dan tentu saja orang Cina terkenal super mencolok, itulah sebabnya Anda harus suka pamer di sana.', '中国 adalah Tiongkok, kan? Itulah yang diwakili oleh 中 ini. Dan tentu saja orang Cina terkenal super mencolok, itulah sebabnya Anda harus suka pamer di sana.') ON CONFLICT (id) DO NOTHING;
