INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3921fc93-0a3d-45d1-ba37-bfd401199be5', 'うわっ！めっちゃ豪華やん。美味しそう。（関西弁）', 'Wow! Itu luar biasa. Kelihatannya enak. (Kansai-ben)') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b93d37b-2171-4ccc-b93f-a2ef69be0b36', 'vocabulary', '鑑定', '鑑定', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Ketika seseorang menentukan sesuatu, mungkin tidak apa-apa. Namun, ketika penentu model menentukan sesuatu, itulah penentuan terbaik yang pernah ada. Itulah penilaian seseorang yang mempunyai pendapat ahli.', 'Ketika seseorang menentukan sesuatu, mungkin tidak apa-apa. Namun, ketika penentu model menentukan sesuatu, itulah penentuan terbaik yang pernah ada. Itulah penilaian seseorang yang mempunyai pendapat ahli.') ON CONFLICT (id) DO NOTHING;
