INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6649aab3-9152-4033-bba2-f8476c7a0a61', 'vocabulary', '尋ねる', '尋ねる', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertanya, jadi versi vocab verbanya adalah bertanya.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertanya, jadi versi vocab verbanya adalah bertanya.') ON CONFLICT (id) DO NOTHING;
