INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63ba8c68-4c15-4675-b141-8d2658ebd111', '「フグ？お前、フグか？」「サーモンか？こいつは驚いた。高校以来だね。元気かい？」', '"Fugu? Apakah itu kamu, Fugu?" "Salmon? Terkutuklah aku. Aku belum pernah melihatmu sejak SMA. Bagaimana kabarmu?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3cad9ebe-6be4-439f-9f57-851074becfb7', 'vocabulary', '驚嘆', '驚嘆', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Aku sangat terkejut hingga membuatku menghela nafas. Ini seperti ketika Anda bertemu dengan seorang bintang film, dan Anda terkejut. Kemudian, Anda menghela nafas karena banyaknya kekaguman dan kekaguman Anda terhadap orang ini.', 'Aku sangat terkejut hingga membuatku menghela nafas. Ini seperti ketika Anda bertemu dengan seorang bintang film, dan Anda terkejut. Kemudian, Anda menghela nafas karena banyaknya kekaguman dan kekaguman Anda terhadap orang ini.') ON CONFLICT (id) DO NOTHING;
