INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cad9ebe-6be4-439f-9f57-851074becfb7', 'その太陽光発電所の規模に驚嘆しました。', 'Saya kagum dengan besarnya pembangkit listrik tenaga surya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e85de4ed-5d7a-4b11-bb10-b59493351cbe', 'vocabulary', '嘆く', '嘆く', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Saat Anda menghela nafas, Anda merasakan jenis emosi tertentu. Tipe yang membuat Anda merasa sedih dan menyebabkan Anda meratap dan berduka.', 'Saat Anda menghela nafas, Anda merasakan jenis emosi tertentu. Tipe yang membuat Anda merasa sedih dan menyebabkan Anda meratap dan berduka.') ON CONFLICT (id) DO NOTHING;
