INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d2e37dc0-4acf-40f9-9474-8acdb1e8e398', 'お前は自分のことを素晴らしいと思っているみたいだけどな、ただの貧乏家族の貧乏人だってことを、よ〜く肝に銘じておくんだな。', 'Anda pikir Anda hebat, tapi ingatlah, Anda hanyalah orang miskin dari keluarga miskin!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc07a9ab-7deb-4257-b858-bbfe3332acb0', 'vocabulary', '撮影禁止', '撮影禁止', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', '撮影 adalah fotografi. 禁止 adalah larangan. Jadi jika fotografi dilarang, maka kita dapat berasumsi bahwa ada aturan dilarang mengambil foto atau tidak boleh mengambil foto.', '撮影 adalah fotografi. 禁止 adalah larangan. Jadi jika fotografi dilarang, maka kita dapat berasumsi bahwa ada aturan dilarang mengambil foto atau tidak boleh mengambil foto.') ON CONFLICT (id) DO NOTHING;
