INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2181b412-4fd7-4ee3-8ebe-d8d5fb95fc66', 'vocabulary', '購読する', '購読する', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Jika 購読 adalah langganan, maka versi kosakata kata kerjanya adalah berlangganan.', 'Jika 購読 adalah langganan, maka versi kosakata kata kerjanya adalah berlangganan.') ON CONFLICT (id) DO NOTHING;
