INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3622e4ec-f885-4201-82aa-02441bc401be', 'その左利きの投手は、大リーグで華々しいデビューを飾りました。', 'Pelempar kidal itu melakukan debut liga utama yang brilian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('507e1f72-4a56-4567-9f5b-c37e29ab690d', 'vocabulary', '驚かす', '驚かす', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Ingat bagaimana 驚く berarti "terkejut"? Ini adalah saat Anda mengejutkan orang lain, melakukan hal yang mengejutkan, membuat kata ini mengejutkan atau mengejutkan.', 'Ingat bagaimana 驚く berarti "terkejut"? Ini adalah saat Anda mengejutkan orang lain, melakukan hal yang mengejutkan, membuat kata ini mengejutkan atau mengejutkan.') ON CONFLICT (id) DO NOTHING;
