INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('507e1f72-4a56-4567-9f5b-c37e29ab690d', '23歳の新入社員は82歳のCEOと結婚して、一緒に仕事をする人全員を驚かした。', 'Rekrutan baru berusia 23 tahun ini mengejutkan semua orang yang bekerja bersamanya dengan menikahi CEO berusia 82 tahun tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b6c87bfc-0ef3-4b59-baca-582b60a049e5', 'vocabulary', '離す', '離す', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Ingat bagaimana 離れる adalah "memisahkan", di mana ada sesuatu yang memisahkan dan Anda tidak melakukan pemisahan? Nah, yang ini mempunyai arti yang sama, namun sekarang Anda sedang melakukan pemisahan. Kata ini adalah 離す, dan Anda tahu bahwa Anda sedang melakukan pemisahan karena jika tidak, orang itu akan menuntut (す) Anda karena memegangnya dan tidak melepaskannya.', 'Ingat bagaimana 離れる adalah "memisahkan", di mana ada sesuatu yang memisahkan dan Anda tidak melakukan pemisahan? Nah, yang ini mempunyai arti yang sama, namun sekarang Anda sedang melakukan pemisahan. Kata ini adalah 離す, dan Anda tahu bahwa Anda sedang melakukan pemisahan karena jika tidak, orang itu akan menuntut (す) Anda karena memegangnya dan tidak melepaskannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b6c87bfc-0ef3-4b59-baca-582b60a049e5', 'Untuk Memisahkan', true) ON CONFLICT DO NOTHING;
