INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b6c87bfc-0ef3-4b59-baca-582b60a049e5', 'はなす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b6c87bfc-0ef3-4b59-baca-582b60a049e5', 'ごめん。いま手が離せないんだ。後でかけ直してもいいかな？', 'Maaf, aku sedang melakukan sesuatu. Saya akan menelepon Anda kembali. Oke?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b28eec64-c59f-4a95-ac50-6e587a784636', 'vocabulary', '御覧になる', '御覧になる', 1, 'c965011a-4757-4bfe-a263-a6ae4b02f870', 'Terhormat(y) menjadi (なる) saat kamu melihat sesuatu. Ini adalah cara yang penuh hormat untuk mengatakan melihat atau tolong melihat sesuatu. Bacaannya を御覧になって下さい！', 'Terhormat(y) menjadi (なる) saat kamu melihat sesuatu. Ini adalah cara yang penuh hormat untuk mengatakan melihat atau tolong melihat sesuatu. Bacaannya を御覧になって下さい！') ON CONFLICT (id) DO NOTHING;
