INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('810c2391-4dfa-4d98-8bf9-ad5e68fbb554', 'radical', '夋', 'spider', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Jika Anda perhatikan lebih dekat dan hati-hati, terkadang Anda dapat melihat beberapa kaki pribadi di musim dingin. Kaki siapa? Kaki laba-laba! Cuacanya terlalu dingin bagi mereka di musim dingin, jadi mereka bersembunyi di celah-celah dan celah-celah, namun terkadang Anda masih bisa melihat kaki kecil mereka mencuat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('810c2391-4dfa-4d98-8bf9-ad5e68fbb554', 'Laba-laba', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4c4b546c-d06d-4b5c-8abb-bf52d8973bf7', 'radical', '[elf]', 'elf', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Anda melihat daun telinga, lebih dikenal sebagai peri! Elf hanyalah manusia yang mempunyai telinga yang lancip seperti daun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4c4b546c-d06d-4b5c-8abb-bf52d8973bf7', 'Peri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('693c71e2-0a1b-4342-80a4-70dc796e12fb', 'radical', '必', 'certain', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Radikal ini sama dengan kanji. Artinya pasti.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('693c71e2-0a1b-4342-80a4-70dc796e12fb', 'Tentu', true) ON CONFLICT DO NOTHING;
