INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cf1ba32c-b413-4dcb-88fe-132250b0651b', 'vocabulary', '巣', '巣', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kata ini bisa merujuk ke berbagai hal, seperti jaring laba-laba, liang tikus, atau sarang lebah, dll. Pada dasarnya, ini adalah tempat tinggal hewan, tidak harus berupa sarang seperti di "sarang" burung, dll.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kata ini bisa merujuk ke berbagai hal, seperti jaring laba-laba, liang tikus, atau sarang lebah, dll. Pada dasarnya, ini adalah tempat tinggal hewan, tidak harus berupa sarang seperti di "sarang" burung, dll.') ON CONFLICT (id) DO NOTHING;
