INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf1ba32c-b413-4dcb-88fe-132250b0651b', '巣の中では、ツバメの雛が五羽、ぴいぴい鳴いていました。', 'Ada lima bayi burung walet yang sedang berkicau di sarangnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2e8ee07-b1f6-476b-82cc-2c7ed5b91fc3', 'vocabulary', '巣立ち', '巣立ち', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Saat Anda keluar dari sarang, Anda bersiap untuk meninggalkannya. Ibumu mungkin sedih dengan hal ini, tapi ini berarti sudah waktunya untuk meninggalkan sarangnya dan menjadi mandiri.', 'Saat Anda keluar dari sarang, Anda bersiap untuk meninggalkannya. Ibumu mungkin sedih dengan hal ini, tapi ini berarti sudah waktunya untuk meninggalkan sarangnya dan menjadi mandiri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a2e8ee07-b1f6-476b-82cc-2c7ed5b91fc3', 'Tinggalkan Sarang', true) ON CONFLICT DO NOTHING;
