INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40c01145-9ba8-4125-8f95-af8935d7df2f', 'ハチの巣の周りで沢山のハチがブンブン飛び回っている。', 'Ada banyak lebah yang berdengung di sekitar sarang lebah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c591936c-21e0-4e16-966b-02bf506d842f', 'vocabulary', 'クモの巣', 'クモの巣', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'クモ adalah seekor laba-laba. Tambahkan sarang ke dalamnya, dan Anda memiliki sarang laba-laba. Laba-laba menyebut sarangnya apa? Mereka menyebutnya sarang laba-laba (kalau mereka bisa bicara).', 'クモ adalah seekor laba-laba. Tambahkan sarang ke dalamnya, dan Anda memiliki sarang laba-laba. Laba-laba menyebut sarangnya apa? Mereka menyebutnya sarang laba-laba (kalau mereka bisa bicara).') ON CONFLICT (id) DO NOTHING;
