INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64ab330f-3875-4799-94f7-c0d1f81a3558', 'vocabulary', '徳川', '徳川', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Ini adalah salah satu kata yang lebih masuk akal ketika Anda melihat bacaannya. "Sungai Kebajikan" bukanlah sungai yang baik, melainkan nama keluarga Tokugawa, juga dikenal sebagai Shogun Tokugawa. Mereka memerintah Jepang untuk sementara waktu, Anda tahu?', 'Ini adalah salah satu kata yang lebih masuk akal ketika Anda melihat bacaannya. "Sungai Kebajikan" bukanlah sungai yang baik, melainkan nama keluarga Tokugawa, juga dikenal sebagai Shogun Tokugawa. Mereka memerintah Jepang untuk sementara waktu, Anda tahu?') ON CONFLICT (id) DO NOTHING;
