INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64ab330f-3875-4799-94f7-c0d1f81a3558', '彼女は歴女で、徳川幕府にはとても精通しています。', 'Dia menyukai sejarah Jepang dan sangat akrab dengan Keshogunan Tokugawa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70115102-3b63-435a-bc5c-43874bf8da7a', 'vocabulary', '徳島県', '徳島県', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Prefektur pulau kebajikan adalah Prefektur Tokushima. Bacaannya akan memberikan arti yang satu ini, selama Anda tahu "prefektur".', 'Prefektur pulau kebajikan adalah Prefektur Tokushima. Bacaannya akan memberikan arti yang satu ini, selama Anda tahu "prefektur".') ON CONFLICT (id) DO NOTHING;
