INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('03d6e207-caf4-48cd-9385-01e0170067c8', 'vocabulary', '内偵', '内偵', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Mata-mata di dalam adalah saat Anda masuk ke dalam wilayah musuh dan memata-matai mereka. Ini adalah kepanduan dan pengintaian.', 'Mata-mata di dalam adalah saat Anda masuk ke dalam wilayah musuh dan memata-matai mereka. Ini adalah kepanduan dan pengintaian.') ON CONFLICT (id) DO NOTHING;
