INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a7dcad76-f5b4-461e-bc17-486f35dd022e', 'vocabulary', '意志', '意志', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Anda punya ide dan Anda punya niat untuk melaksanakannya. Ini adalah kemauan dan kemauan Anda.', 'Anda punya ide dan Anda punya niat untuk melaksanakannya. Ini adalah kemauan dan kemauan Anda.') ON CONFLICT (id) DO NOTHING;
