INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('61c5b45e-22e8-4c59-84e6-ff72c615d917', 'vocabulary', '恩人', '恩人', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Orang yang baik hati adalah orang yang sangat baik hati. Orang ini adalah seorang dermawan.', 'Orang yang baik hati adalah orang yang sangat baik hati. Orang ini adalah seorang dermawan.') ON CONFLICT (id) DO NOTHING;
