INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('61c5b45e-22e8-4c59-84e6-ff72c615d917', 'コウイチは私の恩人です。私がベーコンに溺れていた時、私を救ってくれたんです。', 'Koichi adalah dermawanku. Dia menyelamatkan saya ketika saya kecanduan bacon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f58ff7fc-76a9-48be-b70c-2c8beedd7883', 'vocabulary', '恩賞', '恩賞', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Hadiah kebaikan adalah hadiah yang diberikan seseorang kepada Anda karena kebaikannya. Mungkin Anda telah melakukan sesuatu yang baik, itulah sebabnya mereka memberi Anda hadiah.
