INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d28eda67-5788-4b41-9f36-b5528874ce4e', '相手の気を引いたりうまく釣ったりする人のことを英語ではデコイと言うが、日本語では桜、ネット用語では釣りと言う。', 'Orang yang membujuk atau memikat orang lain disebut decoy dalam bahasa Inggris, sakura dalam bahasa Jepang, dan troll di internet.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a9c448e-972a-4a89-9574-84f9d9f238fe', 'vocabulary', '桜んぼ', '桜んぼ', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Pohon ceri bisa menghasilkan ceri. Inilah arti dari kata ini.', 'Pohon ceri bisa menghasilkan ceri. Inilah arti dari kata ini.') ON CONFLICT (id) DO NOTHING;
