INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a9c448e-972a-4a89-9574-84f9d9f238fe', 'この桜んぼ、やばいくらい美味しいんだけど。', 'Ceri ini luar biasa enaknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4bee248f-5f17-44de-8be6-9acdec2f46fb', 'vocabulary', '桜肉', '桜肉', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Anehnya, daging pohon ceri bukan hanya sejenis steak ceri... tapi daging kuda. Mudah-mudahan Anda baru mengingatnya karena keanehan kanji kata ini.', 'Anehnya, daging pohon ceri bukan hanya sejenis steak ceri... tapi daging kuda. Mudah-mudahan Anda baru mengingatnya karena keanehan kanji kata ini.') ON CONFLICT (id) DO NOTHING;
