INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('be84b89c-ae01-48dd-bc9b-5e825feaa157', 'vocabulary', '老眼', '老眼', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Bola mata lansia adalah bola mata yang tidak dapat melihat sesuatu dari dekat. Itu sebabnya kata ini berarti rabun jauh. Namun rabun dekat ini hanya muncul seiring bertambahnya usia. Jadi, Anda harus menjadi orang tua untuk memiliki 老眼.', 'Bola mata lansia adalah bola mata yang tidak dapat melihat sesuatu dari dekat. Itu sebabnya kata ini berarti rabun jauh. Namun rabun dekat ini hanya muncul seiring bertambahnya usia. Jadi, Anda harus menjadi orang tua untuk memiliki 老眼.') ON CONFLICT (id) DO NOTHING;
