INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8a78bf35-4999-4a97-9a6b-1cda4ba10b62', 'vocabulary', '興味', '興味', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Saya tertarik dengan rasanya... Anda tertarik? Ya, saya mempunyai ketertarikan yang sangat mendalam terhadapnya.', 'Saya tertarik dengan rasanya... Anda tertarik? Ya, saya mempunyai ketertarikan yang sangat mendalam terhadapnya.') ON CONFLICT (id) DO NOTHING;
