INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('93e81f58-11fc-4398-bd09-fe095370c69a', 'vocabulary', '自衛', '自衛', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Pertahanan diri adalah ketika Anda melindungi diri sendiri. Itu pembelaan diri.', 'Pertahanan diri adalah ketika Anda melindungi diri sendiri. Itu pembelaan diri.') ON CONFLICT (id) DO NOTHING;
