INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('93e81f58-11fc-4398-bd09-fe095370c69a', '自衛のための殺人は合法なのでしょうか。', 'Apakah sah membunuh seseorang untuk membela diri?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fbc6e1aa-2b6b-4994-a62c-8a8c6d56f654', 'vocabulary', '衛生', '衛生', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Untuk mempertahankan kehidupan, Anda harus tetap bersih. Jika Anda kotor, Anda akan mati lebih awal (pikirkan: wabah penyakit). Jadi, untuk mempertahankan kehidupan tersebut, Anda harus memiliki kebersihan yang baik.', 'Untuk mempertahankan kehidupan, Anda harus tetap bersih. Jika Anda kotor, Anda akan mati lebih awal (pikirkan: wabah penyakit). Jadi, untuk mempertahankan kehidupan tersebut, Anda harus memiliki kebersihan yang baik.') ON CONFLICT (id) DO NOTHING;
