INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3a0c4a4-7434-4212-8636-ddc6363241ca', '落下する衛星を避けることは、不可能ではありません。', 'Bukan tidak mungkin menghindari satelit yang jatuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d37e064-9f7f-46ca-8407-c554e7aac2ac', 'vocabulary', '酸っぱい', '酸っぱい', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Rasa sesuatu yang asam adalah... yah... Anda mungkin mengira itu asam, tapi rasanya asam. Namun, beberapa hal yang bersifat asam ternyata cukup asam. Lemon cukup asam, dan rasanya juga sangat asam, jadi pikirkanlah hal itu ketika Anda perlu mengingat kata ini.', 'Rasa sesuatu yang asam adalah... yah... Anda mungkin mengira itu asam, tapi rasanya asam. Namun, beberapa hal yang bersifat asam ternyata cukup asam. Lemon cukup asam, dan rasanya juga sangat asam, jadi pikirkanlah hal itu ketika Anda perlu mengingat kata ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9d37e064-9f7f-46ca-8407-c554e7aac2ac', 'asam', true) ON CONFLICT DO NOTHING;
