INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d37e064-9f7f-46ca-8407-c554e7aac2ac', '最初に食べた食べ物は腐りかけていて酸っぱかったです。', 'Makanan pertama yang saya makan busuk dan asam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f6cdf33-dabd-4402-88da-25217bc55419', 'vocabulary', '酸素', '酸素', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Unsur asamnya adalah oksigen. Dalam bahasa Jerman sama dengan dalam bahasa Jepang - disebut “Sauerstoff”, termasuk “sauer”, kata yang berarti “asam”. Versi kata bendanya adalah “säure” yang berarti “asam” dan “asam” (yang juga sama dalam bahasa Jepang, kanji yang sama digunakan di kedua kata tersebut). Kata “oksigenium” dalam bahasa Yunani/Latin secara harafiah berarti “pembuat asam”. Dahulu ahli kimia mengira oksigen adalah ciri khas asam, kemudian mereka menemukan ada juga asam tanpa oksigen seperti asam klorida/muriatik/garam dan ciri penentu sebenarnya adalah hidrogen. Tapi nama itu melekat.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7f6cdf33-dabd-4402-88da-25217bc55419', 'Oksigen', true) ON CONFLICT DO NOTHING;
