INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d35740e-f72d-424a-8f4b-673191738619', 'vocabulary', '銭', '銭', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini juga bisa berarti uang secara lebih umum.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini juga bisa berarti uang secara lebih umum.') ON CONFLICT (id) DO NOTHING;
