INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d0ac87bc-d99b-4449-a220-12f947821280', '祖父の一日は、銭湯から始まります。', 'Kakek saya memulai harinya dengan pergi ke pemandian umum.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1f7ed9eb-a607-44bf-8deb-7f1b8939eb17', 'vocabulary', '飼う', '飼う', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Kanjinya bersifat domestik. Saat Anda menjinakkan hewan, Anda bisa memelihara hewan peliharaan. Anda akan menggunakan ini untuk menggambarkan saat Anda memelihara anjing atau kucing atau sesuatu.', 'Kanjinya bersifat domestik. Saat Anda menjinakkan hewan, Anda bisa memelihara hewan peliharaan. Anda akan menggunakan ini untuk menggambarkan saat Anda memelihara anjing atau kucing atau sesuatu.') ON CONFLICT (id) DO NOTHING;
