INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cb66e3b4-fd72-4f34-a863-27ed797da40d', '彼に振られて傷心気味なので、パリに傷心旅行に行くんです。', 'Dia mencampakkanku dan aku sedikit patah hati, jadi aku akan melakukan perjalanan ke Paris untuk melupakannya.') ON CONFLICT DO NOTHING;
