INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3a34bf9a-24f4-4115-b044-6b5dcf9e684c', 'vocabulary', '密告', '密告', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Secara rahasia Anda harus mengumumkan informasi ini. Ini bukan untuk didengar siapa pun, ini informasi rahasia.', 'Secara rahasia Anda harus mengumumkan informasi ini. Ini bukan untuk didengar siapa pun, ini informasi rahasia.') ON CONFLICT (id) DO NOTHING;
