INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eddcc53d-14c1-4abf-bb66-67c0b22524d3', 'vocabulary', '密輸', '密輸', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Transportasi kerahasiaan adalah saat Anda mengangkut sesuatu secara rahasia. Jika Anda tidak ingin orang lain mengetahui apa yang Anda bawa, Anda harus melakukan penyelundupan.', 'Transportasi kerahasiaan adalah saat Anda mengangkut sesuatu secara rahasia. Jika Anda tidak ingin orang lain mengetahui apa yang Anda bawa, Anda harus melakukan penyelundupan.') ON CONFLICT (id) DO NOTHING;
