INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eddcc53d-14c1-4abf-bb66-67c0b22524d3', '俺は一度麻薬の密輸をする話を持ちかけられたことがあるよ。もちろん断ったけどね。', 'Saya pernah diminta menyelundupkan narkotika.  Tentu saja saya menolak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7df7a372-3472-4fb7-9f88-96332025265d', 'vocabulary', '染める', '染める', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya pewarna jadi versi vocab verbanya adalah mewarnai.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya pewarna jadi versi vocab verbanya adalah mewarnai.') ON CONFLICT (id) DO NOTHING;
