INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7df7a372-3472-4fb7-9f88-96332025265d', '髪を何色に染めるか迷っています。', 'Saya bertanya-tanya warna apa untuk mewarnai rambut saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b3512e56-1b16-4d18-b508-36cf925127ea', 'vocabulary', '感染', '感染', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Rasa pewarna yang menutupi tubuh Anda adalah perasaan adanya kuman dan penyakit jahat yang menembus kulit Anda, masuk ke dalam diri Anda. Ini adalah infeksi, dan ini menjijikkan.', 'Rasa pewarna yang menutupi tubuh Anda adalah perasaan adanya kuman dan penyakit jahat yang menembus kulit Anda, masuk ke dalam diri Anda. Ini adalah infeksi, dan ini menjijikkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b3512e56-1b16-4d18-b508-36cf925127ea', 'Infeksi', true) ON CONFLICT DO NOTHING;
