INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b3512e56-1b16-4d18-b508-36cf925127ea', '歯周病は感染症の一種だとは知りませんでした。', 'Saya tidak tahu kalau periodontitis itu salah satu jenis penyakit menular.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cdafc7c9-8097-4d07-93fa-67d50d2e30c1', 'vocabulary', '伝染病', '伝染病', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Penyakit yang dapat menular dan kemudian mewarnai Anda (alias masuk ke dalam diri Anda dan menulari Anda, melalui penularan) adalah penyakit menular. Semua orang menutup mulutnya saat batuk dan bersin, dan tolong cuci tangan ya.', 'Penyakit yang dapat menular dan kemudian mewarnai Anda (alias masuk ke dalam diri Anda dan menulari Anda, melalui penularan) adalah penyakit menular. Semua orang menutup mulutnya saat batuk dan bersin, dan tolong cuci tangan ya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cdafc7c9-8097-4d07-93fa-67d50d2e30c1', 'Penyakit Menular', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cdafc7c9-8097-4d07-93fa-67d50d2e30c1', 'でんせんびょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cdafc7c9-8097-4d07-93fa-67d50d2e30c1', '世界で一番危険な伝染病は何ですか。', 'Apa penyakit menular paling berbahaya di dunia?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9192ca20-651b-4323-a9ba-c8945c93019a', 'vocabulary', '汚染', '汚染', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Pewarna kotor yang tersebar di langit dan membuat benda menjadi kotor ketika disentuh adalah polusi. Kalau jelek banget itu kayak pewarna juga, bikin baju putih kamu jadi coklat, ih.', 'Pewarna kotor yang tersebar di langit dan membuat benda menjadi kotor ketika disentuh adalah polusi. Kalau jelek banget itu kayak pewarna juga, bikin baju putih kamu jadi coklat, ih.') ON CONFLICT (id) DO NOTHING;
