INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9192ca20-651b-4323-a9ba-c8945c93019a', '自国のPM2.5汚染レベルはどうすれば分かるのでしょうか。', 'Bagaimana saya bisa mengetahui tingkat kontaminasi PM2.5 di komunitas saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('327aba05-39f8-43db-8e47-7145621736ce', 'vocabulary', '暖かい', '暖かい', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari hangat? Ini juga hangat! Meskipun ini untuk cuaca atau suhu yang hangat, bukan makanan hangat atau semacamnya, itu akan menjadi 温かい, あたたかい yang berbeda. Membingungkan, bukan?', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari hangat? Ini juga hangat! Meskipun ini untuk cuaca atau suhu yang hangat, bukan makanan hangat atau semacamnya, itu akan menjadi 温かい, あたたかい yang berbeda. Membingungkan, bukan?') ON CONFLICT (id) DO NOTHING;
