INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6ec18c66-c47e-4307-a4ce-6257230200da', '今年の冬は例年よりも寒くて雪も凄く降ったけど、本当に地球は温暖化してるのかね。', 'Musim dingin ini luar biasa dinginnya dan kita mengalami banyak sekali salju, jadi apakah bumi benar-benar menjadi lebih hangat?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b804e1f5-2c5b-428b-8a25-ef82a73e48a3', 'vocabulary', '秘める', '秘める', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Jika Anda merahasiakan sesuatu, Anda berusaha merahasiakannya. Itu, atau Anda mencoba menyembunyikannya.', 'Jika Anda merahasiakan sesuatu, Anda berusaha merahasiakannya. Itu, atau Anda mencoba menyembunyikannya.') ON CONFLICT (id) DO NOTHING;
