INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cb6a03d4-4f5b-4363-8428-a0f10eb7de05', 'vocabulary', '便秘', '便秘', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Untuk kata ini, 便 berasal dari 便所, yang Anda kenal sebagai "toilet". Rahasia toilet adalah rahasia yang Anda bawa ke kamar mandi, rahasia yang Anda tidak ingin orang lain mengetahuinya. Ini adalah sembelit.', 'Untuk kata ini, 便 berasal dari 便所, yang Anda kenal sebagai "toilet". Rahasia toilet adalah rahasia yang Anda bawa ke kamar mandi, rahasia yang Anda tidak ingin orang lain mengetahuinya. Ini adalah sembelit.') ON CONFLICT (id) DO NOTHING;
