INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e7dffcc3-cc36-4bdc-8696-f0fe049c4c5a', 'vocabulary', '訳', '訳', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Kata ini mengambil arti alasan dari kanji, menjadikannya alasan. Apa alasannya memiliki dua arti? Anda menangkap saya, saya tidak tahu.', 'Kata ini mengambil arti alasan dari kanji, menjadikannya alasan. Apa alasannya memiliki dua arti? Anda menangkap saya, saya tidak tahu.') ON CONFLICT (id) DO NOTHING;
