INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7dffcc3-cc36-4bdc-8696-f0fe049c4c5a', 'どうして便器の上で逆立ちをしようとしたのか訳を聞かせてください。', 'Bisakah Anda memberi tahu saya alasan mengapa Anda mencoba melakukan handstand di atas toilet?') ON CONFLICT DO NOTHING;
