INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c09d334-82b1-45b9-b0e4-886d4cd57917', 'vocabulary', '訳語', '訳語', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Sedikit bahasa yang diterjemahkan adalah istilah yang diterjemahkan.', 'Sedikit bahasa yang diterjemahkan adalah istilah yang diterjemahkan.') ON CONFLICT (id) DO NOTHING;
