INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6b0903c7-fc14-4a3c-ae55-363009b9715b', 'vocabulary', '筋', '筋', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga memiliki makna yang sama, setidaknya dari sisi tendon.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga memiliki makna yang sama, setidaknya dari sisi tendon.') ON CONFLICT (id) DO NOTHING;
