INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b0903c7-fc14-4a3c-ae55-363009b9715b', 'ジョギングをしてる時に足の筋を痛めちゃってさ。', 'Kakiku tegang saat berlari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6b0903c7-fc14-4a3c-ae55-363009b9715b', '今日は久々に牛筋のに込みでも作ってみますか。', 'Saya akhirnya akan membuat sup urat daging sapi hari ini.') ON CONFLICT DO NOTHING;
