INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0fdf01ea-2b1b-42d7-a31f-5a317cd85943', 'vocabulary', '宣伝', '宣伝', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Segala sesuatu yang diberitakan oleh pemimpin disampaikan kepada rakyat. Itu semua adalah propaganda, itulah sebabnya Anda menyebarkannya.', 'Segala sesuatu yang diberitakan oleh pemimpin disampaikan kepada rakyat. Itu semua adalah propaganda, itulah sebabnya Anda menyebarkannya.') ON CONFLICT (id) DO NOTHING;
