INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c98d693c-1d73-4355-aaa2-04f3ce48028f', 'ポツダム宣言っていつだっけ？', 'Kapan Deklarasi Potsdam?') ON CONFLICT DO NOTHING;
