INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('67642c42-1f0a-4bca-b99e-bb9e0b70a336', 'vocabulary', '忠実', '忠実', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Saya memiliki kesetiaan kepada Anda, jadi saya selalu mengatakan yang sebenarnya. Saya sangat setia dan berbakti kepada Anda!', 'Saya memiliki kesetiaan kepada Anda, jadi saya selalu mengatakan yang sebenarnya. Saya sangat setia dan berbakti kepada Anda!') ON CONFLICT (id) DO NOTHING;
