INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d65d2c49-62a0-4f23-ab6a-67b98a6a1702', 'vocabulary', '傷つく', '傷つく', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Ingat bagaimana 傷 adalah "luka"? Kini sebuah luka semakin mendekat padamu, atau dengan kata lain, semakin melekat padamu. Jika ada luka yang menempel di tubuh Anda, kemungkinan besar Anda akan terluka.', 'Ingat bagaimana 傷 adalah "luka"? Kini sebuah luka semakin mendekat padamu, atau dengan kata lain, semakin melekat padamu. Jika ada luka yang menempel di tubuh Anda, kemungkinan besar Anda akan terluka.') ON CONFLICT (id) DO NOTHING;
