INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d65d2c49-62a0-4f23-ab6a-67b98a6a1702', 'おばちゃんって呼ばれる年齢かなあ。傷つくなあ。', 'Bukankah aku terlalu muda untuk disebut wanita paruh baya? saya terluka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('59e64c01-07b8-405e-bd36-c2bbcdae5ad4', 'vocabulary', '傷つける', '傷つける', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Anda つける (menempelkan) luka pada seseorang atau sesuatu. Dengan kata lain, ini berarti menyakiti seseorang, atau mencakar atau merusak sesuatu.', 'Anda つける (menempelkan) luka pada seseorang atau sesuatu. Dengan kata lain, ini berarti menyakiti seseorang, atau mencakar atau merusak sesuatu.') ON CONFLICT (id) DO NOTHING;
