INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('59e64c01-07b8-405e-bd36-c2bbcdae5ad4', 'コンタクトレンズを傷つけちゃったかも。', 'Saya mungkin telah menggores lensa kontak saya.') ON CONFLICT DO NOTHING;
