INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('59e64c01-07b8-405e-bd36-c2bbcdae5ad4', '誰だよ？俺のベンツに鉄棒で傷つけやがったのは？！見つけたらただじゃおかねえぞ！', 'Siapa yang merusak Mercedes saya dengan batang besi?! Mereka akan membayarnya!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d69459a8-6e2b-4b95-a1b6-3e2cd1fe82f4', 'vocabulary', '染み', '染み', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Ini adalah versi kata benda dari 染. Pewarna sepertinya merupakan jawaban yang tepat, tapi apa lagi yang dimaksud dengan pewarna? Jika Anda terkena pada saat Anda tidak ingin terkena, itu akan menjadi noda.', 'Ini adalah versi kata benda dari 染. Pewarna sepertinya merupakan jawaban yang tepat, tapi apa lagi yang dimaksud dengan pewarna? Jika Anda terkena pada saat Anda tidak ingin terkena, itu akan menjadi noda.') ON CONFLICT (id) DO NOTHING;
