INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d69459a8-6e2b-4b95-a1b6-3e2cd1fe82f4', 'この染みなんとか取れないかなあ。', 'Tidak bisakah Anda menemukan cara untuk menghilangkan noda ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2b706a3d-2d5f-4ff4-ba00-944eb32311df', 'vocabulary', '染まる', '染まる', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Jika 染める berarti "mewarnai", maka ini harus diwarnai. Anda tidak melakukan hal yang sekarat, karena Anda tahu bahwa jika Anda melakukannya, Anda akan melakukan hal yang benar, tidak seperti orang lain yang mewarnai rambut Anda. Orang ini merusak (まる) semuanya dengan sangat buruk.', 'Jika 染める berarti "mewarnai", maka ini harus diwarnai. Anda tidak melakukan hal yang sekarat, karena Anda tahu bahwa jika Anda melakukannya, Anda akan melakukan hal yang benar, tidak seperti orang lain yang mewarnai rambut Anda. Orang ini merusak (まる) semuanya dengan sangat buruk.') ON CONFLICT (id) DO NOTHING;
