INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5bfddcf6-16cf-4868-8242-539fa8d2934b', 'vocabulary', '言い訳', '言い訳', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Anda mengatakan alasan atas tindakan Anda, tetapi sebenarnya itu hanyalah alasan.', 'Anda mengatakan alasan atas tindakan Anda, tetapi sebenarnya itu hanyalah alasan.') ON CONFLICT (id) DO NOTHING;
