INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9b080e1-a756-4480-85d0-40f81cde328f', 'vocabulary', '興味がない', '興味がない', 1, '0496335a-1330-4d19-a663-41da10aa742c', '興味 adalah ketertarikan pada sesuatu. Jika Anda tidak memiliki (がない) minat itu, maka Anda tidak tertarik atau tidak tertarik.', '興味 adalah ketertarikan pada sesuatu. Jika Anda tidak memiliki (がない) minat itu, maka Anda tidak tertarik atau tidak tertarik.') ON CONFLICT (id) DO NOTHING;
