INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c4dad02-16d6-4174-95db-f4e019220568', 'あの時、日本政府は非常事態を宣言するべきだったと思わないかい。', 'Tidakkah menurut Anda pemerintah Jepang seharusnya mengumumkan keadaan darurat pada saat itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f5f8237-aa55-43b5-b9c3-108400088fa5', 'vocabulary', '双眼鏡', '双眼鏡', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Sepasang cermin bola mata - itulah teropong. Teropong memiliki cermin di dalamnya yang memungkinkan Anda melihat melalui sepasang lubang mata, sehingga kata ini masuk akal.', 'Sepasang cermin bola mata - itulah teropong. Teropong memiliki cermin di dalamnya yang memungkinkan Anda melihat melalui sepasang lubang mata, sehingga kata ini masuk akal.') ON CONFLICT (id) DO NOTHING;
