INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc4040ab-ce1d-47b3-881b-e0d1fae9b599', 'vocabulary', '傷む', '傷む', 1, '0496335a-1330-4d19-a663-41da10aa742c', 'Kanji artinya luka, dan kata kerjanya intransitif, jadi artinya rusak atau busuk. Lagi pula, buah yang memiliki luka akan menjadi buruk, bukan?', 'Kanji artinya luka, dan kata kerjanya intransitif, jadi artinya rusak atau busuk. Lagi pula, buah yang memiliki luka akan menjadi buruk, bukan?') ON CONFLICT (id) DO NOTHING;
