INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('649000e3-92df-4d2e-b0b3-309f8462326c', 'vocabulary', '熟れる', '熟れる', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya matang, jadi versi vocab verbanya adalah matang.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya matang, jadi versi vocab verbanya adalah matang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('649000e3-92df-4d2e-b0b3-309f8462326c', 'Untuk matang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('649000e3-92df-4d2e-b0b3-309f8462326c', 'うれる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('649000e3-92df-4d2e-b0b3-309f8462326c', 'そろそろ桃が熟れる頃だ。', 'Ini adalah waktu dalam setahun untuk buah persik matang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f36f6e0e-d9e7-41fe-809b-7fc74ff582bf', 'vocabulary', '熟語', '熟語', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Bahasa yang matang adalah kata-kata yang memerlukan waktu untuk terbentuk. Mereka matang, dimulai dengan hanya satu kanji, tapi kemudian menjadi dua, atau tiga, atau lebih. Yaitu kata majemuk atau kanji majemuk. Anda tahu hal "jukugo" yang sering saya bicarakan? Itu dia!', 'Bahasa yang matang adalah kata-kata yang memerlukan waktu untuk terbentuk. Mereka matang, dimulai dengan hanya satu kanji, tapi kemudian menjadi dua, atau tiga, atau lebih. Yaitu kata majemuk atau kanji majemuk. Anda tahu hal "jukugo" yang sering saya bicarakan? Itu dia!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f36f6e0e-d9e7-41fe-809b-7fc74ff582bf', 'Kata Majemuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f36f6e0e-d9e7-41fe-809b-7fc74ff582bf', 'Compound Kanji', false) ON CONFLICT DO NOTHING;
