INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f36f6e0e-d9e7-41fe-809b-7fc74ff582bf', 'じゅくご', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f36f6e0e-d9e7-41fe-809b-7fc74ff582bf', '昨日その熟語を学んだところです。', 'Saya baru mempelajari kata majemuk itu kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc38cb18-e3e6-4e27-ade3-baf4039585db', 'vocabulary', '未熟', '未熟', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Belum matang, berarti belum benar-benar terbentuk. Itu berarti Anda belum mahir dalam suatu hal.', 'Belum matang, berarti belum benar-benar terbentuk. Itu berarti Anda belum mahir dalam suatu hal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc38cb18-e3e6-4e27-ade3-baf4039585db', 'Belum Pandai', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fc38cb18-e3e6-4e27-ade3-baf4039585db', 'Not Good At', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fc38cb18-e3e6-4e27-ade3-baf4039585db', 'みじゅく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc38cb18-e3e6-4e27-ade3-baf4039585db', '俺も昔は未熟で好き勝手してたよ。', 'Saya dulunya belum dewasa dan saya juga melakukan apa pun yang saya inginkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fff87066-960e-4237-8d09-f546892901a6', 'vocabulary', '成熟', '成熟', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Menjadi matang(n) berarti matang dan matang.', 'Menjadi matang(n) berarti matang dan matang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fff87066-960e-4237-8d09-f546892901a6', 'Matang', true) ON CONFLICT DO NOTHING;
