INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fff87066-960e-4237-8d09-f546892901a6', '成熟した女性の脳と成熟した男性の脳の相違点について、論文を書いています。', 'Saya sedang menulis makalah tentang perbedaan antara otak wanita dewasa dan otak pria dewasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1868a20-37dc-4611-9962-4a014c3bcf8a', 'vocabulary', '異なる', '異なる', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbeda sehingga versi vocab verbanya berbeda.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbeda sehingga versi vocab verbanya berbeda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1868a20-37dc-4611-9962-4a014c3bcf8a', 'Untuk Berbeda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1868a20-37dc-4611-9962-4a014c3bcf8a', 'ことなる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1868a20-37dc-4611-9962-4a014c3bcf8a', '種類の異なるコーヒーを飲み比べてみました。', 'Saya minum dan membandingkan berbagai jenis kopi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1868a20-37dc-4611-9962-4a014c3bcf8a', '異なる言語や文化を背景にした人々同士でコミュニケーションを上手く取るのは難しいと思います。', 'Sulit bagi orang-orang dari latar belakang bahasa dan budaya yang berbeda untuk berkomunikasi dengan baik satu sama lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1868a20-37dc-4611-9962-4a014c3bcf8a', 'それぞれの薬には、異なる副作用があります。', 'Setiap obat mempunyai efek samping yang berbeda-beda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c2562f1c-b1fc-4c20-981b-c85ce82f87f0', 'vocabulary', '異状', '異状', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Ini berbeda dari kondisi normal, membuatnya aneh. Ini adalah suatu kelainan. Ada sesuatu yang salah.', 'Ini berbeda dari kondisi normal, membuatnya aneh. Ini adalah suatu kelainan. Ada sesuatu yang salah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c2562f1c-b1fc-4c20-981b-c85ce82f87f0', 'Kelainan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c2562f1c-b1fc-4c20-981b-c85ce82f87f0', 'Something Wrong', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c2562f1c-b1fc-4c20-981b-c85ce82f87f0', 'いじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c2562f1c-b1fc-4c20-981b-c85ce82f87f0', '子宮がん検診の結果が「異状あり」だったのでびびっています。', 'Tes Pap saya "tidak normal" dan saya panik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c84e539a-d6b9-41a5-aba4-01b96427dabd', 'vocabulary', '異性', '異性', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Seseorang yang berbeda jenis kelaminnya dengan Anda berarti berjenis kelamin berbeda. Ini sering digunakan untuk mengartikan lawan jenis dalam arti laki-laki sebagaimana dipandang oleh perempuan dan sebaliknya.', 'Seseorang yang berbeda jenis kelaminnya dengan Anda berarti berjenis kelamin berbeda. Ini sering digunakan untuk mengartikan lawan jenis dalam arti laki-laki sebagaimana dipandang oleh perempuan dan sebaliknya.') ON CONFLICT (id) DO NOTHING;
