INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('95b6bd6a-1d3b-4b3e-9ac1-ea919b7cde55', 'vocabulary', '異義', '異義', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Gagasan saya tentang kebenaran berbeda dengan gagasan Anda. Sebenarnya hanya beda makna saja.', 'Gagasan saya tentang kebenaran berbeda dengan gagasan Anda. Sebenarnya hanya beda makna saja.') ON CONFLICT (id) DO NOTHING;
