INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d28b6e0e-fd95-4e87-9983-2a9a61c86a4e', 'vocabulary', '盛る', '盛る', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menumpuk, jadi versi vocab verbanya adalah menumpuk. Ini juga bisa berarti menyajikan makanan, seperti Anda menumpuk makanan di piring seseorang.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menumpuk, jadi versi vocab verbanya adalah menumpuk. Ini juga bisa berarti menyajikan makanan, seperti Anda menumpuk makanan di piring seseorang.') ON CONFLICT (id) DO NOTHING;
