INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e70f9980-4f6b-4fca-aaa3-f28fd61a7822', 'vocabulary', '兄貴', '兄貴', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Kakak laki-laki itu berharga bagimu. Tapi, betapapun berharganya dia bagimu, dia tetaplah kakakmu. P.S. Anda akan sering melihat beberapa preman gangstah menyebut preman gangstah berpangkat lebih tinggi (yang bertindak seperti kakak bagi semua preman gangstah lainnya) ini. Ini seperti keluarga di dalam geng.', 'Kakak laki-laki itu berharga bagimu. Tapi, betapapun berharganya dia bagimu, dia tetaplah kakakmu. P.S. Anda akan sering melihat beberapa preman gangstah menyebut preman gangstah berpangkat lebih tinggi (yang bertindak seperti kakak bagi semua preman gangstah lainnya) ini. Ini seperti keluarga di dalam geng.') ON CONFLICT (id) DO NOTHING;
