INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4603f5be-2a15-4180-9525-99446146e709', 'vocabulary', '貴族', '貴族', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Orang-orang dari suku yang berharga adalah bagian dari kaum bangsawan. Berbeda dengan suku kami, mereka berharga.', 'Orang-orang dari suku yang berharga adalah bagian dari kaum bangsawan. Berbeda dengan suku kami, mereka berharga.') ON CONFLICT (id) DO NOTHING;
