INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('031dac5b-d41a-44f8-8d3a-a602bbf00eb7', 'vocabulary', '推薦', '推薦', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Menyimpulkan dan merekomendasikan sesuatu berarti memberikan rekomendasi. Menu apa yang Anda sarankan?', 'Menyimpulkan dan merekomendasikan sesuatu berarti memberikan rekomendasi. Menu apa yang Anda sarankan?') ON CONFLICT (id) DO NOTHING;
