INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('24890df8-810b-4bdb-bb17-33517a2729d2', 'この番組を彼に薦められたんだけど、アニメを観るのはあまり好きじゃないんだよね。', 'Dia merekomendasikan acara ini kepadaku, tapi aku tidak terlalu suka menonton anime.') ON CONFLICT DO NOTHING;
