INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6370591f-f288-4689-9219-d27a0405be62', 'vocabulary', '沿線', '沿線', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Berlari di sepanjang jalur (mengacu pada jalur kereta api) berarti sepanjang jalur kereta. Apa yang ada di sepanjang jalur kereta? Segala macam hal jika Anda perhatikan dengan cermat.', 'Berlari di sepanjang jalur (mengacu pada jalur kereta api) berarti sepanjang jalur kereta. Apa yang ada di sepanjang jalur kereta? Segala macam hal jika Anda perhatikan dengan cermat.') ON CONFLICT (id) DO NOTHING;
