INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d6b0f995-424b-40ca-b6b9-7b5168b5d74d', 'vocabulary', '沿う', '沿う', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berlari bersama jadi versi vocab verbanya adalah berlari bersama.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berlari bersama jadi versi vocab verbanya adalah berlari bersama.') ON CONFLICT (id) DO NOTHING;
