INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b48de154-9f51-4496-86c4-ba8aa52b0a8d', 'vocabulary', '震源地', '震源地', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Daerah asal gempa adalah tempat terjadinya gempa. Ini adalah pusat gempa.', 'Daerah asal gempa adalah tempat terjadinya gempa. Ini adalah pusat gempa.') ON CONFLICT (id) DO NOTHING;
