INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e653f84a-1bfd-4d6d-adfa-7899db39cc63', 'vocabulary', '歓楽街', '歓楽街', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Jalan yang menyenangkan dan nyaman. Kedengarannya bagus. Kedengarannya seperti "kawasan kesenangan". Anda akan sering melihatnya di film-film samurai, atau di area yang lebih samar.', 'Jalan yang menyenangkan dan nyaman. Kedengarannya bagus. Kedengarannya seperti "kawasan kesenangan". Anda akan sering melihatnya di film-film samurai, atau di area yang lebih samar.') ON CONFLICT (id) DO NOTHING;
