INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e653f84a-1bfd-4d6d-adfa-7899db39cc63', '黒田はそう言い残すと、歓楽街へと消えていった。', 'Mengatakan itu, Kuroda menghilang ke dalam kawasan kesenangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e653f84a-1bfd-4d6d-adfa-7899db39cc63', '歓楽街のツアーには何が含まれていますか。', 'Apa saja yang termasuk dalam tur kawasan kesenangan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e653f84a-1bfd-4d6d-adfa-7899db39cc63', '私が歓楽街で働いているという噂の源をつきとめました。', 'Saya telah menelusuri sumber rumor bahwa saya bekerja di bagian kesenangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('52bf366b-e09e-46b9-8002-c9925239c4c6', 'vocabulary', '豆', '豆', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
