INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('52bf366b-e09e-46b9-8002-c9925239c4c6', 'お豆さん、お豆さん、魔法の野菜。たくさん食べれば食べるほど、たくさん屁が出るぷっぷぷぷ。たくさんぷっぷぷ屁が出れば、気持ちが良くなるウッフフフ。だから毎食お豆を食べなさい。', 'Kacang-kacangan, kacang-kacangan adalah buah ajaib, semakin banyak Anda makan, semakin banyak Anda makan, semakin banyak Anda makan, semakin baik perasaan Anda, jadi makanlah kacang-kacangan setiap kali makan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f42186a-085c-4002-a84d-300cc715a318', 'vocabulary', '小豆', '小豆', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Kacang kecil mengacu pada jenis kacang yang dikenal sebagai kacang azuki. Akan sangat membantu jika Anda pernah mendengar tentang kacang populer yang lezat ini, karena tidak ada sesuatu pun yang efektif yang dapat kita lakukan dengan mnemonik makna mulai saat ini. Ketahuilah bahwa kacang kecil adalah kacang azuki.', 'Kacang kecil mengacu pada jenis kacang yang dikenal sebagai kacang azuki. Akan sangat membantu jika Anda pernah mendengar tentang kacang populer yang lezat ini, karena tidak ada sesuatu pun yang efektif yang dapat kita lakukan dengan mnemonik makna mulai saat ini. Ketahuilah bahwa kacang kecil adalah kacang azuki.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f42186a-085c-4002-a84d-300cc715a318', 'Kacang Azuki', true) ON CONFLICT DO NOTHING;
