INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f42186a-085c-4002-a84d-300cc715a318', '餡こは小豆から作られているが、けっこう糖分が高い。', 'Pasta kacang azuki terbuat dari kacang azuki, namun kandungan gulanya cukup tinggi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9164b0ae-bf68-48f2-adad-ec8f955674cb', 'vocabulary', '納豆', '納豆', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Persediaan kacang-kacangan adalah saat Anda mengambil seikat kacang-kacangan, menumbuknya menjadi persediaan, lalu memfermentasi semuanya menjadi natto (juga dikenal sebagai kedelai yang difermentasi).', 'Persediaan kacang-kacangan adalah saat Anda mengambil seikat kacang-kacangan, menumbuknya menjadi persediaan, lalu memfermentasi semuanya menjadi natto (juga dikenal sebagai kedelai yang difermentasi).') ON CONFLICT (id) DO NOTHING;
