INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9164b0ae-bf68-48f2-adad-ec8f955674cb', '誤解しないでね。日本料理は大好きなんだけど、納豆だけはどうしても食べられないの。', 'Jangan salah paham. Saya suka makanan Jepang, tapi saya tidak pernah bisa hanya makan natto saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dce6619e-f4ce-4c94-bcb4-d3b92d899721', 'vocabulary', '腐る', '腐る', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membusuk jadi versi vocab verbanya adalah membusuk.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membusuk jadi versi vocab verbanya adalah membusuk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dce6619e-f4ce-4c94-bcb4-d3b92d899721', 'Membusuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('dce6619e-f4ce-4c94-bcb4-d3b92d899721', 'くさる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dce6619e-f4ce-4c94-bcb4-d3b92d899721', '牛乳は腐りやすいんだから冷蔵庫の外に出しっ放しにしないでね。', 'Jangan tinggalkan susu di luar lemari es karena mudah rusak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b29601f9-65e5-4d88-a45b-5ef9c3f32256', 'vocabulary', '腐食', '腐食', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Ketika sesuatu membusuk dan menggerogoti sesuatu, itulah korosi. Bukan hal yang baik.', 'Ketika sesuatu membusuk dan menggerogoti sesuatu, itulah korosi. Bukan hal yang baik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b29601f9-65e5-4d88-a45b-5ef9c3f32256', 'Korosi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b29601f9-65e5-4d88-a45b-5ef9c3f32256', 'ふしょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b29601f9-65e5-4d88-a45b-5ef9c3f32256', 'ステンレスは腐食作用への耐久性があるんじゃなかったっけ？', 'Baja tahan karat seharusnya tahan terhadap korosi, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', 'vocabulary', '腐敗', '腐敗', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Pembusukan dan kegagalan menyebabkan pembusukan dan pembusukan. Kata ini juga memiliki arti yang terkait dengan korupsi, mirip dengan bagaimana “busuk” dapat berarti “korup” dalam bahasa Inggris.', 'Pembusukan dan kegagalan menyebabkan pembusukan dan pembusukan. Kata ini juga memiliki arti yang terkait dengan korupsi, mirip dengan bagaimana “busuk” dapat berarti “korup” dalam bahasa Inggris.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', 'Penguraian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', 'Rotting', false) ON CONFLICT DO NOTHING;
