INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', 'ふはい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', 'そこには、何かが腐敗したような臭いがただよっていた。', 'Ada bau sesuatu yang membusuk di udara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', 'この添加物により、食品の腐敗が防げます。', 'Bahan tambahan ini mencegah makanan membusuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('23cc3aee-6ee7-4326-8402-296a3ca86254', '多くの人々が腐敗した政治組織にうんざりしています。', 'Banyak orang sudah bosan dengan lingkaran politik yang korup.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b34672e-abed-483b-8e68-bc9f7ef31553', 'vocabulary', '盛り上げる', '盛り上げる', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', '盛る adalah "menumpuk". Jika Anda "menaikkan" (上げる) apa yang Anda timbun, itu berarti menimbun sesuatu, menjadikan kata ini menumpuk atau menumpuk. Kata ini juga digunakan ketika ingin menghidupkan suatu hal. Kumpulkan energi itu dan gejolak segalanya!', '盛る adalah "menumpuk". Jika Anda "menaikkan" (上げる) apa yang Anda timbun, itu berarti menimbun sesuatu, menjadikan kata ini menumpuk atau menumpuk. Kata ini juga digunakan ketika ingin menghidupkan suatu hal. Kumpulkan energi itu dan gejolak segalanya!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5b34672e-abed-483b-8e68-bc9f7ef31553', 'Untuk Menumpuk', true) ON CONFLICT DO NOTHING;
