INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5b34672e-abed-483b-8e68-bc9f7ef31553', 'もりあげる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b34672e-abed-483b-8e68-bc9f7ef31553', '俺の友達はメチャクチャ面白くて、パーティーを盛り上げるのが得意なんだよ。', 'Teman saya sangat menarik dan dia hebat dalam meramaikan pesta.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4c33e978-046f-4571-84e5-fe097ad0ab36', 'vocabulary', '納まる', '納まる', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Jika 納める berarti "menyediakan" atau "menyampaikan", maka kata ini berarti sesuatu telah diserahkan: jadi harus dipenuhi atau diselesaikan. Anda tidak melakukan penyediaan, dan Anda mengetahui hal ini karena jika Anda ketahuan memasok, reputasi Anda akan rusak (まる seumur hidup).', 'Jika 納める berarti "menyediakan" atau "menyampaikan", maka kata ini berarti sesuatu telah diserahkan: jadi harus dipenuhi atau diselesaikan. Anda tidak melakukan penyediaan, dan Anda mengetahui hal ini karena jika Anda ketahuan memasok, reputasi Anda akan rusak (まる seumur hidup).') ON CONFLICT (id) DO NOTHING;
