INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c33e978-046f-4571-84e5-fe097ad0ab36', '金を払うだけで、彼らが納まるとは思えないけどな。', 'Saya rasa mereka tidak akan puas hanya dengan uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b6050f6-a3c0-449e-88e5-849418f8de59', 'vocabulary', '納得', '納得', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Saya akan menyediakan dan Anda akan memperolehnya. Apakah itu terdengar bagus? Apakah saya mendapat persetujuan Anda? Saya dapat melihat bahwa Anda memahami dan yakin. Anda berencana menerima lamaran saya, bukan?', 'Saya akan menyediakan dan Anda akan memperolehnya. Apakah itu terdengar bagus? Apakah saya mendapat persetujuan Anda? Saya dapat melihat bahwa Anda memahami dan yakin. Anda berencana menerima lamaran saya, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1b6050f6-a3c0-449e-88e5-849418f8de59', 'Menjadi Yakin', true) ON CONFLICT DO NOTHING;
