INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1b6050f6-a3c0-449e-88e5-849418f8de59', 'なっとく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b6050f6-a3c0-449e-88e5-849418f8de59', '彼の意見には納得だね。', 'Saya yakin dengan pendapatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b6050f6-a3c0-449e-88e5-849418f8de59', 'それは納得できない！', 'Itu yang saya tidak mengerti!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b6050f6-a3c0-449e-88e5-849418f8de59', 'どうせお前は娘を金ずくで納得させたんだろう？', 'Anda membuat putri saya setuju menggunakan uang, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ae29a511-b07d-4a65-88c2-4e5ea6dc8a15', 'vocabulary', '同音異義語', '同音異義語', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Anda memiliki bunyi yang sama dengan arti yang berbeda (異義), dan itu adalah bagian dari bahasa. Kedengarannya sama... artinya berbeda... yang terdengar seperti homofon, atau homonim.', 'Anda memiliki bunyi yang sama dengan arti yang berbeda (異義), dan itu adalah bagian dari bahasa. Kedengarannya sama... artinya berbeda... yang terdengar seperti homofon, atau homonim.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae29a511-b07d-4a65-88c2-4e5ea6dc8a15', 'Homonim', true) ON CONFLICT DO NOTHING;
