INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ae29a511-b07d-4a65-88c2-4e5ea6dc8a15', 'どうおんいぎご', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae29a511-b07d-4a65-88c2-4e5ea6dc8a15', '同音異義語のテストで０点を取って、恥をかいてしまいました。', 'Saya malu ketika mendapat nilai nol pada tes homofon.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae29a511-b07d-4a65-88c2-4e5ea6dc8a15', '日本語には、同音異義語はいくつありますか？', 'Berapa banyak homofon dalam bahasa Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae29a511-b07d-4a65-88c2-4e5ea6dc8a15', '同音異義語に関するユーチューブビデオを作ったので、よかったら見てみてください。', 'Saya membuat video YouTube tentang homonim, jadi silakan lihat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('453db464-7c1d-4c33-ae42-7ccddb9df20d', 'vocabulary', '彫刻', '彫刻', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Anda mengukir lalu Anda mengukir lagi. Banyak sekali ukirannya sampai, tunggu, wow, sepertinya ada sesuatu! Semua ukiran itu menjadi patung!', 'Anda mengukir lalu Anda mengukir lagi. Banyak sekali ukirannya sampai, tunggu, wow, sepertinya ada sesuatu! Semua ukiran itu menjadi patung!') ON CONFLICT (id) DO NOTHING;
