INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('453db464-7c1d-4c33-ae42-7ccddb9df20d', '彫刻を落として、真っ二つに割ってしまいました。', 'Saya menjatuhkan patung itu dan pecah menjadi dua.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1162b5eb-e4b7-4115-aa4a-6dac5f8692e7', 'vocabulary', '推測', '推測', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Anda dapat menyimpulkan dan mengukur semua yang Anda inginkan. Jika Anda melakukan cukup banyak hal, Anda akan mendapatkan dugaan dan spekulasi bagus dari kesimpulan dan pengukuran tersebut.', 'Anda dapat menyimpulkan dan mengukur semua yang Anda inginkan. Jika Anda melakukan cukup banyak hal, Anda akan mendapatkan dugaan dan spekulasi bagus dari kesimpulan dan pengukuran tersebut.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1162b5eb-e4b7-4115-aa4a-6dac5f8692e7', 'Dugaan', true) ON CONFLICT DO NOTHING;
