INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1162b5eb-e4b7-4115-aa4a-6dac5f8692e7', 'すいそく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1162b5eb-e4b7-4115-aa4a-6dac5f8692e7', '私の推測では、彼は宝くじが当たって、バハマに引っ越した。', 'Dugaan saya adalah dia memenangkan lotre dan pindah ke Bahama.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5dc2d96a-c9e4-4e24-b449-9d6fd51f7910', 'vocabulary', '吐き気', '吐き気', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Perasaan muntah adalah mual.', 'Perasaan muntah adalah mual.') ON CONFLICT (id) DO NOTHING;
