INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5dc2d96a-c9e4-4e24-b449-9d6fd51f7910', 'ビールでいい気分になったんだけど、その後吐き気がひどくてさ。', 'Birnya membuatku merasa enak, tapi setelah itu aku merasa sangat mual.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1dc4766b-d9bd-485e-bb89-2676ed536933', 'vocabulary', '吐き出す', '吐き出す', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Jika 吐く berarti muntah, dan jika 出す berarti mengeluarkan atau menyerahkan, maka jika Anda muntah dan menyerahkan muntahan itu kepada seseorang melalui muntahan Anda, Anda akan meludahinya, atau memuntahkannya, atau sesuatu yang menjijikkan seperti itu. Lagi pula, kata ini bisa digunakan seperti "sudahkan infonya!" juga, jadi tidak semuanya benar-benar meludah.', 'Jika 吐く berarti muntah, dan jika 出す berarti mengeluarkan atau menyerahkan, maka jika Anda muntah dan menyerahkan muntahan itu kepada seseorang melalui muntahan Anda, Anda akan meludahinya, atau memuntahkannya, atau sesuatu yang menjijikkan seperti itu. Lagi pula, kata ini bisa digunakan seperti "sudahkan infonya!" juga, jadi tidak semuanya benar-benar meludah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1dc4766b-d9bd-485e-bb89-2676ed536933', 'Untuk Meludahkan', true) ON CONFLICT DO NOTHING;
