INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1dc4766b-d9bd-485e-bb89-2676ed536933', '男は舐めていた飴を吐き出しました。', 'Pria itu memuntahkan permen yang dia hisap.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e13fe89-27be-4753-a8f0-7e0f58428680', 'vocabulary', '奴ら', '奴ら', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Jika 奴 hanyalah seorang laki-laki atau laki-laki, menambahkan ら di sana akan menjadikannya jamak. Sekarang orang-orang itu atau orang-orang itu.', 'Jika 奴 hanyalah seorang laki-laki atau laki-laki, menambahkan ら di sana akan menjadikannya jamak. Sekarang orang-orang itu atau orang-orang itu.') ON CONFLICT (id) DO NOTHING;
