INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e13fe89-27be-4753-a8f0-7e0f58428680', '奴ら、俺たちは働いてるってのに、呑気に日光浴なんかしてやがるぜ。', 'Orang-orang itu sedang mandi dan bersantai di bawah sinar matahari saat kami bekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('76ddcc1c-9858-43c4-b79e-a7e002570539', 'vocabulary', '薦め', '薦め', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Jika 薦める berarti "merekomendasikan", maka versi kata bendanya adalah rekomendasi atau nasihat. Ini umumnya mengacu pada rekomendasi seseorang atau sesuatu, bukan suatu tindakan.', 'Jika 薦める berarti "merekomendasikan", maka versi kata bendanya adalah rekomendasi atau nasihat. Ini umumnya mengacu pada rekomendasi seseorang atau sesuatu, bukan suatu tindakan.') ON CONFLICT (id) DO NOTHING;
