INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('76ddcc1c-9858-43c4-b79e-a7e002570539', 'そのスリッパは私のお薦めです。', 'Sandal itu adalah rekomendasi saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('898cf9a0-bc49-4594-b1ec-7a8f53bc75b5', 'vocabulary', '電磁場', '電磁場', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'A 磁場 adalah "medan magnet". Versi listriknya adalah medan elektromagnetik.', 'A 磁場 adalah "medan magnet". Versi listriknya adalah medan elektromagnetik.') ON CONFLICT (id) DO NOTHING;
