INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('898cf9a0-bc49-4594-b1ec-7a8f53bc75b5', 'でんじば', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('898cf9a0-bc49-4594-b1ec-7a8f53bc75b5', '私の父は、電磁場発生装置の特許を持っているんですが、私はそれが何のためのものなのかよく分かりません。', 'Ayah saya mempunyai hak paten untuk generator medan elektromagnetik, tapi saya tidak yakin untuk apa paten itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3dca42b7-73e3-4163-b2da-967b34c8d31e', 'vocabulary', '放射能', '放射能', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', '放射 adalah "radiasi." Tambahkan kemampuan radiasi dan Anda memiliki radioaktivitas, untuk beberapa alasan. Saya kira benda tidak memiliki radioaktivitas sampai Anda memberinya kemampuan radiasi, bukan?', '放射 adalah "radiasi." Tambahkan kemampuan radiasi dan Anda memiliki radioaktivitas, untuk beberapa alasan. Saya kira benda tidak memiliki radioaktivitas sampai Anda memberinya kemampuan radiasi, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3dca42b7-73e3-4163-b2da-967b34c8d31e', 'Radioaktivitas', true) ON CONFLICT DO NOTHING;
