INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3dca42b7-73e3-4163-b2da-967b34c8d31e', 'ほうしゃのう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3dca42b7-73e3-4163-b2da-967b34c8d31e', '放射能に関する会議を招集する前に、出席者を決める方がいいだろう。', 'Sebelum mengadakan pertemuan tentang radioaktivitas, kita harus memutuskan siapa yang harus hadir.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3dc6c34f-1e53-4f12-a8cd-a645b5faecb1', 'vocabulary', '指揮者', '指揮者', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Jika 指揮 adalah "perintah" atau "memimpin" maka seseorang yang melakukan hal-hal tersebut adalah seorang komandan, atau kondektur. Biasanya jenis yang memimpin orkestra!', 'Jika 指揮 adalah "perintah" atau "memimpin" maka seseorang yang melakukan hal-hal tersebut adalah seorang komandan, atau kondektur. Biasanya jenis yang memimpin orkestra!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3dc6c34f-1e53-4f12-a8cd-a645b5faecb1', 'Konduktor', true) ON CONFLICT DO NOTHING;
