INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3dc6c34f-1e53-4f12-a8cd-a645b5faecb1', 'どちらの指揮者もまだ来てないんだよ。', 'Belum ada komandan yang datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2dc7ec16-8659-42e4-9e53-e3a7e3124df6', 'vocabulary', '源氏物語', '源氏物語', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Ingat 源氏? Dia punya miliknya sendiri. Ini adalah novel pertama yang pernah ditulis (yang kami ketahui). Ini adalah Kisah Genji.', 'Ingat 源氏? Dia punya miliknya sendiri. Ini adalah novel pertama yang pernah ditulis (yang kami ketahui). Ini adalah Kisah Genji.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2dc7ec16-8659-42e4-9e53-e3a7e3124df6', 'Kisah Genji', true) ON CONFLICT DO NOTHING;
