INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2dc7ec16-8659-42e4-9e53-e3a7e3124df6', 'げんじものがたり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2dc7ec16-8659-42e4-9e53-e3a7e3124df6', '私は源氏物語を漫画でしか読んだことがありません。', 'Saya hanya membaca Kisah Genji versi manga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('409f7a5b-78b3-4486-a60f-24bd55be232c', 'vocabulary', '枝豆', '枝豆', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Buncis tidak berarti banyak dengan cara ini, tetapi Anda mungkin tahu makanan yang dijelaskan di sini. Ini edamame, makanan yang terbuat dari kacang kedelai yang dikukus, biasanya diberi sedikit garam untuk menambah rasa.', 'Buncis tidak berarti banyak dengan cara ini, tetapi Anda mungkin tahu makanan yang dijelaskan di sini. Ini edamame, makanan yang terbuat dari kacang kedelai yang dikukus, biasanya diberi sedikit garam untuk menambah rasa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('409f7a5b-78b3-4486-a60f-24bd55be232c', 'Edamame', true) ON CONFLICT DO NOTHING;
