INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('409f7a5b-78b3-4486-a60f-24bd55be232c', '「お早うございます。何にいたしましょうか？」「いつものやつ頼むよ。」「かしこまりました。ビールと枝豆でございますね。」「そうだよ。」', '"Selamat pagi. Apa yang bisa saya bantu?" "Aku pesan yang biasa." "Baiklah. Bir dan Edamame, kan?" "Itu saja."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a7ecae8a-f025-46ad-9c55-46a233209cf7', 'vocabulary', '豆腐', '豆腐', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Busuk kacang terjadi saat Anda mengambil kacang kedelai, membiarkannya berfermentasi, lalu membuat tahu darinya! Ya, itulah tahu. Kacang busuk.', 'Busuk kacang terjadi saat Anda mengambil kacang kedelai, membiarkannya berfermentasi, lalu membuat tahu darinya! Ya, itulah tahu. Kacang busuk.') ON CONFLICT (id) DO NOTHING;
