INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a7ecae8a-f025-46ad-9c55-46a233209cf7', 'うーん。どっちの豆腐もいまいちかな。実は豆腐はあんまり好きじゃないんだよね。', 'Ya, tidak ada tahu yang rasanya enak menurutku. Saya sebenarnya bukan penggemar tahu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1e74ff4c-9478-47a3-a4bd-0fb1709fdfd8', 'vocabulary', '盛り上がる', '盛り上がる', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', '盛り上げる adalah "menumpuk" - ini memiliki gagasan serupa, hanya saja sekarang ini lebih seperti kegembiraan atau pembengkakan. Saat kegembiraan menumpuk dalam diri Anda, Anda akan menjadi bersemangat. Perhatikan bagaimana 上がる ada di sini. Ini berarti sesuatu sedang terjadi pada Anda (atau sesuatu yang lain), namun Anda tidak melakukan tindakan tersebut. Ketika segala jenis kegembiraan mulai terbentuk dalam diri Anda, sebenarnya Anda tidak melakukannya, itu hanya terjadi dengan sendirinya sebagai reaksi terhadap hal lain.', '盛り上げる adalah "menumpuk" - ini memiliki gagasan serupa, hanya saja sekarang ini lebih seperti kegembiraan atau pembengkakan. Saat kegembiraan menumpuk dalam diri Anda, Anda akan menjadi bersemangat. Perhatikan bagaimana 上がる ada di sini. Ini berarti sesuatu sedang terjadi pada Anda (atau sesuatu yang lain), namun Anda tidak melakukan tindakan tersebut. Ketika segala jenis kegembiraan mulai terbentuk dalam diri Anda, sebenarnya Anda tidak melakukannya, itu hanya terjadi dengan sendirinya sebagai reaksi terhadap hal lain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1e74ff4c-9478-47a3-a4bd-0fb1709fdfd8', 'Membengkak', true) ON CONFLICT DO NOTHING;
