INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1e74ff4c-9478-47a3-a4bd-0fb1709fdfd8', '子どもっていうのは、どんなささいなことでも手当たり次第に盛り上がることができるのよね。', 'Anak-anak dapat mengambil hal-hal yang paling biasa dan acak dan menjadi sangat bersemangat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('035ad7c5-b560-41cf-b63f-08055ce3c9b1', 'vocabulary', '湯豆腐', '湯豆腐', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', '豆腐 itu tahu, dan 湯 artinya air panas, jadi tahunya sudah dimasukkan ke dalam air panas alias tahu rebus.', '豆腐 itu tahu, dan 湯 artinya air panas, jadi tahunya sudah dimasukkan ke dalam air panas alias tahu rebus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('035ad7c5-b560-41cf-b63f-08055ce3c9b1', 'Tahu Rebus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('035ad7c5-b560-41cf-b63f-08055ce3c9b1', 'ゆどうふ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('035ad7c5-b560-41cf-b63f-08055ce3c9b1', '最初は、どんなもんかなと思って湯豆腐を食べてみただけなんですが、そしたら好きになっちゃったんですよね。', 'Awalnya saya hanya mencoba tahu rebus karena penasaran, dan kemudian saya semakin menyukainya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8e35e7c4-512f-4b72-a4a0-180498f1e0e8', 'vocabulary', '幕府', '幕府', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Pemerintahan di balik tirai adalah bakufu. Mereka tidak membiarkan siapa pun mengetahui rahasia pemerintahannya sehingga mereka bersembunyi di balik tirai dan menyimpan semuanya untuk diri mereka sendiri.', 'Pemerintahan di balik tirai adalah bakufu. Mereka tidak membiarkan siapa pun mengetahui rahasia pemerintahannya sehingga mereka bersembunyi di balik tirai dan menyimpan semuanya untuk diri mereka sendiri.') ON CONFLICT (id) DO NOTHING;
