INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e35e7c4-512f-4b72-a4a0-180498f1e0e8', '幕府が俺の家族を皆殺しにした。', 'Bakufu membantai keluargaku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9a26b6a5-10f4-4d44-a603-b4db6127d357', 'vocabulary', '貴重', '貴重', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Sesuatu yang berharga dan berat sangatlah berharga dan bahkan mungkin lebih berharga daripada barang yang tidak terlalu berat.', 'Sesuatu yang berharga dan berat sangatlah berharga dan bahkan mungkin lebih berharga daripada barang yang tidak terlalu berat.') ON CONFLICT (id) DO NOTHING;
