INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ae00749-b648-4b52-b76c-07af0f9a79ab', 'vocabulary', '異常', '異常', 1, '880a2c72-1cee-4503-af4a-feddb41fbbd4', 'Apabila ada sesuatu yang berbeda dari biasanya maka disebut tidak normal atau aneh.', 'Apabila ada sesuatu yang berbeda dari biasanya maka disebut tidak normal atau aneh.') ON CONFLICT (id) DO NOTHING;
