INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34b47aa5-b9d2-47b6-a270-b6266214c6b2', 'その石には仏像が彫ってありました。', 'Ada gambar Buddha yang diukir di batu.') ON CONFLICT DO NOTHING;
