INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('33776adc-56bf-45a5-8d30-ead9f45491bb', 'vocabulary', '田舎', '田舎', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Sebuah sawah dan sebuah pondok. Inilah gambaran pedesaan bagi saya. Ini pedesaan. Cuma cottage dan sawah...', 'Sebuah sawah dan sebuah pondok. Inilah gambaran pedesaan bagi saya. Ini pedesaan. Cuma cottage dan sawah...') ON CONFLICT (id) DO NOTHING;
