INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33776adc-56bf-45a5-8d30-ead9f45491bb', '田舎道で死にかけのフクロネズミを見ました。', 'Saya melihat seekor posum sekarat di jalan pedesaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c351c79-1d16-451d-b450-66c06d2ec0a9', 'vocabulary', '兵舎', '兵舎', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Pondok tentara adalah tempat tinggal para prajurit. Ini adalah barak.', 'Pondok tentara adalah tempat tinggal para prajurit. Ini adalah barak.') ON CONFLICT (id) DO NOTHING;
