INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c351c79-1d16-451d-b450-66c06d2ec0a9', 'その兵舎には異臭が漂っており、息をするのもやっとだった。', 'Barak dipenuhi dengan bau busuk yang menyengat sehingga saya hampir tidak bisa bernapas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f73be9ef-f0a2-4518-bcf0-7625fbc26f02', 'vocabulary', '庁舎', '庁舎', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Pondok kantor pemerintahan adalah tempat penyimpanan kantor pemerintahan. Itu gedung kantor pemerintah.', 'Pondok kantor pemerintahan adalah tempat penyimpanan kantor pemerintahan. Itu gedung kantor pemerintah.') ON CONFLICT (id) DO NOTHING;
