INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f73be9ef-f0a2-4518-bcf0-7625fbc26f02', 'ちょうしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f73be9ef-f0a2-4518-bcf0-7625fbc26f02', '庁舎に雷が落ちたみたいだよ。', 'Saya dengar gedung kantor pemerintah disambar petir.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a1e59d3-4334-4c7c-9a52-f06e66cfe7e4', 'vocabulary', '滞る', '滞る', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti stagnan, dan versi kosakata kata kerjanya terlambat. Toh, kalau ada yang mandek, tidak maju, jadi tertunda.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti stagnan, dan versi kosakata kata kerjanya terlambat. Toh, kalau ada yang mandek, tidak maju, jadi tertunda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0a1e59d3-4334-4c7c-9a52-f06e66cfe7e4', 'Terlambat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0a1e59d3-4334-4c7c-9a52-f06e66cfe7e4', 'To Be Delayed', false) ON CONFLICT DO NOTHING;
