INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a1e59d3-4334-4c7c-9a52-f06e66cfe7e4', '支払いが滞っている理由は何ですか。', 'Apa alasan keterlambatan pembayaran?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a1e59d3-4334-4c7c-9a52-f06e66cfe7e4', '授業料の支払いが滞っているって言われたんですが、ちゃんと払ってますよ。', 'Saya diberitahu bahwa biaya sekolah saya telah jatuh tempo, namun saya telah membayarnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a1e59d3-4334-4c7c-9a52-f06e66cfe7e4', '家主が六ヶ月間家賃が滞っている男の家に出向くと、男は家の中で死んでいた。', 'Pemilik rumah mengunjungi seorang pria yang terlambat membayar sewa selama enam bulan dan menemukannya tewas di dalam rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b39bf149-ac07-4471-a3ab-aa026291a66e', 'vocabulary', '遅滞', '遅滞', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Saya terlalu lambat sehingga segalanya mulai mandek. Benar-benar penundaan.', 'Saya terlalu lambat sehingga segalanya mulai mandek. Benar-benar penundaan.') ON CONFLICT (id) DO NOTHING;
