INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b39bf149-ac07-4471-a3ab-aa026291a66e', 'その動画を遅滞なく削除せよ。', 'Hapus video tanpa penundaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('63f04c0f-7782-4871-86a0-7f5477e9ed81', 'vocabulary', '己', '己', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Itu juga berarti diriku dan aku.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Itu juga berarti diriku dan aku.') ON CONFLICT (id) DO NOTHING;
