INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63f04c0f-7782-4871-86a0-7f5477e9ed81', '俺は、みんな死ぬ前に己の墓は己で建てるべきだと思うけどね。', 'Saya pikir orang harus membangun kuburannya sendiri sebelum mereka mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('caf2fc5a-d206-4bcd-86b9-5e80446bfc87', 'vocabulary', '自己', '自己', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Diri Anda sendiri, adalah diri Anda sendiri atau diri Anda sendiri.', 'Diri Anda sendiri, adalah diri Anda sendiri atau diri Anda sendiri.') ON CONFLICT (id) DO NOTHING;
