INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('caf2fc5a-d206-4bcd-86b9-5e80446bfc87', '彼は、「俺様が一番好きな歌手は俺様自身だよ」と自己満足の笑みを浮かべながら豪語していた。', 'Dia sangat bangga pada dirinya sendiri dan berkata, "Saya adalah penyanyi favorit saya," dengan senyuman yang sangat puas diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a5f794cc-2b75-4984-b31c-5adab6e82c15', 'vocabulary', '厄介', '厄介', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Yang kurang beruntung justru terjebak di sana. Banyaknya ketidakberuntungan berujung pada masa-masa yang sangat menyusahkan dan memberatkan.', 'Yang kurang beruntung justru terjebak di sana. Banyaknya ketidakberuntungan berujung pada masa-masa yang sangat menyusahkan dan memberatkan.') ON CONFLICT (id) DO NOTHING;
