INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0e8d329b-8842-4228-b78e-ad5731dea1fb', 'vocabulary', '亀', '亀', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. TERBAKAR, TERBAKAR, TERBAKAR.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. TERBAKAR, TERBAKAR, TERBAKAR.') ON CONFLICT (id) DO NOTHING;
