INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('350ea961-6faa-48bd-9ab3-b006edf38f82', 'vocabulary', '為に', '為に', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Anda bergerak menuju sake. Ketika Anda bergerak ke arah itu, Anda melakukan sesuatu demi kepentingannya. Tapi kenapa menggunakan bahasa mewah seperti itu? Biarkan saja.', 'Anda bergerak menuju sake. Ketika Anda bergerak ke arah itu, Anda melakukan sesuatu demi kepentingannya. Tapi kenapa menggunakan bahasa mewah seperti itu? Biarkan saja.') ON CONFLICT (id) DO NOTHING;
