INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5daea362-6897-4061-a523-38a29847b8f7', 'vocabulary', '行為', '行為', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Anda pergi demi orang lain. Anda terus-menerus melakukan perbuatan seperti ini untuk orang lain.', 'Anda pergi demi orang lain. Anda terus-menerus melakukan perbuatan seperti ini untuk orang lain.') ON CONFLICT (id) DO NOTHING;
