INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8a22758e-e1c0-4973-9610-2d2d69119a34', 'vocabulary', '熊本県', '熊本県', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Prefektur asal beruang adalah Prefektur Kumamoto. Mungkin yang terbaik untuk mempelajari makna ini melalui membaca. Selain itu, Anda harus mencari Kumamon dari Kumamoto-ken.', 'Prefektur asal beruang adalah Prefektur Kumamoto. Mungkin yang terbaik untuk mempelajari makna ini melalui membaca. Selain itu, Anda harus mencari Kumamon dari Kumamoto-ken.') ON CONFLICT (id) DO NOTHING;
