INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('586c7e8f-d53e-43e3-bde5-f836e2cda4be', 'vocabulary', '地獄', '地獄', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Penjara bumi adalah penjara yang berada di dalam bumi. Penjara apa yang ada di bawah bumi? Itu akan menjadi neraka.', 'Penjara bumi adalah penjara yang berada di dalam bumi. Penjara apa yang ada di bawah bumi? Itu akan menjadi neraka.') ON CONFLICT (id) DO NOTHING;
