INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('586c7e8f-d53e-43e3-bde5-f836e2cda4be', '死後地獄に堕ちる事を願って、ありとあらゆる拷問について研究しています。', 'Saya mempelajari setiap jenis penyiksaan dengan harapan bisa hidup di Neraka setelah saya mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e6dd28f0-34d0-45d4-a43e-a4809da3a902', 'vocabulary', '獄内', '獄内', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Jika Anda berada di dalam penjara, Anda berada di penjara.', 'Jika Anda berada di dalam penjara, Anda berada di penjara.') ON CONFLICT (id) DO NOTHING;
