INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9bacc8f7-1912-420c-a391-08f5f9446330', 'vocabulary', '入獄', '入獄', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Ketika Anda masuk penjara, itulah penjara.', 'Ketika Anda masuk penjara, itulah penjara.') ON CONFLICT (id) DO NOTHING;
