INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bacc8f7-1912-420c-a391-08f5f9446330', '初めて入獄した時、何故か安心感を得たんですよね。', 'Ketika saya dipenjara untuk pertama kalinya, entah kenapa saya merasa aman.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('49094b71-61d2-47fb-9235-3aadefd068e4', 'vocabulary', '出獄', '出獄', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Jika Anda keluar dari penjara, Anda mendapatkan pembebasan dari penjara. Namun, sebelum Anda melanjutkan, izinkan saya memberi tahu Anda satu hal: Harapan adalah hal yang berbahaya. Harapan bisa membuat seseorang menjadi gila.', 'Jika Anda keluar dari penjara, Anda mendapatkan pembebasan dari penjara. Namun, sebelum Anda melanjutkan, izinkan saya memberi tahu Anda satu hal: Harapan adalah hal yang berbahaya. Harapan bisa membuat seseorang menjadi gila.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('49094b71-61d2-47fb-9235-3aadefd068e4', 'Bebaskan Dari Penjara', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('49094b71-61d2-47fb-9235-3aadefd068e4', 'しゅつごく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49094b71-61d2-47fb-9235-3aadefd068e4', '出獄した日に万引きしてまた警察に逮捕されました。', 'Pada hari saya keluar dari penjara, saya ditangkap lagi oleh polisi karena mengutil.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49094b71-61d2-47fb-9235-3aadefd068e4', '今日の夜は、ビエト兄貴の出獄祝いにタイの尾頭付きが用意されてるみたいだぜ。', 'Rupanya ikan air tawar berkepala dan berekor sedang dipersiapkan malam ini untuk merayakan pembebasan kakak laki-laki Viet dari penjara.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49094b71-61d2-47fb-9235-3aadefd068e4', 'そして、出獄の日が近づくにつれて、憂鬱になって、何故か危機感を感じたんです。', 'Kemudian, ketika hari pembebasan saya dari penjara semakin dekat, saya menjadi depresi dan karena alasan tertentu saya merasakan malapetaka yang akan datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a97ef86-787a-4006-ac11-a9a093412d1c', 'vocabulary', '脱獄', '脱獄', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Buka pakaian penjara dari dirimu sendiri, kamu keluar dari sini, sobat! Pembobolan penjara!', 'Buka pakaian penjara dari dirimu sendiri, kamu keluar dari sini, sobat! Pembobolan penjara!') ON CONFLICT (id) DO NOTHING;
