INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed4a7db1-4134-4be3-8088-932e2a03a425', 'みんな船に酔ってしまい、そこら中に吐き散らかしていました。', 'Semua orang mabuk laut dan muntah di seluruh kapal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed4a7db1-4134-4be3-8088-932e2a03a425', '酔ってる時に車を運転するのは絶対にダメだよ。', 'Jangan pernah mengemudi saat Anda mabuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f3676cd-e27f-441f-8a9a-fecbe048be1e', 'vocabulary', '泥酔', '泥酔', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Jika Anda mabuk lumpur, Anda sangat mabuk hingga berguling-guling di tanah. Kamu mabuk berat.', 'Jika Anda mabuk lumpur, Anda sangat mabuk hingga berguling-guling di tanah. Kamu mabuk berat.') ON CONFLICT (id) DO NOTHING;
