INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3f3676cd-e27f-441f-8a9a-fecbe048be1e', '完璧に泥酔していて、方向感覚を失っていました。', 'Saya benar-benar mabuk dan kehilangan arah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dd122d24-75de-45f4-a478-6614886ab851', 'vocabulary', '酢', '酢', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
