INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65466ff3-433e-4822-831e-2a2a85411481', '大人になったら酢の物が好きになりました。', 'Dia mulai menyukai makanan acar saat dia besar nanti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6f7c89d8-3416-4c8c-aaa9-e7080edccaae', 'vocabulary', '同盟', '同盟', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Kami berasal dari aliansi yang sama. Kami berada dalam aliansi.', 'Kami berasal dari aliansi yang sama. Kami berada dalam aliansi.') ON CONFLICT (id) DO NOTHING;
