INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e129adf0-4253-4969-ae8f-f3d99f153107', 'vocabulary', '遺産', '遺産', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Jika Anda meninggalkan harta benda, itu dikenal sebagai warisan Anda.', 'Jika Anda meninggalkan harta benda, itu dikenal sebagai warisan Anda.') ON CONFLICT (id) DO NOTHING;
