INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6aaf6fc6-9d01-40ab-85cc-3ae2cb749977', 'vocabulary', '遺失', '遺失', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Hal yang kita tinggalkan karena suatu kesalahan adalah kerugian.', 'Hal yang kita tinggalkan karena suatu kesalahan adalah kerugian.') ON CONFLICT (id) DO NOTHING;
