INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f119f17-6e79-4bc8-b301-edfc38f6ca0d', 'vocabulary', '遺伝', '遺伝', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Apa yang saya tinggalkan dan wariskan kepada Anda adalah warisan Anda. Anda memiliki gen saya, bahkan setelah saya pergi.', 'Apa yang saya tinggalkan dan wariskan kepada Anda adalah warisan Anda. Anda memiliki gen saya, bahkan setelah saya pergi.') ON CONFLICT (id) DO NOTHING;
