INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b321c8a5-90db-47f0-a8ef-d7ca18bf96c7', '債権者は破産手続きによっていくらかお金を受け取れることが多いが、株主は滅多に受け取ることがない。', 'Kreditor sering kali menerima sejumlah uang dari proses kebangkrutan, namun pemegang saham jarang menerima sejumlah uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b1265ef-b4e8-415f-bdd8-1af140a6de15', 'vocabulary', '国債', '国債', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Utang suatu negara adalah utang negara. Bisa juga berupa obligasi, seperti yang Anda beli dari negara Anda.', 'Utang suatu negara adalah utang negara. Bisa juga berupa obligasi, seperti yang Anda beli dari negara Anda.') ON CONFLICT (id) DO NOTHING;
