INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7a894703-b10e-47c1-a030-784567c26b4e', 'vocabulary', '継承', '継承', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Saya akan mewarisi atas persetujuan Anda. Hal ini tidak diberikan secara langsung kepada saya saat lahir, meskipun memang demikian adanya. Saya mendapat suksesi, tapi hanya jika orang bilang tidak apa-apa.', 'Saya akan mewarisi atas persetujuan Anda. Hal ini tidak diberikan secara langsung kepada saya saat lahir, meskipun memang demikian adanya. Saya mendapat suksesi, tapi hanya jika orang bilang tidak apa-apa.') ON CONFLICT (id) DO NOTHING;
