INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('92cd6245-c0e4-4469-9795-0247709d9b39', 'vocabulary', '舞踏', '舞踏', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Kamu menari, kamu melangkah, kamu menari, kamu melangkah. Kerja bagus! Sekarang kamu sedang menari.', 'Kamu menari, kamu melangkah, kamu menari, kamu melangkah. Kerja bagus! Sekarang kamu sedang menari.') ON CONFLICT (id) DO NOTHING;
