INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da022846-c306-4397-bc86-5ef387dda416', 'vocabulary', '自己紹介', '自己紹介', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Pengenalan diri (自己) (紹介) adalah pengenalan diri.', 'Pengenalan diri (自己) (紹介) adalah pengenalan diri.') ON CONFLICT (id) DO NOTHING;
