INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c671c6cd-367c-4492-adf2-f67b2bf08433', 'あいつ、あのウェイトレスさんに三回もこのレストランに汁物はないのかって聞きやがったんだぜ。ウェイトレスさんその度にありませんって言ってさ、困惑してたよ。', 'Dia bertanya kepada pelayan tiga kali apakah ada sup di restoran dan dia menjawab tidak setiap kali. Dia bingung.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('284c2023-df42-4cec-b02d-20d9c3c57eb6', 'vocabulary', '酔っ払い', '酔っ払い', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Saatnya membayar atas mabukmu. Anda mencobanya, tetapi Anda tidak dapat membayar atas mabuknya. Anda pasti sangat mabuk untuk memikirkan hal itu.', 'Saatnya membayar atas mabukmu. Anda mencobanya, tetapi Anda tidak dapat membayar atas mabuknya. Anda pasti sangat mabuk untuk memikirkan hal itu.') ON CONFLICT (id) DO NOTHING;
