INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91e8f519-3f70-4d5b-b64e-4917e6be91cb', 'vocabulary', '二日酔い', '二日酔い', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Di hari kedua, Anda mengalami mabuk dengan cara yang berbeda... dalam bentuk mabuk.', 'Di hari kedua, Anda mengalami mabuk dengan cara yang berbeda... dalam bentuk mabuk.') ON CONFLICT (id) DO NOTHING;
