INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f02626e8-6288-437f-8d4a-d6378575c30a', 'vocabulary', '遺伝子', '遺伝子', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Jika 遺伝 adalah keturunan dan Anda mewariskan keturunan Anda kepada anak Anda, bagaimana cara mewariskannya? Tentu saja melalui gen.', 'Jika 遺伝 adalah keturunan dan Anda mewariskan keturunan Anda kepada anak Anda, bagaimana cara mewariskannya? Tentu saja melalui gen.') ON CONFLICT (id) DO NOTHING;
