INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a4f318aa-ba93-4313-9630-022cfb81ff6a', 'vocabulary', '廃止する', '廃止する', 1, '200785bc-a121-4b10-a87e-88672f08baf9', '廃止 adalah penghapusan, jadi versi kata kerjanya adalah menghapuskan.', '廃止 adalah penghapusan, jadi versi kata kerjanya adalah menghapuskan.') ON CONFLICT (id) DO NOTHING;
