INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7131bc87-5f10-4179-a835-95d3d7b8fe87', 'vocabulary', '沖縄', '沖縄', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Tali laut terbuka merupakan tali yang menghubungkan Okinawa dengan daratan.', 'Tali laut terbuka merupakan tali yang menghubungkan Okinawa dengan daratan.') ON CONFLICT (id) DO NOTHING;
