INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('33af7e5c-0d09-4794-850c-6a070944781a', 'vocabulary', '維持する', '維持する', 1, '200785bc-a121-4b10-a87e-88672f08baf9', '"Melakukan pemeliharaan (維持)" berarti menjaga sesuatu pada posisi terpelihara, yaitu mempertahankan.', '"Melakukan pemeliharaan (維持)" berarti menjaga sesuatu pada posisi terpelihara, yaitu mempertahankan.') ON CONFLICT (id) DO NOTHING;
