INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('59f403fe-bdbc-4330-b4c4-9ac70e20f73c', 'vocabulary', '明治維新', '明治維新', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Anda tahu Meiji, (明治), dan Anda tahu restorasi (維新). Gabungkan keduanya dan Anda akan mendapatkan Restorasi Meiji.', 'Anda tahu Meiji, (明治), dan Anda tahu restorasi (維新). Gabungkan keduanya dan Anda akan mendapatkan Restorasi Meiji.') ON CONFLICT (id) DO NOTHING;
