INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('657090e7-d754-4cc3-937d-d0a20d7d5ca1', 'vocabulary', '及ぼす', '及ぼす', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Jika Anda memiliki jangkauan, itu berarti Anda mampu memberikan pengaruh yang besar kepada orang lain. Namun hati-hati, karena itu juga berarti Anda dapat menimbulkan kerugian besar.', 'Jika Anda memiliki jangkauan, itu berarti Anda mampu memberikan pengaruh yang besar kepada orang lain. Namun hati-hati, karena itu juga berarti Anda dapat menimbulkan kerugian besar.') ON CONFLICT (id) DO NOTHING;
