INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ddd6ae0-f461-45ef-9346-e5641d346d67', 'vocabulary', '踏み込む', '踏み込む', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Untuk menginjak (踏む) dan kemudian mengerumuni (込む) sesuatu, Anda benar-benar melangkah ke dalam sesuatu. Ini berarti melangkah ke dalam atau terburu-buru melakukan sesuatu.', 'Untuk menginjak (踏む) dan kemudian mengerumuni (込む) sesuatu, Anda benar-benar melangkah ke dalam sesuatu. Ini berarti melangkah ke dalam atau terburu-buru melakukan sesuatu.') ON CONFLICT (id) DO NOTHING;
