INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a1c2080-a095-49af-a331-7da34054e7c8', 'vocabulary', '縄張り', '縄張り', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Ambil tali Anda dan rentangkan untuk menunjukkan di mana letak potongannya. Ini adalah saat Anda mengikat sesuatu. Ini menunjukkan wilayah dan wilayah Anda. Jangan lewati tali yang telah saya rentangkan ini, itu wilayah kekuasaan saya.', 'Ambil tali Anda dan rentangkan untuk menunjukkan di mana letak potongannya. Ini adalah saat Anda mengikat sesuatu. Ini menunjukkan wilayah dan wilayah Anda. Jangan lewati tali yang telah saya rentangkan ini, itu wilayah kekuasaan saya.') ON CONFLICT (id) DO NOTHING;
