INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58f30f59-8a9c-4406-ae0d-b298afed73da', 'vocabulary', '剣', '剣', 1, '200785bc-a121-4b10-a87e-88672f08baf9', 'Kanji dan kata-katanya sama. Itu berarti mereka juga berbagi makna. Kata ini mencakup semua jenis pedang dan pedang, meskipun awalnya sebagian besar digunakan untuk pedang bermata dua.', 'Kanji dan kata-katanya sama. Itu berarti mereka juga berbagi makna. Kata ini mencakup semua jenis pedang dan pedang, meskipun awalnya sebagian besar digunakan untuk pedang bermata dua.') ON CONFLICT (id) DO NOTHING;
