INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bab2e1d1-939e-4572-bf7f-24494895df5c', 'vocabulary', '鹿児島県', '鹿児島県', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Prefektur pulau anak rusa adalah Prefektur Kagoshima.', 'Prefektur pulau anak rusa adalah Prefektur Kagoshima.') ON CONFLICT (id) DO NOTHING;
