INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bab2e1d1-939e-4572-bf7f-24494895df5c', '鹿児島県で、今までで運転した中で一番デッコボコの道路をドライブしました。', 'Saya berkendara di jalan paling bergelombang yang pernah saya lalui di Prefektur Kagoshima.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68174920-0bc2-421d-96da-2ba73322abc6', 'vocabulary', '鹿', '鹿', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
