INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68174920-0bc2-421d-96da-2ba73322abc6', '牡鹿と牝鹿の区別がつきません。', 'Saya tidak bisa membedakan antara rusa jantan dan betina.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', 'vocabulary', '承諾', '承諾', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Anda mendapat persetujuan dan persetujuan saya. Ini adalah persetujuan, kesepakatan, atau penerimaan saya.', 'Anda mendapat persetujuan dan persetujuan saya. Ini adalah persetujuan, kesepakatan, atau penerimaan saya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', 'Persetujuan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', 'Agreement', false) ON CONFLICT DO NOTHING;
