INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', 'しょうだく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', '事後承諾になってしまってすみません。', 'Maaf meminta persetujuan Anda setelah keputusan dibuat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', '彼からの承諾の返事はまだないのか？', 'Masih belum ada kabar darinya tentang penerimaannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34d3bf74-b7ef-4c61-bca6-df2ea0985dcc', '父は、私達の結婚を二つ返事で承諾した。', 'Ayah saya menyetujui pernikahan kami tanpa ragu-ragu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bed00767-5f03-4056-9c88-f79cf0137dbf', 'vocabulary', '受諾', '受諾', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Saya akan menerima dan saya mempunyai persetujuan dalam hal ini. Saya telah sampai pada penerimaan.', 'Saya akan menerima dan saya mempunyai persetujuan dalam hal ini. Saya telah sampai pada penerimaan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bed00767-5f03-4056-9c88-f79cf0137dbf', 'Penerimaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bed00767-5f03-4056-9c88-f79cf0137dbf', 'じゅだく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bed00767-5f03-4056-9c88-f79cf0137dbf', 'コウイチはアメリカ合衆国の大統領になることを渋々受諾した。', 'Koichi dengan enggan setuju untuk menjadi presiden Amerika Serikat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a81a369-8955-4461-b072-5ac5daead5b5', 'vocabulary', '許諾', '許諾', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Saya akan mengizinkan ini, dan Anda mendapat persetujuan saya. Kedua hal ini digabungkan menjadi izin dan persetujuan saya.', 'Saya akan mengizinkan ini, dan Anda mendapat persetujuan saya. Kedua hal ini digabungkan menjadi izin dan persetujuan saya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a81a369-8955-4461-b072-5ac5daead5b5', 'Izin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a81a369-8955-4461-b072-5ac5daead5b5', 'Consent', false) ON CONFLICT DO NOTHING;
