INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d06c2a70-ebdf-4e4d-a62b-90a35713056b', 'とぶ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d06c2a70-ebdf-4e4d-a62b-90a35713056b', '彼女は完璧なトリプルアクセルを跳んだのに、スコアはあまり伸びなかった。', 'Dia melakukan triple axel dengan sempurna, tetapi skornya tidak terlalu bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9a74e8c7-639b-4437-848b-0d8e1531f9dd', 'vocabulary', '昭和', '昭和', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Masa damai yang bersinar adalah masa yang dikenal sebagai Era Showa. Ini juga bisa merujuk pada Kaisar Showa atau hanya Showa itu sendiri. Semuanya Showa ada di sini.', 'Masa damai yang bersinar adalah masa yang dikenal sebagai Era Showa. Ini juga bisa merujuk pada Kaisar Showa atau hanya Showa itu sendiri. Semuanya Showa ada di sini.') ON CONFLICT (id) DO NOTHING;
