INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b2cbf41c-f6ba-40c4-aadc-38e11d324e06', 'vocabulary', '償う', '償う', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Melakukan reparasi berarti memberi kompensasi atau menebus sesuatu. Anda akan menebus dosa-dosa Anda.', 'Melakukan reparasi berarti memberi kompensasi atau menebus sesuatu. Anda akan menebus dosa-dosa Anda.') ON CONFLICT (id) DO NOTHING;
