INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1a65bc21-493e-4732-8e34-cb4dd4473daf', 'vocabulary', '刑務所', '刑務所', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Tempat tugas hukuman adalah tempat Anda pergi untuk melakukan tugas hukuman Anda. Itu adalah penjara atau penjara.', 'Tempat tugas hukuman adalah tempat Anda pergi untuk melakukan tugas hukuman Anda. Itu adalah penjara atau penjara.') ON CONFLICT (id) DO NOTHING;
