INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('524f52a7-9d12-4414-9870-d310eb2dcada', 'vocabulary', '刑事', '刑事', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Tindakan menghukum adalah ketika seseorang keluar untuk mencari orang yang berbuat jahat, agar dapat dihukum. Orang yang melakukan ini adalah orang-orang seperti detektif polisi (atau detektif).', 'Tindakan menghukum adalah ketika seseorang keluar untuk mencari orang yang berbuat jahat, agar dapat dihukum. Orang yang melakukan ini adalah orang-orang seperti detektif polisi (atau detektif).') ON CONFLICT (id) DO NOTHING;
