INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('524f52a7-9d12-4414-9870-d310eb2dcada', 'その刑事は俺の彼女の腕を突然掴んで、彼女にキスをしたんだ。だから、俺はそいつを殴りつけてやったんだけど、そしたら逮捕されたんだよ。そんなの不公平だよ。', 'Tanpa peringatan petugas itu meraih lengan pacar saya dan menciumnya. Jadi saya memukulnya dan dia menangkap saya. Ini tidak adil.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('03c3c785-0694-4102-a76e-7378b38b385c', 'vocabulary', '刑期', '刑期', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Masa hukuman adalah masa di mana Anda dihukum di penjara. Ini adalah hukuman penjara Anda.', 'Masa hukuman adalah masa di mana Anda dihukum di penjara. Ini adalah hukuman penjara Anda.') ON CONFLICT (id) DO NOTHING;
