INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('428495d1-3ac9-44a6-8f93-e6bb35159497', 'vocabulary', '執筆', '執筆', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika Anda memiliki kuas menulis yang ulet, Anda banyak menulis. Selain itu, jika Anda menulis untuk majalah, Anda mungkin juga menulis banyak sekali, karena majalah tersebut harus menerbitkan terbitan baru setiap minggu atau bulan.', 'Jika Anda memiliki kuas menulis yang ulet, Anda banyak menulis. Selain itu, jika Anda menulis untuk majalah, Anda mungkin juga menulis banyak sekali, karena majalah tersebut harus menerbitkan terbitan baru setiap minggu atau bulan.') ON CONFLICT (id) DO NOTHING;
