INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('41a60d94-ef93-4696-aabb-0203513d170c', 'vocabulary', '塁', '塁', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
