INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41a60d94-ef93-4696-aabb-0203513d170c', '彼が塁を踏んだのかどうか、よく見えなかった。', 'Saya tidak bisa melihat apakah dia menginjak pangkalan atau tidak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('59937964-aaec-4d7e-8330-95110e944e1d', 'vocabulary', '塁打', '塁打', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Pukulan dasar bisbol adalah pukulan dasar atau pukulan tunggal dalam istilah bisbol.二塁打 adalah double, 三塁打 adalah triple, dan homerun adalah sesuatu yang akan Anda pelajari di WaniKani suatu saat nanti jika Anda belum mempelajarinya.', 'Pukulan dasar bisbol adalah pukulan dasar atau pukulan tunggal dalam istilah bisbol.二塁打 adalah double, 三塁打 adalah triple, dan homerun adalah sesuatu yang akan Anda pelajari di WaniKani suatu saat nanti jika Anda belum mempelajarinya.') ON CONFLICT (id) DO NOTHING;
