INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('59937964-aaec-4d7e-8330-95110e944e1d', '彼が塁打を打つのは久しぶりだね。いつもはホームランだからな。', 'Sudah lama sekali sejak dia melakukan serangan dasar. Dia selalu melakukan homerun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e180eaf3-d9d6-43a1-b205-f9301978443f', 'vocabulary', '塁審', '塁審', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Hakim pangkalan bisbol adalah orang yang menilai sesuatu di lapangan bisbol. Ini adalah wasit bisbol, atau lebih sederhananya, wasit.', 'Hakim pangkalan bisbol adalah orang yang menilai sesuatu di lapangan bisbol. Ini adalah wasit bisbol, atau lebih sederhananya, wasit.') ON CONFLICT (id) DO NOTHING;
