INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e180eaf3-d9d6-43a1-b205-f9301978443f', 'あの一塁の塁審、試合中に屁をこきまくってたぜ。', 'Wasit di base pertama terus kentut selama pertandingan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4c40a891-624d-456c-8eb4-3a847a854470', 'vocabulary', '崩す', '崩す', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanjinya hancur, jadi apa yang terjadi jika Anda menghancurkan sesuatu? Anda akan menghancurkannya. Anda akan merusaknya. Anda tahu bahwa Anda melakukan penghancuran / penghancuran karena seseorang akan menuntut (す) Anda atas apa yang telah Anda lakukan di sini hari ini.', 'Kanjinya hancur, jadi apa yang terjadi jika Anda menghancurkan sesuatu? Anda akan menghancurkannya. Anda akan merusaknya. Anda tahu bahwa Anda melakukan penghancuran / penghancuran karena seseorang akan menuntut (す) Anda atas apa yang telah Anda lakukan di sini hari ini.') ON CONFLICT (id) DO NOTHING;
