INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4c40a891-624d-456c-8eb4-3a847a854470', '「1ドル札を崩してもらえませんか？」「ええっと…25セント硬貨が2枚と10セント硬貨が5枚あります。これでよろしいですか？」「はい。有難うございます。」', '"Apakah kamu punya uang kembalian untuk satu dolar?" "Coba kulihat. Aku punya dua perempat lima sen. Apakah ini bagus?" "Ya, terima kasih."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f76bd632-c461-48c1-ac57-4d28c580cfaa', 'vocabulary', '崩壊', '崩壊', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Ketika sesuatu mulai runtuh dan pecah, suatu saat pasti akan runtuh. Ia tidak bisa bertahan di bawah tekanan.', 'Ketika sesuatu mulai runtuh dan pecah, suatu saat pasti akan runtuh. Ia tidak bisa bertahan di bawah tekanan.') ON CONFLICT (id) DO NOTHING;
