INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f76bd632-c461-48c1-ac57-4d28c580cfaa', '今朝の俺のクソが大き過ぎて、トイレの床が崩壊したんだ。', 'Kotoran saya sangat banyak pagi ini sehingga lantai kamar mandi runtuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('60b83b45-d8b1-4d53-b05f-767d3a0d798d', 'vocabulary', '反抗する', '反抗する', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika Anda anti terhadap sesuatu dan Anda mengonfrontasi pemerintah mengenai hal tersebut, dalam beberapa kasus Anda akan memberontak terhadap pemerintah... yaitu, jika Anda cukup tergila-gila terhadap hal tersebut.', 'Jika Anda anti terhadap sesuatu dan Anda mengonfrontasi pemerintah mengenai hal tersebut, dalam beberapa kasus Anda akan memberontak terhadap pemerintah... yaitu, jika Anda cukup tergila-gila terhadap hal tersebut.') ON CONFLICT (id) DO NOTHING;
