INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60b83b45-d8b1-4d53-b05f-767d3a0d798d', '犬が私に反抗したので、「お前は悪い犬だ！」って叱りつけてやりましたよ。', 'Anjing itu memusuhi saya, jadi saya berteriak padanya, "Kamu anjing nakal!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('982cbc11-4377-4ce1-a0f2-5048b815523c', 'vocabulary', '抗戦', '抗戦', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kami siap menghadapi perang, jika perlu. Kami akan memulai perlawanan terhadap rezim Anda, menghadapi Anda, dan bahkan berperang.', 'Kami siap menghadapi perang, jika perlu. Kami akan memulai perlawanan terhadap rezim Anda, menghadapi Anda, dan bahkan berperang.') ON CONFLICT (id) DO NOTHING;
