INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79f16952-333e-459c-afa5-56fe7f72b967', 'vocabulary', '抵抗する', '抵抗する', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Tolak dan hadapi mereka yang menentang Anda. Ini untuk melawan.', 'Tolak dan hadapi mereka yang menentang Anda. Ini untuk melawan.') ON CONFLICT (id) DO NOTHING;
