INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('79f16952-333e-459c-afa5-56fe7f72b967', 'どうしてあのケーキを食べるのを抵抗したんだ？', 'Mengapa kamu menolak memakan kue itu?') ON CONFLICT DO NOTHING;
