INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c36ae79d-e0be-4914-bd64-29a0a3462672', 'vocabulary', '旬', '旬', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
