INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c9ab9e6-163d-486e-8819-68a620362439', 'vocabulary', '爆弾', '爆弾', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Peluru yang meledak adalah ketika sebuah ledakan menyemburkan sesuatu seperti peluru, namun jauh lebih besar, seperti bom.', 'Peluru yang meledak adalah ketika sebuah ledakan menyemburkan sesuatu seperti peluru, namun jauh lebih besar, seperti bom.') ON CONFLICT (id) DO NOTHING;
