INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7a894b13-0822-44ef-b44b-e77841bd1d80', 'vocabulary', '遣う', '遣う', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanji berarti pengiriman tetapi kata ini berarti mempertimbangkan atau memanfaatkan. Coba pikirkan bagaimana jika Anda memiliki orang-orang yang siap membantu Anda, Anda dapat mengirimi mereka informasi untuk dipertimbangkan dan digunakan.', 'Kanji berarti pengiriman tetapi kata ini berarti mempertimbangkan atau memanfaatkan. Coba pikirkan bagaimana jika Anda memiliki orang-orang yang siap membantu Anda, Anda dapat mengirimi mereka informasi untuk dipertimbangkan dan digunakan.') ON CONFLICT (id) DO NOTHING;
