INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cfe409ac-b38a-4bd4-ba46-c35a092f521e', 'vocabulary', '戦闘', '戦闘', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Perjuangan perang adalah bagian dalam perang di mana Anda harus berjuang satu sama lain. Ini adalah pertempuran.', 'Perjuangan perang adalah bagian dalam perang di mana Anda harus berjuang satu sama lain. Ini adalah pertempuran.') ON CONFLICT (id) DO NOTHING;
