INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b1b63dc-fe14-47f3-b546-5e2ba297bf58', '美香ちゃんは、ウクレレを弾くと心が休まると言っていたよ。', 'Mika mengaku merasa rileks saat memainkan ukulele.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b1b63dc-fe14-47f3-b546-5e2ba297bf58', '古いギターを弾こうとしたら、げんが切れてしまった。', 'Saat saya mencoba memainkan gitar tua, salah satu senarnya putus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b1b63dc-fe14-47f3-b546-5e2ba297bf58', '彼がまたピアノを弾き始めたというニュースに、私は胸を躍らせました。', 'Saya sangat senang dengan berita bahwa dia mulai bermain piano lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('31fce2fc-83ff-46a8-9642-f19459f3b1d1', 'vocabulary', '言葉遣い', '言葉遣い', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika Anda mencoba mempertimbangkan (遣う) kata-kata Anda (言葉), Anda membuat pilihan kata.', 'Jika Anda mencoba mempertimbangkan (遣う) kata-kata Anda (言葉), Anda membuat pilihan kata.') ON CONFLICT (id) DO NOTHING;
