INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9ba202c5-8d20-4fd5-876c-ab6703ed4d3f', 'お子さんには月々お小遣いはいくら渡しているんですか。', 'Berapa banyak uang belanja yang Anda berikan kepada anak Anda sebulan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('28443bfe-0fcd-41ec-9f2d-20d8a64ce85d', 'vocabulary', '削除する', '削除する', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika 削除 adalah "penghapusan", maka versi kata kerjanya adalah menghapus.', 'Jika 削除 adalah "penghapusan", maka versi kata kerjanya adalah menghapus.') ON CONFLICT (id) DO NOTHING;
