INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28443bfe-0fcd-41ec-9f2d-20d8a64ce85d', '今お送りしたメッセージを削除して頂いてもよろしいでしょうか。別の方に送信するはずだったものなんです。', 'Bisakah Anda menghapus pesan yang baru saja saya kirimkan kepada Anda? Saya bermaksud mengirimkannya ke orang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7141bfa3-26b2-463e-972a-da700e97e55a', 'vocabulary', '掲示板', '掲示板', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', '掲示 adalah pemberitahuan atau tanda. Letakkan ini di papan, dan itu menjadi papan buletin.', '掲示 adalah pemberitahuan atau tanda. Letakkan ini di papan, dan itu menjadi papan buletin.') ON CONFLICT (id) DO NOTHING;
