INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68e2bf59-9e2b-4bff-b723-40c0ca131768', 'vocabulary', '原子爆弾', '原子爆弾', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', '原子 adalah atom dan 爆弾 adalah bom. Apa itu bom atom? Sebuah bom atom.', '原子 adalah atom dan 爆弾 adalah bom. Apa itu bom atom? Sebuah bom atom.') ON CONFLICT (id) DO NOTHING;
