INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68e2bf59-9e2b-4bff-b723-40c0ca131768', '私の家は火災保険に入っていますが、もし誰かが原子爆弾を落として、それで家が燃えちゃった場合はどうなるんでしょうか。それでも保険金は降りるんでしょうか。', 'Rumah saya memiliki asuransi kebakaran, tapi bagaimana jika seseorang menjatuhkan bom atom dan rumah saya terbakar? Apakah saya masih akan mendapatkan uang asuransi?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ac662f9-713c-4807-97ee-6cf0092072a9', 'vocabulary', '宜しく', '宜しく', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanjinya adalah salam terbaik dan ini juga bisa menjadi salam terbaik. Bisa juga berarti baik, benar, dan sesuai pula.', 'Kanjinya adalah salam terbaik dan ini juga bisa menjadi salam terbaik. Bisa juga berarti baik, benar, dan sesuai pula.') ON CONFLICT (id) DO NOTHING;
