INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ac662f9-713c-4807-97ee-6cf0092072a9', 'お母様に宜しくお伝えくださいね。', 'Tolong ucapkan terima kasih kepada ibumu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('790d2738-7241-4fa5-b261-e73ac7995622', 'vocabulary', '宜しくお願いします', '宜しくお願いします', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Permintaan 宜しい (baik, oke, baiklah) adalah saat Anda menyampaikan salam kepada seseorang. Ini adalah ungkapan yang Anda ucapkan ketika seseorang akan membantu Anda dan Anda semua berkata "terima kasih atas bantuan Anda" atau "Saya mengandalkan Anda" atau kombinasi keduanya. Ini adalah kata yang sering Anda lihat dengan tingkat kanji dan panjangnya yang berbeda-beda.', 'Permintaan 宜しい (baik, oke, baiklah) adalah saat Anda menyampaikan salam kepada seseorang. Ini adalah ungkapan yang Anda ucapkan ketika seseorang akan membantu Anda dan Anda semua berkata "terima kasih atas bantuan Anda" atau "Saya mengandalkan Anda" atau kombinasi keduanya. Ini adalah kata yang sering Anda lihat dengan tingkat kanji dan panjangnya yang berbeda-beda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('790d2738-7241-4fa5-b261-e73ac7995622', 'Salam Hormat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('790d2738-7241-4fa5-b261-e73ac7995622', 'よろしくおねがいします', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('790d2738-7241-4fa5-b261-e73ac7995622', 'どうして日本人はいつも「宜しくお願いします」って言うの？', 'Mengapa orang Jepang selalu berkata "tolong perlakukan saya dengan baik"?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9217d652-81c4-4c9f-a3bd-4eb28429f3d5', 'vocabulary', '繰り返す', '繰り返す', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', '繰る berarti "berputar" (jadi berputar) dan 返す berarti "kembali" (jadi kembali). Gabungkan semuanya dan Anda akan mendapatkan sesuatu yang berputar dan kembali ke tempat yang sama berulang kali. Sesuatu yang melakukan hal itu adalah mengulangi dirinya sendiri, membuat hal ini berulang atau berulang lagi dan lagi.', '繰る berarti "berputar" (jadi berputar) dan 返す berarti "kembali" (jadi kembali). Gabungkan semuanya dan Anda akan mendapatkan sesuatu yang berputar dan kembali ke tempat yang sama berulang kali. Sesuatu yang melakukan hal itu adalah mengulangi dirinya sendiri, membuat hal ini berulang atau berulang lagi dan lagi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9217d652-81c4-4c9f-a3bd-4eb28429f3d5', 'Untuk Mengulangi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9217d652-81c4-4c9f-a3bd-4eb28429f3d5', 'To Repeat Over And Over', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9217d652-81c4-4c9f-a3bd-4eb28429f3d5', 'くりかえす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9217d652-81c4-4c9f-a3bd-4eb28429f3d5', '同じ失敗を何度も繰り返すのはやめようじゃないか。', 'Tidak bisakah kamu berhenti mengulangi kesalahan yang sama berulang kali?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8e54010a-d6a0-4c40-989d-605662723ed0', 'vocabulary', '避難する', '避難する', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika Anda tahu bahwa 避難 adalah "evakuasi" maka Anda tahu bahwa ini adalah bentuk kata kerjanya: mengungsi.', 'Jika Anda tahu bahwa 避難 adalah "evakuasi" maka Anda tahu bahwa ini adalah bentuk kata kerjanya: mengungsi.') ON CONFLICT (id) DO NOTHING;
