INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8e54010a-d6a0-4c40-989d-605662723ed0', 'ひなんする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e54010a-d6a0-4c40-989d-605662723ed0', '雨が突然降り出したので、先輩と私は桜の木の下で避難しました。', 'Saya dan senior saya menemukan tempat berlindung di bawah pohon sakura ketika hujan tiba-tiba turun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', 'vocabulary', '思い遣り', '思い遣り', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika Anda menyampaikan apa yang Anda pikirkan kepada orang lain, Anda memikirkannya, dan Anda bersikap baik. Anda menunjukkan perhatian, simpati, dan kasih sayang kepada orang lain.', 'Jika Anda menyampaikan apa yang Anda pikirkan kepada orang lain, Anda memikirkannya, dan Anda bersikap baik. Anda menunjukkan perhatian, simpati, dan kasih sayang kepada orang lain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', 'Pertimbangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', 'Compassion', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', 'Sympathy', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', 'おもいやり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', '思い遣りのつもりだったのかもしれないけど、嘘なんてついてほしくなかった。', 'Mungkin kamu melakukannya karena pertimbangan, tapi aku tidak ingin kamu berbohong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', '思い遣りのカケラもない奴だと思っていたが、そんなことはなかった。', 'Tadinya kukira dia pria yang tidak punya belas kasihan sedikit pun, tapi ternyata aku salah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a3e38cf-9b58-4014-aaec-9b7eb66b8929', 'こんなに臭い部屋でいつまでも待たせるなんて、あいつはなんて思い遣りのないやつなんだ。', 'Dia tidak terlalu perhatian jika membuat kita menunggu terlalu lama di ruangan bau seperti ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc5e45fe-2d05-4b76-a4bc-0ff02b84fcdc', 'vocabulary', '掲載する', '掲載する', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', '掲載 adalah publikasi jadi versi kata kerjanya adalah menerbitkan atau mencetak.', '掲載 adalah publikasi jadi versi kata kerjanya adalah menerbitkan atau mencetak.') ON CONFLICT (id) DO NOTHING;
