INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cc5e45fe-2d05-4b76-a4bc-0ff02b84fcdc', 'けいさいする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc5e45fe-2d05-4b76-a4bc-0ff02b84fcdc', 'このコンテンツは、過激すぎて掲載することはできません。', 'Isinya terlalu ekstrim untuk dipublikasikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2a5a6c74-7722-4260-a5f1-5ccdd4060898', 'vocabulary', '馬鹿馬鹿しい', '馬鹿馬鹿しい', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Ingat bagaimana Anda mengetahui bahwa 馬鹿 berarti "idiot?" Gabungkan dua orang idiot dan semua yang mereka katakan dan lakukan benar-benar tidak masuk akal. Ingat betapa konyolnya film "Dumb and Dumber" itu? Ya. Seperti itu.', 'Ingat bagaimana Anda mengetahui bahwa 馬鹿 berarti "idiot?" Gabungkan dua orang idiot dan semua yang mereka katakan dan lakukan benar-benar tidak masuk akal. Ingat betapa konyolnya film "Dumb and Dumber" itu? Ya. Seperti itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a5a6c74-7722-4260-a5f1-5ccdd4060898', 'Tidak masuk akal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a5a6c74-7722-4260-a5f1-5ccdd4060898', 'Ridiculous', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a5a6c74-7722-4260-a5f1-5ccdd4060898', 'Silly', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2a5a6c74-7722-4260-a5f1-5ccdd4060898', 'ばかばかしい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a5a6c74-7722-4260-a5f1-5ccdd4060898', '馬鹿馬鹿しいこと言わないでよ。', 'Jangan mengatakan hal-hal bodoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54eff79f-02d4-4338-ac73-61dfb8269343', 'vocabulary', '弾力', '弾力', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Jika Anda ingin kekuatan menghentikan peluru, Anda harus memiliki jumlah elastisitas yang tepat. Peluru menembus benda-benda yang kaku, tetapi jika bahannya kuat dan memiliki fleksibilitas yang tepat, peluru akan langsung memantul!', 'Jika Anda ingin kekuatan menghentikan peluru, Anda harus memiliki jumlah elastisitas yang tepat. Peluru menembus benda-benda yang kaku, tetapi jika bahannya kuat dan memiliki fleksibilitas yang tepat, peluru akan langsung memantul!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('54eff79f-02d4-4338-ac73-61dfb8269343', 'Elastisitas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('54eff79f-02d4-4338-ac73-61dfb8269343', 'Flexibility', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('54eff79f-02d4-4338-ac73-61dfb8269343', 'だんりょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54eff79f-02d4-4338-ac73-61dfb8269343', 'お肌の弾力が無くなってきているの。', 'Elastisitas kulit saya menghilang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', 'vocabulary', '眉', '眉', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Kanji dan kata-katanya sama persis. Ini juga termasuk tempat tinggal alis Anda: alis Anda.', 'Kanji dan kata-katanya sama persis. Ini juga termasuk tempat tinggal alis Anda: alis Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', 'Alis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', 'Brow', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', 'まゆ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', '眉の形は人によって違う。', 'Bentuk alis berbeda-beda pada setiap orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', '早く、眉にピアス開けたいな。', 'Aku ingin segera menindik alisku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a2585b45-eb17-476e-995f-781497d7b6c3', '眉の動きに注目すると表情を捉えやすいって知ってましたか？', 'Tahukah Anda bahwa memperhatikan gerakan alis akan memudahkan Anda melihat ekspresi wajah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', 'vocabulary', '眉間', '眉間', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Interval alis Anda adalah tempat di antara alis Anda yang disebut alis. Istilah teknis untuk celah di antara alis Anda adalah glabella, tapi saya yakin Anda tidak pernah menggunakan kata itu. Kecuali Anda... seorang dokter alis?', 'Interval alis Anda adalah tempat di antara alis Anda yang disebut alis. Istilah teknis untuk celah di antara alis Anda adalah glabella, tapi saya yakin Anda tidak pernah menggunakan kata itu. Kecuali Anda... seorang dokter alis?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', 'Alis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', 'Glabella', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', 'みけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', '社長は眉間にシワを寄せながら「この資料は誰が書いた？」と言った。', 'Presiden perusahaan berkata, "Siapa yang menulis dokumen-dokumen ini?" sambil mengerutkan alisnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', '私のパグのチャームポイントはやはり眉間のシワです。', 'Tahukah kamu, fitur paling menarik dari anjing pugku adalah garis di alisnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('184ce453-df65-44f9-8f54-d91f6147bf48', '眉間を黒いマジックで塗りつぶしてください。', 'Silakan isi alis Anda dengan spidol hitam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('392640d4-c786-43f6-95a3-ded459b23801', 'vocabulary', '眉毛', '眉毛', 1, '8b7f16eb-160f-486f-a9b6-c118fbf19f49', 'Rambut alis adalah rambut alis individu yang membentuknya.', 'Rambut alis adalah rambut alis individu yang membentuknya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('392640d4-c786-43f6-95a3-ded459b23801', 'Alis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('392640d4-c786-43f6-95a3-ded459b23801', 'まゆげ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('392640d4-c786-43f6-95a3-ded459b23801', '三時間前に眉毛をそったばかりなのに、もう眉毛がつながりそうだ。', 'Padahal aku baru mencukur alisku tiga jam yang lalu, tapi alisku sudah mulai menyatu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('392640d4-c786-43f6-95a3-ded459b23801', 'ドレスの色に合わせて、眉毛を染めたの。', 'Aku mengecat alisku agar serasi dengan gaunku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('392640d4-c786-43f6-95a3-ded459b23801', '眉毛を書くのに毎朝二時間くらいかかる。', 'Saya membutuhkan waktu beberapa jam untuk menggambar alis setiap pagi.') ON CONFLICT DO NOTHING;
