INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9f5fa481-453a-43bf-af22-8823e6d6ac5f', 'vocabulary', '致す', '致す', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melakukan dan versi vocab verbanya adalah melakukan. Ini adalah cara yang sopan untuk mengatakan "melakukan".', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya melakukan dan versi vocab verbanya adalah melakukan. Ini adalah cara yang sopan untuk mengatakan "melakukan".') ON CONFLICT (id) DO NOTHING;
