INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f5fa481-453a-43bf-af22-8823e6d6ac5f', 'もしよろしければ私が町をご案内致しますよ。', 'Saya akan memandu Anda berkeliling kota, jika Anda mau.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('09dd7272-8514-4abe-a6b3-6c9bdeaafa28', 'vocabulary', '一致する', '一致する', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Anda melakukan satu hal dan saya akan melakukan hal lain. Saya akan melakukan hal yang sama untuk mencocokkannya.', 'Anda melakukan satu hal dan saya akan melakukan hal lain. Saya akan melakukan hal yang sama untuk mencocokkannya.') ON CONFLICT (id) DO NOTHING;
