INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09dd7272-8514-4abe-a6b3-6c9bdeaafa28', '偽のベーコンに残された指紋は、マミのものと一致しました。', 'Sidik jari yang tertinggal di daging palsu itu cocok dengan sidik jari Mami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4590ee4b-ee1e-4130-8de2-3713b360dbb4', 'vocabulary', '致命的', '致命的', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Seseorang yang membuatmu gemuk akan... mungkin berakibat fatal!', 'Seseorang yang membuatmu gemuk akan... mungkin berakibat fatal!') ON CONFLICT (id) DO NOTHING;
