INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4590ee4b-ee1e-4130-8de2-3713b360dbb4', '生徒とのスキャンダルは、彼の教師生命にとって致命的でした。', 'Skandal dengan muridnya berakibat fatal bagi karir mengajarnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('787fbd3d-cf43-4a66-8742-d5b057c8748b', 'vocabulary', '奏楽', '奏楽', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Mainkan musik yang akan memberi saya kenyamanan, mengapa saya harus menonton pertunjukan musik agar saya tetap nyaman dan tenang.', 'Mainkan musik yang akan memberi saya kenyamanan, mengapa saya harus menonton pertunjukan musik agar saya tetap nyaman dan tenang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('787fbd3d-cf43-4a66-8742-d5b057c8748b', 'Pertunjukan Musik', true) ON CONFLICT DO NOTHING;
