INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('787fbd3d-cf43-4a66-8742-d5b057c8748b', '千円くらいの、奏楽用のハンドベルはありますか？', 'Apakah Anda memiliki bel musik seharga sekitar 1000 yen?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('406ca3ff-307a-47b1-a7e5-04d99336dfb4', 'vocabulary', '演奏', '演奏', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Jika Anda menampilkan dan memainkan musik, Anda sedang melakukan pertunjukan musik.', 'Jika Anda menampilkan dan memainkan musik, Anda sedang melakukan pertunjukan musik.') ON CONFLICT (id) DO NOTHING;
