INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('406ca3ff-307a-47b1-a7e5-04d99336dfb4', 'バンドが舞台で演奏をしている最中に、電球が切れてしまいました。', 'Bola lampu padam saat band tampil di atas panggung.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f1de254-b377-42d8-81da-e4a60133f557', 'vocabulary', '伴う', '伴う', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menemani dan versi vocab verbanya adalah menemani. Ini dapat digunakan baik secara harfiah maupun kiasan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menemani dan versi vocab verbanya adalah menemani. Ini dapat digunakan baik secara harfiah maupun kiasan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f1de254-b377-42d8-81da-e4a60133f557', 'Untuk Menemani', true) ON CONFLICT DO NOTHING;
