INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f1de254-b377-42d8-81da-e4a60133f557', '技術の進歩に伴って人々は自然環境にだんだん関心がなくなってきた。', 'Seiring dengan kemajuan teknologi, kepedulian masyarakat terhadap lingkungan semakin berkurang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ca634d94-414f-44ba-b19e-e76f2719642c', 'vocabulary', '同伴する', '同伴する', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Teman yang sama berarti Anda berada di tempat yang sama dengan seseorang, dan Anda menemaninya. Kata ini berarti menemani. Ini hanya digunakan untuk menemani orang.', 'Teman yang sama berarti Anda berada di tempat yang sama dengan seseorang, dan Anda menemaninya. Kata ini berarti menemani. Ini hanya digunakan untuk menemani orang.') ON CONFLICT (id) DO NOTHING;
