INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ca634d94-414f-44ba-b19e-e76f2719642c', 'どうはんする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca634d94-414f-44ba-b19e-e76f2719642c', '今日は奥さんが同伴するのかと思ってたよ。', 'Saya pikir Anda akan ditemani istri Anda hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c4cb8d15-73a1-49c4-82eb-9d7e3131d74c', 'vocabulary', '併殺', '併殺', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Join kill adalah ketika dalam satu permainan Anda mendapatkan dua kill (out) dalam bisbol, menjadikannya permainan ganda.', 'Join kill adalah ketika dalam satu permainan Anda mendapatkan dua kill (out) dalam bisbol, menjadikannya permainan ganda.') ON CONFLICT (id) DO NOTHING;
