INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c4cb8d15-73a1-49c4-82eb-9d7e3131d74c', '「ゲッツー」というのは、併殺を意味する和製英語です。', '"Dapatkan dua" adalah kata dalam bahasa Jepang yang berasal dari bahasa Inggris yang berarti permainan ganda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b71d6626-823d-4422-8aab-5a74d64bbca7', 'vocabulary', '併合', '併合', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Bergabunglah dan bergabunglah satu sama lain. Ini adalah penggabungan.', 'Bergabunglah dan bergabunglah satu sama lain. Ini adalah penggabungan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b71d6626-823d-4422-8aab-5a74d64bbca7', 'Penggabungan', true) ON CONFLICT DO NOTHING;
