INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b71d6626-823d-4422-8aab-5a74d64bbca7', 'アメリカ合衆国は、私が生まれた年にテキサスを併合しました。', 'Amerika Serikat mencaplok Texas pada tahun saya dilahirkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6be66ac6-eaa2-4227-82f5-1b0af3ec003e', 'vocabulary', '却って', '却って', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Sesuatu yang bertentangan... ini adalah versi te-bentuk dari kebalikannya, artinya Anda mulai mengatakan sesuatu, menjadikannya sebaliknya.', 'Sesuatu yang bertentangan... ini adalah versi te-bentuk dari kebalikannya, artinya Anda mulai mengatakan sesuatu, menjadikannya sebaliknya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6be66ac6-eaa2-4227-82f5-1b0af3ec003e', 'Sebaliknya', true) ON CONFLICT DO NOTHING;
