INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6be66ac6-eaa2-4227-82f5-1b0af3ec003e', '善かれと思ってしたことが、却って仇となって友人のストレスになってしまいました。', 'Aku hanya ingin melakukan hal yang benar tapi malah menjadi bumerang dan aku malah membuat temanku stres.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cda0cc8d-2c39-478b-a94d-5ceb4a9fe52a', 'vocabulary', '却下', '却下', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Ini bertentangan dengan apa yang menurut saya baik. Itu di bawah standar saya. Jadi, penolakan.', 'Ini bertentangan dengan apa yang menurut saya baik. Itu di bawah standar saya. Jadi, penolakan.') ON CONFLICT (id) DO NOTHING;
