INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('174f76f7-5a81-420c-9671-7d584647b15a', 'vocabulary', '受託', '受託', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Anda menerima dan menyerahkan pekerjaan itu. Anda akan dipercayakan dengan properti ini untuk musim dingin. Jangan masuk ke kamar 237.', 'Anda menerima dan menyerahkan pekerjaan itu. Anda akan dipercayakan dengan properti ini untuk musim dingin. Jangan masuk ke kamar 237.') ON CONFLICT (id) DO NOTHING;
