INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b419861-5ff8-4059-a719-c2b5969fe3c0', 'vocabulary', '贈収賄', '贈収賄', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Hadiah yang Anda peroleh adalah suap. Apa? Itu adalah suap!', 'Hadiah yang Anda peroleh adalah suap. Apa? Itu adalah suap!') ON CONFLICT (id) DO NOTHING;
