INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('094bfcd8-b2fb-4064-93c9-f597d2a76d1e', '行方不明の英語教師は、足が凍傷になっていたものの、無事に生還しました。', 'Meskipun kakinya membeku, guru bahasa Inggris yang hilang itu kembali hidup dengan selamat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('815accc4-10e7-447e-b888-b7054bea16a3', 'vocabulary', '返還', '返還', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Jika kami mengembalikan dan mengirimkan kembali barang, kami telah melakukan pengembalian atau pemulihan.', 'Jika kami mengembalikan dan mengirimkan kembali barang, kami telah melakukan pengembalian atau pemulihan.') ON CONFLICT (id) DO NOTHING;
