INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('815accc4-10e7-447e-b888-b7054bea16a3', '沖縄がアメリカから日本に返還されたのは1972年のことです。', 'Okinawa dikembalikan ke Jepang dari Amerika pada tahun 1972.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('815accc4-10e7-447e-b888-b7054bea16a3', '優勝旗が毎年返還されなくちゃいけないなんて、知らなかったよ。', 'Saya tidak tahu bahwa bendera kejuaraan harus dikembalikan setiap tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a70d6927-1270-4551-a9a3-984883b3b460', 'vocabulary', '還元', '還元', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Kirim kembali ke asal artinya Anda akan kembali ke asal. Lakukan pengurangan hingga ke aslinya.', 'Kirim kembali ke asal artinya Anda akan kembali ke asal. Lakukan pengurangan hingga ke aslinya.') ON CONFLICT (id) DO NOTHING;
