INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('90906aa8-9037-4ca0-8bae-d30feb292ca9', 'vocabulary', '将棋', '将棋', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Bidak catur komandan adalah permainan yang dikenal sebagai shogi (atau catur Jepang, tapi shogi lebih baik). Ini mirip dengan catur dalam banyak hal dan cukup menarik. Lihatlah jika Anda sudah menyukai catur.', 'Bidak catur komandan adalah permainan yang dikenal sebagai shogi (atau catur Jepang, tapi shogi lebih baik). Ini mirip dengan catur dalam banyak hal dan cukup menarik. Lihatlah jika Anda sudah menyukai catur.') ON CONFLICT (id) DO NOTHING;
