INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ca7d1ac2-c6b3-4cfa-b59a-9f5569640ce9', 'もうすぐ日も暮れるぜ。全くこの馬鹿げた渋滞のせいで今日は一日何にもできなかったな。', 'Hari hampir berakhir. Kami tidak dapat melakukan apa pun hari ini karena kemacetan lalu lintas yang parah ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('763480a6-5bb9-4420-91e7-0a961e2f1f5c', 'vocabulary', '邦訳', '邦訳', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Terjemahan negara asal adalah terjemahan ke bahasa negara asal Anda. Karena ini adalah kata dalam bahasa Jepang, terjemahan ini akan menjadi terjemahan ke dalam bahasa Jepang.', 'Terjemahan negara asal adalah terjemahan ke bahasa negara asal Anda. Karena ini adalah kata dalam bahasa Jepang, terjemahan ini akan menjadi terjemahan ke dalam bahasa Jepang.') ON CONFLICT (id) DO NOTHING;
