INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('63dc8413-6dab-44b5-b2bb-bd281e44b471', 'vocabulary', '棋院', '棋院', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Lembaga bidak catur adalah tempat Anda bermain catur... atau, di Jepang, ini bukan catur, melainkan aula Go atau klub Go (ini adalah permainan yang sangat menarik, Anda harus mencarinya!).', 'Lembaga bidak catur adalah tempat Anda bermain catur... atau, di Jepang, ini bukan catur, melainkan aula Go atau klub Go (ini adalah permainan yang sangat menarik, Anda harus mencarinya!).') ON CONFLICT (id) DO NOTHING;
