INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14bcc304-a4f7-4cc3-819c-faeaf5ea4890', '「あぁ、自分がどれだけドライブが好きか忘れてたわ。免許更新しなくちゃ。」「おい、待てよ！お前の免許失効してるのか？ありえねえ。よし、それまで！今すぐ横につけて！」', '"Ah. Aku lupa betapa aku sangat suka mengemudi. Aku harus memperbarui SIM-ku." "Tunggu! Apakah SIM-mu sudah habis masa berlakunya? Ya ampun. Itu dia! Menepi sekarang juga!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bc136ccb-b97b-4a2e-bee5-bdbe7ce8249a', 'vocabulary', '免税', '免税', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Alasan dari pajak? Itu adalah pengecualian pajak.', 'Alasan dari pajak? Itu adalah pengecualian pajak.') ON CONFLICT (id) DO NOTHING;
