INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3e66f429-6574-48a9-9e0d-8bed7b35c45a', 'vocabulary', '御免', '御免', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Hanya alasan terhormat yang kumiliki, dan itu tidak baik. Saya minta maaf dan saya mohon maaf.', 'Hanya alasan terhormat yang kumiliki, dan itu tidak baik. Saya minta maaf dan saya mohon maaf.') ON CONFLICT (id) DO NOTHING;
