INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d660d417-e609-44a2-a178-21bdca577bf4', 'とある仙人から、仙台に行くことを勧められたんだよ。', 'Beberapa pertapa menyarankan agar saya pergi ke Sendai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d660d417-e609-44a2-a178-21bdca577bf4', '探偵が犯人に諦めて大人しく警察へ行くことを勧めた。', 'Detektif mendesak pelakunya untuk menyerah dan melapor ke polisi dengan tenang.') ON CONFLICT DO NOTHING;
