INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9806bd21-8e58-40bd-9909-658f23a18550', 'vocabulary', '遠慮する', '遠慮する', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Jika 遠慮 adalah "menolak" atau "menahan" maka versi kosakata kata kerjanya adalah menolak atau menahan.', 'Jika 遠慮 adalah "menolak" atau "menahan" maka versi kosakata kata kerjanya adalah menolak atau menahan.') ON CONFLICT (id) DO NOTHING;
