INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02f90598-9d0b-4381-876e-8287bdeac9fa', '彼の安否が気に懸かります。', 'Saya khawatir apakah dia baik-baik saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4ad961c3-7a13-470d-b0ec-ca9f2a03897a', 'vocabulary', '一生懸命', '一生懸命', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Anda hanya memiliki satu kehidupan, jadi lakukan segala sesuatunya dengan penuh semangat (懸命). Lakukan segalanya dengan sekuat tenaga. Lakukan semuanya.', 'Anda hanya memiliki satu kehidupan, jadi lakukan segala sesuatunya dengan penuh semangat (懸命). Lakukan segalanya dengan sekuat tenaga. Lakukan semuanya.') ON CONFLICT (id) DO NOTHING;
