INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b6dc99f-a0cd-4816-956d-df19a2cac586', 'ワイングラスの扱いに気をつけるようにと言われた直後に、案の定一つ割ってしまった。', 'Tepat setelah saya diberitahu untuk berhati-hati dengan gelas anggur, benar saja, saya memecahkan satu gelas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('521b4f32-d0da-4993-9abc-93d93509d318', 'vocabulary', '取り扱う', '取り扱う', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Mengambil dan kemudian menangani berarti Anda mengambil dan menanganinya, menyebabkan Anda mengelola atau menangani sesuatu. Anda mendapatkannya karena Anda mengambilnya.', 'Mengambil dan kemudian menangani berarti Anda mengambil dan menanganinya, menyebabkan Anda mengelola atau menangani sesuatu. Anda mendapatkannya karena Anda mengambilnya.') ON CONFLICT (id) DO NOTHING;
