INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64f11bbd-f97b-492b-8fb6-afdcd884e4be', 'vocabulary', '選択する', '選択する', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', '選択 adalah "seleksi" atau "pilihan". Jika Anda melakukan versi kata kerja ini, Anda akan memilih atau memilih.', '選択 adalah "seleksi" atau "pilihan". Jika Anda melakukan versi kata kerja ini, Anda akan memilih atau memilih.') ON CONFLICT (id) DO NOTHING;
