INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64f11bbd-f97b-492b-8fb6-afdcd884e4be', '結婚相手にどちらの女性を選択するか決めましたか？', 'Sudahkah Anda memutuskan gadis mana yang akan dipilih sebagai pasangan nikah Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2757eaa9-ea63-487f-bb1b-eb78e1bf6bf0', 'vocabulary', '称える', '称える', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti gelar, jadi pikirkan saja ketika seseorang memberi Anda gelar yang mengagumkan. Mereka melakukan ini untuk memuji atau memberikan pujian kepada Anda.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti gelar, jadi pikirkan saja ketika seseorang memberi Anda gelar yang mengagumkan. Mereka melakukan ini untuk memuji atau memberikan pujian kepada Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2757eaa9-ea63-487f-bb1b-eb78e1bf6bf0', 'Untuk Memuji', true) ON CONFLICT DO NOTHING;
