INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2757eaa9-ea63-487f-bb1b-eb78e1bf6bf0', 'ワニカニのレビューを毎日していたら、先生から勤勉だと褒め称えられた。', 'Saya mengerjakan ulasan Wanikani setiap hari dan guru memuji ketekunan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('758d7e81-2672-482a-bdb6-c8379250eca7', 'vocabulary', '緩める', '緩める', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', '緩む berarti "melonggarkan", namun berkaitan dengan melonggarkan dengan sendirinya. Kata ini adalah ketika Anda mengendurkan atau mengendurkan sesuatu, artinya mengendurkan atau mengendurkan.', '緩む berarti "melonggarkan", namun berkaitan dengan melonggarkan dengan sendirinya. Kata ini adalah ketika Anda mengendurkan atau mengendurkan sesuatu, artinya mengendurkan atau mengendurkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('758d7e81-2672-482a-bdb6-c8379250eca7', 'Untuk Melonggarkan', true) ON CONFLICT DO NOTHING;
