INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('758d7e81-2672-482a-bdb6-c8379250eca7', 'どうぞネクタイをお緩めになってください。', 'Silakan melonggarkan dasi Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79dd9128-d63c-4c4c-b5e6-a69699e59562', 'vocabulary', '贈賄', '贈賄', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Hadiah yang Anda berikan sebagai suap adalah salah satu bentuk suap.', 'Hadiah yang Anda berikan sebagai suap adalah salah satu bentuk suap.') ON CONFLICT (id) DO NOTHING;
