INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('79dd9128-d63c-4c4c-b5e6-a69699e59562', 'これは、ある国では「プレゼント」と呼ばれるかもしれないが、この国では「贈賄」である。', 'Hal ini mungkin disebut sebagai "hadiah" di beberapa negara, namun di negara ini disebut sebagai "penyuapan".') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06756c8c-874b-49cc-a810-5c0061c527cb', 'vocabulary', '控える', '控える', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti berpantang dan versi vocab verbanya adalah berpantang juga!', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti berpantang dan versi vocab verbanya adalah berpantang juga!') ON CONFLICT (id) DO NOTHING;
