INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('92c78e87-a8a5-41d0-bce2-078c6ac2d968', 'vocabulary', '御免なさい', '御免なさい', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Ingat 御免? Ini adalah cara yang sopan untuk mengatakannya. Artinya maaf dan saya mohon maaf.', 'Ingat 御免? Ini adalah cara yang sopan untuk mengatakannya. Artinya maaf dan saya mohon maaf.') ON CONFLICT (id) DO NOTHING;
