INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c2d9f04-f9c4-4fe1-9300-4018ccc9043f', 'vocabulary', '渋谷', '渋谷', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Lembah Pahit adalah tempat yang dikenal sebagai Shibuya. Ini adalah daerah yang sangat terkenal di Tokyo. Sangat sibuk juga.', 'Lembah Pahit adalah tempat yang dikenal sebagai Shibuya. Ini adalah daerah yang sangat terkenal di Tokyo. Sangat sibuk juga.') ON CONFLICT (id) DO NOTHING;
