INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f6d7d94e-e5ee-4cc2-8b01-d993e7068ab2', 'vocabulary', '充電する', '充電する', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Jika 充電 adalah mengisi ulang maka versi kata kerjanya adalah mengisi ulang atau mengisi baterai.', 'Jika 充電 adalah mengisi ulang maka versi kata kerjanya adalah mengisi ulang atau mengisi baterai.') ON CONFLICT (id) DO NOTHING;
