INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('76061a0c-2651-4ad2-9dae-a18843ec7746', 'vocabulary', '控え', '控え', 1, 'df669efd-13c8-4ea2-a0c0-834cfaea2198', 'Jika Anda tidak melakukan banyak hal, Anda memerlukan rencana cadangan untuk mengeluarkan Anda dari berbagai hal. Seseorang mengajakmu ke pantai? Anda memerlukan cadangan. (Itu karena kamu takut matahari, katakan itu!)', 'Jika Anda tidak melakukan banyak hal, Anda memerlukan rencana cadangan untuk mengeluarkan Anda dari berbagai hal. Seseorang mengajakmu ke pantai? Anda memerlukan cadangan. (Itu karena kamu takut matahari, katakan itu!)') ON CONFLICT (id) DO NOTHING;
