INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f37a7a5-3010-45fd-8167-83fdff15a353', 'vocabulary', '防腐剤', '防腐剤', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Dosis pencegah pembusukan adalah dosis sesuatu yang Anda tempelkan pada luka atau luka Anda yang mencegahnya membusuk (atau Anda menaruhnya pada benda lain untuk mencegahnya membusuk). Ini adalah antiseptik atau pengawet.', 'Dosis pencegah pembusukan adalah dosis sesuatu yang Anda tempelkan pada luka atau luka Anda yang mencegahnya membusuk (atau Anda menaruhnya pada benda lain untuk mencegahnya membusuk). Ini adalah antiseptik atau pengawet.') ON CONFLICT (id) DO NOTHING;
