INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06d8e64b-9411-437e-8f89-684e87ec0a87', 'vocabulary', '〜剤', '〜剤', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Jika Anda meminum satu dosis sesuatu, Anda meminum satu dosis obat. Ambil sirup obat batukmu, Nak!', 'Jika Anda meminum satu dosis sesuatu, Anda meminum satu dosis obat. Ambil sirup obat batukmu, Nak!') ON CONFLICT (id) DO NOTHING;
