INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e5a8f16-6b4b-4a1c-a2c7-d8c5e6b3872f', 'vocabulary', '内堀', '内堀', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Parit bagian dalam adalah parit bagian dalam, atau, jika Anda membuatnya cukup keren, parit bagian dalam. Jika mereka berhasil melewati parit bagian luar, setidaknya kita bisa melewati parit bagian dalam!', 'Parit bagian dalam adalah parit bagian dalam, atau, jika Anda membuatnya cukup keren, parit bagian dalam. Jika mereka berhasil melewati parit bagian luar, setidaknya kita bisa melewati parit bagian dalam!') ON CONFLICT (id) DO NOTHING;
