INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64ce1872-79d7-4259-9d5b-fcc8207b4057', 'vocabulary', '巡回', '巡回', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Anda berpatroli dan berputar di sekitar blok untuk melakukan patroli. Anda berkeliling berpatroli.', 'Anda berpatroli dan berputar di sekitar blok untuk melakukan patroli. Anda berkeliling berpatroli.') ON CONFLICT (id) DO NOTHING;
