INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('089a55c7-795b-45a2-8715-e125d0d075f0', 'vocabulary', '訓戒', '訓戒', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Perintahku adalah perintahku. Anda harus melakukan apa yang saya katakan dalam instruksi/perintah saya. Ini peringatan saya. Ini adalah peringatan saya.', 'Perintahku adalah perintahku. Anda harus melakukan apa yang saya katakan dalam instruksi/perintah saya. Ini peringatan saya. Ini adalah peringatan saya.') ON CONFLICT (id) DO NOTHING;
