INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('17288670-943e-45b4-862f-ecfa098a70ac', 'vocabulary', '排気', '排気', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Energi penolakan yang Anda keluarkan dari mesin adalah gas buang. Bisa juga ventilasi, karena ini adalah udara yang keluar dan ditolak.', 'Energi penolakan yang Anda keluarkan dari mesin adalah gas buang. Bisa juga ventilasi, karena ini adalah udara yang keluar dan ditolak.') ON CONFLICT (id) DO NOTHING;
