INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a3965295-9a5e-49f5-b5fe-2bf35dcd3ac8', 'vocabulary', '排他', '排他', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Jika Anda menolak orang lain, Anda mengecualikan mereka, melakukan pengecualian. Itu bukan hal yang baik untuk dilakukan.', 'Jika Anda menolak orang lain, Anda mengecualikan mereka, melakukan pengecualian. Itu bukan hal yang baik untuk dilakukan.') ON CONFLICT (id) DO NOTHING;
