INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9b38b34e-bd87-439d-b4fe-9a52094670ba', 'vocabulary', '携帯', '携帯', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Sabuk portabel adalah sesuatu yang sangat portabel sehingga Anda dapat memasangnya di ikat pinggang Anda. Ini portabel. Perhatikan, ini juga merupakan istilah yang sangat umum untuk telepon seluler atau telepon genggam. Anda akan mempelajari lebih lanjut tentang hal itu di level mendatang.', 'Sabuk portabel adalah sesuatu yang sangat portabel sehingga Anda dapat memasangnya di ikat pinggang Anda. Ini portabel. Perhatikan, ini juga merupakan istilah yang sangat umum untuk telepon seluler atau telepon genggam. Anda akan mempelajari lebih lanjut tentang hal itu di level mendatang.') ON CONFLICT (id) DO NOTHING;
