INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9b38b34e-bd87-439d-b4fe-9a52094670ba', '携帯の電源を入れるには、電源ボタンを五秒間長押しする必要があります。', 'Untuk menghidupkan ponsel Anda, Anda perlu menekan tombol daya selama lima detik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6ecf64ce-54d0-47e2-9862-44a820621633', 'vocabulary', '携わる', '携わる', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Entah bagaimana kanji portable berubah menjadi kata kerja untuk terlibat atau berpartisipasi atau mengambil bagian. Saya kira jika Anda portabel, Anda dapat terlibat dalam segala macam hal, karena Anda dapat bergerak ke mana-mana, berpartisipasi di mana pun Anda bisa (daripada menjadi tidak portabel dan terjebak di satu tempat).', 'Entah bagaimana kanji portable berubah menjadi kata kerja untuk terlibat atau berpartisipasi atau mengambil bagian. Saya kira jika Anda portabel, Anda dapat terlibat dalam segala macam hal, karena Anda dapat bergerak ke mana-mana, berpartisipasi di mana pun Anda bisa (daripada menjadi tidak portabel dan terjebak di satu tempat).') ON CONFLICT (id) DO NOTHING;
