INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7757c48b-2784-4e5e-939d-134d7fd69182', 'vocabulary', '社会福祉', '社会福祉', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', '福祉 adalah kesejahteraan, 社会 adalah masyarakat. Jadi, kesejahteraan suatu masyarakat adalah kesejahteraan sosial.', '福祉 adalah kesejahteraan, 社会 adalah masyarakat. Jadi, kesejahteraan suatu masyarakat adalah kesejahteraan sosial.') ON CONFLICT (id) DO NOTHING;
