INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7757c48b-2784-4e5e-939d-134d7fd69182', 'しゃかいふくし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7757c48b-2784-4e5e-939d-134d7fd69182', '明日なら、家族の墓参りをした後に、その社会福祉施設に寄れなくもないよ。', 'Saya bisa mampir ke fasilitas kesejahteraan sosial setelah mengunjungi makam keluarga saya besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8766e264-2771-4ad0-8b54-07b2ba8efe63', 'vocabulary', '甲斐性', '甲斐性', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Hasil (甲斐) dari menjadi gender Anda sendiri menunjukkan kecerdikan Anda. Tergantung pada jenis kelamin Anda, hal-hal tertentu lebih sulit daripada yang lain, sehingga kecerdikan dan kompetensi Anda akan membantu Anda mengatasi rintangan tersebut.', 'Hasil (甲斐) dari menjadi gender Anda sendiri menunjukkan kecerdikan Anda. Tergantung pada jenis kelamin Anda, hal-hal tertentu lebih sulit daripada yang lain, sehingga kecerdikan dan kompetensi Anda akan membantu Anda mengatasi rintangan tersebut.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8766e264-2771-4ad0-8b54-07b2ba8efe63', 'Kecerdasan', true) ON CONFLICT DO NOTHING;
