INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8766e264-2771-4ad0-8b54-07b2ba8efe63', 'どうしてあの甲斐性無しが彼女の愛を復活させることができたのか、全く理解できないね。', 'Aku benar-benar tidak mengerti bagaimana pria tidak kompeten seperti itu bisa menghidupkan kembali cintanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8623e03-0d6a-49f8-8133-de2cb7398191', 'vocabulary', '生き甲斐', '生き甲斐', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Anda tahu bahwa 甲斐 adalah "efek" atau "nilai". Jadi, “nilai untuk hidup” adalah alasan Anda untuk hidup. Itu memberi nilai pada hidup. Itu alasanmu untuk hidup.', 'Anda tahu bahwa 甲斐 adalah "efek" atau "nilai". Jadi, “nilai untuk hidup” adalah alasan Anda untuk hidup. Itu memberi nilai pada hidup. Itu alasanmu untuk hidup.') ON CONFLICT (id) DO NOTHING;
