INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8623e03-0d6a-49f8-8133-de2cb7398191', 'ロッククライミングは私の生き甲斐です。', 'Panjat tebing adalah tujuan hidup saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('95388040-55ca-4e44-bf8c-53906dfd6711', 'vocabulary', '手の甲', '手の甲', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Cangkang kura-kura di tangan Anda berada di bagian belakangnya (lihat Anda bisa membuatnya berbentuk seperti cangkang kura-kura jika Anda berusaha keras!). Itu sebabnya ini adalah punggung tangan seseorang.', 'Cangkang kura-kura di tangan Anda berada di bagian belakangnya (lihat Anda bisa membuatnya berbentuk seperti cangkang kura-kura jika Anda berusaha keras!). Itu sebabnya ini adalah punggung tangan seseorang.') ON CONFLICT (id) DO NOTHING;
