INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('95388040-55ca-4e44-bf8c-53906dfd6711', 'とても綺麗な手の甲を持っていることが彼女の自慢です。', 'Dia bangga karena punggung tangannya sangat indah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('960fa2a5-bc23-425a-a4eb-451ab91f1538', 'vocabulary', 'やり甲斐', 'やり甲斐', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Bagian やり berasal dari やる yang berarti "melakukan". Jadi, jika dampaknya (甲斐) baik untuk dilakukan, maka layak untuk dilakukan.', 'Bagian やり berasal dari やる yang berarti "melakukan". Jadi, jika dampaknya (甲斐) baik untuk dilakukan, maka layak untuk dilakukan.') ON CONFLICT (id) DO NOTHING;
