INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4bf478f7-ae20-44fe-b93f-0ec93f9b4e14', 'vocabulary', '駆け込む', '駆け込む', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', '駆ける berarti "berlari kencang" dan 込む berarti "menjadi ramai". Jika Anda berpacu dengan seseorang dan mengerumuninya, Anda akan menyerbunya.', '駆ける berarti "berlari kencang" dan 込む berarti "menjadi ramai". Jika Anda berpacu dengan seseorang dan mengerumuninya, Anda akan menyerbunya.') ON CONFLICT (id) DO NOTHING;
