INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4bf478f7-ae20-44fe-b93f-0ec93f9b4e14', '終電に駆け込み乗車をしようとしましたが、目の前でドアが閉まりました。', 'Saya bergegas ke kereta terakhir, tetapi pintunya tertutup di depan mata saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('af307909-8b55-4b18-b9a6-e27c43670142', 'vocabulary', '駆け出す', '駆け出す', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', '駆ける berarti "berlari kencang" dan 出す berarti "menghapus". Jadi, jika Anda berlari kencang untuk melepaskan diri, Anda mungkin akan terburu-buru keluar. Tenang dan pelan-pelan, kawan!', '駆ける berarti "berlari kencang" dan 出す berarti "menghapus". Jadi, jika Anda berlari kencang untuk melepaskan diri, Anda mungkin akan terburu-buru keluar. Tenang dan pelan-pelan, kawan!') ON CONFLICT (id) DO NOTHING;
