INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af307909-8b55-4b18-b9a6-e27c43670142', '彼に質問を尋ねた時、駆け出しただけだ。 ', 'Ketika saya mengajukan pertanyaan kepadanya, dia lari begitu saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e2f69c92-8472-4609-b49b-fbec60e4087b', 'vocabulary', '駆け回る', '駆け回る', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'To 駆ける berarti "berlari kencang". 回る adalah "berputar". Jadi jika Anda berlari kencang dengan cara berputar, Anda akan berlari kesana kemari.', 'To 駆ける berarti "berlari kencang". 回る adalah "berputar". Jadi jika Anda berlari kencang dengan cara berputar, Anda akan berlari kesana kemari.') ON CONFLICT (id) DO NOTHING;
