INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2f69c92-8472-4609-b49b-fbec60e4087b', 'レシピにサフランがいるって書いてあったから、あちこち駆け回って探したんだけど見つからなくて、結局今回はサフランは使わなかったの。', 'Resepnya bilang mau masukkan saffron, jadi saya berkeliling mencarinya kemana-mana, tapi tidak ketemu, jadi kali ini saya tidak menambahkan saffron.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9922e2e-92e2-4791-b239-30dc537f58b0', 'vocabulary', '携帯電話', '携帯電話', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Anda tahu bahwa 携帯 berarti "portabel" atau "ponsel" atau "ponsel". Lalu 電話 berarti "telepon". Ini pada dasarnya hanyalah versi yang lebih panjang dari sekedar mengucapkan 携帯, menjadikannya telepon portabel atau telepon seluler atau telepon seluler. Ini seperti perbedaan antara mengatakan "ponsel saya" dan "ponsel saya", Anda paham?', 'Anda tahu bahwa 携帯 berarti "portabel" atau "ponsel" atau "ponsel". Lalu 電話 berarti "telepon". Ini pada dasarnya hanyalah versi yang lebih panjang dari sekedar mengucapkan 携帯, menjadikannya telepon portabel atau telepon seluler atau telepon seluler. Ini seperti perbedaan antara mengatakan "ponsel saya" dan "ponsel saya", Anda paham?') ON CONFLICT (id) DO NOTHING;
