INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c04e9568-1623-47bd-9e3f-7dfb1d1d7725', 'あの携帯ストラップが気色悪すぎて、考えるだけでも吐きそうだわ。', 'Tali ponselnya sangat kotor, hanya memikirkannya saja sudah membuatku muntah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e550698-3395-410c-9512-06da981dd63e', 'vocabulary', '囚人', '囚人', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Seorang penjahat akan menjadi tahanan atau narapidana jika tertangkap!', 'Seorang penjahat akan menjadi tahanan atau narapidana jika tertangkap!') ON CONFLICT (id) DO NOTHING;
