INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e550698-3395-410c-9512-06da981dd63e', 'どうして囚人はしましまの服を着ているんですか。', 'Mengapa narapidana memakai pakaian bergaris?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e550698-3395-410c-9512-06da981dd63e', 'そこには、囚人達の道具がしまわれていた。', 'Peralatan para tahanan disimpan di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e550698-3395-410c-9512-06da981dd63e', 'その囚人が、1998年に軍隊に入隊していた記録が見つかった。', 'Ditemukan catatan yang menunjukkan narapidana tersebut bergabung dengan tentara pada tahun 1998.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('609126df-829e-42bc-813d-011cc87792ac', 'vocabulary', '死刑囚', '死刑囚', 1, 'eb4c8899-985e-4b76-aaa1-bbce928d988b', 'Ingat bagaimana Anda mengetahui bahwa 死刑 berarti "hukuman mati?" Nah penjahat yang dijatuhi hukuman itu adalah penjahat yang sudah divonis bersalah atau terpidana mati. Mereka dijatuhi hukuman mati.', 'Ingat bagaimana Anda mengetahui bahwa 死刑 berarti "hukuman mati?" Nah penjahat yang dijatuhi hukuman itu adalah penjahat yang sudah divonis bersalah atau terpidana mati. Mereka dijatuhi hukuman mati.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('609126df-829e-42bc-813d-011cc87792ac', 'Dikutuk Kriminal', true) ON CONFLICT DO NOTHING;
