INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6df507f-c485-44b1-81f7-58ab180a42ec', 'この農場では殺虫剤の使用は厳禁です。', 'Penggunaan insektisida dilarang keras di peternakan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6df507f-c485-44b1-81f7-58ab180a42ec', '殺虫剤は人体に入ると危険です。', 'Pestisida berbahaya jika masuk ke dalam tubuh manusia.') ON CONFLICT DO NOTHING;
