INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b3a0467-3c24-431c-9f17-f7b01191231a', 'vocabulary', '葬儀', '葬儀', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Upacara penguburan disebut dengan pemakaman.', 'Upacara penguburan disebut dengan pemakaman.') ON CONFLICT (id) DO NOTHING;
