INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8d9cdfbf-4018-4843-902e-28b5cca841a3', 'vocabulary', '獲得', '獲得', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda menyita dan memperoleh, Anda melakukan akuisisi atau kepemilikan atas sesuatu.', 'Jika Anda menyita dan memperoleh, Anda melakukan akuisisi atau kepemilikan atas sesuatu.') ON CONFLICT (id) DO NOTHING;
