INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('37edc393-a314-4c82-932d-b12b31ed76f9', 'vocabulary', '捕獲', '捕獲', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Menangkap dan merampas adalah menangkap dan menyita.', 'Menangkap dan merampas adalah menangkap dan menyita.') ON CONFLICT (id) DO NOTHING;
