INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37edc393-a314-4c82-932d-b12b31ed76f9', 'このメモ帳に、巨人の捕獲についての思いついたことを全部メモしています。', 'Di memo pad ini, saya mencatat semua ide saya untuk memotret para raksasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3ca30d8b-a50f-4ee9-8a44-e5165868ffd6', 'vocabulary', '獲物', '獲物', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Sesuatu yang disita adalah sesuatu yang Anda rebut dari kemenangan Anda. Itu rampasanmu. Itu pialamu!', 'Sesuatu yang disita adalah sesuatu yang Anda rebut dari kemenangan Anda. Itu rampasanmu. Itu pialamu!') ON CONFLICT (id) DO NOTHING;
