INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ca30d8b-a50f-4ee9-8a44-e5165868ffd6', '都会には、我々の詐欺の獲物がたくさんいるんだよ。', 'Banyak sekali mangsa yang mudah untuk kita tipu di kota ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c98b1c7d-6ce6-4ece-8398-e918b0e77963', 'vocabulary', '茂る', '茂る', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya subur dan versi vocab verbanya adalah menjadi subur atau tumbuh subur.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya subur dan versi vocab verbanya adalah menjadi subur atau tumbuh subur.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c98b1c7d-6ce6-4ece-8398-e918b0e77963', 'Menjadi Mewah', true) ON CONFLICT DO NOTHING;
