INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c98b1c7d-6ce6-4ece-8398-e918b0e77963', '妖婆の庭には雑草が生い茂っていた。', 'Kebun perempuan tua itu ditumbuhi rumput liar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bbdfaef6-bdd0-4351-b3e0-348963a279ce', 'vocabulary', '繁茂', '繁茂', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Sesuatu yang tumbuh subur dan subur pasti mempunyai pertumbuhan yang cukup subur. Banyak sekali pertumbuhan.', 'Sesuatu yang tumbuh subur dan subur pasti mempunyai pertumbuhan yang cukup subur. Banyak sekali pertumbuhan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bbdfaef6-bdd0-4351-b3e0-348963a279ce', 'Pertumbuhan Mewah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bbdfaef6-bdd0-4351-b3e0-348963a279ce', 'はんも', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bbdfaef6-bdd0-4351-b3e0-348963a279ce', '庭に雑草が繁茂しているので、この週末に草刈りをします。', 'Halaman kami ditumbuhi rumput liar, jadi saya akan memotongnya akhir pekan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8f73a18c-99c1-4fd8-84d4-39ec0e449a33', 'vocabulary', '頻繁', '頻繁', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Sesuatu yang sering ditumbuhi adalah sesuatu yang sangat sering terjadi. Ia tidak pernah berhenti menyerang, tidak pernah berhenti datang, dan sejujurnya semakin gencar dalam seberapa sering ia tumbuh berlebihan. Itu sialan [masukkan nama tanaman di sini].', 'Sesuatu yang sering ditumbuhi adalah sesuatu yang sangat sering terjadi. Ia tidak pernah berhenti menyerang, tidak pernah berhenti datang, dan sejujurnya semakin gencar dalam seberapa sering ia tumbuh berlebihan. Itu sialan [masukkan nama tanaman di sini].') ON CONFLICT (id) DO NOTHING;
