INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('76b95654-cdd2-4bcf-871a-f029f617d1c6', 'vocabulary', '繁栄', '繁栄', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda ditumbuhi kemakmuran, Anda mungkin benar-benar makmur.', 'Jika Anda ditumbuhi kemakmuran, Anda mungkin benar-benar makmur.') ON CONFLICT (id) DO NOTHING;
