INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d5f7cb6-8861-476b-8b74-044aaefae204', 'vocabulary', '褒美', '褒美', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Saya memuji Anda atas kecantikan Anda. Aku sangat menyukai kecantikanmu, aku memberimu hadiah... hadiah, pada dasarnya.', 'Saya memuji Anda atas kecantikan Anda. Aku sangat menyukai kecantikanmu, aku memberimu hadiah... hadiah, pada dasarnya.') ON CONFLICT (id) DO NOTHING;
