INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('894b8b87-a333-49f7-82a7-a20714b86fa7', 'vocabulary', '透ける', '透ける', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti transparan dan versi vocab verbanya berarti transparan (karena biasanya orang tidak bisa "mentransparankan" sesuatu).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti transparan dan versi vocab verbanya berarti transparan (karena biasanya orang tidak bisa "mentransparankan" sesuatu).') ON CONFLICT (id) DO NOTHING;
