INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d0929007-774f-43cd-a03c-87bccf318c4d', 'vocabulary', '近隣', '近隣', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Semua tetangga dekat adalah orang-orang yang tinggal di sekitar Anda dan di dekat Anda. Mereka adalah bagian dari lingkungan sekitar.', 'Semua tetangga dekat adalah orang-orang yang tinggal di sekitar Anda dan di dekat Anda. Mereka adalah bagian dari lingkungan sekitar.') ON CONFLICT (id) DO NOTHING;
