INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f4652188-2801-4669-8bf4-1a5dbc3fb581', 'vocabulary', '隣国', '隣国', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Negara tetangga adalah negara tetangga. Bagi kami, 隣国 kami di Amerika adalah orang-orang Kanada yang licik... yang selalu menunggu untuk menyerang, saya tahu...', 'Negara tetangga adalah negara tetangga. Bagi kami, 隣国 kami di Amerika adalah orang-orang Kanada yang licik... yang selalu menunggu untuk menyerang, saya tahu...') ON CONFLICT (id) DO NOTHING;
