INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8508f10c-ad32-43e2-a056-682b2d93b96a', 'vocabulary', '雅楽', '雅楽', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Ini sangat elegan dan nyaman. Ini adalah musik istana Jepang, dan itulah yang didengarkan oleh orang-orang istana di Jepang pada masa itu. Anda juga bisa menyebutnya gagaku jika Anda mau.', 'Ini sangat elegan dan nyaman. Ini adalah musik istana Jepang, dan itulah yang didengarkan oleh orang-orang istana di Jepang pada masa itu. Anda juga bisa menyebutnya gagaku jika Anda mau.') ON CONFLICT (id) DO NOTHING;
