INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('67ad8a45-4d7c-449a-abc1-b3a8abb29b0e', 'vocabulary', '徹底', '徹底', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Menembus ke bawah. SEMUA jalan ke bawah. Jangan berhenti di tengah jalan. Ini adalah ketelitian. Ini adalah kelengkapan.', 'Menembus ke bawah. SEMUA jalan ke bawah. Jangan berhenti di tengah jalan. Ini adalah ketelitian. Ini adalah kelengkapan.') ON CONFLICT (id) DO NOTHING;
