INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b987b104-19de-44a1-9720-4dcfd5b76324', 'vocabulary', '高瀬', '高瀬', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jeram yang tinggi adalah jeram yang dangkal. Saya tidak tahu mengapa hal ini masuk akal, tapi saya kira jika airnya lebih tinggi, arusnya tidak akan terlalu deras, artinya airnya hanya dangkal (tapi tidak terlalu tinggi untuk menjadi sesuatu yang lain, seperti danau, atau apa pun).', 'Jeram yang tinggi adalah jeram yang dangkal. Saya tidak tahu mengapa hal ini masuk akal, tapi saya kira jika airnya lebih tinggi, arusnya tidak akan terlalu deras, artinya airnya hanya dangkal (tapi tidak terlalu tinggi untuk menjadi sesuatu yang lain, seperti danau, atau apa pun).') ON CONFLICT (id) DO NOTHING;
