INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d1806330-6e7c-4d65-adb3-d0fddc8b5395', 'vocabulary', '潜水', '潜水', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Untuk menyembunyikan diri Anda di dalam air, sebaiknya Anda mulai menyelam dan masuk ke dalam air di tempat yang dapat menyembunyikan Anda!', 'Untuk menyembunyikan diri Anda di dalam air, sebaiknya Anda mulai menyelam dan masuk ke dalam air di tempat yang dapat menyembunyikan Anda!') ON CONFLICT (id) DO NOTHING;
