INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6134d8fd-f5a2-4326-935b-872a01b69576', 'vocabulary', '潜在意識', '潜在意識', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika 意識 adalah secara sadar, maka apa yang tersembunyi dalam pikiran Anda adalah alam bawah sadar Anda.', 'Jika 意識 adalah secara sadar, maka apa yang tersembunyi dalam pikiran Anda adalah alam bawah sadar Anda.') ON CONFLICT (id) DO NOTHING;
