INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b6753257-da66-4a62-ba3b-d33596189a33', 'vocabulary', '拳', '拳', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
