INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dd8c86cd-4056-40f1-9629-f05d7203b76c', 'vocabulary', '拳骨', '拳骨', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Tinju yang seperti tulang (keras) adalah tinju yang terkepal dan siap untuk ditinju, menjadikannya tinju atau ruas jari yang terkepal, jika Anda ingin membuatnya lebih bertulang.', 'Tinju yang seperti tulang (keras) adalah tinju yang terkepal dan siap untuk ditinju, menjadikannya tinju atau ruas jari yang terkepal, jika Anda ingin membuatnya lebih bertulang.') ON CONFLICT (id) DO NOTHING;
