INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f56492b1-87fb-49f1-b36c-d65e3760ad3a', 'vocabulary', '仁', '仁', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
