INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c8bb5e29-98f3-4ceb-bd06-0afdbb915c10', 'vocabulary', '至る', '至る', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Kanji berarti mencapai tetapi arti kata kerja ini adalah mencapai. Saya kira itu karena jika Anda mencapai sesuatu seperti pencerahan, Anda juga sampai pada pencerahan itu. Jadi, untuk sampai pada.', 'Kanji berarti mencapai tetapi arti kata kerja ini adalah mencapai. Saya kira itu karena jika Anda mencapai sesuatu seperti pencerahan, Anda juga sampai pada pencerahan itu. Jadi, untuk sampai pada.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c8bb5e29-98f3-4ceb-bd06-0afdbb915c10', 'Untuk Tiba Di', true) ON CONFLICT DO NOTHING;
