INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c8bb5e29-98f3-4ceb-bd06-0afdbb915c10', 'そういう訳で、あの化け物は今日に至るまで牢屋にぶちこまれることになったんですよ。', 'Dan begitulah monster itu berakhir di balik jeruji besi hingga hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68e23ff0-616d-4609-999e-8e6bc7358fbe', 'vocabulary', '夏至', '夏至', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda telah mencapai musim panas, itu berarti Anda telah menyelesaikan musim sebelumnya dan memasuki musim panas. Ini adalah titik balik matahari musim panas.', 'Jika Anda telah mencapai musim panas, itu berarti Anda telah menyelesaikan musim sebelumnya dan memasuki musim panas. Ini adalah titik balik matahari musim panas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68e23ff0-616d-4609-999e-8e6bc7358fbe', 'Titik Balik Matahari Musim Panas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('68e23ff0-616d-4609-999e-8e6bc7358fbe', 'げし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68e23ff0-616d-4609-999e-8e6bc7358fbe', '父に夏至から11日目のことを何と呼ぶか知っているかと聞かれたので、得意気に「ハゲ症」って答えたんですけど、それって「ハゲ頭の症状」って意味になるみたいで。父は笑って、正しい答えは「半夏生」だよって教えてくれましたけどね。', 'Ayah saya bertanya apakah saya tahu apa yang harus saya sebut hari kesebelas setelah titik balik matahari musim panas, jadi saya menjawab dengan penuh kemenangan "hageshou", yang secara harfiah berarti "gejala kebotakan". Dia tertawa dan memberitahuku bahwa jawaban yang benar adalah "hangeshou."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21b1fa4d-4f3d-438b-92c7-fd37de50a35d', 'vocabulary', '冬至', '冬至', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda akan mencapai musim dingin, maka itu adalah titik balik matahari musim dingin. Selamat musim dingin, semuanya!', 'Jika Anda akan mencapai musim dingin, maka itu adalah titik balik matahari musim dingin. Selamat musim dingin, semuanya!') ON CONFLICT (id) DO NOTHING;
