INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('21b1fa4d-4f3d-438b-92c7-fd37de50a35d', 'とうじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21b1fa4d-4f3d-438b-92c7-fd37de50a35d', 'どうして日本では冬至の日にカボチャを食べると良いというのですか？', 'Mengapa orang mengatakan makan labu pada titik balik matahari musim dingin di Jepang adalah hal yang baik?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc308feb-ec34-42ea-b17c-76df7bc8b07d', 'vocabulary', '必至', '必至', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda yakin akan mencapainya, maka hal itu tidak bisa dihindari. Ini adalah kesimpulan yang sudah pasti.', 'Jika Anda yakin akan mencapainya, maka hal itu tidak bisa dihindari. Ini adalah kesimpulan yang sudah pasti.') ON CONFLICT (id) DO NOTHING;
