INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc308feb-ec34-42ea-b17c-76df7bc8b07d', '子どもへの性教育はある時期では必至になると思うんですが、日本はそうした教育については通常どのように行われるんですか。', 'Saya pikir pendidikan seks pada anak-anak perlu diajarkan pada suatu saat, tapi bagaimana biasanya orang-orang di Jepang mengajarkan hal-hal tersebut?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('42bb537c-9dc8-4509-8926-01a23f7cbfd3', 'vocabulary', '至上', '至上', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda mencapai yang lebih tinggi, itu berarti Anda berada di atas semua orang, dan Anda memandang rendah mereka. Anda memiliki supremasi.', 'Jika Anda mencapai yang lebih tinggi, itu berarti Anda berada di atas semua orang, dan Anda memandang rendah mereka. Anda memiliki supremasi.') ON CONFLICT (id) DO NOTHING;
