INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0d9e4bb0-c2f5-4f9c-b62f-0924b4a0ef29', '裁判官が彼の心神喪失による刑事責任能力の回避の申し立てを受け入れたことは、誠に遺憾です。', 'Saya benar-benar kesal karena hakim menerima pengakuan tidak bersalahnya dengan alasan kegilaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ace5871-99ce-4c95-9ee5-111286f464b8', 'vocabulary', '誠意', '誠意', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Gagasan tentang ketulusan adalah ketulusan. Itu juga untuk memiliki itikad baik pada orang lain.', 'Gagasan tentang ketulusan adalah ketulusan. Itu juga untuk memiliki itikad baik pada orang lain.') ON CONFLICT (id) DO NOTHING;
