INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ace5871-99ce-4c95-9ee5-111286f464b8', '誠意のこもった説明が聞けたので、今回は彼女の言い分を聞いて上げることにしました。', 'Setelah mendengar penjelasan tulusnya, kali ini saya memutuskan untuk memberinya manfaat dari keraguan.') ON CONFLICT DO NOTHING;
