INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('639bd02f-90f8-40a5-ae54-232f5562dfb8', '彼は僕の誠実な友人だから、心配する必要は無いよ。絶対に取引から手を引いたりなんかしないさ。', 'Dia adalah teman setiaku, jadi jangan khawatir. Dia tidak akan pernah mundur dari kesepakatan itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58b83620-304b-47c5-a3a2-b55edda509d9', 'vocabulary', '忠誠', '忠誠', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Saya memiliki ketulusan tentang kesetiaan saya. Itu menunjukkan kesetiaan, bukan?', 'Saya memiliki ketulusan tentang kesetiaan saya. Itu menunjukkan kesetiaan, bukan?') ON CONFLICT (id) DO NOTHING;
