INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58b83620-304b-47c5-a3a2-b55edda509d9', '今振り返ってみると、ハチ公は絶対的な忠誠心を持ったいい犬だったよな。', 'Melihat ke belakang, Hachiko adalah seekor anjing yang memiliki kesetiaan mutlak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06c3b9db-8bc8-490d-9227-db297603f103', 'vocabulary', '故郷', '故郷', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Secara kebetulan, ini adalah kampung halaman Anda. Tidak banyak yang bisa dikatakan selain kampung halaman dan tempat lahir Anda.', 'Secara kebetulan, ini adalah kampung halaman Anda. Tidak banyak yang bisa dikatakan selain kampung halaman dan tempat lahir Anda.') ON CONFLICT (id) DO NOTHING;
