INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06c3b9db-8bc8-490d-9227-db297603f103', '聞いたところによると、彼女、離婚後故郷に戻ったらしいぜ。', 'Dari apa yang saya dengar, dia pindah kembali ke kampung halamannya setelah perceraian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9813435-cedc-4b0d-8b15-a52884c0cbfb', 'vocabulary', '帰郷する', '帰郷する', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda kembali ke kampung halaman, Anda akan kembali ke kampung halaman seseorang.', 'Jika Anda kembali ke kampung halaman, Anda akan kembali ke kampung halaman seseorang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d9813435-cedc-4b0d-8b15-a52884c0cbfb', 'Untuk Kembali Ke Kampung Halaman', true) ON CONFLICT DO NOTHING;
