INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d9813435-cedc-4b0d-8b15-a52884c0cbfb', 'ほとんどの博打打ちが思っているように、彼女も自分には天分があると思っていたんだが、結局あるポーカーのゲームで全財産を失って、帰郷するはめになったんだ。', 'Seperti kebanyakan penjudi, dia percaya bahwa dia mempunyai bakat, namun pada akhirnya dia kehilangan segalanya karena permainan poker dan harus kembali ke kampung halamannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('33e71678-b20c-4d4c-85ce-9b48d79b4f5b', 'vocabulary', '侵攻', '侵攻', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda menyerang dengan agresi, itu adalah invasi.', 'Jika Anda menyerang dengan agresi, itu adalah invasi.') ON CONFLICT (id) DO NOTHING;
