INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('33e71678-b20c-4d4c-85ce-9b48d79b4f5b', '奴らが山のてっぺんにある俺たちの村を侵攻しようとした時、敵陣が全員高山病に罹ってしまったのには笑えたよ。', 'Lucu sekali ketika mereka mencoba menyerang desa kami yang berada jauh di puncak gunung, seluruh kamp musuh terkena penyakit ketinggian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a89b3629-b5f2-4331-82af-291f41141073', 'vocabulary', '侵入', '侵入', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Jika Anda menyerang dan masuk, itu adalah gangguan.', 'Jika Anda menyerang dan masuk, itu adalah gangguan.') ON CONFLICT (id) DO NOTHING;
