INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d0417523-d254-4dc0-abfd-b0d6f7badfa9', 'vocabulary', '不透明', '不透明', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Anda tahu bahwa 透明 adalah "transparansi" atau "transparan" - jadi, jika ada sesuatu yang tidak transparan, maka itu buram, sehingga menjadikan kata ini buram.', 'Anda tahu bahwa 透明 adalah "transparansi" atau "transparan" - jadi, jika ada sesuatu yang tidak transparan, maka itu buram, sehingga menjadikan kata ini buram.') ON CONFLICT (id) DO NOTHING;
