INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b0e53970-d03c-4677-862c-8ed5cd9522ff', 'vocabulary', '軍艦島', '軍艦島', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', '軍艦 adalah kapal perang, dan 島 adalah sebuah pulau. Selamat datang di... Battleship Island (musik Jurassic Park).', '軍艦 adalah kapal perang, dan 島 adalah sebuah pulau. Selamat datang di... Battleship Island (musik Jurassic Park).') ON CONFLICT (id) DO NOTHING;
