INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0e53970-d03c-4677-862c-8ed5cd9522ff', 'アイツはぜんぜん面白くないな。話題といったら軍艦島の都市伝説だけだし。', 'Dia tidak menarik sama sekali. Yang dia bicarakan hanyalah legenda urban Battleship Island.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d0beecda-72e3-475b-80c7-b5319ac20222', 'vocabulary', '誠に', '誠に', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Huruf に di akhir kata ini mengubah ketulusan menjadi kata keterangan. Apa versi kata keterangan dari ketulusan? Itu tulus, atau memang. Memang benar.', 'Huruf に di akhir kata ini mengubah ketulusan menjadi kata keterangan. Apa versi kata keterangan dari ketulusan? Itu tulus, atau memang. Memang benar.') ON CONFLICT (id) DO NOTHING;
