INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d0beecda-72e3-475b-80c7-b5319ac20222', '誠に申し訳ございません。', 'Saya dengan tulus meminta maaf.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d0beecda-72e3-475b-80c7-b5319ac20222', 'わざわざお越しいただき、誠にありがとうございます。', 'Saya sangat berterima kasih karena Anda telah datang jauh-jauh ke sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d0beecda-72e3-475b-80c7-b5319ac20222', 'それは誠に素晴らしいことだ。', 'Sungguh luar biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d0beecda-72e3-475b-80c7-b5319ac20222', '誠に申し訳ありませんが、当ホテルは全室禁煙となっております。', 'Saya benar-benar minta maaf, tapi semua kamar di hotel kami bebas rokok.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('874dcc9e-2de0-4237-80ef-271273ca660e', 'vocabulary', '潜る', '潜る', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menyembunyikan, namun sebagai kata kerja, kata ini berarti masuk ke bawah atau melewati. Umumnya, kata ini berarti menyelam di bawah air atau pergi ke bawah tanah. Dapatkah Anda memahami mengapa kanji untuk menyembunyikan masuk akal dalam kasus ini? Jika Anda berada di bawah air atau di bawah tanah, tidak ada yang bisa melihat Anda!', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menyembunyikan, namun sebagai kata kerja, kata ini berarti masuk ke bawah atau melewati. Umumnya, kata ini berarti menyelam di bawah air atau pergi ke bawah tanah. Dapatkah Anda memahami mengapa kanji untuk menyembunyikan masuk akal dalam kasus ini? Jika Anda berada di bawah air atau di bawah tanah, tidak ada yang bisa melihat Anda!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('874dcc9e-2de0-4237-80ef-271273ca660e', 'Untuk Pergi ke Bawah', true) ON CONFLICT DO NOTHING;
