INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('874dcc9e-2de0-4237-80ef-271273ca660e', 'モグラが土の下に潜って行くところを見ました。', 'Saya melihat seekor tahi lalat bersembunyi di bawah tanah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('874dcc9e-2de0-4237-80ef-271273ca660e', '水の中にどのぐらいの間潜っていられますか。', 'Berapa lama Anda bisa bertahan di bawah air?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('874dcc9e-2de0-4237-80ef-271273ca660e', 'うちの犬は、フラフープをジャンプして潜る技を身につけました。', 'Anjing saya mempelajari trik melompati hula hoop.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b06c83e-0af9-4ccb-b333-b4ae4f937d3a', 'vocabulary', '侵食', '侵食', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Sesuatu yang menyerang dan menggerogoti sesuatu adalah sesuatu yang menyebabkan erosi dan korosi.', 'Sesuatu yang menyerang dan menggerogoti sesuatu adalah sesuatu yang menyebabkan erosi dan korosi.') ON CONFLICT (id) DO NOTHING;
