INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b06c83e-0af9-4ccb-b333-b4ae4f937d3a', '木々を切り倒すことで、土壌の侵食が引き起こされることがあります。', 'Menebang pohon dapat menyebabkan erosi tanah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f438451a-bc94-4860-86c7-fa9a3e2c7a7b', 'vocabulary', '透き通る', '透き通る', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Ini merupakan gabungan kata 透ける dan 通る. Sesuatu yang cukup transparan untuk dilewati benda (seperti cahaya) tetap akan transparan alias tembus pandang.', 'Ini merupakan gabungan kata 透ける dan 通る. Sesuatu yang cukup transparan untuk dilewati benda (seperti cahaya) tetap akan transparan alias tembus pandang.') ON CONFLICT (id) DO NOTHING;
