INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f438451a-bc94-4860-86c7-fa9a3e2c7a7b', 'すきとおる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f438451a-bc94-4860-86c7-fa9a3e2c7a7b', '彼女の手は透き通るほど白かった。', 'Tangannya sangat putih hingga hampir transparan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f438451a-bc94-4860-86c7-fa9a3e2c7a7b', '水が透き通っていてきれい。', 'Airnya sangat jernih dan indah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f438451a-bc94-4860-86c7-fa9a3e2c7a7b', '玉ねぎが透き通ってきたら肉を入れてください。', 'Setelah bawang bombay menjadi transparan, tambahkan daging.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d45cb769-269a-4434-806b-6afc67d8175f', 'vocabulary', '樹脂', '樹脂', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Lemak yang keluar dari kayu pohon digunakan untuk membuat resin. Pohon tidak mempunyai lemak, katamu? Ya, Anda salah, lihatlah. Pohon sangat gemuk dan kami menggunakan resin dari pohon tersebut untuk melakukan segala macam hal.', 'Lemak yang keluar dari kayu pohon digunakan untuk membuat resin. Pohon tidak mempunyai lemak, katamu? Ya, Anda salah, lihatlah. Pohon sangat gemuk dan kami menggunakan resin dari pohon tersebut untuk melakukan segala macam hal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d45cb769-269a-4434-806b-6afc67d8175f', 'Damar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d45cb769-269a-4434-806b-6afc67d8175f', 'じゅし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d45cb769-269a-4434-806b-6afc67d8175f', 'これを透明の樹脂で固めました。', 'Ini dikeraskan dengan resin transparan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', 'vocabulary', '嬉々', '嬉々', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Anda sangat senang, Anda merasa senang lagi. Wow, kamu baru saja menjalani hidup dengan bahagia, bukan? Terimalah kegembiraan itu ke dalam hidup Anda dengan gembira!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', 'Dengan senang hati', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', 'Joyfully', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', 'Merrily', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', 'きき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', '子供ができればすぐ、嬉々として報告してくれるだろう。', 'Begitu mereka hamil, mereka dengan senang hati akan memberi tahu kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', '父は、久しぶりに旧友に会い、嬉々として近況を語り合った。', 'Ayah saya melihat teman lamanya untuk pertama kalinya setelah sekian lama dan mereka dengan gembira bertemu satu sama lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21014da4-b1ea-4139-bc74-ba572564d308', 'コウイチが無事に帰ってきて、村には嬉々たる声が響いた。', 'Koichi kembali dengan selamat dan desa dipenuhi dengan suara gembira.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', 'vocabulary', '嬉しい', '嬉しい', 1, '65165f3b-d080-4b23-abf1-ea0bdf823b76', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat senang? Senang juga!', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat senang? Senang juga!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', 'Senang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', 'Happy', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', 'Joyful', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', 'うれしい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', '今日は何だか嬉しそうですね。', 'Kamu terlihat bahagia hari ini, entah kenapa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', '百年前の今日、あなたが生まれてくれて嬉しかった。お誕生日おめでとう。', 'Saat kamu lahir seratus tahun yang lalu hari ini, aku bahagia. Selamat ulang tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12e67c7a-4d8e-489a-8716-b9db77e7185b', '最近、嬉しいことが全然ない。', 'Tidak ada hal bahagia yang terjadi padaku akhir-akhir ini.') ON CONFLICT DO NOTHING;
