INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5da39adc-de6b-45b2-ba74-f2646e1bc3b9', 'radical', '瓜', 'melon', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ini melon. Bayangkan sebuah melon dipotong menjadi dua, dan Anda melihat bagian dalamnya dari samping. Lihat bagian melon pribadi yang berharga itu? Anda akan menyimpannya untuk diri Anda sendiri, karena melon itu enak dan tidak untuk dibagikan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5da39adc-de6b-45b2-ba74-f2646e1bc3b9', 'melon', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1da365aa-6954-47d6-aa08-73fd9aced8f3', 'radical', '屋', 'shop', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Kita sudah mempunyai akar kata radikal, jadi kita akan menggunakan arti kanji sekunder untuk kata radikal ini. Itu toko, ingat?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1da365aa-6954-47d6-aa08-73fd9aced8f3', 'Belanja', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('cf1d738e-ea2c-46ef-acf8-0abe50c5ba5a', 'radical', '[satellite]', 'satellite', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Lihatlah radikal ini. Dapatkah Anda melihatnya melayang di angkasa? Dapatkah Anda melihat antena dan reflektornya? Itu karena itu adalah satelit.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cf1d738e-ea2c-46ef-acf8-0abe50c5ba5a', 'Satelit', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('91024f20-e6c4-46f4-8358-4cebccc63a35', 'radical', '骨', 'bone', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Radikal ini sama dengan kanji. Artinya tulang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91024f20-e6c4-46f4-8358-4cebccc63a35', 'Tulang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a8e3a869-5793-475f-9d8b-a45e3aca57e3', 'radical', '龍', 'imperial', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Berdirilah di bulan sehingga Anda dapat memandang rendah negara Anda. Segala garis dan perbatasannya adalah perbatasan semua negara yang Anda kuasai, karena Anda adalah seorang kekaisaran.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a8e3a869-5793-475f-9d8b-a45e3aca57e3', 'Kekaisaran', true) ON CONFLICT DO NOTHING;
