INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91d4e453-8908-49dc-8115-2cb4399a3482', 'vocabulary', '偽', '偽', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
