INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91d4e453-8908-49dc-8115-2cb4399a3482', 'どうして俺が偽札を偽札じゃないということが皆の為になるのさ？', 'Apa manfaatnya memberi tahu semua orang bahwa dokumen palsu ini bukan dokumen palsu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8ae8e1e-82aa-4f78-8226-e9b52f651b4d', 'vocabulary', '偽る', '偽る', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya palsu dan versi vocab verbanya mirip, artinya berbohong atau menipu atau menipu.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya palsu dan versi vocab verbanya mirip, artinya berbohong atau menipu atau menipu.') ON CONFLICT (id) DO NOTHING;
