INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0957b240-52f2-449d-b958-9c5eb4390e72', '伯父は、自社製品の表示を偽装して逮捕され、現在は刑務所にいます。', 'Paman saya ditangkap karena menyamarkan produknya dengan label palsu dan saat ini berada di penjara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c4bc8523-963d-4512-b44a-35283c2d78f5', 'vocabulary', '偽造', '偽造', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ayo buat yang palsu. Ini palsu yang kami buat? Itu palsu.', 'Ayo buat yang palsu. Ini palsu yang kami buat? Itu palsu.') ON CONFLICT (id) DO NOTHING;
