INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('383d66ec-ada5-4577-a054-34ee89e2d880', 'vocabulary', '克明', '克明', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Jika Anda diliputi kecerahan, Anda akan dapat melihat semua detail kecil yang bagus.', 'Jika Anda diliputi kecerahan, Anda akan dapat melihat semua detail kecil yang bagus.') ON CONFLICT (id) DO NOTHING;
