INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5a26d5d6-08c1-4c6f-bd34-ea3488617c4f', 'vocabulary', '哲学', '哲学', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ilmu filsafat adalah ilmu yang mempelajari filsafat.', 'Ilmu filsafat adalah ilmu yang mempelajari filsafat.') ON CONFLICT (id) DO NOTHING;
