INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('841fb45b-2ac8-4df4-978d-8829d7d3b9e4', 'この予想は、かなり堅いと思うよ。', 'Menurut saya prediksi ini cukup solid.') ON CONFLICT DO NOTHING;
