INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('14c0b59b-acd5-417b-a856-c06cfa86c4c8', 'vocabulary', '中軸', '中軸', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Tentu saja, bagian tengah sumbu adalah tempat sumbunya berada, tetapi juga tempat porosnya berada.', 'Tentu saja, bagian tengah sumbu adalah tempat sumbunya berada, tetapi juga tempat porosnya berada.') ON CONFLICT (id) DO NOTHING;
