INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4be32955-5848-492d-9483-58b24538e4b8', 'vocabulary', '国柄', '国柄', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Pola negara adalah pola yang dilakukan suatu negara. Inilah karakter nasional suatu bangsa.', 'Pola negara adalah pola yang dilakukan suatu negara. Inilah karakter nasional suatu bangsa.') ON CONFLICT (id) DO NOTHING;
