INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a36ce491-3813-4588-9217-3dcf775cb8d1', '本の内容を表紙で判断するみたいに、人の人柄を見た目で決めつけないでよ。', 'Jangan menilai kepribadian seseorang dari penampilannya seperti Anda menilai buku dari sampulnya.') ON CONFLICT DO NOTHING;
