INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('640ec299-9965-4e38-b671-8d86d22922f0', 'vocabulary', '円滑', '円滑', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Sesuatu yang bulat dan licin dapat bergerak begitu saja tanpa kesulitan sama sekali. Sangat mudah dalam cara meluncurnya. Ini juga sangat halus.', 'Sesuatu yang bulat dan licin dapat bergerak begitu saja tanpa kesulitan sama sekali. Sangat mudah dalam cara meluncurnya. Ini juga sangat halus.') ON CONFLICT (id) DO NOTHING;
