INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7c917860-3c89-4748-9e43-36eda4378753', 'vocabulary', '潟', '潟', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
