INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8e8352a6-d3d8-476c-bbaa-3808e3b2e68f', '交際一ヶ月記念の日に、干潟に潮干狩りに行ってきたの。', 'Kami pergi ke flat pasang surut untuk merayakan satu bulan peringatan persahabatan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a11cdda2-cb21-48a6-8d10-7133b6c86117', 'vocabulary', '焦点', '焦点', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Titik char adalah bagian yang Anda lihat dengan sangat keras hingga membuat lubang kecil di dalamnya. Bayangkan saja diri Anda melihat satu titik dengan sangat tajam hingga mulai membara. Inilah titik fokus atau fokusnya.', 'Titik char adalah bagian yang Anda lihat dengan sangat keras hingga membuat lubang kecil di dalamnya. Bayangkan saja diri Anda melihat satu titik dengan sangat tajam hingga mulai membara. Inilah titik fokus atau fokusnya.') ON CONFLICT (id) DO NOTHING;
