INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6caf24d1-e64d-4fdf-8aed-01c155802a8c', '一定にかき混ぜることで、鍋の底が焦げることが防げるとお母さんが言っていたわ。', 'Ibuku memberitahuku bahwa mengaduk terus-menerus akan membuat dasar wajan tidak gosong.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7817ee73-b925-447e-8b45-6bf21f6a4d7e', 'vocabulary', '範囲', '範囲', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Mari kita lihat contoh ini dan kelilinginya. Contoh ini menunjukkan jangkauan atau ruang lingkup dari apa yang kita lakukan, dan garis yang mengelilinginya menunjukkan sejauh mana cakupan tersebut berjalan.', 'Mari kita lihat contoh ini dan kelilinginya. Contoh ini menunjukkan jangkauan atau ruang lingkup dari apa yang kita lakukan, dan garis yang mengelilinginya menunjukkan sejauh mana cakupan tersebut berjalan.') ON CONFLICT (id) DO NOTHING;
