INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc7b3924-3b87-4d23-b6c0-ef1dd5f0be1e', '不快な気分を紛らすために、裁縫針で耳にピアスの穴を開けました。', 'Saya menusuk telinga saya dengan jarum jahit untuk mengalihkan perhatian saya dari perasaan tidak menyenangkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd8eed94-1b1a-4afd-a279-847ba7179a62', 'vocabulary', '紛糾', '紛糾', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Alihkan perhatianku dengan perubahan pada apa yang kita lakukan. Bayangkan saja Anda sedang mengerjakan sesuatu. Kemudian, perhatian Anda terganggu oleh perubahan pada apa pun yang sedang Anda kerjakan. Perubahan kecil ini tidak menghancurkan segalanya, tetapi menyebabkan komplikasi dan kebingungan.', 'Alihkan perhatianku dengan perubahan pada apa yang kita lakukan. Bayangkan saja Anda sedang mengerjakan sesuatu. Kemudian, perhatian Anda terganggu oleh perubahan pada apa pun yang sedang Anda kerjakan. Perubahan kecil ini tidak menghancurkan segalanya, tetapi menyebabkan komplikasi dan kebingungan.') ON CONFLICT (id) DO NOTHING;
