INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd8eed94-1b1a-4afd-a279-847ba7179a62', 'この問題をこれ以上紛糾させたくないんです。', 'Saya tidak ingin memperumit masalah ini lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4376d4e9-0d3d-47e5-90b8-b34977c876e9', 'vocabulary', '糾弾', '糾弾', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Aku akan memutarbalikkan peluru ini dan membalikkannya padamu. Kaulah yang akan aku salahkan, itulah sebabnya peluru kesalahanku diarahkan kembali padamu.', 'Aku akan memutarbalikkan peluru ini dan membalikkannya padamu. Kaulah yang akan aku salahkan, itulah sebabnya peluru kesalahanku diarahkan kembali padamu.') ON CONFLICT (id) DO NOTHING;
