INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d73e914-abd4-4e56-967c-2c449d82753b', 'vocabulary', '綱', '綱', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Kanjinya adalah kabel tetapi kata ini lebih mengacu pada tali, yang sangat mirip. Ini juga bisa berarti sabuk juara sumo, meskipun Anda mungkin akan melihat maknanya jauh lebih sedikit, kecuali Anda adalah penggemar berat sumo.', 'Kanjinya adalah kabel tetapi kata ini lebih mengacu pada tali, yang sangat mirip. Ini juga bisa berarti sabuk juara sumo, meskipun Anda mungkin akan melihat maknanya jauh lebih sedikit, kecuali Anda adalah penggemar berat sumo.') ON CONFLICT (id) DO NOTHING;
