INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eaa71501-a94c-4f76-b327-fc67959070b1', '僕の伯父さんは、今まで蜂に刺されたことがなくて、どんなものか試してみたかったから、蜂の巣がある木を揺すったんだそうです。', 'Tampaknya paman saya mengguncang pohon yang ada sarang lebahnya karena dia belum pernah disengat lebah dan ingin mencobanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d3aca4b3-a2cc-42c0-b9e0-182ca1844dd0', 'vocabulary', '揺れる', '揺れる', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ingat 揺る yang artinya "mengguncang" atau "tersentak"? Begitulah, tetapi sekarang Anda tidak lagi melakukan guncangan dan guncangan sehingga membuatnya tergoncang atau terguncang. Kamu tahu ini karena sangat jarang (れる) kamu terguncang seperti ini.', 'Ingat 揺る yang artinya "mengguncang" atau "tersentak"? Begitulah, tetapi sekarang Anda tidak lagi melakukan guncangan dan guncangan sehingga membuatnya tergoncang atau terguncang. Kamu tahu ini karena sangat jarang (れる) kamu terguncang seperti ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d3aca4b3-a2cc-42c0-b9e0-182ca1844dd0', 'Terguncang', true) ON CONFLICT DO NOTHING;
