INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d3aca4b3-a2cc-42c0-b9e0-182ca1844dd0', 'ゆれる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d3aca4b3-a2cc-42c0-b9e0-182ca1844dd0', '公園のブランコが風で揺れた。', 'Ayunan di taman bergoyang tertiup angin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ddcb6548-7298-4703-9a27-a2e03e20cb15', 'vocabulary', '滑り台', '滑り台', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ingat bagaimana 滑る adalah "meluncur"? Lalu, bagaimana cara counter untuk mesin? Dalam hal ini, mesin licin tersebut adalah perosotan, lebih khusus lagi perosotan taman bermain.', 'Ingat bagaimana 滑る adalah "meluncur"? Lalu, bagaimana cara counter untuk mesin? Dalam hal ini, mesin licin tersebut adalah perosotan, lebih khusus lagi perosotan taman bermain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ddcb6548-7298-4703-9a27-a2e03e20cb15', 'Perosotan Taman Bermain', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ddcb6548-7298-4703-9a27-a2e03e20cb15', 'Slide', false) ON CONFLICT DO NOTHING;
