INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('532aaddc-48b3-4ff8-9671-6ad97668aa19', 'あせる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('532aaddc-48b3-4ff8-9671-6ad97668aa19', '焦るなよ。小便に行きたい以外は、急ぐ必要はないよ。一日一日を着実にな。', 'Tidak usah buru-buru. Selain ingin buang air kecil, tidak perlu terburu-buru. Suatu hari pada suatu waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4f1020ca-181e-4174-a426-a8366f7ec23d', 'vocabulary', '焦がす', '焦がす', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Anda tahu bahwa 焦げる berarti "dibakar" atau "dibakar". Namun kata ini adalah ketika Anda melakukan pembakaran, membuatnya terbakar atau hangus. Anda mengetahui hal ini karena dalam hal pembakaran, Anda berusaha sekuat tenaga. Anda menggunakan banyak gas (がす) untuk membakar apa pun yang Anda bakar.', 'Anda tahu bahwa 焦げる berarti "dibakar" atau "dibakar". Namun kata ini adalah ketika Anda melakukan pembakaran, membuatnya terbakar atau hangus. Anda mengetahui hal ini karena dalam hal pembakaran, Anda berusaha sekuat tenaga. Anda menggunakan banyak gas (がす) untuk membakar apa pun yang Anda bakar.') ON CONFLICT (id) DO NOTHING;
