INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4f1020ca-181e-4174-a426-a8366f7ec23d', 'いつもトーストを真っ黒に焦がしてしまう。', 'Saya selalu membakar roti panggang saya hingga benar-benar hitam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('14a0619f-9ce1-4f92-9723-c9fa353a29a2', 'vocabulary', '紛れる', '紛れる', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Anda tahu bahwa 紛らす berarti "mengalihkan" atau "mengalihkan perhatian". Ini adalah saat Anda tidak melakukan tindakan, sekarang, membuat kata ini teralihkan atau teralihkan.', 'Anda tahu bahwa 紛らす berarti "mengalihkan" atau "mengalihkan perhatian". Ini adalah saat Anda tidak melakukan tindakan, sekarang, membuat kata ini teralihkan atau teralihkan.') ON CONFLICT (id) DO NOTHING;
