INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14a0619f-9ce1-4f92-9723-c9fa353a29a2', '解熱剤が他の薬に紛れちゃってて、どれがどれだか分かりません。', 'Obat demamnya dimasukkan bersama pil lain dan saya tidak yakin yang mana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('05e4ab85-9d7d-443a-a78c-48f808d5e405', 'vocabulary', '紛らわしい', '紛らわしい', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Kanjinya mengalihkan perhatian dan versi kata sifatnya membingungkan atau menyesatkan.', 'Kanjinya mengalihkan perhatian dan versi kata sifatnya membingungkan atau menyesatkan.') ON CONFLICT (id) DO NOTHING;
