INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05e4ab85-9d7d-443a-a78c-48f808d5e405', '結局それはバスケットボールだったんですが、とても紛らわしかったです。私は完全に妊婦さんの大きなお腹だと思っていました。', 'Bagaimanapun juga, itu adalah bola basket, tapi itu benar-benar menyesatkan. Saya pikir bentuknya persis seperti perut wanita hamil.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a62c6f44-b342-479f-9a64-8986077d6e15', 'vocabulary', '網戸', '網戸', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Pintu jaring adalah pintu kasa. Masuk akal, bukan? Pintu kasa seperti jaring kecil yang dibuat menjadi bentuk pintu.', 'Pintu jaring adalah pintu kasa. Masuk akal, bukan? Pintu kasa seperti jaring kecil yang dibuat menjadi bentuk pintu.') ON CONFLICT (id) DO NOTHING;
