INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a62c6f44-b342-479f-9a64-8986077d6e15', 'あの古い網戸は本当に気持ち悪いね。', 'Pintu kasa tua itu sangat menjijikkan!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fbdd68d5-9f94-4328-b9e8-62000859fe20', 'vocabulary', '引き裂く', '引き裂く', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Anda tahu bahwa 裂く berarti "merobek" atau "merobek". Jadi, jika Anda mencoba merobek atau merobek sesuatu, dan Anda menariknya pada saat yang sama, Anda akan merobek benda itu, atau lebih tepatnya mungkin merobek sesuatu, karena Anda sedang menarik.', 'Anda tahu bahwa 裂く berarti "merobek" atau "merobek". Jadi, jika Anda mencoba merobek atau merobek sesuatu, dan Anda menariknya pada saat yang sama, Anda akan merobek benda itu, atau lebih tepatnya mungkin merobek sesuatu, karena Anda sedang menarik.') ON CONFLICT (id) DO NOTHING;
