INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fbdd68d5-9f94-4328-b9e8-62000859fe20', 'あのカップルの仲をうまく引き裂く事ができたら、お知らせ致します。', 'Saya akan memberi tahu Anda jika saya berhasil memisahkan pasangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fba5ec83-f87b-4649-8cda-ae00346adda7', 'vocabulary', '核分裂', '核分裂', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', '分裂 berarti "pemisahan" atau "pembagian". Versi inti dari perpecahan ini adalah fisi nuklir.', '分裂 berarti "pemisahan" atau "pembagian". Versi inti dari perpecahan ini adalah fisi nuklir.') ON CONFLICT (id) DO NOTHING;
