INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fba5ec83-f87b-4649-8cda-ae00346adda7', '核分裂の過程について、分かりやすいスライドショーを作ってもらえますか。', 'Bisakah Anda membuat tayangan slide tentang proses fisi nuklir yang mudah dipahami?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e1b2be45-ccd2-4beb-9840-14f3a9117960', 'vocabulary', '襲撃する', '襲撃する', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ingat bagaimana 襲撃 merupakan penyerangan atau penyerangan? Ini bentuk kata kerjanya, jadi menyerang atau menyerang.', 'Ingat bagaimana 襲撃 merupakan penyerangan atau penyerangan? Ini bentuk kata kerjanya, jadi menyerang atau menyerang.') ON CONFLICT (id) DO NOTHING;
