INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1b2be45-ccd2-4beb-9840-14f3a9117960', '飛行機で巨人を襲撃することができるようになるとは、知る由もなかった。', 'Mereka tidak menyangka bahwa mereka bisa menyerang para Titan melalui udara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ad453aa-c407-403f-8edc-3e21698776f4', 'vocabulary', '手堅い', '手堅い', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Anda tahu bahwa 堅い itu "padat" atau "tangguh". Jika tangan Anda kokoh dan kuat, maka tangan Anda kokoh dan mantap. Jika tangan Anda gemetar, justru sebaliknya, atau semacamnya.', 'Anda tahu bahwa 堅い itu "padat" atau "tangguh". Jika tangan Anda kokoh dan kuat, maka tangan Anda kokoh dan mantap. Jika tangan Anda gemetar, justru sebaliknya, atau semacamnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0ad453aa-c407-403f-8edc-3e21698776f4', 'Padat', true) ON CONFLICT DO NOTHING;
