INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ad453aa-c407-403f-8edc-3e21698776f4', '中々手堅い仕事みたいだから、葬儀屋になるための勉強をしようかなって思ってるんだよね。', 'Saya berpikir untuk belajar bagaimana menjadi pengurus jenazah karena sepertinya pekerjaan ini cukup aman.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e079237c-bdff-4c6e-95e4-874db1afbae8', 'vocabulary', 'お握り', 'お握り', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', '握り adalah "pegangan". Saat Anda menambahkan お, nilainya sedikit meningkat. Entah kenapa menjadi bola nasi (alias onigiri). Untuk membuat bola nasi, gunakan genggaman Anda untuk membuatnya menjadi bentuk bola, mungkin dari situlah bola nasi tersebut berasal.', '握り adalah "pegangan". Saat Anda menambahkan お, nilainya sedikit meningkat. Entah kenapa menjadi bola nasi (alias onigiri). Untuk membuat bola nasi, gunakan genggaman Anda untuk membuatnya menjadi bentuk bola, mungkin dari situlah bola nasi tersebut berasal.') ON CONFLICT (id) DO NOTHING;
