INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e079237c-bdff-4c6e-95e4-874db1afbae8', '私は息子がコンビニのお握りを食べることを禁止しました。', 'Saya melarang anak saya makan nasi kepal yang ada di toko swalayan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27a47a63-0e85-46b0-94b9-d13f6ddc2e75', 'vocabulary', '揚げ出し', '揚げ出し', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ingat bagaimana 揚げる bisa berarti "menggoreng?" Sesuatu yang digoreng lalu ditaruh di depan Anda adalah digoreng.', 'Ingat bagaimana 揚げる bisa berarti "menggoreng?" Sesuatu yang digoreng lalu ditaruh di depan Anda adalah digoreng.') ON CONFLICT (id) DO NOTHING;
