INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('27a47a63-0e85-46b0-94b9-d13f6ddc2e75', 'あげだし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27a47a63-0e85-46b0-94b9-d13f6ddc2e75', 'これは出来たてホカホカの美味しい揚げ出し豆腐ですよ。', 'Ini sepiring tahu goreng enak yang baru saja saya buat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('abf4ff07-a2ce-4cdd-b1db-0de180731cd7', 'vocabulary', '焦り', '焦り', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Ingat 焦る, yang artinya "terburu-buru" atau "tidak sabar"? Ini adalah versi kata bendanya, yaitu ketidaksabaran.', 'Ingat 焦る, yang artinya "terburu-buru" atau "tidak sabar"? Ini adalah versi kata bendanya, yaitu ketidaksabaran.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('abf4ff07-a2ce-4cdd-b1db-0de180731cd7', 'Ketidaksabaran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('abf4ff07-a2ce-4cdd-b1db-0de180731cd7', 'あせり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('abf4ff07-a2ce-4cdd-b1db-0de180731cd7', '会議に行かなくちゃいけなかったのに、脚がやばいくらいつって全然動けなかったので、焦りを感じましたよ。', 'Saya mengalami kram yang parah di kaki saya dan saya tidak bisa menggerakkannya sama sekali meskipun saya harus pergi ke pertemuan, jadi saya merasa sangat tidak sabar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('37963f72-d6be-4cdc-b6d8-2377be041598', 'vocabulary', '紛れもない', '紛れもない', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', '紛らわしい berarti "membingungkan" atau "menyesatkan". Ini adalah sisi negatifnya (Anda dapat mengetahuinya dari ない), artinya kebalikan dari hal-hal tersebut. Kata ini pasti, tidak salah, dan jelas.', '紛らわしい berarti "membingungkan" atau "menyesatkan". Ini adalah sisi negatifnya (Anda dapat mengetahuinya dari ない), artinya kebalikan dari hal-hal tersebut. Kata ini pasti, tidak salah, dan jelas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('37963f72-d6be-4cdc-b6d8-2377be041598', 'Tentu', true) ON CONFLICT DO NOTHING;
