INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37963f72-d6be-4cdc-b6d8-2377be041598', '彼女は紛れもない田舎っぺの女の子だ。', 'Dia adalah gadis udik desa yang tidak salah lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b35bb7c4-b5a4-4c0c-b623-c335a0dc061d', 'vocabulary', '紛れ', '紛れ', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Saat perhatian Anda terganggu, semua yang Anda lakukan hanyalah sebuah kebetulan. Anda tidak fokus, jadi semuanya terjadi secara kebetulan.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b35bb7c4-b5a4-4c0c-b623-c335a0dc061d', 'Kebetulan', true) ON CONFLICT DO NOTHING;
