INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b35bb7c4-b5a4-4c0c-b623-c335a0dc061d', 'そのクイズの答えが当たったのはただの紛れです。', 'Kebetulan saja saya bisa menjawab pertanyaan-pertanyaan di kuis tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cea50528-1cc0-4025-825a-ed118e92ceda', 'vocabulary', '小柄', '小柄', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Seseorang yang dibangun dari pola kecil memiliki tubuh yang kecil. Saya kenal banyak wanita tua kecil yang dibangun dari pola-pola kecil ini.', 'Seseorang yang dibangun dari pola kecil memiliki tubuh yang kecil. Saya kenal banyak wanita tua kecil yang dibangun dari pola-pola kecil ini.') ON CONFLICT (id) DO NOTHING;
