INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cea50528-1cc0-4025-825a-ed118e92ceda', 'その店では、一人の小柄なおばあさんが買い物をしていた。', 'Wanita tua pendek itu berbelanja sendirian di toko.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1f948565-9c6d-49bb-bb26-238188a6d56a', 'vocabulary', '揺らぐ', '揺らぐ', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Hei lihat! Jika Anda belum muak dengan kata-kata tersebut, itu adalah kata kerja lain yang disertai dengan goyang! Yang ini artinya gemetar juga!', 'Hei lihat! Jika Anda belum muak dengan kata-kata tersebut, itu adalah kata kerja lain yang disertai dengan goyang! Yang ini artinya gemetar juga!') ON CONFLICT (id) DO NOTHING;
