INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f948565-9c6d-49bb-bb26-238188a6d56a', 'それっぽっちのことで、気持ちが揺らぐんだ。', 'Hanya sedikit hal yang mempengaruhi perasaanku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a52b1e73-521c-48b0-914d-ad439b7fb09b', 'vocabulary', '焦燥', '焦燥', 1, 'f269728c-8024-47e1-a67d-7a38cd7c8607', 'Jika ingin mengarang ikan untuk makan malam, ikan itu akan mengering karena ketidaksabaran Anda sendiri. Menghanguskan ikan membutuhkan waktu dan jika Anda terlalu gelisah dan memasukkannya terlalu jauh ke dalam api, ikan akan mengering, gosong, dan menjadi kotor.', 'Jika ingin mengarang ikan untuk makan malam, ikan itu akan mengering karena ketidaksabaran Anda sendiri. Menghanguskan ikan membutuhkan waktu dan jika Anda terlalu gelisah dan memasukkannya terlalu jauh ke dalam api, ikan akan mengering, gosong, dan menjadi kotor.') ON CONFLICT (id) DO NOTHING;
