INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32c628f1-2139-4e69-b14d-91ca210c018c', '最近は毎朝、裂けるチーズを食べています。', 'Akhir-akhir ini saya makan keju yang bisa dibelah (keju tali AKA) setiap pagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32c628f1-2139-4e69-b14d-91ca210c018c', 'ねえ、ケンイチ君。ジーンズの股が裂けてるよ。', 'Hei, Kenichi. Celana jinsmu robek di bagian selangkangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32c628f1-2139-4e69-b14d-91ca210c018c', '悲しすぎて、心が裂けちゃいそうだよ。', 'Aku sangat sedih hingga hatiku terasa seperti akan meledak.') ON CONFLICT DO NOTHING;
