INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a01fdb26-b023-4d1f-944c-dddf916c53ec', '野球のシーズンが到来する春に近づくにつれて、あの投手の球威は益々増しています。', 'Saat musim bisbol semakin dekat di musim semi, pelempar itu menjadi lebih baik dalam lemparannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9dfede33-1c8d-4e52-95f1-24a8d2200353', 'vocabulary', '威厳', '威厳', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Yang Mulia sangat ketat. Jika Anda tidak memiliki martabat dan keagungan, Anda tidak akan menjadi terlalu agung.', 'Yang Mulia sangat ketat. Jika Anda tidak memiliki martabat dan keagungan, Anda tidak akan menjadi terlalu agung.') ON CONFLICT (id) DO NOTHING;
