INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('638cb2fd-f4bb-4646-bd88-982c6ec484c6', 'vocabulary', '慰謝', '慰謝', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Saya menunjukkan penghiburan saya dengan meminta maaf. Ini adalah penghiburan.', 'Saya menunjukkan penghiburan saya dengan meminta maaf. Ini adalah penghiburan.') ON CONFLICT (id) DO NOTHING;
