INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00f24ef3-c0ac-4051-8485-9d711d068764', 'vocabulary', '懇意', '懇意', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Gagasan untuk bersikap sopan membuat Anda memiliki lebih banyak perasaan keintiman dan kebaikan terhadap orang lain. Semakin sopan seseorang terhadap Anda (dan sebaliknya), semakin besar pula kedekatan Anda berdua.', 'Gagasan untuk bersikap sopan membuat Anda memiliki lebih banyak perasaan keintiman dan kebaikan terhadap orang lain. Semakin sopan seseorang terhadap Anda (dan sebaliknya), semakin besar pula kedekatan Anda berdua.') ON CONFLICT (id) DO NOTHING;
