INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3e36fe96-f42c-4f0a-b2b7-6e020013d6cf', 'vocabulary', '懇話', '懇話', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Pembicaraan yang sopan adalah pembicaraan yang bersahabat. Kita semua tahu bahwa "obrolan ramah" tidak pernah seperti yang terlihat... bukan?', 'Pembicaraan yang sopan adalah pembicaraan yang bersahabat. Kita semua tahu bahwa "obrolan ramah" tidak pernah seperti yang terlihat... bukan?') ON CONFLICT (id) DO NOTHING;
