INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('76fe2aff-f32b-469b-b442-0d63300f2696', 'vocabulary', '懇談', '懇談', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Diskusi yang sopan sedikit lebih formal daripada pembicaraan ramah (karena ini adalah diskusi), namun skala diskusinya masih cukup informal, sehingga menjadikannya pembicaraan informal.', 'Diskusi yang sopan sedikit lebih formal daripada pembicaraan ramah (karena ini adalah diskusi), namun skala diskusinya masih cukup informal, sehingga menjadikannya pembicaraan informal.') ON CONFLICT (id) DO NOTHING;
