INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('76fe2aff-f32b-469b-b442-0d63300f2696', '授業参観日の先生との懇談の間、彼女はずっとハンカチを握りしめてていました。', 'Dia memegang erat saputangannya sepanjang pembicaraan persahabatan dengan guru di hari orang tua.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('985db665-7d66-49d1-be91-611bc5a5b3ce', 'vocabulary', '懲りる', '懲りる', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Kanji berarti menghukum tetapi versi kosakata kata kerjanya adalah belajar melalui pengalaman. Saya rasa ini serupa. Ketika Anda melakukan kesalahan, seseorang akan menghukum Anda, dan kemudian Anda akan belajar melalui pengalaman (baik melalui pengalaman atau melalui teguran).', 'Kanji berarti menghukum tetapi versi kosakata kata kerjanya adalah belajar melalui pengalaman. Saya rasa ini serupa. Ketika Anda melakukan kesalahan, seseorang akan menghukum Anda, dan kemudian Anda akan belajar melalui pengalaman (baik melalui pengalaman atau melalui teguran).') ON CONFLICT (id) DO NOTHING;
