INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('84ef3a50-db45-41ce-b157-6dcb4b337dff', 'vocabulary', '懲罰', '懲罰', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Aku akan menghukummu dan memberimu hukuman. Saya melakukan ini sebagai suatu disiplin. Sebuah hukuman.', 'Aku akan menghukummu dan memberimu hukuman. Saya melakukan ini sebagai suatu disiplin. Sebuah hukuman.') ON CONFLICT (id) DO NOTHING;
