INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1f2aeda5-8817-4a50-8f4a-acbc06a1c256', 'vocabulary', '旨', '旨', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Inti dari sesuatu adalah inti dan prinsipnya. Jadi, apa inti dari kata vocab ini? Itu intinya juga.', 'Inti dari sesuatu adalah inti dan prinsipnya. Jadi, apa inti dari kata vocab ini? Itu intinya juga.') ON CONFLICT (id) DO NOTHING;
