INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27a374cc-fe91-4aa3-9844-cc9338b8ae08', 'vocabulary', '恐竜', '恐竜', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Naga ketakutan adalah dinosaurus. Dinosaurus jauh lebih menakutkan daripada naga, dan itulah mengapa dinosaurus disebut naga ketakutan dalam bahasa Jepang.', 'Naga ketakutan adalah dinosaurus. Dinosaurus jauh lebih menakutkan daripada naga, dan itulah mengapa dinosaurus disebut naga ketakutan dalam bahasa Jepang.') ON CONFLICT (id) DO NOTHING;
