INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ef97239-5e55-4f9d-9294-5f076a3ee10c', 'vocabulary', '縁談', '縁談', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Mari kita mengambil sisi positifnya dan mendiskusikannya. Tepian itu adalah tepian pernikahan. Tapi, ketika Anda mencapai tepi itu, sebelum Anda melompatinya, Anda harus melakukan lamaran pernikahan.', 'Mari kita mengambil sisi positifnya dan mendiskusikannya. Tepian itu adalah tepian pernikahan. Tapi, ketika Anda mencapai tepi itu, sebelum Anda melompatinya, Anda harus melakukan lamaran pernikahan.') ON CONFLICT (id) DO NOTHING;
