INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('be2af14a-ed45-4e9b-b48e-10deb7574aec', 'vocabulary', '翼', '翼', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
