INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eedaab50-3b68-464d-a520-60731ab9e26f', '父さん、どうして僕たちはアイツらの侮辱を忍ばなきゃならないの？', 'Mengapa kita harus menanggung hinaan mereka, Ayah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ee41724-e0b2-49be-8b8e-7c9daeca2390', 'vocabulary', '忍者', '忍者', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Seseorang yang bertahan adalah seseorang yang mampu bertahan. Siapa yang menanggung segalanya lebih baik dari siapa pun? Seorang ninja.', 'Seseorang yang bertahan adalah seseorang yang mampu bertahan. Siapa yang menanggung segalanya lebih baik dari siapa pun? Seorang ninja.') ON CONFLICT (id) DO NOTHING;
