INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('385ca9f6-4f02-4ff4-bf41-2509ffc9af41', '刃物をちらつかせながら、男は低い声で私に「こっちへ来い」と言いました。', 'Sambil mengacungkan pisaunya, dia berkata kepadaku dengan suara rendah, “Kemarilah.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8fc63778-9b9f-4442-abf6-1dd034a0de3b', 'vocabulary', '刃先', '刃先', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Bagian depan bilahnya adalah bagian terjauh dari bilahnya dari Anda (karena bilahnya berada di depan Anda). Ini adalah tepi mata pisau atau tepi mata pisau.', 'Bagian depan bilahnya adalah bagian terjauh dari bilahnya dari Anda (karena bilahnya berada di depan Anda). Ini adalah tepi mata pisau atau tepi mata pisau.') ON CONFLICT (id) DO NOTHING;
