INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('52fb87ea-5690-404a-955a-d8a41f0406e2', '日本では、遠距離通学や遠距離通勤はよくあることです。', 'Di Jepang, perjalanan jarak jauh ke sekolah atau tempat kerja adalah hal yang lumrah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9cc9a7c5-ec28-4865-ba87-5f721ea638d2', 'vocabulary', '近距離', '近距離', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', '距離 adalah jarak dan 近 adalah dekat. Jarak dekat adalah jarak yang pendek.', '距離 adalah jarak dan 近 adalah dekat. Jarak dekat adalah jarak yang pendek.') ON CONFLICT (id) DO NOTHING;
