INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9cc9a7c5-ec28-4865-ba87-5f721ea638d2', 'タクシーの運ちゃんは大体みんな近距離乗車は嫌がるよね。', 'Pengemudi taksi pada umumnya tidak menyukai perjalanan jarak dekat, bukan?') ON CONFLICT DO NOTHING;
