INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc443542-8c33-42e0-ad64-6d35c3cb3558', 'ほんの数年後、彼女はようやく自分がその短距離走で優勝した短距離走者だったことを認めました。', 'Hanya beberapa tahun kemudian dia akhirnya mengakui bahwa dialah pelari cepat yang memenangkan perlombaan jarak pendek.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c1c0039b-e6ea-4fe0-9b4c-dc19cb26bb21', 'vocabulary', '一斉に', '一斉に', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', '一斉 bersifat simultan atau sekaligus. Tambahkan に di sana dan Anda menuju ke hal itu. Sebab “simultan” itu menjadi serentak. Untuk "sekaligus" itu tetap sekaligus.', '一斉 bersifat simultan atau sekaligus. Tambahkan に di sana dan Anda menuju ke hal itu. Sebab “simultan” itu menjadi serentak. Untuk "sekaligus" itu tetap sekaligus.') ON CONFLICT (id) DO NOTHING;
