INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1c0039b-e6ea-4fe0-9b4c-dc19cb26bb21', '派遣社員たちは、景気の悪化で一斉に解雇されることを心配しています。', 'Para pekerja sementara khawatir akan dipecat secara bersamaan dalam resesi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('84602d72-ef7d-4916-8aa8-95a3ac1821d5', 'vocabulary', '滅びる', '滅びる', 1, '5c50fbc8-bf60-4777-a407-b58a6b9f9ea8', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghancurkan jadi versi vocab verbanya adalah menghancurkan. Anda tahu Anda tidak menghancurkan sesuatu karena birnya (びる). Anda tidak akan pernah menghancurkan bir... tapi orang lain mungkin. Grr.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghancurkan jadi versi vocab verbanya adalah menghancurkan. Anda tahu Anda tidak menghancurkan sesuatu karena birnya (びる). Anda tidak akan pernah menghancurkan bir... tapi orang lain mungkin. Grr.') ON CONFLICT (id) DO NOTHING;
