INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('19cd945b-1504-430f-ac7d-89ce4708ddec', 'vocabulary', '山岳', '山岳', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Puncak gunung hanyalah pegunungan. Hanya karena Anda hanya dapat melihat puncaknya bukan berarti bagian gunung lainnya tidak ada.', 'Puncak gunung hanyalah pegunungan. Hanya karena Anda hanya dapat melihat puncaknya bukan berarti bagian gunung lainnya tidak ada.') ON CONFLICT (id) DO NOTHING;
