INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19cd945b-1504-430f-ac7d-89ce4708ddec', 'この山岳地帯では、少なくともあと三ヶ月は冬の季節が続くだろうね。', 'Musim dingin akan berlanjut setidaknya selama tiga bulan lagi di distrik pegunungan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a9e0949-5dd0-46a4-831e-91ec87456c5d', 'vocabulary', '岳', '岳', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Puncak gunung adalah puncak atau gunung.', 'Puncak gunung adalah puncak atau gunung.') ON CONFLICT (id) DO NOTHING;
