INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b113ce76-816d-4ea1-a878-08848ae611a1', '夜になると脚がムズムズして、よく眠れないんです。', 'Kaki saya gelisah di malam hari dan saya tidak bisa tidur nyenyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('74ff66e7-43fa-491f-8b48-49e29d4bd79a', 'vocabulary', '脚本', '脚本', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Buku kaki hanyalah kaki dari sebuah buku. Bukan keseluruhan buku. Ini hanya berisi bagian-bagian yang berjalan dan bergerak, tidak begitu banyak deskripsinya (benda yang tidak bergerak). Buku semacam ini adalah naskah atau skenario. "Buku-buku" ini berfokus pada tindakan dan perkataan orang, itulah mengapa ini hanyalah kaki.', 'Buku kaki hanyalah kaki dari sebuah buku. Bukan keseluruhan buku. Ini hanya berisi bagian-bagian yang berjalan dan bergerak, tidak begitu banyak deskripsinya (benda yang tidak bergerak). Buku semacam ini adalah naskah atau skenario. "Buku-buku" ini berfokus pada tindakan dan perkataan orang, itulah mengapa ini hanyalah kaki.') ON CONFLICT (id) DO NOTHING;
