INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ceff20e3-7854-4df5-93f7-4df383f963d1', '日本で初恋の人にバッタリ出くわした時は、可也驚きました。', 'Aku cukup terkejut saat bertemu cinta pertamaku di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9055d9f-dcdc-4829-b398-1c24e5370968', 'vocabulary', '井戸', '井戸', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Pintu sumur hanyalah sebuah sumur. Pintu itulah yang masuk ke dalam lubang sumur sehingga menjadi sumur.', 'Pintu sumur hanyalah sebuah sumur. Pintu itulah yang masuk ke dalam lubang sumur sehingga menjadi sumur.') ON CONFLICT (id) DO NOTHING;
