INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45b87c4c-1fab-4102-ac9b-9612de999972', 'vocabulary', '旧暦', '旧暦', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Kalender sebelumnya adalah kalender sebelumnya. Ini adalah kalender lunisolar dan kalender tradisional Jepang. Tentu saja bukan kalender saat ini.', 'Kalender sebelumnya adalah kalender sebelumnya. Ini adalah kalender lunisolar dan kalender tradisional Jepang. Tentu saja bukan kalender saat ini.') ON CONFLICT (id) DO NOTHING;
