INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45b87c4c-1fab-4102-ac9b-9612de999972', '旧暦の正月といえばいつになりますかね。', 'Kapan Tahun Baru kalender lunar?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cd706591-60e9-4485-a0e4-674770d78912', 'vocabulary', '西暦', '西暦', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Kalender Barat menunjukkan sejarah dan periode waktu "Barat". Bagi orang Jepang dan Cina, zaman ini dikenal dengan sebutan Era Kristen. Dulu juga digunakan sebagai cara untuk merujuk pada Kalender Barat, meskipun saat ini kita biasanya hanya mengucapkan カレンダー.', 'Kalender Barat menunjukkan sejarah dan periode waktu "Barat". Bagi orang Jepang dan Cina, zaman ini dikenal dengan sebutan Era Kristen. Dulu juga digunakan sebagai cara untuk merujuk pada Kalender Barat, meskipun saat ini kita biasanya hanya mengucapkan カレンダー.') ON CONFLICT (id) DO NOTHING;
