INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd706591-60e9-4485-a0e4-674770d78912', '昭和は西暦何年に終わったんですか？', 'Tahun berapa dalam kalender Barat era Showa berakhir?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('363903ad-d60c-49a7-8be8-1bb0fec7475f', 'vocabulary', '眺める', '眺める', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menatap dan versi kosakata kata kerjanya adalah menatap (atau melihat dengan cara yang sangat menatap).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menatap dan versi kosakata kata kerjanya adalah menatap (atau melihat dengan cara yang sangat menatap).') ON CONFLICT (id) DO NOTHING;
