INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4b10d4e9-f3d9-48d8-876d-5a8f329cdf7e', 'vocabulary', '義塾', '義塾', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Sekolah yang menjejalkan kebenaran, karena alasan tertentu, adalah sekolah swasta. Mungkin karena mereka menganggap sekolah negeri tidak ada gunanya, jadi mereka mengambil kebenaran mereka di tempat lain untuk memulai sekolah swasta? Saya tidak yakin.', 'Sekolah yang menjejalkan kebenaran, karena alasan tertentu, adalah sekolah swasta. Mungkin karena mereka menganggap sekolah negeri tidak ada gunanya, jadi mereka mengambil kebenaran mereka di tempat lain untuk memulai sekolah swasta? Saya tidak yakin.') ON CONFLICT (id) DO NOTHING;
