INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25813824-84cb-4085-808e-f57962d34298', 'vocabulary', '塾生', '塾生', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Ingat bagaimana 学生 adalah "siswa"? Ini memainkan peran itu. "Siswa" sekolah menjejalkan adalah siswa dari sekolah menjejalkan, siswa sekolah menjejalkan.', 'Ingat bagaimana 学生 adalah "siswa"? Ini memainkan peran itu. "Siswa" sekolah menjejalkan adalah siswa dari sekolah menjejalkan, siswa sekolah menjejalkan.') ON CONFLICT (id) DO NOTHING;
