INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3109e2ae-5ffa-4365-b29d-53e1317d7116', 'vocabulary', '裸足', '裸足', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Jika Anda bertelanjang kaki, berarti Anda tidak mengenakan apa pun di kaki Anda, sehingga membuat Anda bertelanjang kaki.', 'Jika Anda bertelanjang kaki, berarti Anda tidak mengenakan apa pun di kaki Anda, sehingga membuat Anda bertelanjang kaki.') ON CONFLICT (id) DO NOTHING;
