INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2ba02036-f436-4646-aea6-ce69bb9d1217', '落雷が直撃したのに、奇跡的に無傷だった。', 'Meskipun sambaran petir itu merupakan serangan langsung, secara ajaib saya tidak terluka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', 'vocabulary', '北斗七星', '北斗七星', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Apa yang dapat Anda lihat di utara yang tampak seperti sendok dan terdiri dari tujuh bintang? Itulah kelompok bintang yang kita sebut Biduk atau, tergantung di mana Anda berada, mungkin Bajak.', 'Apa yang dapat Anda lihat di utara yang tampak seperti sendok dan terdiri dari tujuh bintang? Itulah kelompok bintang yang kita sebut Biduk atau, tergantung di mana Anda berada, mungkin Bajak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', 'Biduk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', 'The Plough', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', 'ほくとしちせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', '北斗七星は七つの星で構成されています。', 'Biduk terdiri dari tujuh bintang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', '晴れた日には、窓から北斗七星が見えるよ。', 'Pada malam yang cerah, kita dapat melihat Biduk dari jendela kita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d57f63be-ba1a-4ac3-bfc3-673fd84eed96', 'この写真は、１１月３日未明の北斗七星です。', 'Foto ini adalah Biduk menjelang fajar pada tanggal 3 November.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', 'vocabulary', '一斗缶', '一斗缶', 1, '1f3651ce-236e-40bf-a84b-746f226ed0e4', 'Kaleng satu sendok adalah wadah delapan belas liter, yang juga merupakan wadah lima galon. Itu pasti satu sendok besar!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', 'Wadah Delapan Belas Liter', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', 'Five-Gallon Container', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', 'いっとかん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', '一斗缶は洗剤や石油などを保管するためのものです。', 'Wadah delapan belas liter digunakan untuk menyimpan barang-barang seperti deterjen dan minyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', 'その店では、一斗缶のキャンペーンを行っています。', 'Toko itu sedang mengadakan promosi untuk wadah lima galon.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82d19cf0-7c07-49f6-801e-6b6410e7a00c', 'この一斗缶をあそこのコーナーに積んでください。', 'Tolong susun wadah delapan belas liter ini di pojok sana.') ON CONFLICT DO NOTHING;
