INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d2d9604-e0c4-41a0-b5bd-fb998086d9db', 'vocabulary', '嫁ぐ', '嫁ぐ', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mempelai wanita dan versi vocab verbanya adalah menikah, karena Anda tidak bisa benar-benar "mengantin" seseorang.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mempelai wanita dan versi vocab verbanya adalah menikah, karena Anda tidak bisa benar-benar "mengantin" seseorang.') ON CONFLICT (id) DO NOTHING;
