INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cafb82e-aa77-4cf6-8653-740bcb278537', 'わぁ、A級の新しい魔法を習得中なの？上手くいけば、万歳ものだね！', 'Wow, apakah kamu mempelajari sihir peringkat A yang baru? Jika berjalan baik kita harus merayakannya!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7fd69d5d-2d54-4a6a-94db-ce5aac72f68e', 'vocabulary', '魔術', '魔術', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Seni iblis adalah ilmu hitam dan sihir. Hal-hal yang iblis lakukan.', 'Seni iblis adalah ilmu hitam dan sihir. Hal-hal yang iblis lakukan.') ON CONFLICT (id) DO NOTHING;
