INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fd69d5d-2d54-4a6a-94db-ce5aac72f68e', '「好き嫌いしないの！黒魔術だけじゃなくて白魔術もちゃんと勉強しなさい！」「はいはい。いつも同じこと言ってるよね。」「"はい"は一回でしょ！」', 'Jangan terlalu pilih-pilih! Kamu seharusnya tidak hanya mempelajari ilmu hitam, tetapi ilmu putih juga! "Ya, ya. Kamu selalu mengatakan itu." "Satu ya sudah cukup!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cfd2dc71-caef-4556-8610-074fe9dedab7', 'vocabulary', '魔女', '魔女', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Wanita iblis adalah penyihir. Dia menggunakan sihir, jadi dia pasti penyihir! Juga, apakah dia mengapung seperti kayu/batu yang sangat kecil?', 'Wanita iblis adalah penyihir. Dia menggunakan sihir, jadi dia pasti penyihir! Juga, apakah dia mengapung seperti kayu/batu yang sangat kecil?') ON CONFLICT (id) DO NOTHING;
