INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b06c1870-dca9-4ef8-9a9b-6d9c9b0c36e0', 'vocabulary', '寮生', '寮生', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Pelajar asrama (berasal dari 学生) adalah pelajar asrama atau penghuni asrama. Ini adalah siswa yang tinggal di asrama.', 'Pelajar asrama (berasal dari 学生) adalah pelajar asrama atau penghuni asrama. Ini adalah siswa yang tinggal di asrama.') ON CONFLICT (id) DO NOTHING;
