INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a82f98cc-22db-4f4f-8804-1ee59315dc2b', 'vocabulary', 'お盆', 'お盆', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', '盆 mengacu pada festival lentera atau nampan.お hanya membuat statusnya lebih tinggi. Namun maknanya tetap sama. Jadi, tergantung konteksnya, yang dimaksud adalah Festival Lampion alias festival obon dan obon, atau nampan.', '盆 mengacu pada festival lentera atau nampan.お hanya membuat statusnya lebih tinggi. Namun maknanya tetap sama. Jadi, tergantung konteksnya, yang dimaksud adalah Festival Lampion alias festival obon dan obon, atau nampan.') ON CONFLICT (id) DO NOTHING;
