INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4aa6face-d267-4c41-b5db-516a4adf018a', 'vocabulary', '丁寧', '丁寧', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Sebuah jalan, bukan bukan jalan. Itulah yang saya tawarkan kepada Anda untuk terus berjalan. Jauh lebih bagus seperti ini. Saya bersikap sopan dan sopan dengan menawarkan Anda jalan ini.', 'Sebuah jalan, bukan bukan jalan. Itulah yang saya tawarkan kepada Anda untuk terus berjalan. Jauh lebih bagus seperti ini. Saya bersikap sopan dan sopan dengan menawarkan Anda jalan ini.') ON CONFLICT (id) DO NOTHING;
