INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ffe3a53-b65e-4ab9-8f9e-3fab3fb96db7', '「今日、学校サボってゲーセン行こうぜ。人生は一度っきりだしな！」「そうかな。僕はよく幽霊を見るから、死後の世界を信じてるんだけど。」', '"Ayo bolos sekolah dan pergi ke arcade hari ini. YOLO!" "Kurasa tidak. Aku selalu melihat hantu, jadi aku percaya adanya dunia setelah kematian."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d87e7cf-b623-4846-8bc5-afd88e6b79fa', 'vocabulary', '口癖', '口癖', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Kebiasaan mulut adalah sesuatu yang sering Anda ucapkan dengan mulut. Itu sebuah kebiasaan. Itu adalah frasa atau slogan favorit Anda. Banyak orang mempunyai kebiasaan mengatakan hal-hal tertentu berulang-ulang, baik mereka menginginkannya atau tidak.', 'Kebiasaan mulut adalah sesuatu yang sering Anda ucapkan dengan mulut. Itu sebuah kebiasaan. Itu adalah frasa atau slogan favorit Anda. Banyak orang mempunyai kebiasaan mengatakan hal-hal tertentu berulang-ulang, baik mereka menginginkannya atau tidak.') ON CONFLICT (id) DO NOTHING;
