INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bef4c78a-f290-4bb7-8ada-900c7813641e', 'ある錬金術士が鉛を金に変えようとして失敗した日、外は雨がザザ降りでした。', 'Hujan turun deras di luar pada hari sang alkemis gagal mengubah timah menjadi emas.') ON CONFLICT DO NOTHING;
