INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0142d465-2227-469b-a11b-412896cb0956', 'vocabulary', '稲穂', '稲穂', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Kepala tanaman tanaman padi adalah kepala padi atau bulir padi.', 'Kepala tanaman tanaman padi adalah kepala padi atau bulir padi.') ON CONFLICT (id) DO NOTHING;
