INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('19b15ac1-f708-4255-968c-b6600cb71f4f', 'vocabulary', '帝', '帝', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Satu-satunya penguasa sejati adalah Kaisar Jepang alias Kaisar Jepang. Semua kaisar lainnya tidak hanya 帝 sendiri.', 'Satu-satunya penguasa sejati adalah Kaisar Jepang alias Kaisar Jepang. Semua kaisar lainnya tidak hanya 帝 sendiri.') ON CONFLICT (id) DO NOTHING;
