INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19b15ac1-f708-4255-968c-b6600cb71f4f', '人々は、帝がお出でになるということで、国旗を掲げました。', 'Orang-orang mengibarkan bendera nasional untuk kunjungan Kaisar Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81e03abb-c699-4195-b43b-b50da67689bd', 'vocabulary', '帝国', '帝国', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Negara yang berdaulat adalah negara yang merupakan bagian dari kerajaannya sendiri.', 'Negara yang berdaulat adalah negara yang merupakan bagian dari kerajaannya sendiri.') ON CONFLICT (id) DO NOTHING;
