INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81e03abb-c699-4195-b43b-b50da67689bd', 'トーフグ帝国では、殺人事件の時効は廃止されました。', 'Undang-undang pembatasan pembunuhan dihapuskan di Kekaisaran Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e5937abc-e4a7-45a9-afdc-88ebd4014cf5', 'vocabulary', '帝政', '帝政', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Pemerintahan berdaulat dan Politik adalah mereka yang merupakan bagian dari pemerintahan kekaisaran. Jenis pemerintahan ini adalah imperialisme. Tentu saja, pada masa itu, jumlah pemerintahan yang berdaulat tidak sebanyak itu, jadi imperialisme adalah solusi yang tepat dalam kasus ini.', 'Pemerintahan berdaulat dan Politik adalah mereka yang merupakan bagian dari pemerintahan kekaisaran. Jenis pemerintahan ini adalah imperialisme. Tentu saja, pada masa itu, jumlah pemerintahan yang berdaulat tidak sebanyak itu, jadi imperialisme adalah solusi yang tepat dalam kasus ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5937abc-e4a7-45a9-afdc-88ebd4014cf5', 'Pemerintahan Kekaisaran', true) ON CONFLICT DO NOTHING;
