INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5937abc-e4a7-45a9-afdc-88ebd4014cf5', 'ローマ帝政時代、皇帝はその村の人達に目をつけていました。', 'Pada masa Kekaisaran Romawi, kaisar mengawasi masyarakat desa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3b7b68fc-def2-43cd-a73d-a2d1c363d4fd', 'vocabulary', '稼ぎ', '稼ぎ', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', '稼ぐ adalah "untuk mendapatkan penghasilan." Ini adalah versi kata benda. Itu hanyalah penghasilan, hal-hal yang Anda peroleh.', '稼ぐ adalah "untuk mendapatkan penghasilan." Ini adalah versi kata benda. Itu hanyalah penghasilan, hal-hal yang Anda peroleh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3b7b68fc-def2-43cd-a73d-a2d1c363d4fd', 'Penghasilan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3b7b68fc-def2-43cd-a73d-a2d1c363d4fd', 'かせぎ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3b7b68fc-def2-43cd-a73d-a2d1c363d4fd', '稼ぎがそんなに多くないので、何によくお金を使っているか習慣を見直して節約するために家計簿をつけています。', 'Penghasilan kami tidak terlalu tinggi, jadi saya membuat buku rekening anggaran untuk melihat kebiasaan belanja kami guna menghemat uang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7822c288-59fb-4cc6-86e6-d965145ae04b', 'vocabulary', 'お陰で', 'お陰で', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', '陰 adalah bayangan, dan menambahkan お ke dalamnya akan membuatnya menjadi kehormatan. Itu menjadi bayangan seseorang yang sangat penting, dan berarti terima kasih, seperti dalam "berkat kamu, aku bisa lulus ujian." Ini awalnya berasal dari gagasan berada dalam bayang-bayang para dewa, yang melindungi dan membantu Anda!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7822c288-59fb-4cc6-86e6-d965145ae04b', 'Terima kasih kepada', true) ON CONFLICT DO NOTHING;
