INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af59410e-0523-4470-89e4-23c71ea00b82', '彼は陰では顧客のことを「カモ」と呼んでいる癖に、表ではペコペコ頭を下げておべっかを言っている。', 'Dia menyebut kliennya bodoh di belakang mereka, namun dia menggelengkan kepalanya dan mengatakan hal-hal yang menyanjung di depan wajah mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2886cdd2-44a7-4b1e-a8a0-39888bb18beb', 'vocabulary', '帝国主義', '帝国主義', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Kekaisaran (帝国)isme (主義) adalah saat Anda melakukan imperialisme. Hidup Kaisar!', 'Kekaisaran (帝国)isme (主義) adalah saat Anda melakukan imperialisme. Hidup Kaisar!') ON CONFLICT (id) DO NOTHING;
