INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2886cdd2-44a7-4b1e-a8a0-39888bb18beb', 'あなたの国は、帝国主義国家ですか？', 'Apakah negara Anda termasuk negara imperialis?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('16909182-8a8f-4734-aa7c-f6b1bb334f86', 'vocabulary', '魔法使い', '魔法使い', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Anda tahu bahwa 魔法 adalah "sihir" jadi bagaimana dengan seseorang yang menggunakan sihir? Apa sebutannya? Bagaimana dengan penyihir, pesulap, atau dukun?', 'Anda tahu bahwa 魔法 adalah "sihir" jadi bagaimana dengan seseorang yang menggunakan sihir? Apa sebutannya? Bagaimana dengan penyihir, pesulap, atau dukun?') ON CONFLICT (id) DO NOTHING;
