INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16909182-8a8f-4734-aa7c-f6b1bb334f86', '約束を守らないと、みんなから相手にされなくなるぞ。いいから、お前が先日会ったっていう、その魔法使いを連れてこいよ！', 'Jika kamu tidak menepati janjimu, orang lain tidak akan menganggapmu serius, jadi bawalah penyihir yang kamu bilang kamu temui kemarin!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7087348f-683a-4d24-80b3-30180ba7e7ff', 'vocabulary', '盆踊り', '盆踊り', 1, '98e62ebd-3bca-4b6f-a374-2810cbe8b9be', 'Tarian festival lampion adalah tarian festival bon (atau bon odori atau tarian festival lampion). Ini saat yang menyenangkan, pastikan untuk mengunjunginya kapan-kapan!', 'Tarian festival lampion adalah tarian festival bon (atau bon odori atau tarian festival lampion). Ini saat yang menyenangkan, pastikan untuk mengunjunginya kapan-kapan!') ON CONFLICT (id) DO NOTHING;
