INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b529149-64c3-4c87-a541-6e5e47702c8a', 'vocabulary', '瞬く', '瞬く', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti berkedip dan versi vocab verbanya adalah berkedip.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti berkedip dan versi vocab verbanya adalah berkedip.') ON CONFLICT (id) DO NOTHING;
