INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b529149-64c3-4c87-a541-6e5e47702c8a', '辺りの景色は瞬く間に雪に覆われ、真っ白になった。', 'Pemandangannya tertutup salju dalam sekejap dan semuanya menjadi putih.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dd443808-0e46-43d9-a948-08e845654435', 'vocabulary', '瞬間', '瞬間', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Interval waktu kedipan adalah jangka waktu yang sangat singkat. Itu sekejap atau sesaat.', 'Interval waktu kedipan adalah jangka waktu yang sangat singkat. Itu sekejap atau sesaat.') ON CONFLICT (id) DO NOTHING;
