INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dd443808-0e46-43d9-a948-08e845654435', '蜘蛛の巣にぶつかった瞬間に、人は突然空手の達人へと変身する。', 'Saat mereka masuk ke jaring laba-laba, orang-orang tiba-tiba berubah menjadi ahli karate.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('67a8fb1b-a594-4410-86a6-4ea0187527cf', 'vocabulary', '瞬時', '瞬時', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Sekejap waktu hanyalah sesaat atau sekejap saja.', 'Sekejap waktu hanyalah sesaat atau sekejap saja.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('67a8fb1b-a594-4410-86a6-4ea0187527cf', 'Momen', true) ON CONFLICT DO NOTHING;
