INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('67a8fb1b-a594-4410-86a6-4ea0187527cf', '言いたかったことを彼が瞬時にズバッと言ってくれたので、とても感心しました。', 'Saya sangat terkesan padanya ketika dia mengatakan bahwa saat ini saya akan mengatakannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('920a82d3-f099-439f-8c43-0caa8d7a4bbe', 'vocabulary', '白菊', '白菊', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Bunga krisan putih adalah bunga krisan berwarna putih.', 'Bunga krisan putih adalah bunga krisan berwarna putih.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('920a82d3-f099-439f-8c43-0caa8d7a4bbe', 'Krisan Putih', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('920a82d3-f099-439f-8c43-0caa8d7a4bbe', 'しらぎく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('920a82d3-f099-439f-8c43-0caa8d7a4bbe', '家の前に大量の白菊を並べるなんて、迷惑行為以上のことだよ。だって、白菊は日本では死者を弔う花だからね。言ってる意味が分かりますか？', 'Meletakkan seikat bunga krisan putih di depan rumah lebih dari sekadar merepotkan karena di Jepang digunakan untuk berkabung atas kematian. Apakah Anda mengerti apa yang saya katakan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d6ea2f9a-791f-4005-889f-a61ce1f420e0', 'vocabulary', '誇大', '誇大', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Kebanggaanmu terlalu besar. Faktanya, Anda membuatnya lebih besar dari yang sebenarnya. Anda melakukan ini dengan berlebihan dan hiperbola.', 'Kebanggaanmu terlalu besar. Faktanya, Anda membuatnya lebih besar dari yang sebenarnya. Anda melakukan ini dengan berlebihan dan hiperbola.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d6ea2f9a-791f-4005-889f-a61ce1f420e0', 'Berlebihan', true) ON CONFLICT DO NOTHING;
