INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d5943e0-195c-4900-a20d-017d0f42109f', 'vocabulary', '一瞬', '一瞬', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Satu kedipan adalah sekejap. Itu adalah sekejap atau sesaat.', 'Satu kedipan adalah sekejap. Itu adalah sekejap atau sesaat.') ON CONFLICT (id) DO NOTHING;
