INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e1d4d9b1-6d59-4552-b18c-2a390016442c', 'vocabulary', '庄園', '庄園', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Taman manor hanyalah sebuah manor. Tapi itulah yang dimaksud dengan istana. Ini adalah rumah besar yang memiliki taman/taman mengagumkan di sekitarnya.', 'Taman manor hanyalah sebuah manor. Tapi itulah yang dimaksud dengan istana. Ini adalah rumah besar yang memiliki taman/taman mengagumkan di sekitarnya.') ON CONFLICT (id) DO NOTHING;
