INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c6bfa1e9-9411-438e-b310-0287a99e2305', 'vocabulary', '担架', '担架', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Ia akan membawa atau memikul orang seperti rak. Benda yang dibawa orang ini adalah tandu atau tandu.', 'Ia akan membawa atau memikul orang seperti rak. Benda yang dibawa orang ini adalah tandu atau tandu.') ON CONFLICT (id) DO NOTHING;
