INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('954c43f9-95cf-4178-80f1-d1e8df83c824', 'vocabulary', '粘土', '粘土', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Tanah yang lengket adalah tanah liat. Coba pikirkan tentang merasakan tanah liatnya. Lengket apalagi kalau masih segar dan basah ya?', 'Tanah yang lengket adalah tanah liat. Coba pikirkan tentang merasakan tanah liatnya. Lengket apalagi kalau masih segar dan basah ya?') ON CONFLICT (id) DO NOTHING;
