INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d2556471-946b-4549-947b-72d1810e2ead', 'vocabulary', '粘着', '粘着', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Jika sesuatu yang lengket memakai benda lain di atasnya, maka ia akan saling menempel dan membentuk kohesi atau adhesi pada benda tersebut. Lagipula itu lengket.', 'Jika sesuatu yang lengket memakai benda lain di atasnya, maka ia akan saling menempel dan membentuk kohesi atau adhesi pada benda tersebut. Lagipula itu lengket.') ON CONFLICT (id) DO NOTHING;
