INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3d8a37db-2278-454c-9608-52b5d5eda609', 'vocabulary', '詐欺', '詐欺', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Jika ada kebohongan dan penipuan dalam interaksi Anda dengan orang lain, Anda melakukan penipuan, Anda melakukan penipuan, Anda menipu.', 'Jika ada kebohongan dan penipuan dalam interaksi Anda dengan orang lain, Anda melakukan penipuan, Anda melakukan penipuan, Anda menipu.') ON CONFLICT (id) DO NOTHING;
