INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d8a37db-2278-454c-9608-52b5d5eda609', '色々な詐欺の手口について知りたいなら、ジェニーに聞いたらいいよ。', 'Jika ingin mengetahui berbagai trik penipuan, sebaiknya tanyakan pada Jenny.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d8a37db-2278-454c-9608-52b5d5eda609', 'うちのお婆ちゃん、オレオレ詐欺にあって、百万円を騙し取られたんだ。', 'Nenek saya ditipu satu juta yen dalam penipuan palsu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d8a37db-2278-454c-9608-52b5d5eda609', '詐欺を働いて告訴された経験はおありですか。', 'Pernahkah Anda dituduh melakukan penipuan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('05cdb210-3cd8-442d-a94c-ee4502db1d70', 'vocabulary', '詐取', '詐取', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Anda menggunakan kebohongan Anda untuk mengambil apa yang Anda inginkan. Saat itulah Anda menipu atau menipu seseorang untuk mendapatkan barangnya. Beraninya kamu!', 'Anda menggunakan kebohongan Anda untuk mengambil apa yang Anda inginkan. Saat itulah Anda menipu atau menipu seseorang untuk mendapatkan barangnya. Beraninya kamu!') ON CONFLICT (id) DO NOTHING;
