INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('de83e657-b711-4f26-b3c8-9c03f0729cd2', 'vocabulary', '詐称', '詐称', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Jika Anda berbohong tentang gelar Anda, gelar yang mewakili siapa Anda, maka itu adalah representasi yang keliru. Pernyataan yang salah.', 'Jika Anda berbohong tentang gelar Anda, gelar yang mewakili siapa Anda, maka itu adalah representasi yang keliru. Pernyataan yang salah.') ON CONFLICT (id) DO NOTHING;
