INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('de83e657-b711-4f26-b3c8-9c03f0729cd2', '庭師は彼女が年齢を詐称していることにすぐに気がつきましたが、何も言いませんでした。', 'Tukang kebun segera menyadari bahwa usianya salah diartikan tetapi tidak mengatakan apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a651ea9-f524-4f5a-ba37-cac8c944db27', 'vocabulary', '霧', '霧', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
