INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25eddea7-4930-410a-87ad-584a79cc841d', 'ホームステイ先のお父さんが、今日の夕飯の際に黒い霧事件について説明をしてくれました。', 'Ayah saya yang tinggal di rumah menjelaskan Skandal Kabut Hitam kepada saya saat makan malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9bae21c1-d86c-445a-a090-94f9a66b26fd', 'vocabulary', '朝霧', '朝霧', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Kabut pagi adalah kabut pagi, karena merupakan kabut di pagi hari. Menurutku, ini jenis kabut terbaik.', 'Kabut pagi adalah kabut pagi, karena merupakan kabut di pagi hari. Menurutku, ini jenis kabut terbaik.') ON CONFLICT (id) DO NOTHING;
