INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bae21c1-d86c-445a-a090-94f9a66b26fd', 'チャリティーオークションで、朝霧から山々が浮き出ている素晴らしく美しい絵を落札しました。', 'Pada sebuah lelang amal, saya berhasil menawar sebuah lukisan pegunungan yang sangat indah yang menembus kabut pagi.') ON CONFLICT DO NOTHING;
