INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('59b39a53-2f1e-41c0-a9b7-dd7f08d79dcd', 'vocabulary', '花柳', '花柳', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Bunga willow karena alasan tertentu adalah distrik lampu merah. Bayangkan saja sebuah distrik lampu merah yang teduh, dan tepat di tengahnya ada pohon willow yang berbunga.', 'Bunga willow karena alasan tertentu adalah distrik lampu merah. Bayangkan saja sebuah distrik lampu merah yang teduh, dan tepat di tengahnya ada pohon willow yang berbunga.') ON CONFLICT (id) DO NOTHING;
