INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('32647a15-3182-432f-b0e3-227e432c5c72', 'vocabulary', '伊達', '伊達', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Jika Anda mencapai ke-Italiaan, Anda menjadi seperti orang Italia. Dalam hal ini, itulah keanggunan dan kesopanan murni. Juga kecanggihan. Mamamia!', 'Jika Anda mencapai ke-Italiaan, Anda menjadi seperti orang Italia. Dalam hal ini, itulah keanggunan dan kesopanan murni. Juga kecanggihan. Mamamia!') ON CONFLICT (id) DO NOTHING;
