INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d299c52-675c-4e25-bb0b-0803663b185f', 'vocabulary', '大佐', '大佐', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Bantuan besar adalah seorang kolonel atau kapten angkatan laut. Mereka mengarungi lautan, membantu orang-orang yang membutuhkan dengan melawan orang-orang jahat.', 'Bantuan besar adalah seorang kolonel atau kapten angkatan laut. Mereka mengarungi lautan, membantu orang-orang yang membutuhkan dengan melawan orang-orang jahat.') ON CONFLICT (id) DO NOTHING;
