INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('15491558-f152-44f8-bc79-6ba56ebdc5ae', 'vocabulary', '少佐', '少佐', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Yang sedikit membantu adalah para mayor atau letnan komandan. Mereka adalah segelintir orang yang siap membantu di ketentaraan, menurut kanji kata ini.', 'Yang sedikit membantu adalah para mayor atau letnan komandan. Mereka adalah segelintir orang yang siap membantu di ketentaraan, menurut kanji kata ini.') ON CONFLICT (id) DO NOTHING;
