INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aec20d51-baa4-4053-acd3-587affe8c43c', 'vocabulary', '中佐', '中佐', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Pembantu madya di angkatan darat atau laut adalah letnan kolonel atau panglima angkatan laut. Saya kira peringkat ini berada di skala peringkat menengah atau menengah ke atas?', 'Pembantu madya di angkatan darat atau laut adalah letnan kolonel atau panglima angkatan laut. Saya kira peringkat ini berada di skala peringkat menengah atau menengah ke atas?') ON CONFLICT (id) DO NOTHING;
