INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('53e27555-7b58-4f16-bfd3-331ba1e708ff', 'vocabulary', '巻尺', '巻尺', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Sebuah gulungan shaku. Jadi, gulungannya sudah digulung, kan? Dan shaku adalah bentuk pengukuran Jepang yang lebih tua. Jika benda pengukur digulung ke dalam wadah seperti gulungan... akan jadi apa benda itu? Sebuah pita pengukur!', 'Sebuah gulungan shaku. Jadi, gulungannya sudah digulung, kan? Dan shaku adalah bentuk pengukuran Jepang yang lebih tua. Jika benda pengukur digulung ke dalam wadah seperti gulungan... akan jadi apa benda itu? Sebuah pita pengukur!') ON CONFLICT (id) DO NOTHING;
