INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53e27555-7b58-4f16-bfd3-331ba1e708ff', 'この巻尺で胸囲を測るのを手伝ってもらえませんか。', 'Bisakah Anda membantu saya mengukur dada saya dengan pita pengukur ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8a0463d8-dc48-4b01-9a48-a19c89d8251a', 'vocabulary', '哀れ', '哀れ', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Jika ada sesuatu yang menyedihkan maka Anda patut mengasihaninya. Anda juga harus merasakan sedikit kesedihan dan kesedihan karenanya, karena sungguh, menyedihkan!', 'Jika ada sesuatu yang menyedihkan maka Anda patut mengasihaninya. Anda juga harus merasakan sedikit kesedihan dan kesedihan karenanya, karena sungguh, menyedihkan!') ON CONFLICT (id) DO NOTHING;
