INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a0463d8-dc48-4b01-9a48-a19c89d8251a', '衣食住もままならない彼らの事を哀れに思います。', 'Saya kasihan pada mereka karena mereka tidak mempunyai cukup makanan, pakaian, atau tempat tinggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa7c5186-786b-4a15-9069-756ec55a49a0', 'vocabulary', '可哀想', '可哀想', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Sebuah konsep yang mungkin menyedihkan. Sejujurnya, ini mungkin tidak menyedihkan. Sungguh menyedihkan dan menyedihkan.', 'Sebuah konsep yang mungkin menyedihkan. Sejujurnya, ini mungkin tidak menyedihkan. Sungguh menyedihkan dan menyedihkan.') ON CONFLICT (id) DO NOTHING;
