INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa7c5186-786b-4a15-9069-756ec55a49a0', 'お酒を付き合い程度にしか飲まない人のこと、なんだか可哀想だなって思うんだよね。', 'Menurutku agak menyedihkan menjadi peminum sosial.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6babf972-de67-4c10-a72c-5a8b7b3b6bae', 'vocabulary', '悲哀', '悲哀', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Aku sedih dan menyedihkan dengan apa yang aku rasakan. Duka yang begitu mendalam! Duka yang begitu besar karena perasaanku yang sedih dan menyedihkan.', 'Aku sedih dan menyedihkan dengan apa yang aku rasakan. Duka yang begitu mendalam! Duka yang begitu besar karena perasaanku yang sedih dan menyedihkan.') ON CONFLICT (id) DO NOTHING;
