INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3c9ead9c-51b5-4736-9b52-f814b268f299', 'vocabulary', '痛恨', '痛恨', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Dendam yang menyakitkan adalah rasa sakit yang Anda rasakan karena dendam tersebut. Aku harap aku bisa mengubah dendamku. Ini adalah penyesalan saya.', 'Dendam yang menyakitkan adalah rasa sakit yang Anda rasakan karena dendam tersebut. Aku harap aku bisa mengubah dendamku. Ini adalah penyesalan saya.') ON CONFLICT (id) DO NOTHING;
