INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f814ecd3-a541-4ead-aa96-48749265be04', 'vocabulary', '憩う', '憩う', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti istirahat dan versi vocab verbanya adalah beristirahat atau bersantai.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti istirahat dan versi vocab verbanya adalah beristirahat atau bersantai.') ON CONFLICT (id) DO NOTHING;
