INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8254c3e1-fba7-4ea3-93b6-713743c8a59e', 'vocabulary', '扇ぐ', '扇ぐ', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti kipas lipat dan karena Anda tidak "melipat kipas" sesuatu, kata ini berarti mengipasi.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti kipas lipat dan karena Anda tidak "melipat kipas" sesuatu, kata ini berarti mengipasi.') ON CONFLICT (id) DO NOTHING;
