INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c48ed7ac-93bc-4159-9927-c1e57bbe9a55', 'vocabulary', '扇風機', '扇風機', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Mesin angin kipas lipat merupakan mesin yang menghembuskan angin seperti kipas lipat. Itu kipas angin listrik atau kipas angin elektronik.', 'Mesin angin kipas lipat merupakan mesin yang menghembuskan angin seperti kipas lipat. Itu kipas angin listrik atau kipas angin elektronik.') ON CONFLICT (id) DO NOTHING;
