INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00566cab-6142-4b67-b142-14041dd27238', 'vocabulary', '土俵際', '土俵際', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Sebuah karung tanah di tepinya. Anggaplah karung-karung itu disusun melingkar. Itu adalah tepi ring sumo. Ini juga bisa merujuk pada momen terakhir atau momen kritis, seperti momen sebelum dikeluarkan dari ring.', 'Sebuah karung tanah di tepinya. Anggaplah karung-karung itu disusun melingkar. Itu adalah tepi ring sumo. Ini juga bisa merujuk pada momen terakhir atau momen kritis, seperti momen sebelum dikeluarkan dari ring.') ON CONFLICT (id) DO NOTHING;
