INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00566cab-6142-4b67-b142-14041dd27238', 'その力士は土俵際で踏ん張り、相手力士に打っ棄りを食らわせた。', 'Pegulat sumo itu menguatkan dirinya di tepi ring dan mampu mengusir lawannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00566cab-6142-4b67-b142-14041dd27238', '平和交渉は土俵際で難航して、打ち切りになった。', 'Perundingan perdamaian mengalami masalah pada saat-saat terakhir dan terhenti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c4b4bca-b5c4-4bbc-ad8a-681bcf64f2b8', 'vocabulary', '貨幣価値', '貨幣価値', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', '貨幣 adalah "mata uang" dan 価値 adalah "nilai". Ini menunjukkan nilai mata uang. Semoga bermanfaat bagi anda ketika berkunjung ke Jepang!', '貨幣 adalah "mata uang" dan 価値 adalah "nilai". Ini menunjukkan nilai mata uang. Semoga bermanfaat bagi anda ketika berkunjung ke Jepang!') ON CONFLICT (id) DO NOTHING;
