INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c4b4bca-b5c4-4bbc-ad8a-681bcf64f2b8', 'その時からどれぐらい貨幣価値が変わったか、知っているかい？', 'Tahukah Anda seberapa besar perubahan nilai uang sejak saat itu?') ON CONFLICT DO NOTHING;
