INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d483659c-4065-4ba1-9114-ed829e7dcd8c', 'vocabulary', '憩い', '憩い', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Jika 憩う berarti istirahat, maka versi kata benda ini (saya tahu ini terlihat seperti kata sifat, tapi sebenarnya bukan) adalah istirahat.', 'Jika 憩う berarti istirahat, maka versi kata benda ini (saya tahu ini terlihat seperti kata sifat, tapi sebenarnya bukan) adalah istirahat.') ON CONFLICT (id) DO NOTHING;
