INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5270e29e-e145-452d-a4f2-f997f0ea4ca3', 'vocabulary', '詐欺師', '詐欺師', 1, '90b294cb-3cbd-49c9-a62c-91af440a1143', 'Anda tahu bahwa 詐欺 adalah "penipuan." Seorang ahli dalam penipuan adalah seseorang yang sering melakukan hal ini, dan mungkin mencari nafkah. Itu penipu, penipu, atau penipu.', 'Anda tahu bahwa 詐欺 adalah "penipuan." Seorang ahli dalam penipuan adalah seseorang yang sering melakukan hal ini, dan mungkin mencari nafkah. Itu penipu, penipu, atau penipu.') ON CONFLICT (id) DO NOTHING;
