INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5270e29e-e145-452d-a4f2-f997f0ea4ca3', '不動産詐欺師というものが結構いるらしい。', 'Saya mendengar bahwa ada beberapa penipu real estate di luar sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5270e29e-e145-452d-a4f2-f997f0ea4ca3', '「ねぇ、今俺のこと、嘘つきって言った？」「そうは言ってないけど、詐欺師とは言ったよ。」', '"Hei, apa kamu baru saja menyebutku pembohong?" "Tidak, tapi aku menyebutmu penipu."') ON CONFLICT DO NOTHING;
