INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a4606aa1-f2ce-4800-8e9c-8bb5ae547276', 'vocabulary', '明瞭', '明瞭', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Sesuatu yang terang dan jernih mempunyai kejernihan dan kejernihan yang luar biasa. Lihat saja sesuatu dengan kecerahan dan kejelasan seperti itu! Ada begitu banyak kejelasan!', 'Sesuatu yang terang dan jernih mempunyai kejernihan dan kejernihan yang luar biasa. Lihat saja sesuatu dengan kecerahan dan kejelasan seperti itu! Ada begitu banyak kejelasan!') ON CONFLICT (id) DO NOTHING;
