INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f5df9e2-84f7-4d2b-8c6a-9036ab5bea0b', '地下室に一年分のトイレットペーパーの備蓄をしてるんです。', 'Kami memiliki persediaan tisu toilet selama setahun yang disimpan di ruang bawah tanah kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f5df9e2-84f7-4d2b-8c6a-9036ab5bea0b', 'これで石油を備蓄する必要がなくなりましたね。', 'Jadi kita tidak perlu menimbun minyak lagi kan?') ON CONFLICT DO NOTHING;
