INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fd245df-f0cf-4a5e-80d3-d901429f12c4', 'ついに食料の備蓄が尽きた。', 'Persediaan makanan kami akhirnya habis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fd245df-f0cf-4a5e-80d3-d901429f12c4', '人は、命が尽きる瞬間が一番輝いていると思わない？', 'Tidakkah menurut Anda orang-orang bersinar paling terang di akhir hidup mereka?') ON CONFLICT DO NOTHING;
