INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71c2ae35-7e53-4796-b566-01a832a328db', 'vocabulary', '理不尽', '理不尽', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Alasannya belum habis... tapi apa yang Anda tanyakan tidak masuk akal. Namun, alasanku akan segera habis.', 'Alasannya belum habis... tapi apa yang Anda tanyakan tidak masuk akal. Namun, alasanku akan segera habis.') ON CONFLICT (id) DO NOTHING;
