INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71c2ae35-7e53-4796-b566-01a832a328db', '超理不尽な上司とやっていかなくちゃいけなくて、理想の仕事が一気に悪夢になったよ。', 'Pekerjaan impian saya seketika berubah menjadi mimpi buruk karena harus berhadapan dengan atasan yang tidak masuk akal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('15f0a3a4-35d2-4b26-8bfc-02c484ecdfc1', 'vocabulary', '尽力', '尽力', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Jika Anda menghabiskan tenaga, Anda melakukan upaya.', 'Jika Anda menghabiskan tenaga, Anda melakukan upaya.') ON CONFLICT (id) DO NOTHING;
