INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f29c6284-b1e4-4794-8d1f-3cd2b2bc9afa', '環境に優しいアイテムに切り替えることは、あなたの暮らしを彩ります。', 'Beralih ke barang ramah lingkungan tentu akan mewarnai hidup Anda.') ON CONFLICT DO NOTHING;
