INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b2a979d9-65e2-4aa4-a72e-534f60e253ff', 'vocabulary', '迷彩', '迷彩', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Pewarnaan sesat adalah pewarnaan yang ada dimana-mana. Itu tersesat di seluruh pakaianmu. Pewarnaan yang menyimpang ini adalah kamuflase.', 'Pewarnaan sesat adalah pewarnaan yang ada dimana-mana. Itu tersesat di seluruh pakaianmu. Pewarnaan yang menyimpang ini adalah kamuflase.') ON CONFLICT (id) DO NOTHING;
