INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1349718b-18e4-4a23-889d-1855a80592d8', 'vocabulary', '油彩', '油彩', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Pewarnaan minyak lebih dikenal dengan sebutan lukisan cat minyak. Pukulan yang bagus sekali! Garis yang sangat bagus!', 'Pewarnaan minyak lebih dikenal dengan sebutan lukisan cat minyak. Pukulan yang bagus sekali! Garis yang sangat bagus!') ON CONFLICT (id) DO NOTHING;
