INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1f3e878-b30d-409c-bd5e-24575f793fc7', '人々は、その試合は八百長だったのではないかと憶測している。', 'Orang-orang berspekulasi bahwa pertandingan itu mungkin telah diperbaiki.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1f3e878-b30d-409c-bd5e-24575f793fc7', 'これはただの憶測だけどね。', 'Itu hanya dugaanku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1f3e878-b30d-409c-bd5e-24575f793fc7', 'コウイチの引退について、憶測が飛び交っている。', 'Ada banyak spekulasi tentang pensiunnya Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b494aa1d-9e1c-47a8-89be-5978620732f8', 'vocabulary', '耐える', '耐える', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya tahan. Jika Anda menolak sesuatu, maka Anda bertahan dan menahannya. Itu sebabnya ini harus bertahan dan bertahan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya tahan. Jika Anda menolak sesuatu, maka Anda bertahan dan menahannya. Itu sebabnya ini harus bertahan dan bertahan.') ON CONFLICT (id) DO NOTHING;
