INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('11cd4e33-6ebe-4f77-ba0c-4a81d19df47a', 'vocabulary', '輝き', '輝き', 1, '36587fe5-6df1-433d-a0b7-e97143e100f7', 'Jika 輝く berarti "bersinar" atau "berkilau" pikirkan versi kata bendanya. Ini akan menjadi cahaya. Cahayanya bisa datang dalam bentuk bersinar dan berkilauan.', 'Jika 輝く berarti "bersinar" atau "berkilau" pikirkan versi kata bendanya. Ini akan menjadi cahaya. Cahayanya bisa datang dalam bentuk bersinar dan berkilauan.') ON CONFLICT (id) DO NOTHING;
