INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('62c9936c-c61d-4a6a-b255-e2c4fcd715f7', 'vocabulary', '斜め', '斜め', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
