INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('62c9936c-c61d-4a6a-b255-e2c4fcd715f7', '水平な横線を引くように言ったのに、ちょっと斜めになっています。', 'Saya menyuruhnya menggambar garis horizontal, tapi agak diagonal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6274727c-1c7a-4b77-b239-7efc28c6a2f3', 'vocabulary', '斜面', '斜面', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Permukaan diagonalnya miring. Sebuah kemiringan.', 'Permukaan diagonalnya miring. Sebuah kemiringan.') ON CONFLICT (id) DO NOTHING;
