INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6274727c-1c7a-4b77-b239-7efc28c6a2f3', 'しゃめん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6274727c-1c7a-4b77-b239-7efc28c6a2f3', 'うちの私道は急斜面になってるので、上まで上がってくるにはスノータイヤがいります。', 'Jalan masuk kami telah menjadi lereng yang curam, jadi Anda memerlukan ban salju untuk mendakinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('818bb807-aa2e-4604-b293-de81af85e916', 'vocabulary', '斜体', '斜体', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Jika teks memiliki badan diagonal, maka teks tersebut condong. Bentuknya miring atau gaya font miring.', 'Jika teks memiliki badan diagonal, maka teks tersebut condong. Bentuknya miring atau gaya font miring.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('818bb807-aa2e-4604-b293-de81af85e916', 'Miring', true) ON CONFLICT DO NOTHING;
