INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('818bb807-aa2e-4604-b293-de81af85e916', 'どうしてこの単語の文字のフォントを斜体に変えたんですか。', 'Mengapa Anda mengubah font kata ini menjadi miring?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('878365b3-2bf3-4e1b-a897-af3a44a0f91d', 'vocabulary', '殴る', '殴る', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti penyerangan. Apa sajakah cara untuk menyerang seseorang? Bagaimana kalau memukul, menyerang, atau memukul, dan masih banyak lagi?', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti penyerangan. Apa sajakah cara untuk menyerang seseorang? Bagaimana kalau memukul, menyerang, atau memukul, dan masih banyak lagi?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('878365b3-2bf3-4e1b-a897-af3a44a0f91d', 'Untuk Meninju', true) ON CONFLICT DO NOTHING;
