INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('878365b3-2bf3-4e1b-a897-af3a44a0f91d', 'なぐる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('878365b3-2bf3-4e1b-a897-af3a44a0f91d', 'ゴングが鳴った瞬間、そのボクサーは相手の顎を思い切り殴り付けた。', 'Saat gong dibunyikan, petinju itu meninju rahang lawannya dengan sekuat tenaga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb570545-a85b-4557-ba30-33885d23dfde', 'vocabulary', '殴打', '殴打', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Pukulan serbu adalah pukulan atau pukulan atau pukulan. Bukan serangan persahabatan, itu sudah pasti.', 'Pukulan serbu adalah pukulan atau pukulan atau pukulan. Bukan serangan persahabatan, itu sudah pasti.') ON CONFLICT (id) DO NOTHING;
