INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('634c0d52-4b0e-4439-a1bc-26b4d0b796a2', '畑は違えど、新規市場を開拓するという点においては、前職とさほど変わりはないよ。', 'Meskipun ini adalah bidang yang sama sekali berbeda, tidak banyak perbedaan dalam hal mengembangkan pasar baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba5712ed-74e1-4142-86b3-a056619521ae', 'vocabulary', '拘置', '拘置', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Tangkap dan masukkan penjahat ke dalam tahanan dan kurungan. Masuk ke sana, penjahat!', 'Tangkap dan masukkan penjahat ke dalam tahanan dan kurungan. Masuk ke sana, penjahat!') ON CONFLICT (id) DO NOTHING;
