INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba5712ed-74e1-4142-86b3-a056619521ae', 'その女性は豆柴を膝に載せたまま酔っぱらっていたので、見かねた警察がその犬を保護拘置し、後から返してあげたそうです。', 'Saya mendengar bahwa wanita itu sedang mabuk dengan miniatur Shiba Inu di pangkuannya, jadi polisi, yang tidak tahan melihat situasinya, membawa anjing itu ke dalam tahanan pelindung dan kemudian mengembalikannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e62d280-0f38-4c03-9b11-8e2d9f30f2d8', 'vocabulary', '礎', '礎', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
