INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e62d280-0f38-4c03-9b11-8e2d9f30f2d8', 'ここにいる人は皆、総合格闘技の礎を築いた故人の死を悼んでいると思います。', 'Saya pikir semua orang di sini berduka atas meninggalnya orang yang meletakkan dasar bagi seni bela diri campuran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e62d280-0f38-4c03-9b11-8e2d9f30f2d8', '手塚治虫は日本文化の礎となった人物と考えていいと思います。', 'Saya rasa dapat dikatakan bahwa Osamu Tezuka adalah landasan budaya Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e62d280-0f38-4c03-9b11-8e2d9f30f2d8', '大変だ。お城の礎となる石が誰かに壊されてしまった。一刻も早く避難しないと城が崩れるぞ！', 'Oh tidak. Seseorang memecahkan batu yang menjadi fondasi kastil. Jika kita tidak mengungsi secepat mungkin, kastilnya akan runtuh!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26adb4ec-98e9-4838-b389-e436b9a0e2f8', 'vocabulary', '基礎', '基礎', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Fondasi dari fondasi adalah fondasi. Ini adalah hal mendasar.', 'Fondasi dari fondasi adalah fondasi. Ini adalah hal mendasar.') ON CONFLICT (id) DO NOTHING;
