INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25b1d8d9-ead2-475a-8a58-95aa764963e0', '草を刈り終わったから、放してやってよ。', 'Saya sudah selesai memotong rumput, jadi lepaskan dia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('04fb3766-7e8d-49b2-a759-e9bf171146f4', 'vocabulary', '草刈り', '草刈り', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Mari kita ambil rumputnya dan pangkasnya. Ini disebut memotong.', 'Mari kita ambil rumputnya dan pangkasnya. Ini disebut memotong.') ON CONFLICT (id) DO NOTHING;
