INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9aa4772c-edae-4f03-9394-04dcd8eb743e', '私の実家は農家で米を育てているので、今週末は稲の刈り取りを手伝わなきゃいけないんです。', 'Orang tua saya adalah petani yang bercocok tanam padi jadi saya harus membantu mereka memanen padi di akhir pekan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2fbf22e5-3ca3-458e-9805-18914df73209', 'vocabulary', '剛健', '剛健', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Ketika Anda kokoh dan sehat, Anda penuh semangat dan kejantanan.', 'Ketika Anda kokoh dan sehat, Anda penuh semangat dan kejantanan.') ON CONFLICT (id) DO NOTHING;
