INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2fbf22e5-3ca3-458e-9805-18914df73209', '彼は剛健な昔の武士のような見た目だが、彼の足にある血豆を誤って押してしまった時に、泣き叫んでいました。', 'Dia tampak seperti pejuang yang kuat di masa lalu, tetapi dia meratap ketika saya secara tidak sengaja menekan kakinya yang melepuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dccbfaf4-03c3-4d55-96ad-b07daec6410f', 'vocabulary', '唯', '唯', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Kanji artinya semata-mata, dan ini artinya semata-mata, tetapi juga hal-hal terkait lainnya seperti hanya atau semata-mata. Semuanya cukup dekat, jadi cobalah mengingat beberapa!', 'Kanji artinya semata-mata, dan ini artinya semata-mata, tetapi juga hal-hal terkait lainnya seperti hanya atau semata-mata. Semuanya cukup dekat, jadi cobalah mengingat beberapa!') ON CONFLICT (id) DO NOTHING;
