INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b200dfde-e2d7-452b-bb40-e256eb9167a1', 'vocabulary', '唯物論', '唯物論', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Teori satu-satunya hal adalah teori bahwa hanya hal-hal yang penting. Ini juga dikenal sebagai materialisme.', 'Teori satu-satunya hal adalah teori bahwa hanya hal-hal yang penting. Ini juga dikenal sebagai materialisme.') ON CONFLICT (id) DO NOTHING;
