INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5459540b-bab9-4276-9004-9be5942e6008', '青年海外協力隊についての概要は、こちらのページでお読み頂けます。', 'Garis besar Korps Perdamaian Jepang dapat Anda baca di halaman ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cd0f743f-6f18-477d-8cc9-2f6bf320fb63', 'vocabulary', '大概', '大概', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Perkiraan besarnya adalah ketika saya mengatakan sesuatu secara umum. Saya terutama dan sebagian besar menceritakan semuanya.', 'Perkiraan besarnya adalah ketika saya mengatakan sesuatu secara umum. Saya terutama dan sebagian besar menceritakan semuanya.') ON CONFLICT (id) DO NOTHING;
