INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd0f743f-6f18-477d-8cc9-2f6bf320fb63', '万引きをするのは大概、退屈で孤独を感じている女性だと言う人がいますが、ある調査が男性の方が女性よりも万引きをすることが多い可能性を示唆しているそうですよ。', 'Beberapa orang berpendapat bahwa pengutil kebanyakan adalah wanita yang bosan dan kesepian, namun saya mendengar bahwa sebuah penelitian menunjukkan bahwa lebih banyak pria yang mengutil dibandingkan wanita.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ceb9a9fd-a640-4605-91ca-cde232fdefc4', 'vocabulary', '一概に', '一概に', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Kami bergerak menuju satu perkiraan. Dulunya lebih banyak perkiraan, tapi sekarang hanya satu, dan karena hanya satu, maka sebenarnya bukan perkiraan lagi. Itu sudah diatur tanpa syarat. Itu sudah ditetapkan sebagai aturan.', 'Kami bergerak menuju satu perkiraan. Dulunya lebih banyak perkiraan, tapi sekarang hanya satu, dan karena hanya satu, maka sebenarnya bukan perkiraan lagi. Itu sudah diatur tanpa syarat. Itu sudah ditetapkan sebagai aturan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ceb9a9fd-a640-4605-91ca-cde232fdefc4', 'Tanpa syarat', true) ON CONFLICT DO NOTHING;
