INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2d70a40-27ac-414d-9f2e-4b7cfbf53a0f', 'お風呂で図書館から借りたホーソンの『巌の顔』を読んでいたんですが、うっかりお湯に浸ってしまったんです。', 'Saya sedang membaca "The Great Stone Face" karya Hawthorne yang saya pinjam dari perpustakaan di kamar mandi dan tanpa berpikir panjang merendamnya dalam air mandi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('63303166-b410-422b-bc8b-66ebebdf88b7', 'vocabulary', '浸水', '浸水', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Dicelupkan ke dalam air. Kedengarannya seperti tenggelam. Bahkan mungkin seperti banjir.', 'Dicelupkan ke dalam air. Kedengarannya seperti tenggelam. Bahkan mungkin seperti banjir.') ON CONFLICT (id) DO NOTHING;
