INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63303166-b410-422b-bc8b-66ebebdf88b7', '気温が上がるのは素晴らしいことだけど、私達は雪解け水による浸水を心配しています。', 'Sangat menyenangkan melihat suhu meningkat, tapi kami khawatir akan terjadi banjir akibat salju yang mencair.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f588070-47d7-434e-b0fc-df20e488f0fd', 'vocabulary', '淡い', '淡い', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat pingsan? Itu samar.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat pingsan? Itu samar.') ON CONFLICT (id) DO NOTHING;
