INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1a2cc0e8-88de-486e-8771-41ef97d1c3f9', 'vocabulary', '煮物', '煮物', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Makanan yang direbus berubah menjadi makanan yang direbus atau makanan yang direbus. Anda bisa makan apa saja, asal direbus cukup lama.', 'Makanan yang direbus berubah menjadi makanan yang direbus atau makanan yang direbus. Anda bisa makan apa saja, asal direbus cukup lama.') ON CONFLICT (id) DO NOTHING;
