INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a02a6ecc-6c47-4183-b00f-b3c0b0a5cbf7', 'vocabulary', '転覆', '転覆', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Ia berputar lalu terbalik. Ketika sebuah kapal berputar telentang dan kemudian terbalik, hal ini menyebabkan terbalik.', 'Ia berputar lalu terbalik. Ketika sebuah kapal berputar telentang dan kemudian terbalik, hal ini menyebabkan terbalik.') ON CONFLICT (id) DO NOTHING;
