INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c78526f-78f0-43ea-91e1-ab5db419cc43', 'vocabulary', '隔週', '隔週', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Pisahkan minggu ini dari minggu depan, dan lakukan itu berulang kali. Dengan cara itu kita punya waktu dua minggu sekali.', 'Pisahkan minggu ini dari minggu depan, dan lakukan itu berulang kali. Dengan cara itu kita punya waktu dua minggu sekali.') ON CONFLICT (id) DO NOTHING;
