INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0c78526f-78f0-43ea-91e1-ab5db419cc43', 'このアニメは隔週で放送されていて、私はそのオープニング曲とエンディング曲が好きです。', 'Anime ini tayang dua minggu sekali dan saya suka lagu pembuka dan penutupnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9ba5ef83-0cff-4f44-a534-92bb98d9823c', 'vocabulary', '間隔', '間隔', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Saya ingin mengisolasi interval waktu ini. Ambil, pisahkan, lalu lihat. Sekarang ada ruang di sana. Interval, jika Anda mau.', 'Saya ingin mengisolasi interval waktu ini. Ambil, pisahkan, lalu lihat. Sekarang ada ruang di sana. Interval, jika Anda mau.') ON CONFLICT (id) DO NOTHING;
