INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1d96f14-a455-473e-a297-d95b573f42df', '私のアパートでは、浴槽と洗面所はシャワーカーテン一枚で隔てられています。', 'Di apartemen saya, bak mandi dan kamar mandi dipisahkan oleh satu tirai mandi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d153d77c-df23-4943-b552-b8add6b7ed9a', 'vocabulary', '遠征', '遠征', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Jarak yang jauh harus kita tempuh untuk menundukkan musuh kita. Ini adalah ekspedisi dan kampanye yang panjang untuk melakukan hal itu!', 'Jarak yang jauh harus kita tempuh untuk menundukkan musuh kita. Ini adalah ekspedisi dan kampanye yang panjang untuk melakukan hal itu!') ON CONFLICT (id) DO NOTHING;
