INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('abb2778a-91c6-4149-808a-04e0dd968181', 'vocabulary', '征服', '征服', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Saya akan menundukkan semua orang untuk mengenakan pakaian yang saya ingin mereka kenakan. Mereka akan memakai seragamku, karena mereka berada di bawah penaklukanku. Aku akan menaklukkan mereka!', 'Saya akan menundukkan semua orang untuk mengenakan pakaian yang saya ingin mereka kenakan. Mereka akan memakai seragamku, karena mereka berada di bawah penaklukanku. Aku akan menaklukkan mereka!') ON CONFLICT (id) DO NOTHING;
