INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d97a5067-30fc-4539-b220-df8bedc2b008', 'vocabulary', '俗語', '俗語', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Bahasa vulgar belum tentu kata-kata buruk atau semacamnya. Hanya saja lebih kasar dan tidak standar seperti bahasa standar. Ini adalah bahasa sehari-hari atau bahasa sehari-hari.', 'Bahasa vulgar belum tentu kata-kata buruk atau semacamnya. Hanya saja lebih kasar dan tidak standar seperti bahasa standar. Ini adalah bahasa sehari-hari atau bahasa sehari-hari.') ON CONFLICT (id) DO NOTHING;
