INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3348fbeb-d7dd-477a-a5fc-24dd1549fe03', 'vocabulary', '民俗', '民俗', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Orang yang vulgar bukanlah orang kota yang beradab. Mereka adalah orang-orang dengan adat istiadat rakyat dan adat istiadat etnis.', 'Orang yang vulgar bukanlah orang kota yang beradab. Mereka adalah orang-orang dengan adat istiadat rakyat dan adat istiadat etnis.') ON CONFLICT (id) DO NOTHING;
