INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a7085b5b-7a43-417a-8c6e-dd25bf3e4aca', 'vocabulary', '俗', '俗', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Hal-hal yang vulgar adalah hal-hal seperti bahasa gaul, tata krama setempat, dan hal-hal biasa.', 'Hal-hal yang vulgar adalah hal-hal seperti bahasa gaul, tata krama setempat, dan hal-hal biasa.') ON CONFLICT (id) DO NOTHING;
