INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec088fa6-29c1-4433-befa-53295d80fc95', 'vocabulary', '殴り込み', '殴り込み', 1, '7a458093-a1c4-4e55-a73f-b0f6ef4e69f7', 'Untuk menyerang lalu berkerumun. Itu berarti Anda menyerang suatu tempat, lalu berkerumun di dalamnya, mungkin melakukan penyerbuan terhadap tempat tersebut.', 'Untuk menyerang lalu berkerumun. Itu berarti Anda menyerang suatu tempat, lalu berkerumun di dalamnya, mungkin melakukan penyerbuan terhadap tempat tersebut.') ON CONFLICT (id) DO NOTHING;
