INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f607dc1f-8ab3-42d4-a1c2-cdcf9e5a81a9', 'radical', '甚', 'crab-trap', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Radikal ini terlihat seperti binatang kecil (匹) yang ada kepiting (其) yang mencuat di dalamnya. Seringkali ketika seekor kepiting sedang memakan hewan kecil, hewan kecil tersebut dimasukkan ke dalam perangkap kepiting untuk menangkap kepiting tersebut, dan memikatnya bersama hewan kecil tersebut. Itu sebabnya radikal ini adalah perangkap kepiting.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f607dc1f-8ab3-42d4-a1c2-cdcf9e5a81a9', 'Perangkap Kepiting', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0bfd8163-b9b1-43fe-81ff-caacc17539a3', 'radical', '夆', 'signpost', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Ini adalah postingan dengan tanda di atasnya. Dan di atasnya ada penanda musim dingin, yang menunjukkan bahwa jika Anda pergi ke utara, di sana sedang musim dingin. Tanda-tandanya bertuliskan "Narnia ↑" dan "Meridell ←" dan "Bananaland →" sehingga Anda tahu itu adalah penunjuk arah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0bfd8163-b9b1-43fe-81ff-caacc17539a3', 'Plang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d7500e9b-9b00-4330-8da0-e56faf412fe8', 'radical', '太', 'fat', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Radikal ini sama dengan kanji. Artinya gemuk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d7500e9b-9b00-4330-8da0-e56faf412fe8', 'Gemuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d80d85fc-d3bf-414d-b3b4-82424b1651f2', 'radical', '名', 'name', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Radikal ini sama dengan kanji. Artinya nama.') ON CONFLICT (id) DO NOTHING;
