INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('83679a28-9ded-4f91-90a9-8794af789e25', 'vocabulary', '桑', '桑', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Kanji berarti murbei, tapi ini mengacu pada pohon murbei.', 'Kanji berarti murbei, tapi ini mengacu pada pohon murbei.') ON CONFLICT (id) DO NOTHING;
