INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83679a28-9ded-4f91-90a9-8794af789e25', '桑の実と林檎と胡桃の組み合わせが最強に美味しいんだよね。', 'Mulberry, apel, dan kenari terasa paling enak jika digabungkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cf062e81-eea8-4df5-bc51-063508393386', 'vocabulary', '桑原', '桑原', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Ladang murbei adalah ladang murbei.', 'Ladang murbei adalah ladang murbei.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cf062e81-eea8-4df5-bc51-063508393386', 'Ladang Murbei', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cf062e81-eea8-4df5-bc51-063508393386', 'くわばら', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf062e81-eea8-4df5-bc51-063508393386', 'かつては桑畑がたくさんあったため、この場所は「桑原」と呼ばれるようになりました。', 'Orang-orang mulai menyebut tempat ini "Kuwabara" karena dulunya banyak terdapat ladang murbei di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('94e07229-a133-4be0-aa13-fa2d73279c8b', 'vocabulary', '潤う', '潤う', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya disiram. Ketika sesuatu disiram, itu lembab dan lembap. Itu sebabnya kata kerjanya menjadi lembab atau lembab atau disiram.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya disiram. Ketika sesuatu disiram, itu lembab dan lembap. Itu sebabnya kata kerjanya menjadi lembab atau lembab atau disiram.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('94e07229-a133-4be0-aa13-fa2d73279c8b', 'Menjadi Lembab', true) ON CONFLICT DO NOTHING;
