INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94e07229-a133-4be0-aa13-fa2d73279c8b', 'このローションを使えば、あなたのお肌はプルプルに潤いますよ。', 'Jika menggunakan lotion ini akan melembabkan kulit sehingga kencang dan lembut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6eeff580-910b-4909-80e1-b25bc4b34af4', 'vocabulary', '利潤', '利潤', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Keuntungan yang saya peroleh mengalir deras ke seluruh tubuh saya. Itu keuntungan dan keuntungan saya.', 'Keuntungan yang saya peroleh mengalir deras ke seluruh tubuh saya. Itu keuntungan dan keuntungan saya.') ON CONFLICT (id) DO NOTHING;
