INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6eadd31a-db03-4d55-b476-d1722c575d71', 'vocabulary', '奨学金', '奨学金', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Uang dorongan belajar adalah uang yang Anda berikan kepada seorang anak untuk mendorongnya belajar. Itu datang dalam bentuk beasiswa atau tunjangan.', 'Uang dorongan belajar adalah uang yang Anda berikan kepada seorang anak untuk mendorongnya belajar. Itu datang dalam bentuk beasiswa atau tunjangan.') ON CONFLICT (id) DO NOTHING;
