INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2a65ff74-6758-4484-b461-f3adfc6448da', 'vocabulary', '劣化', '劣化', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Inferioritas Anda telah berubah. Faktanya, kondisinya semakin memburuk, berubah dari menit ke menit. Setiap menit yang berlalu adalah menit di mana kondisi Anda semakin buruk. Ini adalah kemunduran.', 'Inferioritas Anda telah berubah. Faktanya, kondisinya semakin memburuk, berubah dari menit ke menit. Setiap menit yang berlalu adalah menit di mana kondisi Anda semakin buruk. Ini adalah kemunduran.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2a65ff74-6758-4484-b461-f3adfc6448da', 'Kemunduran', true) ON CONFLICT DO NOTHING;
