INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a65ff74-6758-4484-b461-f3adfc6448da', '女優やモデルの見た目が以前よりも老けた時、日本のネット用語で「劣化した」と言います。', 'Ketika aktris atau model menua dan terlihat lebih tua dari biasanya, kata di internet dalam bahasa Jepang untuk mereka adalah "memburuk".') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8eeb1239-6787-491e-aeca-91480e4a1656', 'vocabulary', '劣悪', '劣悪', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Inferioritas itu buruk. Ini adalah inferioritas.', 'Inferioritas itu buruk. Ini adalah inferioritas.') ON CONFLICT (id) DO NOTHING;
