INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b27174d3-b6a3-41da-8939-6e52452e873f', '成功の秘訣は、鋭い勘をもつことです。', 'Memiliki intuisi yang tajam adalah kunci kesuksesan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1e4a73ac-785d-4104-aa24-e77c262d6669', 'vocabulary', '勘案', '勘案', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Dengan menggunakan intuisi kita, kita akan membuat rencana. Kami akan mempertimbangkan informasi yang kami miliki beserta intuisi kami, jadi jangan khawatir.', 'Dengan menggunakan intuisi kita, kita akan membuat rencana. Kami akan mempertimbangkan informasi yang kami miliki beserta intuisi kami, jadi jangan khawatir.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1e4a73ac-785d-4104-aa24-e77c262d6669', 'Mempertimbangkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1e4a73ac-785d-4104-aa24-e77c262d6669', 'Giving Consideration', false) ON CONFLICT DO NOTHING;
