INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('345c7972-6d5c-4110-9860-201e5153d362', '勘弁してちゃぶ台。今日は忙しかったし、滅茶苦茶疲れているんだ。', 'Beri aku waktu luang. Ini hari yang panjang dan aku sangat lelah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d7c6f762-33e1-4349-9822-dc53930aec9e', 'vocabulary', '割り勘', '割り勘', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Saya akan membagi intuisi. Untuk beberapa alasan ketika saya mengatakan "intuisi" yang saya maksud adalah "uang" karena ini mengacu pada pembagian biaya, seperti ketika Anda berada di restoran.', 'Saya akan membagi intuisi. Untuk beberapa alasan ketika saya mengatakan "intuisi" yang saya maksud adalah "uang" karena ini mengacu pada pembagian biaya, seperti ketika Anda berada di restoran.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d7c6f762-33e1-4349-9822-dc53930aec9e', 'Membagi Biaya', true) ON CONFLICT DO NOTHING;
