INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7c6f762-33e1-4349-9822-dc53930aec9e', '私は下戸でお酒を飲まないので、お酒のお勘定は割り勘じゃない方が嬉しいんですが。', 'Saya tidak bisa minum karena saya mudah mabuk, jadi alangkah baiknya jika kita tidak membagi tagihan alkoholnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('596d3d2f-7745-4147-85a2-751f7d828e3e', 'vocabulary', '勘違い', '勘違い', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Perbedaan intuisi adalah kesalahpahaman atau kesalahan tebakan. Maaf! Intuisi saya salah.', 'Perbedaan intuisi adalah kesalahpahaman atau kesalahan tebakan. Maaf! Intuisi saya salah.') ON CONFLICT (id) DO NOTHING;
