INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('596d3d2f-7745-4147-85a2-751f7d828e3e', '「すみません、間違えました。違う人と 勘違いしました。」「正確には誰と間違えたんですか？お願いします。教えてください。」', '“Maaf, kesalahan saya. Saya pikir Anda adalah orang lain.” "Sebenarnya siapa yang membuatmu salah mengira aku? Tolong. Katakan padaku."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a927d74f-8b88-4b47-be59-c55d5aea7688', 'vocabulary', '王妃', '王妃', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Raja para putri adalah putri terhebat dan berperingkat tertinggi di antara mereka semua.', 'Raja para putri adalah putri terhebat dan berperingkat tertinggi di antara mereka semua.') ON CONFLICT (id) DO NOTHING;
