INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9ae27ff-4fe5-4257-8875-9ac839ce40c1', 'vocabulary', '皇太子妃', '皇太子妃', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Ingat bagaimana 皇太子 adalah "putra mahkota"? Ubah putra mahkota ini menjadi "ratu putra mahkota". Bukan ratu sungguhan, melainkan ratu anak-anak. Ini adalah putri mahkota.', 'Ingat bagaimana 皇太子 adalah "putra mahkota"? Ubah putra mahkota ini menjadi "ratu putra mahkota". Bukan ratu sungguhan, melainkan ratu anak-anak. Ini adalah putri mahkota.') ON CONFLICT (id) DO NOTHING;
