INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3b958237-17e8-4c73-a93d-26134602803b', 'vocabulary', '妃', '妃', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
