INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3634a23b-9c9d-415e-9a5d-4f96d9bb7a90', '妹と私は、雲の上にそびえる富士山の峰に登頂しました。', 'Saya dan saudara perempuan saya mendaki ke puncak Gunung Fuji, menjulang di atas awan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3ffcb943-aa25-4842-bba7-437caca4167b', 'vocabulary', '連峰', '連峰', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Ikutilah pertemuan puncak ini dan pindahkan ke berbagai tempat, kunjungi lebih banyak puncak. Satu demi satu pertemuan puncak Anda ikuti. Dengan menutupi banyak puncak ini, Anda melihat ada serangkaian gunung. Ini adalah pegunungan!', 'Ikutilah pertemuan puncak ini dan pindahkan ke berbagai tempat, kunjungi lebih banyak puncak. Satu demi satu pertemuan puncak Anda ikuti. Dengan menutupi banyak puncak ini, Anda melihat ada serangkaian gunung. Ini adalah pegunungan!') ON CONFLICT (id) DO NOTHING;
