INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3ffcb943-aa25-4842-bba7-437caca4167b', '今日の連峰はよく晴れていて見晴らしがいいです。', 'Pegunungan hari ini cerah dengan indah dan pemandangannya sangat bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a27ad026-2146-4a94-8992-c3f2b1d55403', 'vocabulary', '巧い', '巧い', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Kamu sangat mahir! Itu membuatmu mahir dalam hal itu. Terampil dan pintar adalah cara lain untuk melakukannya juga.', 'Kamu sangat mahir! Itu membuatmu mahir dalam hal itu. Terampil dan pintar adalah cara lain untuk melakukannya juga.') ON CONFLICT (id) DO NOTHING;
