INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25aa2b65-19ee-420a-98c0-f9bbff43bbc4', 'vocabulary', '巧妙', '巧妙', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Sesuatu yang mahir namun aneh dalam kemahirannya pastilah sesuatu yang benar-benar cerdik dan terampil. Seperti melihat teknologi alien.', 'Sesuatu yang mahir namun aneh dalam kemahirannya pastilah sesuatu yang benar-benar cerdik dan terampil. Seperti melihat teknologi alien.') ON CONFLICT (id) DO NOTHING;
