INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25aa2b65-19ee-420a-98c0-f9bbff43bbc4', 'ある邪悪な魔法使いが、巧妙に偶然を装って女性に近づきました。', 'Penyihir jahat dengan cerdik berpura-pura mendekati gadis itu secara kebetulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ad4e636c-f090-46ed-b54b-77ccc70a72f7', 'vocabulary', '風邪', '風邪', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Angin jahat datang dan menerpamu. Dingin sekali, dan akhirnya membuatmu sakit. Anda sekarang sedang flu.', 'Angin jahat datang dan menerpamu. Dingin sekali, dan akhirnya membuatmu sakit. Anda sekarang sedang flu.') ON CONFLICT (id) DO NOTHING;
