INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ad4e636c-f090-46ed-b54b-77ccc70a72f7', '「なんで母親の葬式に来ないの？」「風邪ひいてるからだよ。」', '"Kenapa kamu tidak datang ke pemakaman ibumu?" "Karena aku masuk angin."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('66e894c3-a4e9-4ed5-b6b8-d34c2ebea7f8', 'vocabulary', '邪魔', '邪魔', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Iblis yang jahat! Ugh, aku benci hal-hal itu. Mereka selalu menjadi penghalang dan gangguan. Bayangkan saja setan jahat berkeliaran di rumah Anda, memakan makanan Anda, dan tidur di tempat tidur Anda. Benar-benar sebuah hambatan.', 'Iblis yang jahat! Ugh, aku benci hal-hal itu. Mereka selalu menjadi penghalang dan gangguan. Bayangkan saja setan jahat berkeliaran di rumah Anda, memakan makanan Anda, dan tidur di tempat tidur Anda. Benar-benar sebuah hambatan.') ON CONFLICT (id) DO NOTHING;
