INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66e894c3-a4e9-4ed5-b6b8-d34c2ebea7f8', '私の邪魔をするな。一人で出来るよ！', 'Jangan menghalangi jalanku. Saya bisa melakukannya sendiri!') ON CONFLICT DO NOTHING;
