INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7fca65c9-de6a-47c9-81b8-73592cffff08', 'vocabulary', '翻意', '翻意', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Saat Anda membalikkan gagasan Anda tentang sesuatu, Anda mengubah cara Anda memikirkannya. Itu sebabnya kata ini adalah mengubah pikiran.', 'Saat Anda membalikkan gagasan Anda tentang sesuatu, Anda mengubah cara Anda memikirkannya. Itu sebabnya kata ini adalah mengubah pikiran.') ON CONFLICT (id) DO NOTHING;
