INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b04ea7d4-5425-47f0-a5c9-d220e0e2e64f', 'vocabulary', '翻訳', '翻訳', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Balikkan terjemahan kata dari satu bahasa ke bahasa lain. Itu adalah terjemahan dari kata itu (atau frase, dll).', 'Balikkan terjemahan kata dari satu bahasa ke bahasa lain. Itu adalah terjemahan dari kata itu (atau frase, dll).') ON CONFLICT (id) DO NOTHING;
