INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10f6f8fd-2c94-4bd3-8e7d-be9b11c0d3e4', 'vocabulary', '軌道', '軌道', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Sebuah bekas roda di jalan karena alasan tertentu merupakan orbit atau lintasan. Mungkin bayangkan sebuah lubang besar di jalan. Anda mengendarainya dengan kecepatan sangat tinggi, menabraknya, dan terbang ke angkasa dengan lintasan yang akan mengirim Anda ke orbit. Sekarang Anda berada di luar angkasa, mengelilingi bumi, berharap Anda tidak mengemudi begitu cepat.', 'Sebuah bekas roda di jalan karena alasan tertentu merupakan orbit atau lintasan. Mungkin bayangkan sebuah lubang besar di jalan. Anda mengendarainya dengan kecepatan sangat tinggi, menabraknya, dan terbang ke angkasa dengan lintasan yang akan mengirim Anda ke orbit. Sekarang Anda berada di luar angkasa, mengelilingi bumi, berharap Anda tidak mengemudi begitu cepat.') ON CONFLICT (id) DO NOTHING;
