INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5ba9afc2-58f1-4b01-b72e-4c488c2a1429', 'vocabulary', '皇后', '皇后', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Kaisar permaisuri adalah istri kaisar. Itu adalah Permaisuri Jepang, khususnya, karena 皇 biasanya mengacu pada kaisar Jepang.', 'Kaisar permaisuri adalah istri kaisar. Itu adalah Permaisuri Jepang, khususnya, karena 皇 biasanya mengacu pada kaisar Jepang.') ON CONFLICT (id) DO NOTHING;
