INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('07057ab8-4d1d-47c5-8bd2-938a172b05e4', 'vocabulary', '信仰', '信仰', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Saya percaya dan memandang kepada kekuatan yang lebih tinggi, karena saya mempunyai keyakinan agama.', 'Saya percaya dan memandang kepada kekuatan yang lebih tinggi, karena saya mempunyai keyakinan agama.') ON CONFLICT (id) DO NOTHING;
