INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8703fb28-614f-44d0-bd6e-e815bda78812', 'vocabulary', '伯母', '伯母', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Ibu utama bukanlah ibumu sendiri, tapi dia adalah ibu utamamu. Dia adalah saudara perempuan ibumu, yang selalu memiliki ibumu. Dia adalah ibu utama. Dia bibimu.', 'Ibu utama bukanlah ibumu sendiri, tapi dia adalah ibu utamamu. Dia adalah saudara perempuan ibumu, yang selalu memiliki ibumu. Dia adalah ibu utama. Dia bibimu.') ON CONFLICT (id) DO NOTHING;
