INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ab07b934-9820-4d78-815e-73d60e248f8d', 'vocabulary', '古墳', '古墳', 1, 'bfef5fff-8234-4cba-a9c0-1f5377e2b572', 'Makam tua adalah makam kuno. Kebanyakan dari mereka berasal dari zaman Kofun, dan memang dari sanalah zaman tersebut mendapatkan namanya.', 'Makam tua adalah makam kuno. Kebanyakan dari mereka berasal dari zaman Kofun, dan memang dari sanalah zaman tersebut mendapatkan namanya.') ON CONFLICT (id) DO NOTHING;
