INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab07b934-9820-4d78-815e-73d60e248f8d', '近年その古墳を訪れる人が増えています。', 'Jumlah orang yang mengunjungi makam kuno tersebut meningkat dalam beberapa tahun terakhir.') ON CONFLICT DO NOTHING;
