INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab07b934-9820-4d78-815e-73d60e248f8d', '古川君は、古墳マニアなんですよ。', 'Furukawa-kun adalah penggila makam kuno.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab07b934-9820-4d78-815e-73d60e248f8d', '古墳時代は、三世紀末頃から七世紀頃までの時代を言います。', 'Periode Kofun mengacu pada periode sekitar akhir abad ke-3 hingga abad ke-7.') ON CONFLICT DO NOTHING;
