INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d71defac-50ee-4018-850e-780f65913d16', 'オーストラリアの検疫法はすっごく厳しいから、食べ物は何も持って行かない方が身のためだよ。', 'Undang-undang karantina Australia sangat ketat, jadi Anda tidak boleh membawa makanan apa pun ke sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('573797bc-6ab3-4a91-ada4-06d4dffea0b3', 'vocabulary', '免疫', '免疫', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Untuk menghindari epidemi, Anda harus memiliki kekebalan atau imunisasi terhadap penyakit tersebut.', 'Untuk menghindari epidemi, Anda harus memiliki kekebalan atau imunisasi terhadap penyakit tersebut.') ON CONFLICT (id) DO NOTHING;
