INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8710ac4-8313-40af-b5fd-a81b14c6b734', 'vocabulary', '召喚', '召喚', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Jika Anda memanggil seseorang dengan berteriak, Anda mungkin mencoba memanggil mereka seperti yang dilakukan pesulap. Penyihir harus meneriakkan mantranya agar bisa bekerja. Jadi kamu harus meneriakkan namanya saat memanggil mereka jika ingin memanggil seseorang.', 'Jika Anda memanggil seseorang dengan berteriak, Anda mungkin mencoba memanggil mereka seperti yang dilakukan pesulap. Penyihir harus meneriakkan mantranya agar bisa bekerja. Jadi kamu harus meneriakkan namanya saat memanggil mereka jika ingin memanggil seseorang.') ON CONFLICT (id) DO NOTHING;
