INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('754f9cc0-a1e8-4ffc-80b1-aa066da819e0', 'vocabulary', '慈愛', '慈愛', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Ketika Anda mengasihani orang yang Anda cintai, itu disebut kasih sayang. Anda akhirnya melakukan sesuatu karena kebaikan hati Anda karena itu sangat berarti bagi Anda.', 'Ketika Anda mengasihani orang yang Anda cintai, itu disebut kasih sayang. Anda akhirnya melakukan sesuatu karena kebaikan hati Anda karena itu sangat berarti bagi Anda.') ON CONFLICT (id) DO NOTHING;
