INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('270c41b5-713b-46ba-85be-b59a99c34763', 'vocabulary', '苗', '苗', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
