INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('832b8c2d-49b1-4785-a6e3-bb3e6f02307e', 'vocabulary', '蓮', '蓮', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Ini bukan sembarang teratai. Itu teratai. Teratai Suci. Saat Anda melihatnya mekar sendirian di kolam keruh, Anda pasti tahu.', 'Ini bukan sembarang teratai. Itu teratai. Teratai Suci. Saat Anda melihatnya mekar sendirian di kolam keruh, Anda pasti tahu.') ON CONFLICT (id) DO NOTHING;
