INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68667263-2970-4789-af58-21b620f190eb', 'この池にはいつから蓮花があるのですか。', 'Sudah berapa lama bunga teratai berada di kolam ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('34f50f4e-abd2-4835-b180-3e898947dce2', 'vocabulary', '貞節', '貞節', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Kesucian selalu ada pada musimnya jadi selalu menyenangkan untuk mencoba menjaga kesucian Anda. Musim semi, musim panas? Tidak masalah. Keputusan Anda untuk tetap seperti itu baik-baik saja, tidak peduli jam berapa sekarang.', 'Kesucian selalu ada pada musimnya jadi selalu menyenangkan untuk mencoba menjaga kesucian Anda. Musim semi, musim panas? Tidak masalah. Keputusan Anda untuk tetap seperti itu baik-baik saja, tidak peduli jam berapa sekarang.') ON CONFLICT (id) DO NOTHING;
