INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d8705f11-febe-4a78-a0bf-634e08a1519f', 'vocabulary', '不貞', '不貞', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Ketika Anda tidak memiliki kesucian, itu mungkin karena Anda tidak setia pada janji Anda kepada siapa pun yang Anda katakan untuk tetap suci.', 'Ketika Anda tidak memiliki kesucian, itu mungkin karena Anda tidak setia pada janji Anda kepada siapa pun yang Anda katakan untuk tetap suci.') ON CONFLICT (id) DO NOTHING;
