INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('537a7a9e-e864-4a17-9d14-f8d8eabc7218', 'vocabulary', '私邸', '私邸', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Tempat tinggal pribadi adalah tempat tinggal pribadi!', 'Tempat tinggal pribadi adalah tempat tinggal pribadi!') ON CONFLICT (id) DO NOTHING;
