INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f61d00ff-7770-4bc7-b431-42ff0d4c1985', 'vocabulary', '官邸', '官邸', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Tempat tinggal pemerintah adalah tempat tinggal yang diperuntukkan bagi pejabat pemerintah. Itu berarti itu adalah kediaman resmi mereka, dan itu menjadi urusan semua dokumen resmi mereka.', 'Tempat tinggal pemerintah adalah tempat tinggal yang diperuntukkan bagi pejabat pemerintah. Itu berarti itu adalah kediaman resmi mereka, dan itu menjadi urusan semua dokumen resmi mereka.') ON CONFLICT (id) DO NOTHING;
