INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d9122b0-cc5a-482a-9936-e97b4720d034', 'vocabulary', '邸宅', '邸宅', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Jika Anda mempunyai tempat tinggal yang juga merupakan rumah Anda, itu tetaplah tempat tinggal Anda. Tapi Anda mungkin punya banyak uang jika bisa memiliki rumah sendiri, jadi mungkin rumah itu bagus dan besar juga.', 'Jika Anda mempunyai tempat tinggal yang juga merupakan rumah Anda, itu tetaplah tempat tinggal Anda. Tapi Anda mungkin punya banyak uang jika bisa memiliki rumah sendiri, jadi mungkin rumah itu bagus dan besar juga.') ON CONFLICT (id) DO NOTHING;
