INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c1d249bf-e2df-4eb3-b958-d25a1aa0abe7', 'vocabulary', '会釈', '会釈', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Sebelum Anda bisa memberikan penjelasan tentang siapa diri Anda kepada seseorang yang akan Anda temui, Anda harus mengangguk atau membungkukkan badan sebagai salam terlebih dahulu. Tidak sopan untuk mulai menjelaskan siapa Anda sebelum menyapa mereka.', 'Sebelum Anda bisa memberikan penjelasan tentang siapa diri Anda kepada seseorang yang akan Anda temui, Anda harus mengangguk atau membungkukkan badan sebagai salam terlebih dahulu. Tidak sopan untuk mulai menjelaskan siapa Anda sebelum menyapa mereka.') ON CONFLICT (id) DO NOTHING;
