INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3c4bea4d-26f1-4a0b-8eaf-db43923c70e2', 'vocabulary', '玄人', '玄人', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Orang misterius sangat pandai dalam pekerjaannya. Begitu bagusnya sampai-sampai mereka tidak begitu yakin apa yang mereka lakukan, tapi Anda tahu mereka pastinya ahli dalam apa pun itu.', 'Orang misterius sangat pandai dalam pekerjaannya. Begitu bagusnya sampai-sampai mereka tidak begitu yakin apa yang mereka lakukan, tapi Anda tahu mereka pastinya ahli dalam apa pun itu.') ON CONFLICT (id) DO NOTHING;
