INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58f95cba-bcf3-4392-8da0-b78205438f59', 'vocabulary', '風呂場', '風呂場', 1, 'c0a798f4-6f01-4e2a-ae06-a24abb642888', 'Ingat bagaimana Anda mengetahui bahwa 風呂 berarti "mandi?" Nah, tempat kamu mandi adalah kamar mandi!', 'Ingat bagaimana Anda mengetahui bahwa 風呂 berarti "mandi?" Nah, tempat kamu mandi adalah kamar mandi!') ON CONFLICT (id) DO NOTHING;
