INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b92313a8-096c-4f8f-b892-9e97d296b453', 'vocabulary', '不倫', '不倫', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Jika Anda tidak memiliki etika, Anda mungkin akan melakukan sesuatu yang buruk, seperti melakukan perzinahan. Biasanya hanya orang yang tidak etis saja yang selingkuh dari pasangannya, bukan?', 'Jika Anda tidak memiliki etika, Anda mungkin akan melakukan sesuatu yang buruk, seperti melakukan perzinahan. Biasanya hanya orang yang tidak etis saja yang selingkuh dari pasangannya, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b92313a8-096c-4f8f-b892-9e97d296b453', 'Perzinahan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b92313a8-096c-4f8f-b892-9e97d296b453', 'ふりん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b92313a8-096c-4f8f-b892-9e97d296b453', 'どうやら妻が不倫をしているようなんです。', 'Tampaknya istri saya melakukan perzinahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c4acf75-d4ea-43dd-a5ce-eba5915a377b', 'vocabulary', '倫理', '倫理', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Etika dan akal budi yang menyatu dalam diri seseorang menjadikan mereka mempunyai etika dan moral yang sangat kuat.', 'Etika dan akal budi yang menyatu dalam diri seseorang menjadikan mereka mempunyai etika dan moral yang sangat kuat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6c4acf75-d4ea-43dd-a5ce-eba5915a377b', 'Etika', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6c4acf75-d4ea-43dd-a5ce-eba5915a377b', 'Morals', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6c4acf75-d4ea-43dd-a5ce-eba5915a377b', 'りんり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c4acf75-d4ea-43dd-a5ce-eba5915a377b', 'ちゃんと職業倫理を守ってください。', 'Harap patuhi etika bisnis dengan benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', 'vocabulary', '偏る', '偏る', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bias, jadi versi verbanya menjadi bias atau berprasangka buruk.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bias, jadi versi verbanya menjadi bias atau berprasangka buruk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', 'Menjadi Bias', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', 'To Be One Sided', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', 'To Be Partial', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', 'To Be Prejudiced', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', 'かたよる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2159470e-6b37-4c4f-aa9b-aa3c6cf67d42', '栄養が偏るのは良くない。', 'Nutrisi satu sisi tidak baik untuk Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('47b401c9-b6e5-4738-94cd-904834b10f6e', 'vocabulary', '偏見', '偏見', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Jika Anda memiliki cara pandang yang bias, orang akan mengira Anda berprasangka buruk terhadap mereka.', 'Jika Anda memiliki cara pandang yang bias, orang akan mengira Anda berprasangka buruk terhadap mereka.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('47b401c9-b6e5-4738-94cd-904834b10f6e', 'Prasangka', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('47b401c9-b6e5-4738-94cd-904834b10f6e', 'へんけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47b401c9-b6e5-4738-94cd-904834b10f6e', 'それが偏見というものです。', 'Itu disebut prasangka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47b401c9-b6e5-4738-94cd-904834b10f6e', '偏見が全くない世界なんてものは存在しない。', 'Tidak ada dunia di mana tidak ada prasangka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('47b401c9-b6e5-4738-94cd-904834b10f6e', '彼女はアジア人に偏見があるようだ。', 'Dia tampaknya berprasangka buruk terhadap orang Asia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a38e7833-7fab-46d7-87cb-035275c6de1e', 'vocabulary', '偏狭', '偏狭', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Orang dengan bias sempit dianggap berpikiran sempit dan biasanya tidak disukai karena tidak toleran terhadap budaya lain dan segala sesuatu yang asing bagi mereka.', 'Orang dengan bias sempit dianggap berpikiran sempit dan biasanya tidak disukai karena tidak toleran terhadap budaya lain dan segala sesuatu yang asing bagi mereka.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a38e7833-7fab-46d7-87cb-035275c6de1e', 'Berpikiran Sempit', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a38e7833-7fab-46d7-87cb-035275c6de1e', 'Intolerance', false) ON CONFLICT DO NOTHING;
