INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a38e7833-7fab-46d7-87cb-035275c6de1e', 'ステレオタイプは人間を偏狭にします。', 'Stereotipnya adalah manusia berpikiran sempit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4374411d-ba09-41ed-91ae-3307ff26eea9', 'vocabulary', '偏食', '偏食', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Orang yang bias terhadap apa yang mereka makan biasanya hanya makan makanan manis seperti permen dan es krim. Pola makan yang pilih-pilih ini memberi mereka pola makan yang sangat tidak seimbang. Permen dan es krim boleh saja, tetapi Anda juga harus terbuka untuk mengonsumsi makanan lain.', 'Orang yang bias terhadap apa yang mereka makan biasanya hanya makan makanan manis seperti permen dan es krim. Pola makan yang pilih-pilih ini memberi mereka pola makan yang sangat tidak seimbang. Permen dan es krim boleh saja, tetapi Anda juga harus terbuka untuk mengonsumsi makanan lain.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4374411d-ba09-41ed-91ae-3307ff26eea9', 'Pola Makan Tidak Seimbang', true) ON CONFLICT DO NOTHING;
