INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4374411d-ba09-41ed-91ae-3307ff26eea9', '子供が偏食がちなので困っています。', 'Saya khawatir karena anak-anak saya cenderung memiliki pola makan yang tidak seimbang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('113c761b-a537-4a1f-8d47-b1ff3dd38113', 'vocabulary', '示唆', '示唆', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Seseorang yang cenderung memberi isyarat dan menghasut akan banyak memberikan saran kepada orang lain. Dengan memberikan petunjuk, mereka dapat menunjukkan masalah dan memicu pertengkaran di antara orang-orang. Implikasinya sangat merugikan.', 'Seseorang yang cenderung memberi isyarat dan menghasut akan banyak memberikan saran kepada orang lain. Dengan memberikan petunjuk, mereka dapat menunjukkan masalah dan memicu pertengkaran di antara orang-orang. Implikasinya sangat merugikan.') ON CONFLICT (id) DO NOTHING;
