INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('113c761b-a537-4a1f-8d47-b1ff3dd38113', 'メッシが、移籍を示唆するコメントをしたようだ。', 'Sepertinya Messi melontarkan komentar yang mengisyaratkan transfernya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('87bebb5c-d2e1-4514-a807-af95e6886bde', 'vocabulary', '噴火', '噴火', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika gunung berapi meletus disertai api, maka terjadilah letusan yang sangat besar. Anda mungkin harus mulai berlari.', 'Ketika gunung berapi meletus disertai api, maka terjadilah letusan yang sangat besar. Anda mungkin harus mulai berlari.') ON CONFLICT (id) DO NOTHING;
