INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06994367-4096-4f95-9838-f025757d359e', 'vocabulary', '噴煙', '噴煙', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Terkadang gunung berapi meletus hanya dengan asap, bukan lava atau api. Itu disebut asap vulkanik.', 'Terkadang gunung berapi meletus hanya dengan asap, bukan lava atau api. Itu disebut asap vulkanik.') ON CONFLICT (id) DO NOTHING;
