INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06994367-4096-4f95-9838-f025757d359e', '噴煙を上げる桜島の写真を撮りました。', 'Saya mengambil gambar asap vulkanik yang membubung di atas Sakurajima.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8abde49d-5e52-4c7e-a157-0bf122efa177', 'vocabulary', '噴射', '噴射', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika sesuatu meletus dan mengeluarkan banyak air atau lava, ia akan keluar dalam aliran besar dan menyemprotkan segalanya.', 'Ketika sesuatu meletus dan mengeluarkan banyak air atau lava, ia akan keluar dalam aliran besar dan menyemprotkan segalanya.') ON CONFLICT (id) DO NOTHING;
