INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8abde49d-5e52-4c7e-a157-0bf122efa177', '催涙スプレーの噴射方法を教えてください。', 'Tolong tunjukkan saya cara menyemprotkan gas air mata.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c4ab91f6-9430-4702-9aba-aa7ced071125', 'vocabulary', '噴水', '噴水', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Air meletus dari air mancur. Terkadang letusannya besar dan terkadang kecil, namun letusannya selalu menyenangkan untuk dilihat dan dinikmati di musim panas.', 'Air meletus dari air mancur. Terkadang letusannya besar dan terkadang kecil, namun letusannya selalu menyenangkan untuk dilihat dan dinikmati di musim panas.') ON CONFLICT (id) DO NOTHING;
