INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c4ab91f6-9430-4702-9aba-aa7ced071125', 'あそこの噴水で待ち合わせをしましょう。', 'Mari kita bertemu di air mancur di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a6b91b6-96a1-47f1-befb-172c49e3cab5', 'vocabulary', '噴出', '噴出', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika sesuatu keluar dari pintu keluar, biasanya ia harus berjuang cukup keras untuk mencapai pintu keluar tersebut. Itu sebabnya ia akhirnya memuntahkan dan memancar ke mana-mana.', 'Ketika sesuatu keluar dari pintu keluar, biasanya ia harus berjuang cukup keras untuk mencapai pintu keluar tersebut. Itu sebabnya ia akhirnya memuntahkan dan memancar ke mana-mana.') ON CONFLICT (id) DO NOTHING;
