INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d7e201b1-c9bb-484e-9a11-9fa400fd40f2', 'vocabulary', '孤児', '孤児', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Sayangnya, seorang anak yatim piatu tetaplah yatim piatu.', 'Sayangnya, seorang anak yatim piatu tetaplah yatim piatu.') ON CONFLICT (id) DO NOTHING;
