INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5950e8af-4fee-4df0-b6e2-5830aec487d0', '今は孤島を舞台とした小説を書いています。', 'Saya sedang menulis novel berlatar pulau terpencil.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da871b36-6eae-4ec2-bd8c-6db67460eb7e', 'vocabulary', '孤独', '孤独', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Seorang anak yatim piatu yang sendirian terjebak dalam dunia isolasi dan kesepian. Tidak memiliki orang tua saja sudah cukup sulit, namun tidak memiliki orang lain bahkan lebih menyedihkan.', 'Seorang anak yatim piatu yang sendirian terjebak dalam dunia isolasi dan kesepian. Tidak memiliki orang tua saja sudah cukup sulit, namun tidak memiliki orang lain bahkan lebih menyedihkan.') ON CONFLICT (id) DO NOTHING;
