INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da871b36-6eae-4ec2-bd8c-6db67460eb7e', 'ずっと孤独な人生を送ってきたんです。', 'Saya selalu menjalani kehidupan yang terisolasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3276079d-4727-40f8-a5f3-a8d61d474af3', 'vocabulary', '孤立', '孤立', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Seorang anak yatim piatu berdiri sendirian di jalanan. Anak yatim piatu tidak mempunyai orang tua dan seringkali mereka juga tidak punya teman. Sungguh menyedihkan.', 'Seorang anak yatim piatu berdiri sendirian di jalanan. Anak yatim piatu tidak mempunyai orang tua dan seringkali mereka juga tidak punya teman. Sungguh menyedihkan.') ON CONFLICT (id) DO NOTHING;
