INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3276079d-4727-40f8-a5f3-a8d61d474af3', 'ある事件があって、職場で孤立してしまったんです。', 'Insiden tersebut terisolasi dari tempat kerja mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ff03c5db-b6e0-4af5-aec8-79e548bc58a5', 'vocabulary', '怠惰', '怠惰', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Orang yang malas dan malas dirundung kemalasan yang tidak ada habisnya. Mereka tidak pernah bangun. Mereka hanya bergerak perlahan di sekitar lantai.', 'Orang yang malas dan malas dirundung kemalasan yang tidak ada habisnya. Mereka tidak pernah bangun. Mereka hanya bergerak perlahan di sekitar lantai.') ON CONFLICT (id) DO NOTHING;
