INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0636512e-1dda-4f6f-80e3-adba8a3d50eb', 'vocabulary', '恒星', '恒星', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Bintang konstan adalah bintang yang tetap berada di satu tempat. Itu hanyalah bintang biasa, seperti bintang utara atau matahari kita, bukan komet atau asteroid.', 'Bintang konstan adalah bintang yang tetap berada di satu tempat. Itu hanyalah bintang biasa, seperti bintang utara atau matahari kita, bukan komet atau asteroid.') ON CONFLICT (id) DO NOTHING;
