INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f73510b8-f0ae-45ac-9b9b-3e23947d205e', 'vocabulary', '恒常', '恒常', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Hal-hal normal yang konstan dalam hidup Anda juga konstan. Jika Anda biasanya selalu melakukannya, mungkin hal tersebut juga merupakan bagian dari rutinitas Anda sehari-hari.', 'Hal-hal normal yang konstan dalam hidup Anda juga konstan. Jika Anda biasanya selalu melakukannya, mungkin hal tersebut juga merupakan bagian dari rutinitas Anda sehari-hari.') ON CONFLICT (id) DO NOTHING;
