INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e66784cb-8bbe-4407-9938-e1b7d2d7af9d', 'vocabulary', '我慢', '我慢', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Aku sering diejek, tapi itu membuatku memiliki daya tahan yang sangat kuat. Kalau kamu sering dimarahi, katakan saja, "Aku punya kesabaran dan pengendalian diri, dan aku bisa melewati ini."', 'Aku sering diejek, tapi itu membuatku memiliki daya tahan yang sangat kuat. Kalau kamu sering dimarahi, katakan saja, "Aku punya kesabaran dan pengendalian diri, dan aku bisa melewati ini."') ON CONFLICT (id) DO NOTHING;
