INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('65ae0ff9-5491-4a5d-9338-b1482da96777', 'vocabulary', '自慢', '自慢', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Anda mengejek semua orang kecuali diri Anda sendiri karena Anda memiliki begitu banyak harga diri. Saat kamu berbicara tentang dirimu sendiri kamu hanya bermegah karena tidak ada yang perlu dicemooh. Menurut Anda, betapa hebatnya diri Anda.', 'Anda mengejek semua orang kecuali diri Anda sendiri karena Anda memiliki begitu banyak harga diri. Saat kamu berbicara tentang dirimu sendiri kamu hanya bermegah karena tidak ada yang perlu dicemooh. Menurut Anda, betapa hebatnya diri Anda.') ON CONFLICT (id) DO NOTHING;
