INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b097ca6f-58a8-4fe8-b615-7c91f60ddb5b', 'vocabulary', '緩慢', '緩慢', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika kemalasan Anda hilang, Anda tidak dapat menguasai diri dan akhirnya bergerak sangat lambat. Lengan dan kaki Anda menjadi kendur dan gerakan Anda menjadi lamban.', 'Ketika kemalasan Anda hilang, Anda tidak dapat menguasai diri dan akhirnya bergerak sangat lambat. Lengan dan kaki Anda menjadi kendur dan gerakan Anda menjadi lamban.') ON CONFLICT (id) DO NOTHING;
