INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('461ed40d-dbbc-464a-b033-e7a6d5a7c28f', 'vocabulary', '怠慢', '怠慢', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Anda mengabaikan segala sesuatu di sekitar Anda karena Anda malas dengan kemalasan. Itu terlalu malas untuk satu orang sehingga Anda rentan terhadap kelalaian dan penundaan. Anda pasti tidak bisa mengurus segala sesuatunya jika Anda sedang malas ini.', 'Anda mengabaikan segala sesuatu di sekitar Anda karena Anda malas dengan kemalasan. Itu terlalu malas untuk satu orang sehingga Anda rentan terhadap kelalaian dan penundaan. Anda pasti tidak bisa mengurus segala sesuatunya jika Anda sedang malas ini.') ON CONFLICT (id) DO NOTHING;
