INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4f24aa02-d54a-459c-b642-07bc3ef153b0', 'vocabulary', '慢性', '慢性', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Jika sudah menjadi sifat Anda untuk mengejek orang lain, itu akan menjadi masalah kronis. Anda tidak dapat mengubah sesuatu yang sudah tertanam dalam diri Anda, dan itu memalukan, karena Anda brengsek.', 'Jika sudah menjadi sifat Anda untuk mengejek orang lain, itu akan menjadi masalah kronis. Anda tidak dapat mengubah sesuatu yang sudah tertanam dalam diri Anda, dan itu memalukan, karena Anda brengsek.') ON CONFLICT (id) DO NOTHING;
