INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('76a8d784-b862-4b5a-868f-17633eb830fa', 'vocabulary', '抱擁', '抱擁', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Pelukan dan pelukan hampir sama. Jadi, Anda tetap akan merangkul dan memeluk orang lain!', 'Pelukan dan pelukan hampir sama. Jadi, Anda tetap akan merangkul dan memeluk orang lain!') ON CONFLICT (id) DO NOTHING;
