INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f157abcb-2c7d-498c-a624-dc89edb87337', 'vocabulary', '擁立', '擁立', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Berdirilah di belakang seseorang dan peluklah dia. Begitulah cara Anda menunjukkan kepada mereka bahwa Anda mendukung dan mendukung mereka. Lakukan ini pada politisi lokal Anda.', 'Berdirilah di belakang seseorang dan peluklah dia. Begitulah cara Anda menunjukkan kepada mereka bahwa Anda mendukung dan mendukung mereka. Lakukan ini pada politisi lokal Anda.') ON CONFLICT (id) DO NOTHING;
