INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ddd797f1-6b24-4d12-bfa8-557f2ed0ef99', 'vocabulary', '擁する', '擁する', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Melakukan pelukan berarti memeluk orang atau hewan tersebut. Anda memeluknya dan kemudian melarikan diri dengannya. Itu milikmu sekarang.', 'Melakukan pelukan berarti memeluk orang atau hewan tersebut. Anda memeluknya dan kemudian melarikan diri dengannya. Itu milikmu sekarang.') ON CONFLICT (id) DO NOTHING;
