INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('847fc554-45d3-4884-9784-45a9d7a04036', 'vocabulary', '殊勝', '殊勝', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika Anda menang dengan sangat baik, semua orang akan menganggap Anda mengagumkan. Jadi keluarlah dan menangkan!', 'Ketika Anda menang dengan sangat baik, semua orang akan menganggap Anda mengagumkan. Jadi keluarlah dan menangkan!') ON CONFLICT (id) DO NOTHING;
