INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('34cb406c-c366-4b39-9d06-a7b320169352', 'vocabulary', '没', '没', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika tumbuhan atau hewan mati, Anda harus membuangnya. Anda tidak bisa membiarkannya begitu saja di rumah setelah kematian, itu aneh.', 'Ketika tumbuhan atau hewan mati, Anda harus membuangnya. Anda tidak bisa membiarkannya begitu saja di rumah setelah kematian, itu aneh.') ON CONFLICT (id) DO NOTHING;
