INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7fb3290b-730d-45c0-9e6f-3a2a7c173e7c', 'vocabulary', '沈没', '沈没', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Jika Anda tenggelam dan mati, itu karena Anda tenggelam di laut atau kolam atau apalah. Penting untuk diperhatikan bahwa Anda akan terjatuh agar Anda tidak mati seperti itu.', 'Jika Anda tenggelam dan mati, itu karena Anda tenggelam di laut atau kolam atau apalah. Penting untuk diperhatikan bahwa Anda akan terjatuh agar Anda tidak mati seperti itu.') ON CONFLICT (id) DO NOTHING;
