INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3eaaf512-1612-404e-b610-4ec2ed67181e', 'vocabulary', '日没', '日没', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Pada malam hari matahari mati saat matahari terbenam. Jangan khawatir, ia akan terlahir kembali besok pagi saat matahari terbit dan semuanya akan baik-baik saja.', 'Pada malam hari matahari mati saat matahari terbenam. Jangan khawatir, ia akan terlahir kembali besok pagi saat matahari terbit dan semuanya akan baik-baik saja.') ON CONFLICT (id) DO NOTHING;
