INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dedac86-6e1f-40a7-b8a5-4a15654a3bfe', '整形手術で二重の埋没手術をしました。', 'Saya menjalani operasi kelopak mata ganda dengan operasi plastik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c5cd0255-c8a2-4395-8445-f7df9cd06d54', 'vocabulary', '出没', '出没', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Hewan keluar dari pegunungan menuju tanah Anda dan sepertinya tidak pernah mati! Mereka akhirnya sering muncul di kebun Anda, memakan semua wortel dan semangka lezat Anda, dan kemudian keluar kembali ke perbukitan. Mereka memenuhi rumah Anda sekarang dan Anda tidak tahu harus berbuat apa!', 'Hewan keluar dari pegunungan menuju tanah Anda dan sepertinya tidak pernah mati! Mereka akhirnya sering muncul di kebun Anda, memakan semua wortel dan semangka lezat Anda, dan kemudian keluar kembali ke perbukitan. Mereka memenuhi rumah Anda sekarang dan Anda tidak tahu harus berbuat apa!') ON CONFLICT (id) DO NOTHING;
