INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c5cd0255-c8a2-4395-8445-f7df9cd06d54', '日本各地でクマが大量出没している。', 'Beruang sering muncul dalam jumlah besar di seluruh Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3a17d98a-dca5-437a-8b93-26e5356b175e', 'vocabulary', '没収', '没収', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ketika Anda mendapatkan sesuatu yang seolah-olah orang tersebut telah meninggal, itu disebut penyitaan atau penyitaan. Mungkin jika mereka masih hidup, menurut Anda, mereka tidak akan membiarkan saya mengambilnya. Ya, mereka masih hidup jadi itu milik mereka dan Anda tidak bisa menyimpannya selamanya.', 'Ketika Anda mendapatkan sesuatu yang seolah-olah orang tersebut telah meninggal, itu disebut penyitaan atau penyitaan. Mungkin jika mereka masih hidup, menurut Anda, mereka tidak akan membiarkan saya mengambilnya. Ya, mereka masih hidup jadi itu milik mereka dan Anda tidak bisa menyimpannya selamanya.') ON CONFLICT (id) DO NOTHING;
