INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d3d1ffd7-bfbc-421e-bfb8-3572bcea08cc', 'vocabulary', '陳列', '陳列', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Pameran sesuatu secara berturut-turut hanya terjadi di pameran. Semuanya akan berjejer rapi dipajang untuk Anda di sana.', 'Pameran sesuatu secara berturut-turut hanya terjadi di pameran. Semuanya akan berjejer rapi dipajang untuk Anda di sana.') ON CONFLICT (id) DO NOTHING;
