INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71d106c9-eabb-455e-b91c-d364f03c4bd2', 'vocabulary', '陳列室', '陳列室', 1, '557bbf48-2af8-4a64-a525-74a7c810dd65', 'Ruangan tempat Anda memamerkan barang-barang secara berurutan adalah ruang pamer. Mungkin ada mobil yang berjejer, atau perahu, atau kucing porselen kecil! Bagaimanapun, mereka membutuhkan ruang pamer besar yang bagus untuk memamerkannya.', 'Ruangan tempat Anda memamerkan barang-barang secara berurutan adalah ruang pamer. Mungkin ada mobil yang berjejer, atau perahu, atau kucing porselen kecil! Bagaimanapun, mereka membutuhkan ruang pamer besar yang bagus untuk memamerkannya.') ON CONFLICT (id) DO NOTHING;
