INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b2233f78-2689-4cff-a858-406c44ed064f', 'vocabulary', '丹念', '丹念', 1, '6670de59-0841-4bc1-a510-dbc86c44ee42', 'Jika tidak ingin pikiran Anda berubah warna, Anda perlu rajin belajar, belajar, dan mengalami hal-hal baru. Tanpa ketekunan, otakmu dan semua pikiranmu akan menjadi tua, basi, berubah warna menjadi kotor dan berkarat.', 'Jika tidak ingin pikiran Anda berubah warna, Anda perlu rajin belajar, belajar, dan mengalami hal-hal baru. Tanpa ketekunan, otakmu dan semua pikiranmu akan menjadi tua, basi, berubah warna menjadi kotor dan berkarat.') ON CONFLICT (id) DO NOTHING;
