INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43dd997b-373b-48ce-a81a-46b0840fb8b1', 'vocabulary', '批准', '批准', 1, '6670de59-0841-4bc1-a510-dbc86c44ee42', 'Kalau hanya ada semi kritik terhadap suatu undang-undang, pengesahan masih mungkin dilakukan. Hanya jika semua orang mengkritik maka perjanjian tersebut tidak akan diratifikasi.', 'Kalau hanya ada semi kritik terhadap suatu undang-undang, pengesahan masih mungkin dilakukan. Hanya jika semua orang mengkritik maka perjanjian tersebut tidak akan diratifikasi.') ON CONFLICT (id) DO NOTHING;
