INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ea6ebe41-2033-4da5-89be-49e418b3a4b8', 'vocabulary', '真鯉', '真鯉', 1, '6670de59-0841-4bc1-a510-dbc86c44ee42', 'Faktanya, ikan mas biasanya adalah ikan mas hitam. Yang berwarna tidak umum, orang hanya berharap demikian.', 'Faktanya, ikan mas biasanya adalah ikan mas hitam. Yang berwarna tidak umum, orang hanya berharap demikian.') ON CONFLICT (id) DO NOTHING;
