INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('235baee5-5b8c-45c7-9688-ab3b01be4bde', 'vocabulary', '洗浄剤', '洗浄剤', 1, '6670de59-0841-4bc1-a510-dbc86c44ee42', 'Anda telah mengetahui bahwa kata 洗浄 berarti "mencuci". Jadi saat Anda mencuci cucian, Anda harus menggunakan deterjen dengan takaran yang tepat untuk memastikan cucian dicuci dengan benar. Jika Anda menggunakan terlalu sedikit deterjen, baunya masih akan tetap ada, tetapi jika Anda menggunakan terlalu banyak deterjen, mesin cuci akan meledak dengan gelembung-gelembung! Berhati-hatilah ya, jangan berakhir seperti saya.', 'Anda telah mengetahui bahwa kata 洗浄 berarti "mencuci". Jadi saat Anda mencuci cucian, Anda harus menggunakan deterjen dengan takaran yang tepat untuk memastikan cucian dicuci dengan benar. Jika Anda menggunakan terlalu sedikit deterjen, baunya masih akan tetap ada, tetapi jika Anda menggunakan terlalu banyak deterjen, mesin cuci akan meledak dengan gelembung-gelembung! Berhati-hatilah ya, jangan berakhir seperti saya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('235baee5-5b8c-45c7-9688-ab3b01be4bde', 'Deterjen', true) ON CONFLICT DO NOTHING;
