INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68cdd986-53d2-4bc6-89c8-b46e08648bd5', 'vocabulary', '勲章', '勲章', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Untuk menunjukkan bahwa Anda mempunyai prestasi dalam satu babak kehidupan Anda, Anda akan diberi hiasan atau medali. Apalagi jika Anda seorang tentara atau atlet.', 'Untuk menunjukkan bahwa Anda mempunyai prestasi dalam satu babak kehidupan Anda, Anda akan diberi hiasan atau medali. Apalagi jika Anda seorang tentara atau atlet.') ON CONFLICT (id) DO NOTHING;
