INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e57959b0-a0ae-4f19-82fc-8ad7f18286a1', 'vocabulary', '叙事詩', '叙事詩', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Puisi yang menggambarkan sesuatu adalah puisi epik. Ini untuk puisi-puisi yang sangat panjang dan deskriptif yang terpaksa Anda baca di kelas bahasa Inggris.', 'Puisi yang menggambarkan sesuatu adalah puisi epik. Ini untuk puisi-puisi yang sangat panjang dan deskriptif yang terpaksa Anda baca di kelas bahasa Inggris.') ON CONFLICT (id) DO NOTHING;
