INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3976d0ba-d14b-4d6f-a06f-e31410bfee11', 'vocabulary', '叙述', '叙述', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Gambarkan lingkungan sekitar Anda dengan menyebutkan semua yang Anda lihat. Apa yang baru saja Anda katakan adalah deskripsi.', 'Gambarkan lingkungan sekitar Anda dengan menyebutkan semua yang Anda lihat. Apa yang baru saja Anda katakan adalah deskripsi.') ON CONFLICT (id) DO NOTHING;
