INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('61e0e19f-478d-4914-823a-bfa989ac7fd8', 'vocabulary', '時期尚早', '時期尚早', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Anda telah mengetahui bahwa kata 時期 berarti "periode waktu", jadi jika Anda menambahkannya lebih jauh dan lebih awal, itu berarti sesuatu telah terjadi sebelumnya. Artinya prematur.', 'Anda telah mengetahui bahwa kata 時期 berarti "periode waktu", jadi jika Anda menambahkannya lebih jauh dan lebih awal, itu berarti sesuatu telah terjadi sebelumnya. Artinya prematur.') ON CONFLICT (id) DO NOTHING;
