INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0e09cb70-68a5-4695-880a-f00a767d5c4f', 'vocabulary', '庶務', '庶務', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Semua tugas adalah bagian dari urusan umum rakyat. Itu sebabnya mereka bersifat umum, merekalah yang melibatkan semua orang.', 'Semua tugas adalah bagian dari urusan umum rakyat. Itu sebabnya mereka bersifat umum, merekalah yang melibatkan semua orang.') ON CONFLICT (id) DO NOTHING;
