INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba672731-07dd-4f44-ab4c-096ba2a08039', 'vocabulary', '愚', '愚', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Karena kata ini merupakan kata benda dan kata sifat na, kata ini juga bisa berarti kebodohan dan kebodohan.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Karena kata ini merupakan kata benda dan kata sifat na, kata ini juga bisa berarti kebodohan dan kebodohan.') ON CONFLICT (id) DO NOTHING;
