INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f872d0f2-9d07-4f3c-a7c0-253b75f61861', 'vocabulary', '実践', '実践', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Sejujurnya, latihan adalah latihan. Anda tidak bisa hanya menggantinya dengan sesuatu yang lain. Anda hanya akan membuat kemajuan dengan latihan nyata! Kamu bisa!', 'Sejujurnya, latihan adalah latihan. Anda tidak bisa hanya menggantinya dengan sesuatu yang lain. Anda hanya akan membuat kemajuan dengan latihan nyata! Kamu bisa!') ON CONFLICT (id) DO NOTHING;
