INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('87b8b425-c16f-4bb4-b8fe-e25ca994836e', 'vocabulary', '逸話', '逸話', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Bagaimana Anda menyimpang dari pembicaraan normal? Dengan banyak anekdot. Jika Anda menambahkan cukup banyak kata-kata tersebut ke dalam percakapan Anda, tidak seorang pun akan dapat melacak apa yang Anda bicarakan sejak awal.', 'Bagaimana Anda menyimpang dari pembicaraan normal? Dengan banyak anekdot. Jika Anda menambahkan cukup banyak kata-kata tersebut ke dalam percakapan Anda, tidak seorang pun akan dapat melacak apa yang Anda bicarakan sejak awal.') ON CONFLICT (id) DO NOTHING;
