INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dddcf8f1-5dea-43b8-9474-bb628e6f8b61', 'vocabulary', '秀逸', '秀逸', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Apakah Anda unggul ketika Anda menyimpang dari norma? Kalau begitu, kamu diciptakan untuk menjadi yang terbaik, kawan!', 'Apakah Anda unggul ketika Anda menyimpang dari norma? Kalau begitu, kamu diciptakan untuk menjadi yang terbaik, kawan!') ON CONFLICT (id) DO NOTHING;
