INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d85e085-08a1-4a7b-9ca4-e95796044399', 'vocabulary', '逸らす', '逸らす', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menyimpang, jadi versi verbanya adalah berpaling atau menghindar.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menyimpang, jadi versi verbanya adalah berpaling atau menghindar.') ON CONFLICT (id) DO NOTHING;
