INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('82ed24f8-bdb7-4988-a587-08023dc09e65', 'vocabulary', '応酬', '応酬', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Bayar kembali apa yang dipinjamkan seseorang kepada Anda sebagai tanggapan atas mereka yang telah meminjamkan uang kepada ANDA, dan Anda berdua akan menukarkan uang.', 'Bayar kembali apa yang dipinjamkan seseorang kepada Anda sebagai tanggapan atas mereka yang telah meminjamkan uang kepada ANDA, dan Anda berdua akan menukarkan uang.') ON CONFLICT (id) DO NOTHING;
