INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('82ed24f8-bdb7-4988-a587-08023dc09e65', '両チームのファンからやじの応酬が続いた。', 'Fans kedua tim terus saling mengejek.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed93a630-8e75-4a7d-a9b1-0952bb9d89df', 'vocabulary', '報酬', '報酬', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Balas orang-orang atas berita yang mereka sampaikan kepada Anda dengan memberi penghargaan kepada mereka! Setiap orang berhak mendapatkan kompensasi atas waktu yang mereka habiskan untuk menyampaikan informasi kepada Anda.', 'Balas orang-orang atas berita yang mereka sampaikan kepada Anda dengan memberi penghargaan kepada mereka! Setiap orang berhak mendapatkan kompensasi atas waktu yang mereka habiskan untuk menyampaikan informasi kepada Anda.') ON CONFLICT (id) DO NOTHING;
