INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed93a630-8e75-4a7d-a9b1-0952bb9d89df', 'このプロジェクトが成功すれば、報酬として、クリステンがほっぺにキスをしてくれます。', 'Jika proyek ini sukses, Kristen akan memberiku ciuman di pipi sebagai hadiahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('135b80c0-03fc-415c-9b08-30f7c6c616c2', 'vocabulary', '酷', '酷', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Sesuatu yang kejam cenderung keras, parah, dan mengerikan. Dan tentu saja, masih kejam untuk melakukan booting.', 'Sesuatu yang kejam cenderung keras, parah, dan mengerikan. Dan tentu saja, masih kejam untuk melakukan booting.') ON CONFLICT (id) DO NOTHING;
