INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('135b80c0-03fc-415c-9b08-30f7c6c616c2', 'それをあいつに頼むのは、ちょっと酷すぎやしないか。', 'Meminta orang itu untuk itu agak terlalu kasar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('135b80c0-03fc-415c-9b08-30f7c6c616c2', 'あれは、みんな酷な実践方法だったと言っていた。', 'Semua orang mengatakan itu adalah cara berlatih yang parah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8a25c501-7148-4155-8536-15ef5c3253da', 'vocabulary', '過酷', '過酷', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Bos Anda melampaui kekejamannya yang normal dan menghujani kepala Anda dengan kekerasan. Anda memiliki hal lain yang harus dilakukan akhir pekan ini dan sekarang Anda harus menyelesaikannya? Keras...', 'Bos Anda melampaui kekejamannya yang normal dan menghujani kepala Anda dengan kekerasan. Anda memiliki hal lain yang harus dilakukan akhir pekan ini dan sekarang Anda harus menyelesaikannya? Keras...') ON CONFLICT (id) DO NOTHING;
