INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a25c501-7148-4155-8536-15ef5c3253da', '彼らは、不当に過酷な労働を強いられています。', 'Mereka dipaksa melakukan pekerjaan kasar yang sangat berat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('34259c58-2b05-42a5-ade2-37acaeb8dc9c', 'vocabulary', '酷使', '酷使', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Jika Anda menggunakan sesuatu dengan cara yang kejam, itu disebut eksploitasi. Anda mungkin akan menggunakannya secara berlebihan, jika terus begini. Hentikan itu, kawan.', 'Jika Anda menggunakan sesuatu dengan cara yang kejam, itu disebut eksploitasi. Anda mungkin akan menggunakannya secara berlebihan, jika terus begini. Hentikan itu, kawan.') ON CONFLICT (id) DO NOTHING;
