INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('34259c58-2b05-42a5-ade2-37acaeb8dc9c', '労働者を酷使するブラック企業をこのまま野放しにしていてもいいんですか。', 'Menurut Anda, apakah boleh membiarkan perusahaan kulit hitam yang mengeksploitasi pekerjanya terus mengurus dirinya sendiri?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('570d0594-cef8-4bae-a880-70c9f293aede', 'vocabulary', '酷似', '酷似', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Jika Anda mirip dengan seseorang yang kejam, Anda mirip dengan mereka. Mungkin kamu juga sangat jahat. Saya kira hanya Anda yang bisa mengetahuinya. Tapi kamu memang terlihat seperti pria lain itu...', 'Jika Anda mirip dengan seseorang yang kejam, Anda mirip dengan mereka. Mungkin kamu juga sangat jahat. Saya kira hanya Anda yang bisa mengetahuinya. Tapi kamu memang terlihat seperti pria lain itu...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('570d0594-cef8-4bae-a880-70c9f293aede', 'Kemiripan', true) ON CONFLICT DO NOTHING;
