INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('570d0594-cef8-4bae-a880-70c9f293aede', '三冊の本は、どれも内容が酷似している。', 'Semua isi dalam ketiga jilid buku tersebut mirip satu sama lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('55957a59-72a4-4cf3-b468-050317948e0f', 'vocabulary', '酷い', '酷い', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari kejam? Kejam atau mengerikan.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari kejam? Kejam atau mengerikan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('55957a59-72a4-4cf3-b468-050317948e0f', 'Kejam', true) ON CONFLICT DO NOTHING;
