INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55957a59-72a4-4cf3-b468-050317948e0f', '彼女の作った料理は、どれも酷い味だった。', 'Semua makanan yang dia buat terasa tidak enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55957a59-72a4-4cf3-b468-050317948e0f', '自分の彼女によくもそんな酷い事が言えるね。', 'Bagaimana kamu bisa mengatakan hal yang begitu kejam kepada pacarmu sendiri?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55957a59-72a4-4cf3-b468-050317948e0f', 'こんなに暑さが酷くなるって分かっていたら、この国に引っ越していなかったよ。', 'Jika saya tahu panasnya akan separah ini, saya tidak akan pindah ke negara ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f39da039-2e89-47f0-9ff2-ab6a9ba0d2ce', 'vocabulary', '酷暑', '酷暑', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Cuaca panas yang kejam adalah cuaca yang sulit untuk ditangani oleh siapa pun. Ini sangat panas. Terdampar di gurun pada musim panas, panas.', 'Cuaca panas yang kejam adalah cuaca yang sulit untuk ditangani oleh siapa pun. Ini sangat panas. Terdampar di gurun pada musim panas, panas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f39da039-2e89-47f0-9ff2-ab6a9ba0d2ce', 'Panas Intens', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f39da039-2e89-47f0-9ff2-ab6a9ba0d2ce', 'こくしょ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f39da039-2e89-47f0-9ff2-ab6a9ba0d2ce', '今年の夏は、酷暑が続きました。', 'Musim panas ini panas yang menyengat terus berlanjut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1629b63-4721-46cf-89b3-8c5862b9e68e', 'vocabulary', '残酷', '残酷', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Sisa dari kekejaman adalah kekejaman. Tampaknya selalu ada banyak hal yang bisa dilakukan, dan itu agak menyebalkan.', 'Sisa dari kekejaman adalah kekejaman. Tampaknya selalu ada banyak hal yang bisa dilakukan, dan itu agak menyebalkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1629b63-4721-46cf-89b3-8c5862b9e68e', 'Kekejaman', true) ON CONFLICT DO NOTHING;
