INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a1629b63-4721-46cf-89b3-8c5862b9e68e', 'ざんこく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1629b63-4721-46cf-89b3-8c5862b9e68e', '私は、ひどく残酷な決断を迫られました。', 'Saya didesak untuk mengambil keputusan yang sangat kejam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('429eeea7-0d41-4348-9223-c8e87949ace4', 'vocabulary', '冷酷', '冷酷', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Orang keren yang kejam lebih kejam dan berhati dingin daripada orang kejam pada umumnya. Mungkin karena mereka selalu kedinginan dan itu membuat mereka marah. Sebaiknya kamu menjauhi orang-orang seperti itu.', 'Orang keren yang kejam lebih kejam dan berhati dingin daripada orang kejam pada umumnya. Mungkin karena mereka selalu kedinginan dan itu membuat mereka marah. Sebaiknya kamu menjauhi orang-orang seperti itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('429eeea7-0d41-4348-9223-c8e87949ace4', 'Kejam', true) ON CONFLICT DO NOTHING;
