INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('429eeea7-0d41-4348-9223-c8e87949ace4', 'あなたのこと、ずっと冷酷な人だと思っていました。', 'Saya selalu berpikir Anda adalah orang yang kejam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3c2edc9a-9e90-4b23-b04e-d09d33659436', 'vocabulary', '酷評', '酷評', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Evaluasi dengan cara yang kejam sehingga Anda dapat memberikan kritik keras terhadap pesaing Anda! Ini bukan hal terbaik untuk dilakukan, dan tidak terlalu konstruktif bagi mereka, tapi itu akan membuat Anda terlihat lebih baik.', 'Evaluasi dengan cara yang kejam sehingga Anda dapat memberikan kritik keras terhadap pesaing Anda! Ini bukan hal terbaik untuk dilakukan, dan tidak terlalu konstruktif bagi mereka, tapi itu akan membuat Anda terlihat lebih baik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3c2edc9a-9e90-4b23-b04e-d09d33659436', 'Kritik Parah', true) ON CONFLICT DO NOTHING;
