INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8389a780-9fa2-4420-8a58-85d124f24579', 'vocabulary', '顕在', '顕在', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Jika tampaknya ada, maka itu mungkin hal yang nyata... Anda tahu, ada dan sebagainya. Itu seharusnya sudah cukup jelas.', 'Jika tampaknya ada, maka itu mungkin hal yang nyata... Anda tahu, ada dan sebagainya. Itu seharusnya sudah cukup jelas.') ON CONFLICT (id) DO NOTHING;
