INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a0ef2b13-a243-4aeb-9a1b-4e724f66f7b5', 'vocabulary', '顕著', '顕著', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Ketika seorang penulis muncul di depan umum, itu selalu luar biasa. Orang-orang biasanya tidak ingat ada orang di balik halaman-halaman itu, jadi ketika penulis sebenarnya muncul secara langsung, itu cukup mengejutkan.', 'Ketika seorang penulis muncul di depan umum, itu selalu luar biasa. Orang-orang biasanya tidak ingat ada orang di balik halaman-halaman itu, jadi ketika penulis sebenarnya muncul secara langsung, itu cukup mengejutkan.') ON CONFLICT (id) DO NOTHING;
