INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dea23ca2-0477-4c85-8b28-cc6b3715bb21', 'vocabulary', '無報酬', '無報酬', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Anda sudah mengetahui bahwa 報酬 berarti "kompensasi", jadi menambahkan bukan berarti orang yang bekerja tidak dibayar alias bekerja tanpa bayaran.', 'Anda sudah mengetahui bahwa 報酬 berarti "kompensasi", jadi menambahkan bukan berarti orang yang bekerja tidak dibayar alias bekerja tanpa bayaran.') ON CONFLICT (id) DO NOTHING;
