INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dea23ca2-0477-4c85-8b28-cc6b3715bb21', '無報酬でもかまいませんよ。', 'Tidak ada bayaran, tapi saya tidak keberatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f6a38ece-839e-4716-9cd2-8711717dda1d', 'vocabulary', '諒一郎', '諒一郎', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Jika kamu hanya memahami satu orang, jadikanlah pria itu Ryoichiro.', 'Jika kamu hanya memahami satu orang, jadikanlah pria itu Ryoichiro.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f6a38ece-839e-4716-9cd2-8711717dda1d', 'Ryoichiro', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f6a38ece-839e-4716-9cd2-8711717dda1d', 'りょういちろう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6a38ece-839e-4716-9cd2-8711717dda1d', '諒一郎って、あだ名とかあるの？', 'Ryoichiro, apakah kamu punya nama panggilan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6a38ece-839e-4716-9cd2-8711717dda1d', '諒一郎君と付き合うことになったんだ。', 'Aku sudah mulai pacaran dengan Ryoichiro-kun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6a38ece-839e-4716-9cd2-8711717dda1d', '諒一郎は今、外出中です。', 'Ryoichiro sedang keluar sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e31d4ce9-e3ce-4685-87d6-c1e51d76d26d', 'vocabulary', '莉子', '莉子', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Anak melati adalah salah satu cara penulisan nama anak perempuan Riko. Bayangkan membuat seorang anak dari melati, dan memanggilnya Riko. Contoh orang yang bernama Riko termasuk bintang pop dan penyanyi Fukumoto Riko (福本 莉子) dan idola dan aktris Nakayama Riko (中山 莉子).', 'Anak melati adalah salah satu cara penulisan nama anak perempuan Riko. Bayangkan membuat seorang anak dari melati, dan memanggilnya Riko. Contoh orang yang bernama Riko termasuk bintang pop dan penyanyi Fukumoto Riko (福本 莉子) dan idola dan aktris Nakayama Riko (中山 莉子).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e31d4ce9-e3ce-4685-87d6-c1e51d76d26d', 'Riko', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e31d4ce9-e3ce-4685-87d6-c1e51d76d26d', 'りこ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e31d4ce9-e3ce-4685-87d6-c1e51d76d26d', '今度、莉子ちゃんと韓国旅行に行く予定なんだよね。', 'Aku berencana melakukan perjalanan ke Korea bersama Riko-chan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e31d4ce9-e3ce-4685-87d6-c1e51d76d26d', '莉子って、ちょっとぶりっ子じゃない？', 'Riko bertingkah seperti gadis yang baik, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e31d4ce9-e3ce-4685-87d6-c1e51d76d26d', 'うちの莉子が、ご迷惑をおかけしました。', 'Saya minta maaf atas masalah yang disebabkan oleh Riko kami kepada Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'vocabulary', '駿馬', '駿馬', 1, 'bee85e03-be73-4ac7-ab45-0203a5e5493e', 'Kuda cepat adalah kuda yang cepat, dan kuda yang bagus. Kata ini tidak terlalu umum, namun muncul dalam konteks pacuan kuda, dan penulisan kreatif.', 'Kuda cepat adalah kuda yang cepat, dan kuda yang bagus. Kata ini tidak terlalu umum, namun muncul dalam konteks pacuan kuda, dan penulisan kreatif.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'Kuda Cepat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'Fine Horse', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'しゅんめ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'しゅんば', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', '王は、自慢の駿馬に乗って姿を現した。', 'Raja muncul dengan menunggangi kuda cepatnya yang berharga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'その大名には、数々の駿馬が献じられた。', 'Daimyo dihadiahi sejumlah kuda yang bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('196bdfa9-5ce3-4c4b-8977-6ab9b170b600', 'とても良い毛並みの駿馬を一億円で落札した。', 'Dia berhasil mengajukan tawaran sebesar 100 juta yen untuk seekor kuda bagus dengan bulu yang sangat bagus.') ON CONFLICT DO NOTHING;
