INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8368963f-f793-4183-b454-3afb5d52de6f', 'vocabulary', '悠久', '悠久', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Kenyamanan yang berlangsung lama akhirnya berlangsung selamanya. Itu tidak pernah berakhir, dan mengapa harus demikian? Kamu sangat santai, kamu tidak mungkin bisa berhenti.', 'Kenyamanan yang berlangsung lama akhirnya berlangsung selamanya. Itu tidak pernah berakhir, dan mengapa harus demikian? Kamu sangat santai, kamu tidak mungkin bisa berhenti.') ON CONFLICT (id) DO NOTHING;
