INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8368963f-f793-4183-b454-3afb5d52de6f', '悠久な大自然で、人生について色々なことを考えてみました。', 'Saya memikirkan berbagai hal tentang kehidupan manusia dalam keabadian alam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('058a9d88-e509-405e-8d84-ea3aa51317f9', 'vocabulary', '悠長', '悠長', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Waktu luang yang panjang membuat segala sesuatu yang Anda lakukan menjadi santai dan lambat. Anda dapat melakukan tugas dengan kecepatan yang disengaja karena tidak ada yang terburu-buru. Dan Anda sudah seperti ini begitu lama, mengapa harus mencoba?', 'Waktu luang yang panjang membuat segala sesuatu yang Anda lakukan menjadi santai dan lambat. Anda dapat melakukan tugas dengan kecepatan yang disengaja karena tidak ada yang terburu-buru. Dan Anda sudah seperti ini begitu lama, mengapa harus mencoba?') ON CONFLICT (id) DO NOTHING;
