INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f7850fa3-05a3-4a7b-ac6f-6b7a72d76803', 'vocabulary', '愚痴', '愚痴', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Orang bodoh dan dungu akan banyak melontarkan keluhan-keluhan yang tidak berguna. Anda benar-benar tidak suka berada di dekat mereka karena mereka selalu mengomel tentang betapa tidak ada yang cukup baik sepanjang waktu. Tapi mereka benar-benar tidak mengerti.', 'Orang bodoh dan dungu akan banyak melontarkan keluhan-keluhan yang tidak berguna. Anda benar-benar tidak suka berada di dekat mereka karena mereka selalu mengomel tentang betapa tidak ada yang cukup baik sepanjang waktu. Tapi mereka benar-benar tidak mengerti.') ON CONFLICT (id) DO NOTHING;
