INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b18504c5-c688-4d8c-ad77-777fc4ae7a6a', 'vocabulary', '降伏', '降伏', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Membungkuk saat Anda turun ke wilayah musuh. Beginilah cara Anda harus menyerah jika ingin hidup. Jaga agar kepala Anda tetap tenang dan rendahkan diri dan turunlah ke barisan mereka.', 'Membungkuk saat Anda turun ke wilayah musuh. Beginilah cara Anda harus menyerah jika ingin hidup. Jaga agar kepala Anda tetap tenang dan rendahkan diri dan turunlah ke barisan mereka.') ON CONFLICT (id) DO NOTHING;
