INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b18504c5-c688-4d8c-ad77-777fc4ae7a6a', '絶対にあいつらを降伏させてみせる。', 'Saya membiarkan mereka menyerah tanpa syarat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fe93bbc3-16bc-44c1-a750-8e703d39c18f', 'vocabulary', '潜伏', '潜伏', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Tundukkan kepala Anda untuk menyembunyikan diri Anda lebih baik daripada sebelumnya. Jika Anda ingin bersembunyi, Anda harus tahu cara bersembunyi!', 'Tundukkan kepala Anda untuk menyembunyikan diri Anda lebih baik daripada sebelumnya. Jika Anda ingin bersembunyi, Anda harus tahu cara bersembunyi!') ON CONFLICT (id) DO NOTHING;
