INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c9bb912-c8cc-4bbb-a572-083b29cc41a0', 'vocabulary', '伏線', '伏線', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Hubungkan banyak hal dalam satu baris. Sesuatu sedang terjadi di sini. Anda tidak dapat menebaknya, tetapi Anda cukup yakin ini adalah pertanda sesuatu yang lain.', 'Hubungkan banyak hal dalam satu baris. Sesuatu sedang terjadi di sini. Anda tidak dapat menebaknya, tetapi Anda cukup yakin ini adalah pertanda sesuatu yang lain.') ON CONFLICT (id) DO NOTHING;
