INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a5fa5a5e-5917-415d-9986-e19427837b75', 'vocabulary', '伏兵', '伏兵', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Seorang prajurit hanya berbaring ketika hendak menyergap musuh! Jika Anda melihat beberapa tentara tergeletak di sana-sini, itu bukan karena mereka malas, melainkan karena mereka bersiap-siap menerkam!', 'Seorang prajurit hanya berbaring ketika hendak menyergap musuh! Jika Anda melihat beberapa tentara tergeletak di sana-sini, itu bukan karena mereka malas, melainkan karena mereka bersiap-siap menerkam!') ON CONFLICT (id) DO NOTHING;
