INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8d885933-e17a-47bc-8c04-f061ed3b0f76', 'vocabulary', '傍観', '傍観', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Di dekatnya ada pemandangan yang indah. Lihatlah saat matahari terbenam dan langit berubah warna. Anda akan menyerahkan segalanya untuk bisa menyaksikan hal semacam ini sepanjang waktu.', 'Di dekatnya ada pemandangan yang indah. Lihatlah saat matahari terbenam dan langit berubah warna. Anda akan menyerahkan segalanya untuk bisa menyaksikan hal semacam ini sepanjang waktu.') ON CONFLICT (id) DO NOTHING;
