INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5465ea7-2428-445c-b4b0-e4e566ebd06d', '警察は、犯罪捜査のために、通信の傍受を行うことがあります。', 'Polisi dapat melakukan pemantauan korespondensi untuk kepentingan penyelidikan kriminal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('498f9741-b9ad-4c59-a855-58d244aa9bc5', 'vocabulary', '奉仕', '奉仕', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Dedikasikan diri Anda untuk melakukan yang terbaik di sekolah dengan kehadiran yang sempurna! Begitulah cara Anda menunjukkan bahwa Anda benar-benar berdedikasi untuk belajar.', 'Dedikasikan diri Anda untuk melakukan yang terbaik di sekolah dengan kehadiran yang sempurna! Begitulah cara Anda menunjukkan bahwa Anda benar-benar berdedikasi untuk belajar.') ON CONFLICT (id) DO NOTHING;
