INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ff8e466-197e-4eed-bd25-d69703bb1ffa', 'vocabulary', '弥生', '弥生', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Kehidupan di Jepang meningkat pada tingkat tercepat selama Periode Yayoi. Ini adalah salah satu periode paling awal dalam sejarah Jepang yang kita ketahui! Anda harus mencarinya, jika Anda belum mengetahuinya.', 'Kehidupan di Jepang meningkat pada tingkat tercepat selama Periode Yayoi. Ini adalah salah satu periode paling awal dalam sejarah Jepang yang kita ketahui! Anda harus mencarinya, jika Anda belum mengetahuinya.') ON CONFLICT (id) DO NOTHING;
