INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c5092cb6-3bbf-4fad-82d1-b74ec73db093', 'vocabulary', '惜しむ', '惜しむ', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya hemat, jadi versi verbanya adalah berhemat atau hemat.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya hemat, jadi versi verbanya adalah berhemat atau hemat.') ON CONFLICT (id) DO NOTHING;
