INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c5092cb6-3bbf-4fad-82d1-b74ec73db093', 'お前がちょっとした手間を惜しんだために、全ての計画がおじゃんになったんだぞ！', 'Anda tidak akan meluangkan waktu sedikit pun sehingga semua rencana Anda gagal!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8450a4e2-d91d-40a6-bc75-de3a25135d57', 'vocabulary', '惜敗', '惜敗', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Tim Anda hampir memenangkan permainan tetapi Anda memutuskan untuk berhemat dengan tembakan Anda menjelang akhir dan itu mengakibatkan kegagalan, sehingga kalah dalam permainan jarak dekat. Jika Anda baru saja mengambil gambar itu, tim Anda mungkin akan menang. Kekalahan yang sangat disesalkan.', 'Tim Anda hampir memenangkan permainan tetapi Anda memutuskan untuk berhemat dengan tembakan Anda menjelang akhir dan itu mengakibatkan kegagalan, sehingga kalah dalam permainan jarak dekat. Jika Anda baru saja mengambil gambar itu, tim Anda mungkin akan menang. Kekalahan yang sangat disesalkan.') ON CONFLICT (id) DO NOTHING;
