INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8450a4e2-d91d-40a6-bc75-de3a25135d57', 'わが校は、惜敗でベスト8入りを逃しました。', 'Sekolah kami gagal masuk ke delapan besar karena kalah dalam pertandingan yang ketat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b15aff0c-adcf-4b54-8c57-98e2384d3b11', 'vocabulary', '憂国', '憂国', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Setiap kali sesuatu yang buruk terjadi pada negara Anda, rasakan kesedihan yang luar biasa bagi masyarakat sesama negara Anda. Ini adalah keprihatinan patriotik serius yang sedang Anda alami. Semoga saja Anda memanfaatkan kekhawatiran tersebut untuk sesuatu yang baik dan jangan terlalu terbawa suasana.', 'Setiap kali sesuatu yang buruk terjadi pada negara Anda, rasakan kesedihan yang luar biasa bagi masyarakat sesama negara Anda. Ini adalah keprihatinan patriotik serius yang sedang Anda alami. Semoga saja Anda memanfaatkan kekhawatiran tersebut untuk sesuatu yang baik dan jangan terlalu terbawa suasana.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b15aff0c-adcf-4b54-8c57-98e2384d3b11', 'Kepedulian Patriotik', true) ON CONFLICT DO NOTHING;
