INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b15aff0c-adcf-4b54-8c57-98e2384d3b11', '憂国の若きサムライたちよ、今こそ立ち上がれ！', 'Pejuang muda patriotisme, sekaranglah saatnya untuk bangkit!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bfbd4f80-be2b-488a-81cd-d35129f96eee', 'vocabulary', '憂慮', '憂慮', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Yang bisa Anda lakukan hanyalah mempertimbangkan kesedihan Anda dan bagaimana hal itu menghancurkan hidup Anda. Itu disebut kecemasan, dan ini bisa menjadi masalah nyata. Anda akhirnya khawatir tentang segalanya, tapi jangan khawatir. Ada cara untuk melawannya. Anda akan baik-baik saja!', 'Yang bisa Anda lakukan hanyalah mempertimbangkan kesedihan Anda dan bagaimana hal itu menghancurkan hidup Anda. Itu disebut kecemasan, dan ini bisa menjadi masalah nyata. Anda akhirnya khawatir tentang segalanya, tapi jangan khawatir. Ada cara untuk melawannya. Anda akan baik-baik saja!') ON CONFLICT (id) DO NOTHING;
