INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79f0dc87-6a99-4184-b5b8-052d4c9b80b7', 'vocabulary', '素朴', '素朴', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Orang yang terbuat dari unsur sederhana juga cukup sederhana. Dan mereka juga bisa menjadi naif. Tapi begitulah cara mereka dibangun.', 'Orang yang terbuat dari unsur sederhana juga cukup sederhana. Dan mereka juga bisa menjadi naif. Tapi begitulah cara mereka dibangun.') ON CONFLICT (id) DO NOTHING;
