INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e21d5f89-2fcb-4383-8047-af85decdee8c', 'vocabulary', '癒着', '癒着', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Apa yang Anda kenakan untuk menyembuhkan cedera yang sangat serius? Sebuah adhesi. Oke, jadi Anda sebenarnya tidak memakai ini, tapi tubuh Anda membuatnya untuk dipakai di dalam tubuh Anda sehingga Anda bisa sembuh. Kerja bagus di dalam!', 'Apa yang Anda kenakan untuk menyembuhkan cedera yang sangat serius? Sebuah adhesi. Oke, jadi Anda sebenarnya tidak memakai ini, tapi tubuh Anda membuatnya untuk dipakai di dalam tubuh Anda sehingga Anda bisa sembuh. Kerja bagus di dalam!') ON CONFLICT (id) DO NOTHING;
