INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d3a71fac-fa93-45bd-8693-fd4d14e63d1d', 'vocabulary', '鎮魂', '鎮魂', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Untuk menenangkan jiwa, Anda harus memiliki jiwa yang tenang secara massal. Kemudian jiwa mereka akan berpindah ke kehidupan selanjutnya dan berhenti berkeliaran di sini, menghantui payung.', 'Untuk menenangkan jiwa, Anda harus memiliki jiwa yang tenang secara massal. Kemudian jiwa mereka akan berpindah ke kehidupan selanjutnya dan berhenti berkeliaran di sini, menghantui payung.') ON CONFLICT (id) DO NOTHING;
