INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d3a71fac-fa93-45bd-8693-fd4d14e63d1d', '星祭りは、平和を祈り、戦死者を鎮魂する儀式です。', 'Festival Bintang merupakan ritual berdoa bagi perdamaian dan memberikan ketenangan kepada orang-orang yang tewas dalam perang.') ON CONFLICT DO NOTHING;
