INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cee0b05e-2867-4ec7-ba72-671e259a1f43', 'vocabulary', '重鎮', '重鎮', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Jika Anda cukup menenangkan diri, Anda akan sama seperti semua pemimpin dunia lainnya saat ini. Mereka semua cukup terbius. Tenangkan diri Anda juga dan Anda akan menjadi seperti mereka!', 'Jika Anda cukup menenangkan diri, Anda akan sama seperti semua pemimpin dunia lainnya saat ini. Mereka semua cukup terbius. Tenangkan diri Anda juga dan Anda akan menjadi seperti mereka!') ON CONFLICT (id) DO NOTHING;
