INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2430d6ab-3b63-47ff-a336-dceb40f53257', 'vocabulary', '方向音痴', '方向音痴', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Ini merupakan gabungan kata 方向 dan 音痴. Jika indera Anda terhadap arah tidak peka terhadap nada, itu berarti Anda tidak mempunyai indra arah. Anda tersesat tidak peduli seberapa keras Anda mencoba.', 'Ini merupakan gabungan kata 方向 dan 音痴. Jika indera Anda terhadap arah tidak peka terhadap nada, itu berarti Anda tidak mempunyai indra arah. Anda tersesat tidak peduli seberapa keras Anda mencoba.') ON CONFLICT (id) DO NOTHING;
