INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c1d9ca8f-bf28-4e2a-86bb-4048a0c58536', 'vocabulary', '悪循環', '悪循環', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Anda sudah tahu bahwa 循環 berarti "sirkulasi" atau "siklus", jadi menambahkan kata buruk ke dalamnya akan menjadikannya lingkaran setan.', 'Anda sudah tahu bahwa 循環 berarti "sirkulasi" atau "siklus", jadi menambahkan kata buruk ke dalamnya akan menjadikannya lingkaran setan.') ON CONFLICT (id) DO NOTHING;
