INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ecac389-38b4-4a89-b4e6-c427c644d3ed', 'vocabulary', '惜しい', '惜しい', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari hemat? Ini sangat disesalkan atau berharga. Jika Anda terlalu hemat untuk membeli sesuatu, tindakan Anda akan disesalkan di kemudian hari ketika Anda menyadari bahwa Anda menginginkan barang itu. Jika Anda sangat berhemat dan hanya membeli satu barang saja, itu sangat berharga bagi Anda.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari hemat? Ini sangat disesalkan atau berharga. Jika Anda terlalu hemat untuk membeli sesuatu, tindakan Anda akan disesalkan di kemudian hari ketika Anda menyadari bahwa Anda menginginkan barang itu. Jika Anda sangat berhemat dan hanya membeli satu barang saja, itu sangat berharga bagi Anda.') ON CONFLICT (id) DO NOTHING;
