INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b31011ad-ca24-4940-8b16-e7163cce6997', 'vocabulary', '憂き目', '憂き目', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Kesedihan terlihat di mata Anda dengan membuatnya tampak seperti Anda telah melalui banyak kepahitan dan kesulitan. Anda selalu dapat melihatnya pada orang lain jika Anda menatap matanya juga.', 'Kesedihan terlihat di mata Anda dengan membuatnya tampak seperti Anda telah melalui banyak kepahitan dan kesulitan. Anda selalu dapat melihatnya pada orang lain jika Anda menatap matanya juga.') ON CONFLICT (id) DO NOTHING;
