INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16d0e595-10db-405f-9036-2fd069a0ccf7', '疲れを癒して、早く回復するために、一週間緑茶を飲んだりお餅を食べたりしました。', 'Untuk menyembuhkan rasa lelah dan cepat pulih, saya minum teh hijau dan makan mochi selama seminggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('16d0e595-10db-405f-9036-2fd069a0ccf7', '莉子ちゃんの優しい笑顔に癒された。', 'Aku disembuhkan oleh senyuman ramah Riko-chan.') ON CONFLICT DO NOTHING;
