INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29d4210b-dee7-4647-a11f-e9d6c8ad4202', 'vocabulary', '茜色', '茜色', 1, '208a48cb-5412-4cd6-a858-cae554a194e7', 'Warna pewarna merah adalah merah tua, atau merah tua. Kata ini paling sering digunakan untuk menggambarkan warna langit saat matahari terbenam.', 'Warna pewarna merah adalah merah tua, atau merah tua. Kata ini paling sering digunakan untuk menggambarkan warna langit saat matahari terbenam.') ON CONFLICT (id) DO NOTHING;
