INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29d4210b-dee7-4647-a11f-e9d6c8ad4202', '空が夕焼けで茜色に染まっていて、とても綺麗でした。', 'Langit berwarna merah tua saat matahari terbenam, dan sangat indah.') ON CONFLICT DO NOTHING;
