INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e6f53651-7ff6-479d-aea4-c905a778f933', 'vocabulary', '之', '之', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
