INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6f53651-7ff6-479d-aea4-c905a778f933', 'よかったら之も持って行きなさい。', 'Ambil ini juga, jika kamu mau.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7264167b-219d-47c0-9c12-e0de0fa9eb6f', 'vocabulary', '凝固', '凝固', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Puding Anda membeku dan semuanya keras. Bagaimana bisa itu mengeras seperti ini? Seharusnya tidak membeku kecuali Anda memasukkannya ke dalam freezer. Kecuali, bukan? Aduh...', 'Puding Anda membeku dan semuanya keras. Bagaimana bisa itu mengeras seperti ini? Seharusnya tidak membeku kecuali Anda memasukkannya ke dalam freezer. Kecuali, bukan? Aduh...') ON CONFLICT (id) DO NOTHING;
