INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7264167b-219d-47c0-9c12-e0de0fa9eb6f', '煮詰めたジャムは、冷めてくると粘性が強まり、ゼリー状に凝固します。', 'Selai yang saya rebus setelah dingin akan menjadi kental dan mengeras menjadi agar-agar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8228a1c1-f038-48f3-ac62-c1a3c7e360c6', 'vocabulary', '凝視', '凝視', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Diam dan lihat aku. Tatapanmu membuatku merinding! Anda bisa pindah sekarang. Hai. Anda bisa pindah sekarang. Berhenti, kataku!', 'Diam dan lihat aku. Tatapanmu membuatku merinding! Anda bisa pindah sekarang. Hai. Anda bisa pindah sekarang. Berhenti, kataku!') ON CONFLICT (id) DO NOTHING;
