INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9c418be-710d-44a3-b0c1-bca6a031201b', '利害が一致すれば、呉越同舟も厭わない。', 'Jika kami bisa berbagi kepentingan yang sama, saya tidak akan keberatan berada di posisi yang sama dengan rival saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3b8351bd-fb44-4e18-8bda-0d7a9aca5e3f', 'vocabulary', '主宰', '主宰', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Manajer utama mengatur semua manajer lainnya dan dia bertanggung jawab atas pengawasan mereka. Jika terjadi kesalahan maka dialah yang disalahkan! Dia harus terus mencermati mereka!', 'Manajer utama mengatur semua manajer lainnya dan dia bertanggung jawab atas pengawasan mereka. Jika terjadi kesalahan maka dialah yang disalahkan! Dia harus terus mencermati mereka!') ON CONFLICT (id) DO NOTHING;
