INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('060d7954-436d-4305-b2a5-3bcbcd0b256f', 'vocabulary', '拍手', '拍手', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Pukulan tangan sebenarnya adalah tepuk tangan. Padahal... kamu mungkin melakukan kesalahan jika kamu benar-benar menghajar mereka bersama-sama.', 'Pukulan tangan sebenarnya adalah tepuk tangan. Padahal... kamu mungkin melakukan kesalahan jika kamu benar-benar menghajar mereka bersama-sama.') ON CONFLICT (id) DO NOTHING;
