INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4f60328f-8d86-447a-a320-e5da7ac24a06', 'vocabulary', '穀物', '穀物', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Biji-bijian adalah biji-bijian dan sereal!', 'Biji-bijian adalah biji-bijian dan sereal!') ON CONFLICT (id) DO NOTHING;
