INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9466f322-4035-4529-987d-4d2ba5195d0b', 'vocabulary', '窒息', '窒息', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Tercekik sampai Anda tidak punya nafas lagi dan Anda akan mati karena mati lemas. Kunyah makanan Anda dan ini tidak boleh terjadi!', 'Tercekik sampai Anda tidak punya nafas lagi dan Anda akan mati karena mati lemas. Kunyah makanan Anda dan ini tidak boleh terjadi!') ON CONFLICT (id) DO NOTHING;
