INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f329cdbf-0702-4234-a6f0-0a6ea96f587f', 'vocabulary', '窒素', '窒素', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Salah satu unsur yang dapat menyebabkan seseorang mati lemas adalah nitrogen. Terlalu banyak atau terlalu sedikit akan menyebabkannya.', 'Salah satu unsur yang dapat menyebabkan seseorang mati lemas adalah nitrogen. Terlalu banyak atau terlalu sedikit akan menyebabkannya.') ON CONFLICT (id) DO NOTHING;
