INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4874b5e2-ff5f-4c67-b3f4-514550c42ffb', 'vocabulary', '窮地', '窮地', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Negeri-negeri miskin akan menghadapi dilema. Apakah mereka pergi? Atau apakah mereka mencoba memanfaatkannya sebaik mungkin?', 'Negeri-negeri miskin akan menghadapi dilema. Apakah mereka pergi? Atau apakah mereka mencoba memanfaatkannya sebaik mungkin?') ON CONFLICT (id) DO NOTHING;
