INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69ee4bfe-7faf-43d0-b020-800306036f1d', 'vocabulary', '窮屈', '窮屈', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Jangan menyerah pada apapun ketika kamu sedang melarat karena itu akan membuat keadaan menjadi semakin ketat. Biasanya Anda harus bersikap kaku mengenai apa yang Anda mampu dan tidak mampu beli.', 'Jangan menyerah pada apapun ketika kamu sedang melarat karena itu akan membuat keadaan menjadi semakin ketat. Biasanya Anda harus bersikap kaku mengenai apa yang Anda mampu dan tidak mampu beli.') ON CONFLICT (id) DO NOTHING;
