INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69ee4bfe-7faf-43d0-b020-800306036f1d', '窮屈な下着は体によくない。', 'Pakaian dalam yang ketat tidak baik untuk Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69ee4bfe-7faf-43d0-b020-800306036f1d', '部屋が窮屈でごめんね。ここに座っていてくれる？今、お茶持ってくるから。', 'Maaf kamarnya sempit sekali. Bisakah kamu duduk di sini saja? Aku akan membuatkanmu teh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3f485289-3732-492d-93f7-12d1e76c3fc4', 'vocabulary', '窮乏', '窮乏', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Kota-kota yang miskin dan kekurangan makanan akan berakhir dengan kemiskinan dan kemelaratan.', 'Kota-kota yang miskin dan kekurangan makanan akan berakhir dengan kemiskinan dan kemelaratan.') ON CONFLICT (id) DO NOTHING;
