INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('46472bf4-c3f2-48ba-a598-da744c9e802c', 'vocabulary', '困窮', '困窮', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Anda akan tertekan dan melarat jika Anda hidup dalam kemiskinan.', 'Anda akan tertekan dan melarat jika Anda hidup dalam kemiskinan.') ON CONFLICT (id) DO NOTHING;
