INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36b30654-1771-4ebe-8817-fa072fb2f0ec', 'vocabulary', '窮状', '窮状', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Kondisi kemiskinan menyebabkan kesusahan.', 'Kondisi kemiskinan menyebabkan kesusahan.') ON CONFLICT (id) DO NOTHING;
