INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('401f2261-b371-4f1e-a440-9f9713f6d80f', 'ここは、南署の管轄です。', 'Polisi selatan memiliki yurisdiksi di sini.') ON CONFLICT DO NOTHING;
