INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('20bd6173-bff2-48d3-b02c-67c674cdb344', 'とにかく、まずは所轄の警察署に連絡をいれましょう。', 'Bagaimanapun, mari kita hubungi kantor polisi yang memiliki yurisdiksi terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1cbc30c7-d5b1-4504-94fd-7ef600eca812', 'vocabulary', '直轄', '直轄', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Perbaiki kendali Anda atas planet ini dengan mengambil kendali langsung.', 'Perbaiki kendali Anda atas planet ini dengan mengambil kendali langsung.') ON CONFLICT (id) DO NOTHING;
