INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1cbc30c7-d5b1-4504-94fd-7ef600eca812', 'それじゃあ、ここも政府が直轄している機関なんですか。', 'Kalau begitu, apakah ada lembaga yang dikontrol langsung oleh pemerintah juga?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1b23feee-b838-44f2-99de-dfaa19ac2123', 'vocabulary', '錯誤', '錯誤', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Jika Anda bingung dan melakukan kesalahan, betapapun Anda tidak bersungguh-sungguh, itu tetaplah kesalahan. Anda harus meminta bantuan lain kali Anda tidak tahu apa yang Anda lakukan dan Anda tidak akan membuat kesalahan ini.', 'Jika Anda bingung dan melakukan kesalahan, betapapun Anda tidak bersungguh-sungguh, itu tetaplah kesalahan. Anda harus meminta bantuan lain kali Anda tidak tahu apa yang Anda lakukan dan Anda tidak akan membuat kesalahan ini.') ON CONFLICT (id) DO NOTHING;
