INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1b23feee-b838-44f2-99de-dfaa19ac2123', 'ちょっとそれは時代錯誤じゃないか。', 'Tidakkah menurut Anda itu sedikit ketinggalan jaman?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0fac57bb-6b68-438c-8bec-96756a8dac95', 'vocabulary', '錯覚', '錯覚', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Anda mengira Anda sudah hafal seperti apa gambar ini, namun tiba-tiba semuanya tampak membingungkan dan berbeda. Itu karena itu hanya ilusi.', 'Anda mengira Anda sudah hafal seperti apa gambar ini, namun tiba-tiba semuanya tampak membingungkan dan berbeda. Itu karena itu hanya ilusi.') ON CONFLICT (id) DO NOTHING;
