INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0fac57bb-6b68-438c-8bec-96756a8dac95', 'それがまるで自分のもののような錯覚に襲われたんです。', 'Saya diserang oleh ilusi yang tampak seperti saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('856d665c-4354-4ad6-be9f-7e9a519d91ae', 'vocabulary', '錯乱', '錯乱', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Kerusuhan yang membingungkan menyebabkan lebih banyak kebingungan. Sebentar lagi akan terjadi begitu banyak gangguan, misalnya mobil-mobil terbalik dan kebakaran terjadi, sehingga tak seorang pun tahu arah mana yang harus diambil!', 'Kerusuhan yang membingungkan menyebabkan lebih banyak kebingungan. Sebentar lagi akan terjadi begitu banyak gangguan, misalnya mobil-mobil terbalik dan kebakaran terjadi, sehingga tak seorang pun tahu arah mana yang harus diambil!') ON CONFLICT (id) DO NOTHING;
