INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('856d665c-4354-4ad6-be9f-7e9a519d91ae', '薬で意識が錯乱しているようでした。', 'Kesadaran mereka sepertinya dibingungkan oleh obat tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e79072ba-0083-4a95-b2da-7afcf440d789', 'vocabulary', '交錯', '交錯', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Anda mencampurkan banyak bahan ke dalam campuran yang membingungkan. Itu akan menjadi kue yang aneh, atau apa pun kegunaan campurannya.', 'Anda mencampurkan banyak bahan ke dalam campuran yang membingungkan. Itu akan menjadi kue yang aneh, atau apa pun kegunaan campurannya.') ON CONFLICT (id) DO NOTHING;
