INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2371b4e5-727f-49d0-8cef-18d2416ac535', 'vocabulary', '弦楽器', '弦楽器', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Anda sudah tahu bahwa 楽器 berarti "alat musik" jadi menambahkan beberapa tali busur ke dalamnya akan menjadikannya alat musik petik.', 'Anda sudah tahu bahwa 楽器 berarti "alat musik" jadi menambahkan beberapa tali busur ke dalamnya akan menjadikannya alat musik petik.') ON CONFLICT (id) DO NOTHING;
