INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('65b3c961-6fe3-4247-97bf-4f5ad464deac', 'vocabulary', '管弦楽', '管弦楽', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Anda sudah tahu bahwa 弦楽 berarti "musik senar", jadi tambahkan beberapa pipa ke dalamnya, seperti terompet dan saksofon, dan Anda akan mendapatkan musik orkestra. Anda tidak dapat memiliki keseluruhan orkestra hanya dengan bagian string!', 'Anda sudah tahu bahwa 弦楽 berarti "musik senar", jadi tambahkan beberapa pipa ke dalamnya, seperti terompet dan saksofon, dan Anda akan mendapatkan musik orkestra. Anda tidak dapat memiliki keseluruhan orkestra hanya dengan bagian string!') ON CONFLICT (id) DO NOTHING;
