INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4b2ea1f3-878e-476f-b14b-c6d084925b7e', 'vocabulary', '拍子', '拍子', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Anak dari irama musik adalah tempo. Anda hanya dapat menjaga waktu jika Anda memiliki irama yang bagus untuk membimbing Anda, seperti seorang ayah.', 'Anak dari irama musik adalah tempo. Anda hanya dapat menjaga waktu jika Anda memiliki irama yang bagus untuk membimbing Anda, seperti seorang ayah.') ON CONFLICT (id) DO NOTHING;
