INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('615a068c-5129-400e-8c91-7afc5756069d', 'vocabulary', '執行猶予', '執行猶予', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Ingat bagaimana Anda mengetahui bahwa 猶予 berarti "perpanjangan?" Ya, juri mempunyai tekad kuat untuk mencoba melepaskan Anda dan mereka meminta perpanjangan, jadi mereka memberi Anda hukuman percobaan sampai mereka tahu cara melakukannya dengan benar. Anda mungkin dibebaskan! E... akhirnya.', 'Ingat bagaimana Anda mengetahui bahwa 猶予 berarti "perpanjangan?" Ya, juri mempunyai tekad kuat untuk mencoba melepaskan Anda dan mereka meminta perpanjangan, jadi mereka memberi Anda hukuman percobaan sampai mereka tahu cara melakukannya dengan benar. Anda mungkin dibebaskan! E... akhirnya.') ON CONFLICT (id) DO NOTHING;
