INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('284aeff3-64c9-482d-856d-101103a1c9ae', 'vocabulary', '縛り首', '縛り首', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Ingat bagaimana 縛る berarti "mengikat?" Nah kalau mengikat sesuatu di leher seseorang maka itu namanya digantung. Mereka mungkin akan mati karenanya juga, jadi bisa juga mati karena digantung.', 'Ingat bagaimana 縛る berarti "mengikat?" Nah kalau mengikat sesuatu di leher seseorang maka itu namanya digantung. Mereka mungkin akan mati karenanya juga, jadi bisa juga mati karena digantung.') ON CONFLICT (id) DO NOTHING;
