INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f80fa6d6-738f-478b-ab63-4552b99783db', 'この度は弊社のサービスをご利用いただきまして誠にありがとうございます。', 'Terima kasih banyak telah menggunakan layanan perusahaan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f80fa6d6-738f-478b-ab63-4552b99783db', 'キャンセルの場合は、お手数ではございますが弊社カスタマーサポートまでご連絡ください。', 'Jika terjadi pembatalan, silakan hubungi dukungan pelanggan perusahaan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f80fa6d6-738f-478b-ab63-4552b99783db', '本キャンペーンは、弊社の都合により告知なしに終了する場合がございます。', 'Kampanye ini dapat dihentikan tanpa pemberitahuan tergantung pada keadaan perusahaan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'vocabulary', '瑛斗', '瑛斗', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Sendok kristal adalah nama pemberian Jepang Eito. Jika Anda mengenal penyanyi-penulis lagu Eito, bayangkan dia memegang sendok kristal. Jika tidak, Eito mana pun bisa melakukannya! Tokoh masyarakat lain yang memiliki nama tersebut termasuk pemain bisbol profesional Tanaka Eito (田中 瑛斗) dan aktor Takarazuka Namiki Eito (波輝 瑛斗).', 'Sendok kristal adalah nama pemberian Jepang Eito. Jika Anda mengenal penyanyi-penulis lagu Eito, bayangkan dia memegang sendok kristal. Jika tidak, Eito mana pun bisa melakukannya! Tokoh masyarakat lain yang memiliki nama tersebut termasuk pemain bisbol profesional Tanaka Eito (田中 瑛斗) dan aktor Takarazuka Namiki Eito (波輝 瑛斗).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'Eito', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'Akito', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'えいと', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'あきと', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', '頑張れよ、瑛斗。', 'Lakukan yang terbaik, Eito.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'あそこに田中瑛斗選手がいるよ！', 'Atlet profesional Eito Tanaka ada di sana!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2b6bf8c-0c53-4608-93b8-098e1098c48c', 'シンガーソングライターの瑛斗は、ソーシャルメディアで有名になりました。', 'Penyanyi-penulis lagu Eito menjadi terkenal di media sosial.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f75ce14c-d183-4496-bc55-19a844d80716', 'vocabulary', '遼太', '遼太', 1, '7d3c216e-73da-40ce-ad9f-a1e7c189fe0b', 'Lemak jauh membentuk nama Jepang Ryota. Bayangkan pemain sepak bola Noguchi Ryota (野口 遼太) menendang bola gemuk ke kejauhan sementara pengisi suara Asari Ryota (浅利 遼太) berkomentar.', 'Lemak jauh membentuk nama Jepang Ryota. Bayangkan pemain sepak bola Noguchi Ryota (野口 遼太) menendang bola gemuk ke kejauhan sementara pengisi suara Asari Ryota (浅利 遼太) berkomentar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f75ce14c-d183-4496-bc55-19a844d80716', 'Ryota', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f75ce14c-d183-4496-bc55-19a844d80716', 'りょうた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f75ce14c-d183-4496-bc55-19a844d80716', '今朝、夢に遼太君が現れた。', 'Pagi ini, Ryota-kun muncul dalam mimpiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f75ce14c-d183-4496-bc55-19a844d80716', '遼太と綾乃ちゃん、付き合ってるらしいよ。', 'Kudengar Ryota dan Ayano berpacaran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f75ce14c-d183-4496-bc55-19a844d80716', '遼太、早く起きないと遅刻するよ！', 'Ryota, cepat bangun atau kamu akan terlambat!') ON CONFLICT DO NOTHING;
