INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b84723f6-2a7d-4df7-ab5d-65322cdd335a', 'vocabulary', '意匠', '意匠', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Seorang pengrajin punya ide dan membuat desain baru!', 'Seorang pengrajin punya ide dan membuat desain baru!') ON CONFLICT (id) DO NOTHING;
