INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b8481bdc-f340-46b0-a9bc-fd2a1b076561', 'vocabulary', '師匠', '師匠', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Seorang perajin yang cukup baik untuk menjadi guru harus menjadi ahli dalam keahliannya.', 'Seorang perajin yang cukup baik untuk menjadi guru harus menjadi ahli dalam keahliannya.') ON CONFLICT (id) DO NOTHING;
