INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f4582fca-b431-443f-a6db-43efed1dae7f', 'vocabulary', '巨匠', '巨匠', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Seorang pengrajin yang merupakan raksasa di bidangnya adalah seorang master! Semua orang tahu nama mereka! Atau, mereka sangat besar... seperti tinggi, jadi semua orang menyebut mereka master karena mereka tidak ingin dihancurkan.', 'Seorang pengrajin yang merupakan raksasa di bidangnya adalah seorang master! Semua orang tahu nama mereka! Atau, mereka sangat besar... seperti tinggi, jadi semua orang menyebut mereka master karena mereka tidak ingin dihancurkan.') ON CONFLICT (id) DO NOTHING;
