INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3648715c-5a11-4904-ad55-9b896d544c26', 'vocabulary', '嘉日', '嘉日', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Hari yang Anda hargai adalah hari yang baik. Itu cara yang bagus untuk mengatakan ini adalah hari yang sangat beruntung!', 'Hari yang Anda hargai adalah hari yang baik. Itu cara yang bagus untuk mengatakan ini adalah hari yang sangat beruntung!') ON CONFLICT (id) DO NOTHING;
