INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9dc8f70d-ffea-4983-b750-42a8d5398756', 'vocabulary', '大尉', '大尉', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Perwira militer besar bertanggung jawab atas semua orang. Dia kaptennya. Anda bisa mengetahuinya karena dia memakai topi kapten yang sangat besar.', 'Perwira militer besar bertanggung jawab atas semua orang. Dia kaptennya. Anda bisa mengetahuinya karena dia memakai topi kapten yang sangat besar.') ON CONFLICT (id) DO NOTHING;
