INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9dc8f70d-ffea-4983-b750-42a8d5398756', '大尉の死は決して無駄ではなかった。', 'Kematian sang kapten sama sekali tidak sia-sia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b2edee0-3751-48a2-9e83-3c3110737444', 'vocabulary', '少尉', '少尉', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Seseorang yang baru menjadi perwira militer selama beberapa tahun belum mampu mencapai pangkat yang tinggi. Mereka seorang panji, atau letnan dua. Itu masih bukan posisi yang buruk!', 'Seseorang yang baru menjadi perwira militer selama beberapa tahun belum mampu mencapai pangkat yang tinggi. Mereka seorang panji, atau letnan dua. Itu masih bukan posisi yang buruk!') ON CONFLICT (id) DO NOTHING;
