INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('49792e41-1981-40f7-a09f-5a64b467a284', 'vocabulary', '中尉', '中尉', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Seorang perwira militer yang sedang berkarir telah menjadi letnan satu.', 'Seorang perwira militer yang sedang berkarir telah menjadi letnan satu.') ON CONFLICT (id) DO NOTHING;
