INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49792e41-1981-40f7-a09f-5a64b467a284', '我が軍の中尉が敵軍に拉致され、処刑されました。', 'Letnan satu tentara kita ditangkap oleh musuh dan dieksekusi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5fd48265-d9d8-48ae-81e0-a8d0d12be322', 'vocabulary', '搾る', '搾る', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memeras, jadi versi verbanya adalah memeras. Perbedaan kata ini dengan 絞る adalah 絞る berarti "memeras" dan 搾る berarti memeras atau membuat jus buah/sayuran atau memerah susu sapi.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memeras, jadi versi verbanya adalah memeras. Perbedaan kata ini dengan 絞る adalah 絞る berarti "memeras" dan 搾る berarti memeras atau membuat jus buah/sayuran atau memerah susu sapi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5fd48265-d9d8-48ae-81e0-a8d0d12be322', 'Untuk Meremas', true) ON CONFLICT DO NOTHING;
