INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5fd48265-d9d8-48ae-81e0-a8d0d12be322', 'レモンを唐揚げに搾ってもいいですか？', 'Bisakah saya memeras lemon di atas gorengan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e3c05292-9ea4-4bec-b6cd-4bacca79e9ec', 'vocabulary', '搾取', '搾取', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Keluarkan anak-anak dari rumah mereka dan peras semua bakat mereka sampai mereka tidak punya apa-apa lagi. Itu disebut eksploitasi, dan banyak perusahaan menghasilkan uang darinya. Tapi itu tidak terlalu bagus.', 'Keluarkan anak-anak dari rumah mereka dan peras semua bakat mereka sampai mereka tidak punya apa-apa lagi. Itu disebut eksploitasi, dan banyak perusahaan menghasilkan uang darinya. Tapi itu tidak terlalu bagus.') ON CONFLICT (id) DO NOTHING;
