INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26c32cd6-bde7-433a-960c-3260999a008f', 'vocabulary', '搾乳', '搾乳', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Peras ambing untuk mendapatkan susu. Lihat itu, kamu sedang memerah susu sapi!', 'Peras ambing untuk mendapatkan susu. Lihat itu, kamu sedang memerah susu sapi!') ON CONFLICT (id) DO NOTHING;
