INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26c32cd6-bde7-433a-960c-3260999a008f', '牧場で搾乳体験をしてきました。', 'Saya pribadi mengalami pemerahan di peternakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', 'vocabulary', '摂氏', '摂氏', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Oke, jadi ini sulit tapi tetaplah bersamaku! Selain nama keluarga, hal pertama yang perlu dipelajari semasa kecil adalah bagaimana memahami derajat Celcius. Jika Anda tidak dapat mengetahui berapa suhu di luar, atau di rumah Anda, atau di dalam tubuh Anda untuk mengetahui apakah Anda sakit, Anda tidak akan bisa menangani makhluk hidup ini dengan baik. Jadi ketika Anda mengingat kembali hal pertama yang Anda pelajari selain nama keluarga Anda sendiri, pikirkanlah suhu celcius!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', 'Celcius', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', 'Celsius', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', 'せっし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', '今日の最高気温は、摂氏二十五度です。', 'Suhu maksimum saat ini adalah dua puluh lima derajat Celcius.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', '摂氏100度が水の沸点です。', '100 derajat Celcius adalah titik didih air.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('81fd9a1c-9f61-4513-ac6b-26b585720c4c', 'アメリカも早く華氏から摂氏に変えればいいのに。', 'Saya berharap Amerika segera mengubah suhu dari Fahrenheit ke Celsius.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('75043cb8-79fe-4cea-aa2d-feb202ffb75e', 'vocabulary', '摂理', '摂理', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Beberapa hal terjadi di luar nalar. Itu terjadi sebagai tambahannya. Itu disebut pemeliharaan ilahi. Anda tidak bisa menjelaskannya, tetapi sesuatu di luar nalar pasti mempengaruhi hal-hal di sekitar Anda.', 'Beberapa hal terjadi di luar nalar. Itu terjadi sebagai tambahannya. Itu disebut pemeliharaan ilahi. Anda tidak bisa menjelaskannya, tetapi sesuatu di luar nalar pasti mempengaruhi hal-hal di sekitar Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('75043cb8-79fe-4cea-aa2d-feb202ffb75e', 'Penyelenggaraan Ilahi', true) ON CONFLICT DO NOTHING;
