INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('75043cb8-79fe-4cea-aa2d-feb202ffb75e', '誰も自然の摂理には逆らえないよ。', 'Tidak ada seorang pun yang bisa menentang hukum alam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('99228ad4-3b26-4623-80a5-4d947997daf1', 'vocabulary', '摂取', '摂取', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Tubuh Anda menyerap nutrisi ke dalam dirinya sendiri selain semua makanan tambahan yang Anda makan. Ini disebut asupan harian Anda. Dan itu mendapatkan semua nutrisi itu ke dalam tubuh Anda melalui penyerapan.', 'Tubuh Anda menyerap nutrisi ke dalam dirinya sendiri selain semua makanan tambahan yang Anda makan. Ini disebut asupan harian Anda. Dan itu mendapatkan semua nutrisi itu ke dalam tubuh Anda melalui penyerapan.') ON CONFLICT (id) DO NOTHING;
