INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('99228ad4-3b26-4623-80a5-4d947997daf1', '一日の摂取カロリーを計算してみました。', 'Saya menghitung asupan kalori saya untuk satu hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b60cf5b0-3b36-4845-a83c-5f4e6b15cda1', 'vocabulary', '智', '智', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
