INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f487616d-ff01-4905-83d2-b966ed099ac1', 'vocabulary', '墓碑', '墓碑', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Gabungkan kuburan dan batu nisan dan Anda membuat batu nisan.', 'Gabungkan kuburan dan batu nisan dan Anda membuat batu nisan.') ON CONFLICT (id) DO NOTHING;
