INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43d7f07b-3435-42a2-b898-b937310632db', 'vocabulary', '石碑', '石碑', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Sebuah batu nisan yang terbuat dari batu besar digunakan sebagai tugu batu. Batu-batu ini biasanya sangat besar sehingga digunakan untuk beberapa orang yang meninggal bersama-sama.', 'Sebuah batu nisan yang terbuat dari batu besar digunakan sebagai tugu batu. Batu-batu ini biasanya sangat besar sehingga digunakan untuk beberapa orang yang meninggal bersama-sama.') ON CONFLICT (id) DO NOTHING;
