INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43d7f07b-3435-42a2-b898-b937310632db', 'これが石碑に彫られていた文字です。', 'Inilah kata-kata yang terukir di batu tugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43d7f07b-3435-42a2-b898-b937310632db', '無人島のはずのこの島に石碑が建っているのはなぜですか。', 'Mengapa ada tugu batu di pulau yang konon tak berpenghuni ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43d7f07b-3435-42a2-b898-b937310632db', '津波が襲った高さの地点に石碑が建てられているのです。', 'Sebuah monumen batu dibangun di lokasi ketinggian tsunami melanda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c948e492-ccbf-4613-9a41-b0b86e03b892', 'vocabulary', '碑文', '碑文', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Tulisan di batu nisan merupakan prasasti atau batu nisan yang diputuskan oleh anggota keluarga untuk ditaruh di sana.', 'Tulisan di batu nisan merupakan prasasti atau batu nisan yang diputuskan oleh anggota keluarga untuk ditaruh di sana.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c948e492-ccbf-4613-9a41-b0b86e03b892', 'Prasasti', true) ON CONFLICT DO NOTHING;
