INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c948e492-ccbf-4613-9a41-b0b86e03b892', 'この慰霊碑の碑文は誰が考えたのですか。', 'Siapa yang memikirkan prasasti peringatan ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e4db460a-c8db-4f25-85be-c49db4b769dc', 'vocabulary', '記念碑', '記念碑', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Beberapa batu nisan digunakan untuk menuliskan pemikiran orang yang sudah meninggal. Itu adalah monumen. Mereka bisa sangat besar atau sangat kecil, tetapi mereka harus dipersembahkan kepada seseorang (biasanya orang yang sudah meninggal).', 'Beberapa batu nisan digunakan untuk menuliskan pemikiran orang yang sudah meninggal. Itu adalah monumen. Mereka bisa sangat besar atau sangat kecil, tetapi mereka harus dipersembahkan kepada seseorang (biasanya orang yang sudah meninggal).') ON CONFLICT (id) DO NOTHING;
