INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4db460a-c8db-4f25-85be-c49db4b769dc', 'これは何の記念碑ですか。', 'Monumen macam apa ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d4fe727-a43c-41c3-ad2f-6bd99c15d11d', 'vocabulary', '紳士', '紳士', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Tuan-tuan yang juga samurai tetaplah tuan-tuan. Mereka hanya membawa pedang.', 'Tuan-tuan yang juga samurai tetaplah tuan-tuan. Mereka hanya membawa pedang.') ON CONFLICT (id) DO NOTHING;
