INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('99c30758-255d-4994-9719-010c09c52ee4', 'vocabulary', '蝶', '蝶', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
