INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dcf840f7-7b60-4383-ba1e-3782fd3a9140', 'vocabulary', '遥か', '遥か', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
