INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1be6d159-0074-4fce-ba72-95682cb3427f', 'vocabulary', '靖国神社', '靖国神社', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Anda sudah tahu bahwa 神社 berarti "kuil shinto", jadi tambahkan kedamaian dan pedesaan ke dalamnya dan Anda akan mendapatkan kuil yang menyerukan perdamaian seluruh negara. Itu Kuil Yasukuni. Jika Anda menonton berita, Anda pasti tahu bahwa nama ini dan semua maknanya selalu menjadi topik perdebatan saat ini.', 'Anda sudah tahu bahwa 神社 berarti "kuil shinto", jadi tambahkan kedamaian dan pedesaan ke dalamnya dan Anda akan mendapatkan kuil yang menyerukan perdamaian seluruh negara. Itu Kuil Yasukuni. Jika Anda menonton berita, Anda pasti tahu bahwa nama ini dan semua maknanya selalu menjadi topik perdebatan saat ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1be6d159-0074-4fce-ba72-95682cb3427f', 'Kuil Yasukuni', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1be6d159-0074-4fce-ba72-95682cb3427f', 'やすくにじんじゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1be6d159-0074-4fce-ba72-95682cb3427f', '靖国神社に参拝したことはありますか。', 'Pernahkah Anda mengunjungi Kuil Yasukuni?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('92db67e8-6618-4fef-b79f-16072986333d', 'vocabulary', '飽和', '飽和', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Jika Anda bosan dengan perdamaian karena yang ada hanyalah perdamaian, maka hal ini disebut kejenuhan pasar perdamaian. Anda sudah cukup banyak diliputi kedamaian dan sekarang Anda menginginkan sedikit kegembiraan yang kacau!', 'Jika Anda bosan dengan perdamaian karena yang ada hanyalah perdamaian, maka hal ini disebut kejenuhan pasar perdamaian. Anda sudah cukup banyak diliputi kedamaian dan sekarang Anda menginginkan sedikit kegembiraan yang kacau!') ON CONFLICT (id) DO NOTHING;
