INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cab14661-b2d3-4dba-b4bc-7e0b29d9dd2c', 'vocabulary', '飽きる', '飽きる', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bosan, jadi versi verbanya bosan atau kehilangan minat.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bosan, jadi versi verbanya bosan atau kehilangan minat.') ON CONFLICT (id) DO NOTHING;
