INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7990402-c0c7-4788-8f9c-3b620bf0972a', 'vocabulary', '間伐', '間伐', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Menebang pohon secara berkala, bukan sekaligus, dan ini disebut penjarangan pohon. Dengan begitu masih ada hutan di sana, tapi kayunya bisa digunakan untuk hal lain juga.', 'Menebang pohon secara berkala, bukan sekaligus, dan ini disebut penjarangan pohon. Dengan begitu masih ada hutan di sana, tapi kayunya bisa digunakan untuk hal lain juga.') ON CONFLICT (id) DO NOTHING;
