INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('714d9065-9b9b-4a3c-bfd0-8bb77827ac05', 'vocabulary', '減俸', '減俸', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Atasan Anda mengatakan dia akan menurunkan gaji Anda dengan pengurangan gaji di seluruh perusahaan. Anda mungkin harus mulai mencari pekerjaan baru yang tidak akan melakukan pemotongan gaji seperti ini.', 'Atasan Anda mengatakan dia akan menurunkan gaji Anda dengan pengurangan gaji di seluruh perusahaan. Anda mungkin harus mulai mencari pekerjaan baru yang tidak akan melakukan pemotongan gaji seperti ini.') ON CONFLICT (id) DO NOTHING;
