INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('48d0c6d4-53c6-4ca5-a82d-728b103b8b9c', 'vocabulary', '鼓舞', '鼓舞', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Iramanya membuat Anda ingin menari. Itu adalah inspirasi yang Anda butuhkan untuk menari. Iramanya memberi Anda dorongan untuk menari sepanjang malam. Dan tanpa hentakan yang begitu hebat, gerakan tarian Anda akan timpang.', 'Iramanya membuat Anda ingin menari. Itu adalah inspirasi yang Anda butuhkan untuk menari. Iramanya memberi Anda dorongan untuk menari sepanjang malam. Dan tanpa hentakan yang begitu hebat, gerakan tarian Anda akan timpang.') ON CONFLICT (id) DO NOTHING;
