INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36efdcc8-f1b3-489f-9ae4-e4d22a72f599', 'vocabulary', '鼓', '鼓', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Apa yang Anda pukul untuk membuat pukulan yang menyakitkan? Drum tangan kecil yang keren.', 'Apa yang Anda pukul untuk membuat pukulan yang menyakitkan? Drum tangan kecil yang keren.') ON CONFLICT (id) DO NOTHING;
