INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36efdcc8-f1b3-489f-9ae4-e4d22a72f599', 'あの女性の鼓の打ち方は絶品だ。', 'Cara wanita itu memukul genderang tangannya sungguh luar biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36efdcc8-f1b3-489f-9ae4-e4d22a72f599', '彼女は、袋の中に鼓を大切そうにしまった。', 'Dia menyimpan drum tangan itu dengan hati-hati ke dalam tas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36efdcc8-f1b3-489f-9ae4-e4d22a72f599', 'そんな可愛い鼓、見たことないよ。もしかして、手作り？', 'Aku belum pernah melihat tsuzumi semanis ini. Apakah Anda berhasil?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e4c3a049-512d-4873-9152-2f654daeecab', 'vocabulary', '鼓動', '鼓動', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Detak yang bergerak di dalam tubuhmu adalah detak jantungmu. Letakkan tangan Anda di leher dan Anda akan bisa merasakan denyut nadinya.', 'Detak yang bergerak di dalam tubuhmu adalah detak jantungmu. Letakkan tangan Anda di leher dan Anda akan bisa merasakan denyut nadinya.') ON CONFLICT (id) DO NOTHING;
