INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4c3a049-512d-4873-9152-2f654daeecab', '少女の顔が赤くなり、鼓動が高鳴りました。', 'Wajah gadis muda itu memerah dan jantungnya berdebar-debar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10f56084-3f35-4160-bb3d-cb8c8060466c', 'vocabulary', '太鼓', '太鼓', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Drum yang gemuk tetaplah drum. Kata ini bisa digunakan untuk semua jenis drum, tapi yang umum di Jepang adalah taiko. Ada banyak jenis taiko yang berbeda, dan sebagian besar berukuran besar dan gemuk, serta menghasilkan suara dalam yang indah. Mereka sangat keren untuk ditonton dan dimainkan!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('10f56084-3f35-4160-bb3d-cb8c8060466c', 'gendang', true) ON CONFLICT DO NOTHING;
