INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10f56084-3f35-4160-bb3d-cb8c8060466c', 'うちの子供は太鼓で遊ぶのが好きです。', 'Anak-anak saya suka bermain drum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10f56084-3f35-4160-bb3d-cb8c8060466c', 'お腹がパンパンで太鼓みたいになっています。', 'Perutku penuh sekali hingga terlihat seperti drum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10f56084-3f35-4160-bb3d-cb8c8060466c', '「太鼓の達人」っていうゲームにハマってるんだ。', 'Saya sangat menyukai permainan yang disebut "Taiko Master."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('48590a32-f681-4e74-a67a-e8f8e22a31d1', 'vocabulary', '紳士協定', '紳士協定', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Ingat bagaimana Anda mengetahui bahwa 紳士 berarti "pria terhormat?" Nah, ketika dua pria memutuskan bahwa hal terbaik untuk dilakukan adalah bekerja sama, mereka membentuk perjanjian yang sopan.', 'Ingat bagaimana Anda mengetahui bahwa 紳士 berarti "pria terhormat?" Nah, ketika dua pria memutuskan bahwa hal terbaik untuk dilakukan adalah bekerja sama, mereka membentuk perjanjian yang sopan.') ON CONFLICT (id) DO NOTHING;
