INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48590a32-f681-4e74-a67a-e8f8e22a31d1', 'あいつらとは紳士協定を結んでいるはずだ。', 'Mereka seharusnya terikat pada kesepakatan yang mulia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('78f0a7be-7240-4535-91ae-a505c3fc2d90', 'vocabulary', '蝶々', '蝶々', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Seekor kupu-kupu dengan kupu-kupu lain yang ditambahkan ke dalamnya? Itu masih kupu-kupu, hanya kupu-kupu yang sangat besar dengan... empat sayap. Dan mata laser? Oh baiklah, ikuti saja. Itu kupu-kupu.', 'Seekor kupu-kupu dengan kupu-kupu lain yang ditambahkan ke dalamnya? Itu masih kupu-kupu, hanya kupu-kupu yang sangat besar dengan... empat sayap. Dan mata laser? Oh baiklah, ikuti saja. Itu kupu-kupu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('78f0a7be-7240-4535-91ae-a505c3fc2d90', 'Kupu-kupu', true) ON CONFLICT DO NOTHING;
