INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('78f0a7be-7240-4535-91ae-a505c3fc2d90', '彼女は蝶々のように自由な女性でした。', 'Dia adalah seorang wanita yang sebebas kupu-kupu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('40097d50-bfdf-4138-98a6-4d0f5fed4350', 'vocabulary', '飽き', '飽き', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Jika Anda merasa bosan terus-terusan akan membuat Anda lelah dan keletihan yang Anda rasakan akan terpancar di wajah Anda.', 'Jika Anda merasa bosan terus-terusan akan membuat Anda lelah dan keletihan yang Anda rasakan akan terpancar di wajah Anda.') ON CONFLICT (id) DO NOTHING;
