INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('40097d50-bfdf-4138-98a6-4d0f5fed4350', 'あき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40097d50-bfdf-4138-98a6-4d0f5fed4350', '私って、飽きっぽいのよね。', 'Yah, aku plin-plan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3771b2b8-b4b0-4e34-b74b-d65cdfcaea84', 'vocabulary', '飽くまでも', '飽くまでも', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Saya sangat bosan. Yang paling membuatku bosan adalah くまでも. Jika Anda mengartikannya secara terpisah, artinya "bahkan seperti beruang". Jadi itu seperti maksudmu aku sangat bosan, meskipun aku seekor beruang. Jika Anda begitu bosan sehingga Anda merasa bosan bahkan sebagai seekor beruang, Anda akan merasa bosan sampai akhir atau sampai akhir. Tidak ada yang bisa menyenangkanmu, dasar orang beruang yang bosan.', 'Saya sangat bosan. Yang paling membuatku bosan adalah くまでも. Jika Anda mengartikannya secara terpisah, artinya "bahkan seperti beruang". Jadi itu seperti maksudmu aku sangat bosan, meskipun aku seekor beruang. Jika Anda begitu bosan sehingga Anda merasa bosan bahkan sebagai seekor beruang, Anda akan merasa bosan sampai akhir atau sampai akhir. Tidak ada yang bisa menyenangkanmu, dasar orang beruang yang bosan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3771b2b8-b4b0-4e34-b74b-d65cdfcaea84', 'Sampai Yang Terakhir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3771b2b8-b4b0-4e34-b74b-d65cdfcaea84', 'To The End', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3771b2b8-b4b0-4e34-b74b-d65cdfcaea84', 'あくまでも', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3771b2b8-b4b0-4e34-b74b-d65cdfcaea84', '飽くまでも、これは個人的な見解です。', 'Ini adalah pendapat yang keras kepala dan egois.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', 'vocabulary', '早乙女', '早乙女', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Remaja putri yang menanam padi dari pagi hingga sore hari adalah gadis penanam padi. Anda akan melihat mereka di luar sana sepanjang hari, dari fajar hingga senja, menanam, merawat, dan memetik padi.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', 'Gadis Penanam Padi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', 'Saotome', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', 'さおとめ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', '昔は稲の苗を水田に植えつける女性のことを「早乙女」や「植女」と呼んでいました。', 'Dahulu kala, perempuan yang menanam bibit padi disebut Saotome atau Ueme.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', '早乙女勝元の児童文学作品の中では平和をテーマとしているものが多い。', 'Dalam sastra anak Saotome Katsumoto banyak terdapat karya yang mengangkat tema perdamaian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fae9a045-2639-4d28-9036-44d4374e899a', '女優の早乙女愛はデビューした時に漫画 『愛と誠』の映画化で同じ名前をした主人公を演じ、そのまま芸名にしたらしいよ。', 'Rupanya, saat debut, aktris Saotome Ai memainkan karakter utama dengan nama yang sama dalam film adaptasi manga "Ai to Makoto", lalu mengadopsinya sebagai nama panggungnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('050cd10a-dfea-420a-a499-a851a5b220e8', 'vocabulary', '漬物', '漬物', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Acarnya adalah acar sayuran Jepang! Atau tsukemono jika Anda sudah pernah makan acar jahe, daikon, dan umeboshi yang lezat!', 'Acarnya adalah acar sayuran Jepang! Atau tsukemono jika Anda sudah pernah makan acar jahe, daikon, dan umeboshi yang lezat!') ON CONFLICT (id) DO NOTHING;
