INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('050cd10a-dfea-420a-a499-a851a5b220e8', 'この漬物は誰が漬けたんですか。', 'Siapa yang membuat acar tsukemono ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('900bccd7-331b-461d-9240-25c50d7f9ec1', 'vocabulary', '〜漬け', '〜漬け', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Anda sudah mengetahui bahwa 漬ける berarti "mengasinkan", jadi jika Anda menambahkannya di akhir kata makanan (dan menghilangkan る), itu berarti makanan tersebut telah diasamkan.', 'Anda sudah mengetahui bahwa 漬ける berarti "mengasinkan", jadi jika Anda menambahkannya di akhir kata makanan (dan menghilangkan る), itu berarti makanan tersebut telah diasamkan.') ON CONFLICT (id) DO NOTHING;
