INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('900bccd7-331b-461d-9240-25c50d7f9ec1', '胡瓜の浅漬けならありますよ。', 'Ini adalah mentimun yang diasinkan ringan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0de35635-8bb6-43ed-a39e-a28ed98a0500', 'vocabulary', '漬かる', '漬かる', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Anda sudah mengetahui bahwa 漬ける berarti "mengasinkan", jadi artinya "diasinkan".', 'Anda sudah mengetahui bahwa 漬ける berarti "mengasinkan", jadi artinya "diasinkan".') ON CONFLICT (id) DO NOTHING;
