INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0de35635-8bb6-43ed-a39e-a28ed98a0500', '温泉に漬かってゆっくりした。', 'Saya berendam dan bersantai di onsen.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a6d5156-0446-4ad5-bdd7-4f47cf94bbaf', 'vocabulary', '大腸菌', '大腸菌', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Ingat bagaimana Anda mengetahui bahwa 大腸 berarti "usus besar?" Nah, ketika ada bakteri di sana, Anda akan terkena E. Coli. Segera pergi ke dokter! Anda akan terjebak di kamar mandi untuk sementara waktu. Maaf...', 'Ingat bagaimana Anda mengetahui bahwa 大腸 berarti "usus besar?" Nah, ketika ada bakteri di sana, Anda akan terkena E. Coli. Segera pergi ke dokter! Anda akan terjebak di kamar mandi untuk sementara waktu. Maaf...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0a6d5156-0446-4ad5-bdd7-4f47cf94bbaf', 'E.Coli', true) ON CONFLICT DO NOTHING;
