INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0a6d5156-0446-4ad5-bdd7-4f47cf94bbaf', 'だいちょうきん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a6d5156-0446-4ad5-bdd7-4f47cf94bbaf', '大腸菌を美少女に擬人化させたカードアプリ・ゲームがあります。', 'Ada permainan aplikasi kartu yang melambangkan E. Coli sebagai wanita cantik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', 'vocabulary', '那智の滝', '那智の滝', 1, 'e2cb85f8-40bf-4b46-a269-c1225b62bafc', 'Air terjun kebijaksanaan adalah Air Terjun Nachi, salah satu air terjun paling terkenal (dan paling bijaksana) di Jepang.', 'Air terjun kebijaksanaan adalah Air Terjun Nachi, salah satu air terjun paling terkenal (dan paling bijaksana) di Jepang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', 'Air Terjun Nachi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', 'Nachinotaki', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', 'なちのたき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', '日曜日は、熊野古道を歩いて、那智の滝を見に行く予定です。', 'Pada hari Minggu, kami berencana berjalan di Kumano Kodō dan melihat Air Terjun Nachi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', 'これは、この間行った那智の滝で一番よくとれた写真です。', 'Ini adalah foto terbaik yang bisa saya dapatkan dari Air Terjun Nachi yang saya kunjungi beberapa hari yang lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a231bdbc-1e6e-47c6-81d7-d604eb6c8c81', '那智の滝は、国の名勝に指定されています。', 'Air Terjun Nachi telah ditetapkan sebagai tempat keindahan nasional.') ON CONFLICT DO NOTHING;
