INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fc61b6a4-c7b8-4392-9093-43250e0a2329', 'vocabulary', '凸版', '凸版', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Tekan ukiran yang tidak rata pada kertas untuk membuat edisi terbaru majalah Anda. Yang Anda gunakan adalah mesin cetak. Hal ini membuat pencetakan massal menjadi bagus dan murah di Jepang!', 'Tekan ukiran yang tidak rata pada kertas untuk membuat edisi terbaru majalah Anda. Yang Anda gunakan adalah mesin cetak. Hal ini membuat pencetakan massal menjadi bagus dan murah di Jepang!') ON CONFLICT (id) DO NOTHING;
