INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fc61b6a4-c7b8-4392-9093-43250e0a2329', '我が社では、特殊な技術を用いて、樹脂凸版の直接製版を格安で行っています。', 'Di perusahaan kami, kami menggunakan teknik khusus untuk melakukan pencetakan relief resin dan pembuatan pelat langsung dengan harga murah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c1726368-7444-49b0-a778-62f3163f767e', 'vocabulary', '凹凸', '凹凸', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Permukaan yang ditutupi bagian cembung dan cekung akan menjadi sangat tidak rata dan kasar.', 'Permukaan yang ditutupi bagian cembung dan cekung akan menjadi sangat tidak rata dan kasar.') ON CONFLICT (id) DO NOTHING;
