INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1726368-7444-49b0-a778-62f3163f767e', '凹凸のはっきりした顔立ちですね。', 'Ciri-cirinya sangat tidak merata, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c3001b68-431d-48b2-afa1-0df9d325fd4e', 'vocabulary', '恐喝', '恐喝', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Seorang pria berjaket kulit menegur Anda dan menggunakan taktik ketakutan untuk mendapatkan bayaran. Dia memerasmu! Itu ilegal. Kalau dipikir-pikir, dia mungkin anggota yakuza. Anda harus pindah.', 'Seorang pria berjaket kulit menegur Anda dan menggunakan taktik ketakutan untuk mendapatkan bayaran. Dia memerasmu! Itu ilegal. Kalau dipikir-pikir, dia mungkin anggota yakuza. Anda harus pindah.') ON CONFLICT (id) DO NOTHING;
