INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5ec34c39-4b6a-4df9-ab4a-a64d981c8280', 'vocabulary', '堕落', '堕落', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Terjerumus ke dalam kehidupan yang merosot dan Anda mungkin akan terlibat dalam banyak korupsi. Mencuri, menusuk, mencuci uang, dan sebagainya.', 'Terjerumus ke dalam kehidupan yang merosot dan Anda mungkin akan terlibat dalam banyak korupsi. Mencuri, menusuk, mencuci uang, dan sebagainya.') ON CONFLICT (id) DO NOTHING;
