INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eaf6d081-939f-4819-9cd3-24ecb6b8e057', 'vocabulary', '果敢', '果敢', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Buah yang berani sangatlah tegas dan berani! Dia akan keluar dan menjadi superhero buah atau ilmuwan atau semacamnya.', 'Buah yang berani sangatlah tegas dan berani! Dia akan keluar dan menjadi superhero buah atau ilmuwan atau semacamnya.') ON CONFLICT (id) DO NOTHING;
