INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2b33f99f-d22a-4b4b-b830-98ca3def1f09', '人の話を遮るのは失礼です。', 'Tidak sopan menyela seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('15716e53-6eab-4003-9f51-1444ed678615', 'vocabulary', '遮断', '遮断', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Jika Anda mencegat perdagangan dan memisahkan suatu negara dari dunia luar, negara tersebut akan terjebak dalam keadaan terisolasi atau jika mereka mengidap penyakit seperti zombie-itus, maka itu adalah karantina.', 'Jika Anda mencegat perdagangan dan memisahkan suatu negara dari dunia luar, negara tersebut akan terjebak dalam keadaan terisolasi atau jika mereka mengidap penyakit seperti zombie-itus, maka itu adalah karantina.') ON CONFLICT (id) DO NOTHING;
