INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d1b748f-16cf-4a4f-83df-dbb608754364', 'vocabulary', '酵素', '酵素', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Satu-satunya elemen yang Anda perlukan untuk memfermentasi sesuatu adalah enzim. Itu menghancurkan apa pun yang Anda coba fermentasi dengan cara yang benar.', 'Satu-satunya elemen yang Anda perlukan untuk memfermentasi sesuatu adalah enzim. Itu menghancurkan apa pun yang Anda coba fermentasi dengan cara yang benar.') ON CONFLICT (id) DO NOTHING;
