INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0ed52140-c42c-42f7-b88b-bcd089b741a6', 'vocabulary', '酵母', '酵母', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Ibu dari fermentasi yang baik adalah ragi! Jika Anda ingin memanggang pai atau roti, Anda harus mendapatkan yang terbaik. Dan jika Anda tidak punya, mungkin tetangga Anda punya uang tambahan yang bisa Anda pinjam?', 'Ibu dari fermentasi yang baik adalah ragi! Jika Anda ingin memanggang pai atau roti, Anda harus mendapatkan yang terbaik. Dan jika Anda tidak punya, mungkin tetangga Anda punya uang tambahan yang bisa Anda pinjam?') ON CONFLICT (id) DO NOTHING;
