INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc212415-b936-4c6a-a6d4-31e4284b80c5', 'vocabulary', '発酵', '発酵', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Saat Anda memfermentasi sesuatu, ia menyimpang dari aslinya dan berubah selama fermentasi menjadi sesuatu yang baru.', 'Saat Anda memfermentasi sesuatu, ia menyimpang dari aslinya dan berubah selama fermentasi menjadi sesuatu yang baru.') ON CONFLICT (id) DO NOTHING;
