INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f401c8fc-df29-4e4b-93ac-021f97c507fa', 'vocabulary', '閲覧', '閲覧', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Jika Anda ingin melihat dan memeriksa beberapa hal dengan cepat, Anda cukup menjelajah. Belum mau beli, tinggal lihat-lihat saja.', 'Jika Anda ingin melihat dan memeriksa beberapa hal dengan cepat, Anda cukup menjelajah. Belum mau beli, tinggal lihat-lihat saja.') ON CONFLICT (id) DO NOTHING;
