INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68748fe8-a846-42a7-adef-1cf2e0e425d7', 'vocabulary', '校閲', '校閲', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Inspeksi yang Anda lakukan terhadap pekerjaan rumah Anda sebelum sekolah adalah revisi. Terkadang mengoreksi akan membantu Anda menemukan kesalahan sebelum Anda menyerahkannya juga. Pastikan Anda memeriksa semuanya.', 'Inspeksi yang Anda lakukan terhadap pekerjaan rumah Anda sebelum sekolah adalah revisi. Terkadang mengoreksi akan membantu Anda menemukan kesalahan sebelum Anda menyerahkannya juga. Pastikan Anda memeriksa semuanya.') ON CONFLICT (id) DO NOTHING;
