INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1872fd30-1b72-4ab9-8016-3d7c755ec21f', 'vocabulary', '奔走', '奔走', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Jika Anda sibuk dan berlarian sepanjang hari karena sibuk, Anda akhirnya berlari untuk menyelesaikan semuanya. Anda akan sibuk menyelesaikan semuanya, namun usaha Anda tidak akan sia-sia!', 'Jika Anda sibuk dan berlarian sepanjang hari karena sibuk, Anda akhirnya berlari untuk menyelesaikan semuanya. Anda akan sibuk menyelesaikan semuanya, namun usaha Anda tidak akan sia-sia!') ON CONFLICT (id) DO NOTHING;
