INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('113426e9-ec4a-4fb6-b6cd-279ddac0b13e', '結局成功もせず、女もできずに朽ちていくはめになった。', 'Pada akhirnya, saya tidak berhasil, tidak pernah punya pacar, dan sekarang saya akan mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8a961242-40fc-4118-9ab0-2ec52d3a38d5', 'vocabulary', '殻', '殻', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ingatlah bahwa kata ini dapat digunakan untuk cangkang hewan dan biji.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ingatlah bahwa kata ini dapat digunakan untuk cangkang hewan dan biji.') ON CONFLICT (id) DO NOTHING;
