INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e769323-fb65-49fe-a024-115482428945', 'vocabulary', '汚濁', '汚濁', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Kalau udaranya becek dan kotor, itu karena terlalu banyak polusi di kawasan itu. Anda harus memakai masker dan berhati-hati terhadap kontaminasi.', 'Kalau udaranya becek dan kotor, itu karena terlalu banyak polusi di kawasan itu. Anda harus memakai masker dan berhati-hati terhadap kontaminasi.') ON CONFLICT (id) DO NOTHING;
