INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('441eef04-1fa6-4f60-816f-5af13357f17a', 'vocabulary', '濁す', '濁す', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berlumpur, jadi versi verbanya adalah membuat berlumpur atau membuat keruh.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berlumpur, jadi versi verbanya adalah membuat berlumpur atau membuat keruh.') ON CONFLICT (id) DO NOTHING;
