INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a450a520-9437-45f4-be3b-f459b666328d', 'vocabulary', '硫黄', '硫黄', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Belerang yang berwarna kuning tetaplah belerang. Baunya seperti telur busuk, warnanya juga agak kuning.', 'Belerang yang berwarna kuning tetaplah belerang. Baunya seperti telur busuk, warnanya juga agak kuning.') ON CONFLICT (id) DO NOTHING;
