INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('af94ef30-f63a-4a16-b2ed-c4cbe235239e', 'vocabulary', '容赦なく', '容赦なく', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Ingat bagaimana 容赦 bisa berarti "pengampunan" dan "belas kasihan?" Tambahkan なく (pada dasarnya BUKAN itu), dan itu menjadi tanpa henti dan tanpa ampun. Kebalikan dari sebelumnya!', 'Ingat bagaimana 容赦 bisa berarti "pengampunan" dan "belas kasihan?" Tambahkan なく (pada dasarnya BUKAN itu), dan itu menjadi tanpa henti dan tanpa ampun. Kebalikan dari sebelumnya!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('af94ef30-f63a-4a16-b2ed-c4cbe235239e', 'Tanpa henti', true) ON CONFLICT DO NOTHING;
