INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af94ef30-f63a-4a16-b2ed-c4cbe235239e', '父は弟を容赦なく殴りつけました。', 'Ayah tanpa henti memukuli adik laki-laki saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4541b598-0a35-4772-8a55-018907499ca2', 'vocabulary', '蒼白', '蒼白', 1, '78748cfe-31ab-4d14-a809-a0ada1f2e2eb', 'Jika Anda berkulit putih pucat, Anda pucat, atau pucat. Kata ini biasanya digunakan untuk membicarakan pucatnya wajah seseorang.', 'Jika Anda berkulit putih pucat, Anda pucat, atau pucat. Kata ini biasanya digunakan untuk membicarakan pucatnya wajah seseorang.') ON CONFLICT (id) DO NOTHING;
