INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1003c65b-6388-4b05-a99d-ab288d64f863', 'vocabulary', '享受', '享受', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Hal terbaik untuk diterima dan diterima dalam hidup Anda adalah kesenangan! Jangan menghalanginya, biarkan masuk! Berbahagialah!', 'Hal terbaik untuk diterima dan diterima dalam hidup Anda adalah kesenangan! Jangan menghalanginya, biarkan masuk! Berbahagialah!') ON CONFLICT (id) DO NOTHING;
