INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1003c65b-6388-4b05-a99d-ab288d64f863', '我が社は円安の恩恵をもろに享受しているんだ。', 'Perusahaan kami menikmati manfaat yen yang murah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('089a0169-7780-4dac-a678-7bcd96ae0130', 'vocabulary', '傑作', '傑作', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Sesuatu yang Anda buat yang memancarkan kehebatan adalah mahakarya Anda. Karya terbaik yang pernah Anda buat sepanjang hidup Anda.', 'Sesuatu yang Anda buat yang memancarkan kehebatan adalah mahakarya Anda. Karya terbaik yang pernah Anda buat sepanjang hidup Anda.') ON CONFLICT (id) DO NOTHING;
