INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('089a0169-7780-4dac-a678-7bcd96ae0130', 'これはピカソの傑作だね。', 'Ini adalah mahakarya Picasso.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0920d0a6-0e53-498a-913d-4e3c3826a36c', 'vocabulary', '豪傑', '豪傑', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Jika Anda melihat kembali sejarah dan melihat seseorang dengan kehebatan luar biasa, mungkin dia adalah seorang pahlawan. Bukan sekedar orang biasa, tapi orang luar biasa seperti Hercules atau Mae Jemison.', 'Jika Anda melihat kembali sejarah dan melihat seseorang dengan kehebatan luar biasa, mungkin dia adalah seorang pahlawan. Bukan sekedar orang biasa, tapi orang luar biasa seperti Hercules atau Mae Jemison.') ON CONFLICT (id) DO NOTHING;
