INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0920d0a6-0e53-498a-913d-4e3c3826a36c', '日本史上、 最強の豪傑は誰だと思いますか。', 'Menurut Anda siapa pahlawan terhebat dalam sejarah Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('83b04687-4d16-44d2-a0ec-b2c0e09b795e', 'vocabulary', '凌ぐ', '凌ぐ', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertahan, jadi versi verbanya adalah bertahan atau menahan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertahan, jadi versi verbanya adalah bertahan atau menahan.') ON CONFLICT (id) DO NOTHING;
