INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83b04687-4d16-44d2-a0ec-b2c0e09b795e', '貧乏な時は、雑草を食べて飢えを凌いでいました。', 'Ketika saya miskin, saya makan rumput liar untuk mencegah kelaparan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ad5048ae-7d45-4639-9e59-9c2fe577e7f9', 'vocabulary', '解剖', '解剖', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Bagilah tubuh dan lepaskan ikatan organnya untuk melakukan otopsi. Anda harus memotong semuanya dan menguraikan bagian-bagiannya untuk mengetahui mengapa orang atau hewan tersebut mati.', 'Bagilah tubuh dan lepaskan ikatan organnya untuk melakukan otopsi. Anda harus memotong semuanya dan menguraikan bagian-bagiannya untuk mengetahui mengapa orang atau hewan tersebut mati.') ON CONFLICT (id) DO NOTHING;
