INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c4c164c4-7bbd-40d8-8bc0-cdebefb167e8', 'vocabulary', '嘱託', '嘱託', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Sebuah perusahaan meminta pekerjaan konsinyasi dan Anda mengambilnya untuk menjadi karyawan paruh waktu.', 'Sebuah perusahaan meminta pekerjaan konsinyasi dan Anda mengambilnya untuk menjadi karyawan paruh waktu.') ON CONFLICT (id) DO NOTHING;
