INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf394440-b5ce-41ae-a462-6765d9c9440f', '鳥が伝染病の媒介となると仮定しよう。', 'Anggaplah burung telah menjadi perantara penyakit menular.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e7936afd-8cca-4302-9439-5c8480cff28f', 'vocabulary', '媒体', '媒体', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Seorang mediator yang bekerja dengan seseorang yang tidak memiliki tubuh harus menggunakan semacam media fana untuk merekam apa yang mereka katakan. Media cetak? Tentu. media elektronik? Baiklah? Media hantu? TIDAK! Manusia tidak bisa membaca hal itu!', 'Seorang mediator yang bekerja dengan seseorang yang tidak memiliki tubuh harus menggunakan semacam media fana untuk merekam apa yang mereka katakan. Media cetak? Tentu. media elektronik? Baiklah? Media hantu? TIDAK! Manusia tidak bisa membaca hal itu!') ON CONFLICT (id) DO NOTHING;
