INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c82ff70-bfbc-4874-b62f-58ae93253e6f', 'つまり彼は二人にとって触媒のような役割を果たしたということだ。', 'Dengan kata lain, dia berhasil memainkan peran sebagai katalisator bagi kedua orang tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9cd36ea-dd42-4e9a-bf97-c489ad7fc736', 'vocabulary', '媒酌', '媒酌-8448', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Seorang mediator melayani keluarga dan bahkan negara dengan menjodohkan mereka. Mereka mengenal semua orang dan segalanya sehingga untuk menghentikan pertengkaran dan perang keluarga, mereka menyatukan dua orang dari masing-masing pihak untuk menikah dan itu memperbaiki segalanya.', 'Seorang mediator melayani keluarga dan bahkan negara dengan menjodohkan mereka. Mereka mengenal semua orang dan segalanya sehingga untuk menghentikan pertengkaran dan perang keluarga, mereka menyatukan dua orang dari masing-masing pihak untuk menikah dan itu memperbaiki segalanya.') ON CONFLICT (id) DO NOTHING;
