INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e9cd36ea-dd42-4e9a-bf97-c489ad7fc736', '私どもの結婚式の媒酌の労をおとりいただき、本当にありがとうございました。 ', 'Terima kasih banyak atas semua kerja keras Anda dalam perjodohan upacara pernikahan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4b5aad7c-38f7-4538-9ab3-0c4d340fc88b', 'vocabulary', '帆', '帆', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
