INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2eea0198-33b6-4420-bb97-c87fd239b6cc', 'vocabulary', '帆走', '帆走', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Sebuah layar menjalankan perahu di sepanjang laut dengan berlayar! Anda tidak dapat berlari di sepanjang air kecuali layarnya terbuka dan menangkap angin.', 'Sebuah layar menjalankan perahu di sepanjang laut dengan berlayar! Anda tidak dapat berlari di sepanjang air kecuali layarnya terbuka dan menangkap angin.') ON CONFLICT (id) DO NOTHING;
