INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60654b19-1dfb-4231-b824-aa5d50aa6e99', '今年は祖父の三回忌です。', 'Hari ini adalah peringatan dua tahun kematian kakekku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60654b19-1dfb-4231-b824-aa5d50aa6e99', 'みんな忙しいので、各回忌に家族全員集まることは難しいです。', 'Semua orang begitu sibuk sehingga sulit mengumpulkan seluruh keluarga untuk setiap hari jadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60654b19-1dfb-4231-b824-aa5d50aa6e99', '死んだお嫁さんの一回忌もまだ終わってないのにもう再婚するつもりなの？', 'Mendiang istri Anda baru saja meninggal dunia dan Anda sudah berencana menikah lagi?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('13f73ed8-b8aa-4b3e-8bec-a08cf57b72f4', 'vocabulary', '忌', '忌', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
