INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79d0257a-aeeb-43e3-a300-a53021a7995d', 'vocabulary', '禁忌', '禁忌', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Larangan terhadap sesuatu dengan hukuman yang sangat berat sehingga Anda akan berakhir berkabung setelahnya adalah hal yang tabu.', 'Larangan terhadap sesuatu dengan hukuman yang sangat berat sehingga Anda akan berakhir berkabung setelahnya adalah hal yang tabu.') ON CONFLICT (id) DO NOTHING;
