INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9d49dbd-b859-46d6-8b04-88ac3f22d37a', 'vocabulary', '憤慨', '憤慨', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Anda sangat membenci seseorang sehingga Anda menghela nafas marah setiap kali orang itu ada. Segala sesuatu yang mereka lakukan membuat Anda merasakan kebencian yang sangat kuat.', 'Anda sangat membenci seseorang sehingga Anda menghela nafas marah setiap kali orang itu ada. Segala sesuatu yang mereka lakukan membuat Anda merasakan kebencian yang sangat kuat.') ON CONFLICT (id) DO NOTHING;
