INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7cb89b5b-ca3f-4047-ba1d-aaafbc111eaf', 'vocabulary', '浄瑠璃', '浄瑠璃', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Jika Anda membersihkan batu lapis lazuli hingga menjadi seperti kaca, Anda dapat menggunakannya dalam pertunjukan joruri. Jika Anda belum pernah mendengar tentang joruri, itu adalah nyanyian cerita tradisional Jepang, seperti balada, diiringi musik shamisen, dan seringkali boneka.', 'Jika Anda membersihkan batu lapis lazuli hingga menjadi seperti kaca, Anda dapat menggunakannya dalam pertunjukan joruri. Jika Anda belum pernah mendengar tentang joruri, itu adalah nyanyian cerita tradisional Jepang, seperti balada, diiringi musik shamisen, dan seringkali boneka.') ON CONFLICT (id) DO NOTHING;
