INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cb89b5b-ca3f-4047-ba1d-aaafbc111eaf', '江戸時代の娯楽は、浄瑠璃や歌舞伎だった。', 'Hiburan pada zaman Edo adalah joruri dan kabuki.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cb89b5b-ca3f-4047-ba1d-aaafbc111eaf', '人形浄瑠璃のチケットをもらいました。', 'Saya mendapat tiket untuk pertunjukan ningyo joruri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cb89b5b-ca3f-4047-ba1d-aaafbc111eaf', '今回は、浄瑠璃人形の作り手にインタビューをしました。', 'Kali ini kami mewawancarai seorang pencipta wayang joruri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('35a023df-04c8-42b7-a14e-540ca9b7951f', 'vocabulary', '瑠璃色', '瑠璃色', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Apa warna kaca lapis lazuli? Warnanya biru cerah. Jika Anda belum pernah melihat batu lapis lazuli, carilah dan Anda akan mengetahui mengapa artinya biru cerah!', 'Apa warna kaca lapis lazuli? Warnanya biru cerah. Jika Anda belum pernah melihat batu lapis lazuli, carilah dan Anda akan mengetahui mengapa artinya biru cerah!') ON CONFLICT (id) DO NOTHING;
