INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35a023df-04c8-42b7-a14e-540ca9b7951f', '莉子は、瑠璃色のワンピースを着て諒一郎との待ち合わせ場所に現れた。', 'Riko muncul dengan mengenakan gaun biru cerah di tempat dia bertemu Ryoichiro.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35a023df-04c8-42b7-a14e-540ca9b7951f', 'ヒゴタイは、瑠璃色で丸い形をした、とても可愛い花です。', 'Berwarna biru cerah dan berbentuk bulat, higotai adalah bunga yang sangat cantik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35a023df-04c8-42b7-a14e-540ca9b7951f', 'ふと、瑠璃色の美しい宝石のような虫が目にとまった。', 'Tiba-tiba, seekor serangga cantik berwarna biru cerah yang tampak seperti permata menarik perhatian saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7db3fec6-977a-41b4-9651-94676b2ee861', 'vocabulary', '酌', '酌', 1, '6847501a-6a9e-40e2-a957-e83e793969eb', 'Jika Anda melayani seseorang, Anda menuangkan alkohol atau menuangkan sake untuknya. Anda sedang mengisi gelas seseorang.', 'Jika Anda melayani seseorang, Anda menuangkan alkohol atau menuangkan sake untuknya. Anda sedang mengisi gelas seseorang.') ON CONFLICT (id) DO NOTHING;
