INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cefb1631-7061-4cef-9486-94dd151bb097', 'vocabulary', '約款', '約款', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Artikel yang Anda tuliskan janji adalah sebuah perjanjian. Pastikan Anda membacanya dengan seksama sebelum menandatanganinya!', 'Artikel yang Anda tuliskan janji adalah sebuah perjanjian. Pastikan Anda membacanya dengan seksama sebelum menandatanganinya!') ON CONFLICT (id) DO NOTHING;
