INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4bf13672-6810-4c4c-9029-b8a3d6a83a7f', 'vocabulary', '借款', '借款-8380', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Artikel yang membuktikan bahwa Anda hanya meminjam uang atau boneka binatang disebut pinjaman. Anda harus membayar kembali orang itu untuk makhluk berbulu halus itu.', 'Artikel yang membuktikan bahwa Anda hanya meminjam uang atau boneka binatang disebut pinjaman. Anda harus membayar kembali orang itu untuk makhluk berbulu halus itu.') ON CONFLICT (id) DO NOTHING;
