INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4bf13672-6810-4c4c-9029-b8a3d6a83a7f', '日本が多くの国に円借款を提供しているのはご存知ですか。', 'Tahukah Anda bahwa Jepang menawarkan pinjaman yen internasional ke banyak negara?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('59cb6fa9-4ec9-4e84-814b-895a9cfa2197', 'vocabulary', '東亜', '東亜', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Asia Timur adalah Asia Timur! Di situlah Jepang berada!', 'Asia Timur adalah Asia Timur! Di situlah Jepang berada!') ON CONFLICT (id) DO NOTHING;
