INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f97fc6cf-3954-4fa7-a101-1f0a58ec4980', 'vocabulary', '侮る', '侮る', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghina, jadi versi verbanya adalah menghina.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menghina, jadi versi verbanya adalah menghina.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f97fc6cf-3954-4fa7-a101-1f0a58ec4980', 'Untuk Membenci', true) ON CONFLICT DO NOTHING;
