INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f97fc6cf-3954-4fa7-a101-1f0a58ec4980', '子供だからといって侮らない方がいい。', 'Anda tidak boleh meremehkannya hanya karena dia masih anak-anak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c261aced-428a-41ca-8f63-3845df4633be', 'vocabulary', '侮辱', '侮辱', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Kamu sangat membenci pria yang satu ini sehingga kamu ingin mempermalukannya sehingga kamu menghinanya di depan umum. Itu tidak terlalu bagus, tapi sepertinya itu membuatnya malu. Saya kira kamu menang.', 'Kamu sangat membenci pria yang satu ini sehingga kamu ingin mempermalukannya sehingga kamu menghinanya di depan umum. Itu tidak terlalu bagus, tapi sepertinya itu membuatnya malu. Saya kira kamu menang.') ON CONFLICT (id) DO NOTHING;
