INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56aaae1e-b974-4fbd-a707-967b8975320c', '親しい友人の慶事は自分のことの様にうれしい。', 'Peristiwa bahagia yang dialami teman-teman dekatku membuatku bahagia seolah-olah itu adalah kebahagiaanku sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d21ee551-7d63-48f2-8fd4-f76c63cda24e', 'vocabulary', '弁慶', '弁慶', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Anda harus memberi selamat kepada seseorang yang berbicara banyak dialek karena mereka harus menjadi orang yang sangat kuat, seperti Pak Benkei. Anda pikir belajar bahasa Jepang itu sulit sekarang, tunggu saja sampai Anda mendengar Osaka-ben dan Hokkaido-ben. Dibutuhkan orang yang sangat kuat — seorang Benkei — untuk mempelajari semua dialek tersebut, jadi ucapkan selamat kepada mereka dan beri tahu mereka betapa kuatnya mereka!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d21ee551-7d63-48f2-8fd4-f76c63cda24e', 'Benkei', true) ON CONFLICT DO NOTHING;
