INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3941873e-7985-406f-bffc-919572983a5a', 'vocabulary', '擬装', '擬装', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Gunakan pakaian yang meniru lingkungan sekitar Anda untuk membuat penyamaran. Atau kenakan kamuflase agar tidak ada yang bisa menemukan Anda di Walmart.', 'Gunakan pakaian yang meniru lingkungan sekitar Anda untuk membuat penyamaran. Atau kenakan kamuflase agar tidak ada yang bisa menemukan Anda di Walmart.') ON CONFLICT (id) DO NOTHING;
