INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('293d8e32-e478-46ae-abf6-486f389bc6c1', 'vocabulary', '法曹', '法曹', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Metode resmi dalam melakukan apa pun memerlukan menyewa pengacara. Mereka harus ada di sana ketika Anda menandatangani formulir atau menuntut orang, atau hal itu tidak resmi sama sekali.', 'Metode resmi dalam melakukan apa pun memerlukan menyewa pengacara. Mereka harus ada di sana ketika Anda menandatangani formulir atau menuntut orang, atau hal itu tidak resmi sama sekali.') ON CONFLICT (id) DO NOTHING;
