INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9fc23da9-c445-4edc-8a59-9432d7f19c93', 'vocabulary', '流浪', '流浪', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Berkeliaran dari sungai ke sungai dan Anda akan benar-benar terbiasa mengembara. Anda akan sangat menyukainya sehingga Anda akan berpindah ke nomadisme. Langit terbuka adalah rumah Anda!', 'Berkeliaran dari sungai ke sungai dan Anda akan benar-benar terbiasa mengembara. Anda akan sangat menyukainya sehingga Anda akan berpindah ke nomadisme. Langit terbuka adalah rumah Anda!') ON CONFLICT (id) DO NOTHING;
