INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9fc23da9-c445-4edc-8a59-9432d7f19c93', '全てのジプシーが貧しい流浪の民というわけではない。', 'Itu tidak berarti semua orang Gipsi adalah orang miskin dan nomaden.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d441a847-f019-4504-b4c2-b62290de0e89', 'vocabulary', '浪費', '浪費', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Jika Anda berkeliaran tanpa melakukan apa pun dengan biaya sendiri, itu akan membuang-buang uang. Ini tidak seperti Anda sedang melakukan atau membeli sesuatu yang penting, Anda hanya berkeliaran saja.', 'Jika Anda berkeliaran tanpa melakukan apa pun dengan biaya sendiri, itu akan membuang-buang uang. Ini tidak seperti Anda sedang melakukan atau membeli sesuatu yang penting, Anda hanya berkeliaran saja.') ON CONFLICT (id) DO NOTHING;
