INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d441a847-f019-4504-b4c2-b62290de0e89', '妻の浪費癖がなかなか治らないんです。', 'Kebiasaan boros istri saya tidak mudah disembuhkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b4b1670e-1bcb-4f92-8ad1-253e9dd90cac', 'vocabulary', '放浪', '放浪', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Lepaskan ikatan duniawimu dan jelajahi dunia. Anda akan terbiasa mengembara dan Anda akan menghabiskan sisa hari Anda menjelajahi dunia sampai Anda mati. Sungguh hidup yang luar biasa! Tapi Anda hanya bisa melakukannya jika Anda melepaskan segalanya.', 'Lepaskan ikatan duniawimu dan jelajahi dunia. Anda akan terbiasa mengembara dan Anda akan menghabiskan sisa hari Anda menjelajahi dunia sampai Anda mati. Sungguh hidup yang luar biasa! Tapi Anda hanya bisa melakukannya jika Anda melepaskan segalanya.') ON CONFLICT (id) DO NOTHING;
