INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4b1670e-1bcb-4f92-8ad1-253e9dd90cac', '当時は、逃げるように各地を転々と放浪していました。', 'Pada hari-hari itu saya harus mengembara dari satu tempat ke tempat lain untuk melarikan diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('86517af0-c745-4a0b-8a36-230d99864d4c', 'vocabulary', '浪人', '浪人', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Seseorang yang mengembara karena tuannya dibunuh, dikenal sebagai ronin, atau samurai tak bertuan. Sekarang mereka sama seperti kita semua, tapi mereka tidak bisa berhenti mengembara karena mereka tidak punya tempat tinggal.
