INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('541d6fca-7021-4b60-afba-d01548499274', 'vocabulary', '漆', '漆', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
