INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('957203f3-9045-4fb5-b460-5fd3dea2bb28', 'vocabulary', '酪農', '酪農', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Peternakan sapi perah adalah peternakan sapi perah!', 'Peternakan sapi perah adalah peternakan sapi perah!') ON CONFLICT (id) DO NOTHING;
