INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('957203f3-9045-4fb5-b460-5fd3dea2bb28', 'ここは日本酪農発祥の地です。', 'Di sinilah letak asal mula peternakan sapi perah Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1d613d2c-dbbe-4180-8223-ad39b53c513e', 'vocabulary', '鋳造', '鋳造', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Jika Anda ingin membuat cast, Anda perlu mempelajari casting terlebih dahulu. Kemudian Anda bisa menghasilkan banyak karya seni, kerajinan tangan, dan uang palsu yang rapi. Tunggu, tidak, jangan lakukan yang terakhir itu.', 'Jika Anda ingin membuat cast, Anda perlu mempelajari casting terlebih dahulu. Kemudian Anda bisa menghasilkan banyak karya seni, kerajinan tangan, dan uang palsu yang rapi. Tunggu, tidak, jangan lakukan yang terakhir itu.') ON CONFLICT (id) DO NOTHING;
