INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f8583ee4-b24e-49fd-8071-a8da4e113119', 'vocabulary', '閑散', '閑散', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Ini adalah hari yang santai sehingga semua orang berpencar dan meninggalkan daerah itu sepi. Hanya kamu sekarang. Bersantai di tempat teduh.', 'Ini adalah hari yang santai sehingga semua orang berpencar dan meninggalkan daerah itu sepi. Hanya kamu sekarang. Bersantai di tempat teduh.') ON CONFLICT (id) DO NOTHING;
