INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f8583ee4-b24e-49fd-8071-a8da4e113119', '駅の南側は、いつも閑散としています。', 'Sisi selatan stasiun selalu sepi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e73478cb-5d0b-4894-b2dc-b695acf75ee5', 'vocabulary', '閑静', '閑静', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Keheningan yang santai adalah jenis ketenangan yang terbaik. Bahkan otakmu menjadi sunyi karena kamu tidak lagi peduli pada dunia.', 'Keheningan yang santai adalah jenis ketenangan yang terbaik. Bahkan otakmu menjadi sunyi karena kamu tidak lagi peduli pada dunia.') ON CONFLICT (id) DO NOTHING;
