INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e73478cb-5d0b-4894-b2dc-b695acf75ee5', 'この辺りは、閑静な住宅街になっています。', 'Lingkungan ini kini menjadi kawasan perumahan yang tenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4ee3d47d-bd3e-4237-84d7-4fa488e029ea', 'vocabulary', '逝去', '逝去', 1, 'c20d49b0-cc90-4d76-a451-ce65fe83f263', 'Mati di masa lalu dan kematian itulah yang Anda derita!', 'Mati di masa lalu dan kematian itulah yang Anda derita!') ON CONFLICT (id) DO NOTHING;
