INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dca73655-ff12-4244-b3af-3059e1f2b3ff', 'vocabulary', '倹約', '倹約', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Saya berjanji ini akan menjadi tempat yang sangat hemat karena ini adalah toko barang bekas! Mereka tidak akan berbohong tentang hal itu!', 'Saya berjanji ini akan menjadi tempat yang sangat hemat karena ini adalah toko barang bekas! Mereka tidak akan berbohong tentang hal itu!') ON CONFLICT (id) DO NOTHING;
