INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dca73655-ff12-4244-b3af-3059e1f2b3ff', 'いくらマイホームを買いたいからって、度を過ぎた倹約を強いるのはどうかと思います。', 'Menurut saya, bukanlah ide yang baik untuk memaksakan diri untuk berhemat lebih tinggi hanya karena Anda ingin membeli rumah sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('41b35e04-7932-404e-ba9d-d2bd843ab963', 'vocabulary', '弾劾', '弾劾', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Peluru kecaman terakhir adalah pemakzulan. Anda telah dipermalukan di depan umum dan sekarang Anda dimakzulkan karenanya. Astaga.', 'Peluru kecaman terakhir adalah pemakzulan. Anda telah dipermalukan di depan umum dan sekarang Anda dimakzulkan karenanya. Astaga.') ON CONFLICT (id) DO NOTHING;
