INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41b35e04-7932-404e-ba9d-d2bd843ab963', '大統領の弾劾を求める大規模な反政府デモが開かれました。', 'Demonstrasi anti-pemerintah besar-besaran diadakan untuk pemakzulan Presiden.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e2632aa4-0fdb-4fe5-89a5-c9b2f6cb973f', 'vocabulary', '隠匿', '隠匿', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Sembunyikan dan sembunyikan, sembunyikan! Banyak persembunyian terjadi di sekitar sini. Saya pikir... Saya tidak dapat menemukan siapa pun jadi saya hanya bisa berasumsi.', 'Sembunyikan dan sembunyikan, sembunyikan! Banyak persembunyian terjadi di sekitar sini. Saya pikir... Saya tidak dapat menemukan siapa pun jadi saya hanya bisa berasumsi.') ON CONFLICT (id) DO NOTHING;
