INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2632aa4-0fdb-4fe5-89a5-c9b2f6cb973f', '彼女は犯人を隠匿していたんだよ。', 'Dia menyembunyikan penjahatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6d5a8602-ee5f-49c6-a9ca-00356b2b5707', 'vocabulary', '匿名', '匿名', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Sembunyikan nama Anda untuk anonimitas. Ada banyak hal seperti itu di internet. Faktanya, Anda mungkin menggunakan nama samaran saat ini, bukan? Ya, benar. Setidaknya kamu tidak bisa menyembunyikan ITU dariku... uh... Ssssteve?', 'Sembunyikan nama Anda untuk anonimitas. Ada banyak hal seperti itu di internet. Faktanya, Anda mungkin menggunakan nama samaran saat ini, bukan? Ya, benar. Setidaknya kamu tidak bisa menyembunyikan ITU dariku... uh... Ssssteve?') ON CONFLICT (id) DO NOTHING;
