INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c667a5b1-1b50-4d5b-85bb-cc4a79198dfd', 'vocabulary', '升', '升', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
