INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c667a5b1-1b50-4d5b-85bb-cc4a79198dfd', '作文の書き出しは、一升空けて下さい。', 'Saat memulai komposisi Anda, harap biarkan kotak pertama kosong.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('02f06023-c914-41ba-98fb-907b25ca5ead', 'vocabulary', '升目', '升目', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Ukur bentuk itu di kertas dengan mata Anda. Ada empat sisinya.. itu.. itu persegi! Atau kotak dari atas mungkin... Tapi itu pasti jenis yang Anda isi pada grafik.', 'Ukur bentuk itu di kertas dengan mata Anda. Ada empat sisinya.. itu.. itu persegi! Atau kotak dari atas mungkin... Tapi itu pasti jenis yang Anda isi pada grafik.') ON CONFLICT (id) DO NOTHING;
