INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02f06023-c914-41ba-98fb-907b25ca5ead', '升目を数えると、全部で400ありました。', 'Ketika saya menghitung kotaknya, totalnya ada 400.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d166b94a-f435-4874-a8b4-b280fede7b5c', 'vocabulary', '唄', '唄', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Lagu shamisen itu lagu shamisen ya. Tapi tahukah Anda itu juga... sebuah lagu?! Oh, benarkah? Baiklah kalau begitu.', 'Lagu shamisen itu lagu shamisen ya. Tapi tahukah Anda itu juga... sebuah lagu?! Oh, benarkah? Baiklah kalau begitu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d166b94a-f435-4874-a8b4-b280fede7b5c', 'Lagu', true) ON CONFLICT DO NOTHING;
