INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d166b94a-f435-4874-a8b4-b280fede7b5c', 'この唄は、私と兄が一緒に作りました。', 'Aku menulis lagu ini bersama kakak laki-lakiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d407349-a965-4309-8b05-958e7a13ee12', 'vocabulary', '唄う', '唄う', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti lagu Shamisen, jadi versi verbanya adalah bernyanyi.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti lagu Shamisen, jadi versi verbanya adalah bernyanyi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2d407349-a965-4309-8b05-958e7a13ee12', 'Bernyanyi', true) ON CONFLICT DO NOTHING;
