INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d407349-a965-4309-8b05-958e7a13ee12', '私のおじさんは、唄うアコーディオン弾きです。', 'Paman saya adalah pemain akordeon yang bernyanyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dbc9e243-9cd4-4373-9fa5-3bf1cef30c78', 'vocabulary', '長唄', '長唄', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Lagu shamisen yang panjang adalah lagu shamisen yang panjang! Mereka juga disebut nagauta, dan biasanya juga cukup epik.', 'Lagu shamisen yang panjang adalah lagu shamisen yang panjang! Mereka juga disebut nagauta, dan biasanya juga cukup epik.') ON CONFLICT (id) DO NOTHING;
