INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('41ed3ef8-20be-4f1c-8c85-9c3f583e55ce', 'vocabulary', '煩い', '煩い', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari mengganggu? Itu menjengkelkan!', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari mengganggu? Itu menjengkelkan!') ON CONFLICT (id) DO NOTHING;
