INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b859509a-2474-4d21-ade6-57e046be375d', 'vocabulary', '煩雑', '煩雑', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Jika Anda berpikir seseorang mencoba mengganggu Anda secara acak, perhatikan saja dan Anda akan melihat bahwa mereka memiliki pola menjengkelkan yang rumit yang mereka gunakan pada Anda. Setelah Anda mengetahuinya, hal itu tidak akan terlalu mengganggu Anda dan Anda akan menang!', 'Jika Anda berpikir seseorang mencoba mengganggu Anda secara acak, perhatikan saja dan Anda akan melihat bahwa mereka memiliki pola menjengkelkan yang rumit yang mereka gunakan pada Anda. Setelah Anda mengetahuinya, hal itu tidak akan terlalu mengganggu Anda dan Anda akan menang!') ON CONFLICT (id) DO NOTHING;
