INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('73146816-239a-4354-ae89-0dc617d99f53', 'vocabulary', '煩忙', '煩忙', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Jika Anda mengganggu seseorang yang sibuk, dia akan tetap sibuk. Anda mengganggu mereka tidak dapat mengubahnya. Meskipun sekarang mereka mungkin sedang sibuk DAN kesal.', 'Jika Anda mengganggu seseorang yang sibuk, dia akan tetap sibuk. Anda mengganggu mereka tidak dapat mengubahnya. Meskipun sekarang mereka mungkin sedang sibuk DAN kesal.') ON CONFLICT (id) DO NOTHING;
