INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1c41e63e-f308-44a3-8845-e8d1b31505e4', 'vocabulary', '海藻', '海藻', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Rumput laut tetaplah rumput laut!', 'Rumput laut tetaplah rumput laut!') ON CONFLICT (id) DO NOTHING;
