INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd5b2238-a024-435c-b3af-9b2ef14ead72', 'vocabulary', '野蛮', '野蛮', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Orang barbar yang tinggal di ladang, bahkan tidak di gubuk atau rumah atau apa pun, disebut biadab oleh orang yang tinggal di gubuk dan rumah. Mereka berpikir jika Anda tinggal di suatu bidang, Anda benar-benar tidak beradab. Tapi itu semua hanya masalah opini, menurutku.', 'Orang barbar yang tinggal di ladang, bahkan tidak di gubuk atau rumah atau apa pun, disebut biadab oleh orang yang tinggal di gubuk dan rumah. Mereka berpikir jika Anda tinggal di suatu bidang, Anda benar-benar tidak beradab. Tapi itu semua hanya masalah opini, menurutku.') ON CONFLICT (id) DO NOTHING;
