INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd5b2238-a024-435c-b3af-9b2ef14ead72', 'そんな野蛮な人たちと付き合ってはいけません。', 'Anda tidak boleh bergaul dengan orang-orang biadab seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6bfc3e4d-3aa9-4f07-947b-61a46a7195ab', 'vocabulary', '南蛮', '南蛮', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Orang barbar selatan disebut orang barbar selatan! Meskipun awalnya merujuk pada masyarakat Asia Tenggara, istilah Nanban digunakan untuk merujuk pada pedagang Barat yang mulai berdatangan ke Jepang pada tahun 1500-an. Ada juga makanan enak yang diberi nama sesuai nama mereka!', 'Orang barbar selatan disebut orang barbar selatan! Meskipun awalnya merujuk pada masyarakat Asia Tenggara, istilah Nanban digunakan untuk merujuk pada pedagang Barat yang mulai berdatangan ke Jepang pada tahun 1500-an. Ada juga makanan enak yang diberi nama sesuai nama mereka!') ON CONFLICT (id) DO NOTHING;
