INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('240496d8-d130-4090-9964-2dba87dc86fa', 'vocabulary', '蛮行', '蛮行', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Orang barbar berkeliling dan melakukan tindakan barbarisme! Apa lagi yang akan mereka lakukan? Mereka orang barbar!', 'Orang barbar berkeliling dan melakukan tindakan barbarisme! Apa lagi yang akan mereka lakukan? Mereka orang barbar!') ON CONFLICT (id) DO NOTHING;
