INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b0c02081-b25d-47f6-93c4-0cb7a3139332', 'vocabulary', '醜悪', '醜悪', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Jelek, hal-hal buruk itu jelek, kejam, dan menyinggung.', 'Jelek, hal-hal buruk itu jelek, kejam, dan menyinggung.') ON CONFLICT (id) DO NOTHING;
