INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0c02081-b25d-47f6-93c4-0cb7a3139332', '「被害者たたき」ってほんと醜悪だよね。', 'Menyalahkan korban sungguh buruk, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0c02081-b25d-47f6-93c4-0cb7a3139332', '「醜悪な文章は健全なディベートの害になるか」というテーマの研究を行っています。', 'Saya sedang melakukan penelitian dengan topik, "Apakah tulisan yang menyinggung merugikan perdebatan yang sehat?"') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0c02081-b25d-47f6-93c4-0cb7a3139332', '老婆の幽霊が、醜悪な顔でこちらをにらんでいた。', 'Hantu wanita tua itu menatapku dengan wajah jeleknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4528d157-6c77-4c50-be3b-4f042fc46a21', 'vocabulary', '醜態', '醜態', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Sesuatu yang berpenampilan jelek merupakan pemandangan yang memalukan, atau perilaku yang tercela. Anda merasa tidak enak hanya dengan melihatnya. Mungkin rasanya juga tidak enak.', 'Sesuatu yang berpenampilan jelek merupakan pemandangan yang memalukan, atau perilaku yang tercela. Anda merasa tidak enak hanya dengan melihatnya. Mungkin rasanya juga tidak enak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4528d157-6c77-4c50-be3b-4f042fc46a21', 'Pemandangan Memalukan', true) ON CONFLICT DO NOTHING;
