INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4528d157-6c77-4c50-be3b-4f042fc46a21', 'しゅうたい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4528d157-6c77-4c50-be3b-4f042fc46a21', 'あんな醜態を演じたのに、よく平気な顔で会社に行けるね。', 'Bagaimana Anda bisa pergi bekerja tanpa peduli pada dunia setelah perilaku tercela seperti itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4528d157-6c77-4c50-be3b-4f042fc46a21', 'とんだ醜態を晒してしまったよ。', 'Mereka dihadapkan pada pemandangan yang sangat memalukan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4528d157-6c77-4c50-be3b-4f042fc46a21', '好きな子に醜態を見られたし、悲しみしかない。', 'Seorang gadis yang kusuka melihat kelakuanku yang tercela dan aku tidak bisa merasakan apa pun selain kesedihan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('76b826e8-8c56-48e7-b53d-539ce7535262', 'vocabulary', '醜聞', '醜聞', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Apa yang kamu dengar yang benar-benar jelek? Sebuah skandal. Skandal adalah topik gosip yang paling jelek.', 'Apa yang kamu dengar yang benar-benar jelek? Sebuah skandal. Skandal adalah topik gosip yang paling jelek.') ON CONFLICT (id) DO NOTHING;
