INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('673a679f-ab75-4c32-93bc-1285feb77909', 'これは、山田某の話である。', 'Ini adalah kisah Yamada seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('673a679f-ab75-4c32-93bc-1285feb77909', 'たしか、鈴木某とかいう人じゃなかったっけ？', 'Bukankah itu pria bernama Suzuki?') ON CONFLICT DO NOTHING;
