INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d90a6c6e-e9e7-4e7a-8e92-b1f4562af634', 'vocabulary', '某国', '某国', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Negara tertentu adalah negara tertentu!', 'Negara tertentu adalah negara tertentu!') ON CONFLICT (id) DO NOTHING;
