INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d90a6c6e-e9e7-4e7a-8e92-b1f4562af634', '日本に留学生を多く送りこんでいる某国で教えています。', 'Saya mengajar di negara yang banyak mengirimkan siswa pertukaran ke Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d90a6c6e-e9e7-4e7a-8e92-b1f4562af634', '梓川さんは派遣員として某国大使館に勤めていました。', 'Azusagawa-san bekerja sebagai pegawai sementara di kedutaan negara tertentu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d90a6c6e-e9e7-4e7a-8e92-b1f4562af634', '菅原沙羅が某国のスパイであるという嫌疑はぬぐえません。', 'Kita tidak bisa menghilangkan kecurigaan bahwa Sara Sugawara adalah mata-mata suatu negara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e40199c-d83d-4e9b-958a-0329969d955c', 'vocabulary', '某所', '某所', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Tidak ada kejutan di sini. Tempat tertentu adalah tempat tertentu.', 'Tidak ada kejutan di sini. Tempat tertentu adalah tempat tertentu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7e40199c-d83d-4e9b-958a-0329969d955c', 'Tempat Tertentu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7e40199c-d83d-4e9b-958a-0329969d955c', 'ぼうしょ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e40199c-d83d-4e9b-958a-0329969d955c', '栃木県の某所で行われたイベントに行ってきました。', 'Saya pergi ke sebuah acara yang diadakan di suatu tempat di Prefektur Tochigi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e40199c-d83d-4e9b-958a-0329969d955c', '昨夜、某所にて、有名人による太鼓の演奏会が行われたようです。', 'Tadi malam ada pertunjukan taiko yang dibawakan oleh seorang selebritis di suatu tempat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e40199c-d83d-4e9b-958a-0329969d955c', '彼女と出会ったのは、都内某所の居酒屋で食事をしている時だった。', 'Saya sedang makan di izakaya di suatu tempat di Tokyo ketika saya bertemu pacar saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('da3f7dd1-15ef-4121-9c8a-a8c65b2ca603', 'vocabulary', '某氏', '某氏', 1, '99df5e2e-748d-4421-a9da-c6f7ce6caba4', 'Nama keluarga tertentu milik orang tertentu.', 'Nama keluarga tertentu milik orang tertentu.') ON CONFLICT (id) DO NOTHING;
