INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da3f7dd1-15ef-4121-9c8a-a8c65b2ca603', '審査員の某氏に会いました。', 'Saya bertemu dengan salah satu juri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da3f7dd1-15ef-4121-9c8a-a8c65b2ca603', '社長に近い立場の某氏は、「難しい状況にしてしまった」とコメントしている。', 'Seseorang yang dekat dengan presiden berkomentar, "Kami menempatkan diri kami dalam situasi yang sulit".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('da3f7dd1-15ef-4121-9c8a-a8c65b2ca603', '「こういちはいつか世界を征服する」と某氏が語っていた。', 'Seseorang memberitahuku bahwa Koichi akan menaklukkan dunia suatu hari nanti.') ON CONFLICT DO NOTHING;
